import { useEffect, useRef } from "react";
import { ElementApi, KEYS, NodeApi, type Operation, type SlateEditor } from "platejs";

import { useEditorFlushes } from "../../hooks/use-editor-flushes";
import { FOOTNOTE_DEF_KEY } from "../../lib/document/editor-document-schema";
import { isTextOnlyBatch } from "../../lib/features/editor-operation-batch";
import { DEFAULT_PLACEHOLDER } from "../../lib/features/editor-placeholder";
import { useEditorReadOnly, useEditorRef, useEditorSelector } from "platejs/react";

const PLACEHOLDER_ATTR = "data-block-placeholder";
const PLACEHOLDER_INSET_VAR = "--block-placeholder-inset";

// The distance from the block's border-box left to where the text starts. A
// plain block is 0; a list item or to-do is offset by its marker/checkbox
// indent (the first child `<ul>`/`<ol>` padding).
function placeholderInset(block: HTMLElement): number {
  const first = block.firstElementChild;
  if (!(first instanceof HTMLElement)) {
    return 0;
  }
  const blockLeft = block.getBoundingClientRect().left;
  const style = getComputedStyle(first);
  const offset =
    first.getBoundingClientRect().left -
    blockLeft +
    (Number.parseFloat(style.paddingLeft) || 0) +
    (Number.parseFloat(style.marginLeft) || 0);
  return offset > 0 ? offset : 0;
}

// Block types that own an editable text line and can show a placeholder.
const PLACEHOLDER_TYPES = new Set<string>([
  KEYS.p,
  KEYS.h1,
  KEYS.h2,
  KEYS.h3,
  KEYS.codeLine,
  FOOTNOTE_DEF_KEY,
]);

const HEADING_TEXT: Record<string, string> = {
  [KEYS.h1]: "Heading 1",
  [KEYS.h2]: "Heading 2",
  [KEYS.h3]: "Heading 3",
};

type Placement = { parentType: string | null; index: number };

function placementOf(editor: SlateEditor, path: readonly number[]): Placement {
  const index = path[path.length - 1] ?? 0;
  const parentPath = path.slice(0, -1);
  let parentType: string | null = null;
  if (parentPath.length > 0) {
    const parent = editor.api.node(parentPath);
    const node = parent?.[0];
    if (parent && ElementApi.isElement(node) && typeof node.type === "string") {
      parentType = node.type;
    }
  }
  return { parentType, index };
}

type PlaceholderSpec = { text: string; always: boolean };

// The placeholder text for an empty block, and whether it shows whenever the
// block is empty (typed blocks with a role) or only while it holds the caret
// (a plain paragraph, so blank spacer lines stay clean).
export function placeholderSpec(
  node: Record<string, unknown>,
  placement: Placement,
  paragraphText: string,
): PlaceholderSpec | null {
  const type = typeof node.type === "string" ? node.type : "";
  if (!PLACEHOLDER_TYPES.has(type)) {
    return null;
  }
  if (NodeApi.string(node as never) !== "") {
    return null;
  }
  if (type === KEYS.h1 || type === KEYS.h2 || type === KEYS.h3) {
    return { text: HEADING_TEXT[type], always: true };
  }
  if (type === KEYS.codeLine) {
    return { text: "Code", always: true };
  }
  if (type === FOOTNOTE_DEF_KEY) {
    return { text: "Footnote", always: true };
  }
  const listStyle = typeof node.listStyleType === "string" ? node.listStyleType : null;
  if (listStyle === KEYS.listTodo) {
    return { text: "To-do", always: true };
  }
  if (listStyle !== null) {
    return { text: "List", always: true };
  }
  const { parentType, index } = placement;
  if (parentType === KEYS.callout && index === 0) {
    return { text: paragraphText, always: true };
  }
  if (parentType === KEYS.toggle && index === 0) {
    return { text: "Toggle", always: true };
  }
  if (parentType === KEYS.blockquote && index === 0) {
    return { text: "Quote", always: true };
  }
  // The first line inside a toggle body reads as the container's main line.
  if (parentType === KEYS.toggle && index === 1) {
    return { text: paragraphText, always: true };
  }
  return { text: paragraphText, always: false };
}

function placeholderFor(
  editor: SlateEditor,
  node: Record<string, unknown>,
  path: readonly number[],
  paragraphText: string,
): PlaceholderSpec | null {
  return placeholderSpec(node, placementOf(editor, path), paragraphText);
}

function editableOf(editor: SlateEditor): HTMLElement | null {
  const first = editor.children[0];
  if (!first || !ElementApi.isElement(first)) {
    return null;
  }
  const dom = editor.api.toDOMNode(first);
  const editable = dom?.closest("[data-slate-editor]");
  return editable instanceof HTMLElement ? editable : null;
}

function isSingleEmptyDocument(editor: SlateEditor): boolean {
  const first = editor.children[0];
  return (
    editor.children.length === 1 &&
    first !== undefined &&
    ElementApi.isElement(first) &&
    NodeApi.string(first) === ""
  );
}

// The elements a text-only batch can change: every ancestor of an edited text
// node. An edit alters only the empty state of those elements.
function textEditAncestors(operations: readonly Operation[]): number[][] {
  const paths: number[][] = [];
  for (const operation of operations) {
    if (operation.type !== "insert_text" && operation.type !== "remove_text") {
      continue;
    }
    for (let depth = 1; depth < operation.path.length; depth += 1) {
      paths.push(operation.path.slice(0, depth));
    }
  }
  return paths;
}

// Writes one element's placeholder state with the same rule as the full pass.
function placeholderAt(
  editor: SlateEditor,
  path: number[],
  placeholder: string,
  caret: string | null,
): void {
  const entry = editor.api.node(path);
  if (!entry || !ElementApi.isElement(entry[0])) {
    return;
  }
  const node = entry[0];
  const dom = editor.api.toDOMNode(node);
  if (!(dom instanceof HTMLElement)) {
    return;
  }
  dom.removeAttribute(PLACEHOLDER_ATTR);
  const info =
    typeof node.type === "string" && PLACEHOLDER_TYPES.has(node.type)
      ? placeholderFor(editor, node, path, placeholder)
      : null;
  if (!info || (!info.always && path.join(".") !== caret)) {
    return;
  }
  dom.setAttribute(PLACEHOLDER_ATTR, info.text);
  dom.style.setProperty(PLACEHOLDER_INSET_VAR, `${String(placeholderInset(dom))}px`);
}

// What the last pass left on the DOM. A text-only pass needs it to find the
// caret block the previous pass set its state from.
type PassState = {
  editable: HTMLElement;
  placeholder: string;
  readOnly: boolean;
  singleEmpty: boolean;
  caret: number[] | null;
};

// One mechanism for every empty editable block. It writes a data attribute and
// a single CSS rule renders the text, so nothing enters the document model.
// A full pass runs on mount, on a structural batch, on a placeholder or
// read-only change, and when the single-empty state flips. A text-only batch
// touches only the edited blocks and the previous and current caret blocks.
export function BlockPlaceholders({ placeholder = DEFAULT_PLACEHOLDER }: { placeholder?: string }) {
  const editor = useEditorRef();
  const readOnly = useEditorReadOnly();
  const { version, take } = useEditorFlushes();
  const selectionKey = useEditorSelector(
    (instance) => (instance.selection ? instance.selection.anchor.path.join(".") : ""),
    [],
  );
  const passRef = useRef<PassState | null>(null);

  useEffect(() => {
    const operations = take();
    const editable = editableOf(editor);
    if (!editable) {
      passRef.current = null;
      return;
    }
    const singleEmpty = isSingleEmptyDocument(editor);
    const caret = editor.selection ? editor.selection.anchor.path.slice(0, -1) : null;
    const caretKey = caret ? caret.join(".") : null;
    const previous = passRef.current;
    passRef.current = { editable, placeholder, readOnly, singleEmpty, caret };
    if (
      previous !== null &&
      previous.editable === editable &&
      previous.placeholder === placeholder &&
      !previous.readOnly &&
      !previous.singleEmpty &&
      !readOnly &&
      !singleEmpty &&
      isTextOnlyBatch(operations)
    ) {
      const touched = new Map<string, number[]>();
      for (const path of [
        ...textEditAncestors(operations),
        ...(previous.caret ? [previous.caret] : []),
        ...(caret ? [caret] : []),
      ]) {
        touched.set(path.join("."), path);
      }
      for (const path of touched.values()) {
        placeholderAt(editor, path, placeholder, caretKey);
      }
      return;
    }

    for (const node of editable.querySelectorAll(`[${PLACEHOLDER_ATTR}]`)) {
      node.removeAttribute(PLACEHOLDER_ATTR);
    }
    // The document-level placeholder (slate-react) covers a single empty block;
    // skip it here so the two do not stack.
    if (readOnly || singleEmpty) {
      return;
    }
    for (const [node, path] of editor.api.nodes({
      at: [],
      match: (candidate) =>
        ElementApi.isElement(candidate) &&
        typeof candidate.type === "string" &&
        PLACEHOLDER_TYPES.has(candidate.type),
    })) {
      if (!ElementApi.isElement(node)) {
        continue;
      }
      const info = placeholderFor(editor, node, path, placeholder);
      if (!info) {
        continue;
      }
      if (!info.always && path.join(".") !== caretKey) {
        continue;
      }
      const dom = editor.api.toDOMNode(node);
      if (dom instanceof HTMLElement) {
        dom.setAttribute(PLACEHOLDER_ATTR, info.text);
        // A list item's text starts after the marker/checkbox indent, not at the
        // block's left edge. Tell the ::before where the text begins.
        dom.style.setProperty(PLACEHOLDER_INSET_VAR, `${String(placeholderInset(dom))}px`);
      }
    }
  }, [editor, placeholder, readOnly, selectionKey, take, version]);

  return null;
}

import { Skeleton } from "@/components/ui/skeleton";

export function EditorDocumentSkeleton() {
  return (
    <div className="mx-auto flex min-h-full w-full max-w-[var(--editor-max-width,700px)] min-w-0 flex-col gap-3 py-8 sm:py-12">
      <Skeleton className="h-4 w-2/3" />
      <Skeleton className="h-4 w-full" />
      <Skeleton className="h-4 w-4/5" />
      <Skeleton className="mt-4 h-4 w-full" />
    </div>
  );
}

"use client";

import { RotateCcw } from "lucide-react";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { CopyButton } from "@/components/huanngdev/notion-like-editor/components/copy-button";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";

import { EditorTextButton } from "../ui/block-toolbar";
import { ScrollFadeArea } from "../ui/editor-scroll";

import { EDITOR_SCHEMA_VERSION } from "../../lib/document/editor-document";
import type { EditorRecoveryResult } from "../../hooks/use-editor-document";

type EditorRecoveryNoticeProps = {
  result: EditorRecoveryResult;
  raw: unknown;
  error?: string;
  onStartOver: () => void;
};

function titleFor(result: EditorRecoveryResult): string {
  switch (result.status) {
    case "invalid":
      return "This document could not be read";
    case "unsupported":
      return "This document uses unsupported content";
    case "future-version":
      return "This document is from a newer editor";
  }
}

function detailFor(result: EditorRecoveryResult): string {
  switch (result.status) {
    case "invalid":
      return "The saved document is not valid. Copy the JSON if you need it, or start over. The original stays in recovery storage.";
    case "unsupported":
      return "This editor cannot open some of the saved content. Copy the JSON if you need it, or start over. The original stays in recovery storage.";
    case "future-version":
      return `This document uses schema version ${String(result.schemaVersion)}. This editor reads version ${String(EDITOR_SCHEMA_VERSION)}. Copy the JSON if you need it, or start over. The original stays in recovery storage.`;
  }
}

function rawJson(raw: unknown): string {
  if (typeof raw === "string") {
    return raw;
  }

  try {
    const text = JSON.stringify(raw, null, 2);
    if (typeof text === "string") {
      return text;
    }
  } catch {
    return "";
  }

  return "";
}

export function EditorRecoveryNotice({
  result,
  raw,
  error,
  onStartOver,
}: EditorRecoveryNoticeProps) {
  const text = rawJson(raw);
  const issues = result.status === "future-version" ? [] : result.issues;
  const shown = issues.slice(0, 5);
  const extra = issues.length - shown.length;

  return (
    <div className="mx-auto w-full max-w-[var(--editor-max-width,700px)] min-w-0 py-8 sm:py-12">
      <Alert className="min-w-0">
        <AlertTitle>{titleFor(result)}</AlertTitle>
        <AlertDescription>
          <p>{detailFor(result)}</p>
          {shown.length > 0 ? (
            <ul className="mt-3 list-disc pl-5">
              {shown.map((issue, index) => (
                <li key={`${issue.path.join(".")}-${String(index)}`}>{issue.message}</li>
              ))}
            </ul>
          ) : null}
          {extra > 0 ? <p className="mt-2">{`${String(extra)} more.`}</p> : null}
        </AlertDescription>
        <ScrollFadeArea
          orientation="vertical"
          className="border-border bg-muted text-foreground mt-3 max-h-60 w-full max-w-full min-w-0 rounded-md border"
        >
          <pre
            tabIndex={0}
            aria-label="Document JSON"
            className="w-full p-3 font-mono text-sm [overflow-wrap:anywhere] whitespace-pre-wrap"
          >
            {text}
          </pre>
        </ScrollFadeArea>
        {error ? (
          <p role="alert" className="text-destructive mt-3 text-sm text-pretty">
            {error}
          </p>
        ) : null}
        <TooltipProvider>
          <div className="mt-3 flex flex-wrap items-center gap-2">
            <Tooltip>
              <TooltipTrigger asChild>
                <CopyButton text={text} variant="outline" size="icon" aria-label="Copy JSON" />
              </TooltipTrigger>
              <TooltipContent>Copy JSON</TooltipContent>
            </Tooltip>
            <EditorTextButton
              variant="outline"
              label="Start over"
              icon={<RotateCcw aria-hidden="true" />}
              onClick={onStartOver}
            />
          </div>
        </TooltipProvider>
      </Alert>
    </div>
  );
}

"use client";

import { RefreshCw } from "lucide-react";

import { cn } from "@/lib/utils";

import { EditorTextButton } from "../ui/block-toolbar";

import type { AutosaveStatus } from "../../lib/document/editor-autosave";

type EditorSaveStatusProps = {
  status: AutosaveStatus;
  message?: string;
  onRetry: () => void;
};

const FALLBACK_ERROR =
  "The document could not be saved. Copy it before closing this tab, then try again.";

function statusText(status: AutosaveStatus, message: string | undefined): string {
  switch (status) {
    case "saved":
      return "Saved";
    case "saving":
      return "Saving…";
    case "dirty":
      return "Unsaved changes";
    case "conflict":
      return "Changed in another tab. Your copy was saved for recovery. Reload to continue.";
    case "error":
      return message && message.length > 0 ? message : FALLBACK_ERROR;
  }
}

// The healthy states are silent: no "Saved"/"Saving…"/"Unsaved changes" label.
// Only the failure states are visible, because they are the only way the user
// learns their text is not being saved. This is a deliberate exception.
export function EditorSaveStatus({ status, message, onRetry }: EditorSaveStatusProps) {
  if (status !== "error" && status !== "conflict") {
    return null;
  }
  const isError = status === "error";

  return (
    <div
      aria-live="polite"
      className={cn(
        "flex max-w-full flex-wrap items-center justify-end gap-2 text-right text-sm text-pretty",
        isError ? "text-destructive" : "text-muted-foreground",
      )}
    >
      <span>{statusText(status, message)}</span>
      {isError ? (
        <EditorTextButton
          variant="outline"
          label="Retry"
          icon={<RefreshCw aria-hidden="true" />}
          onClick={onRetry}
        />
      ) : null}
    </div>
  );
}

"use client";

import type { ComponentProps, ReactNode } from "react";
import { Plate, PlateContent } from "platejs/react";

import { TooltipProvider } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

import { LIST_SIBLING_GAP_CLASS } from "../elements/block-list";
import type { EditorValue } from "../../lib/document/editor-value";
import { LinkPreviewProvider } from "../elements/bookmark-element";
import type { LinkPreviewAdapter } from "../../lib/features/editor-bookmark-url";
import { mentionUiPlugin } from "../../lib/plugins/editor-mention";
import { FileUploadScope, UploadEditorLink } from "../elements/file-upload-scope";
import { PageLinkScope } from "../elements/page-link-element";
import { PageLinkPicker } from "../ui/page-link-picker";
import type { PageOpenRequest, PageProvider } from "../../lib/features/editor-page-link";
import { repairMentionInputs, type MentionProvider } from "../../lib/features/editor-mention-node";
import { LinkToolbar } from "../elements/link-element";
import { BookmarkUrlPopover } from "../ui/bookmark-url-popover";
import { LinkPopover } from "../ui/link-popover";
import { MentionScope } from "../elements/mention-element";
import { BlockHandle } from "../ui/block-handle";
import { BlockSelection } from "../ui/block-selection";
import { BlockPlaceholders } from "./block-placeholders";
import { PasteRepairNotice } from "../ui/paste-repair-notice";
import { PasteUrlMenu } from "../ui/paste-url-menu";
import { SelectionToolbar } from "../ui/selection-toolbar";
import { SlashMenu } from "../ui/slash-menu";
import { EmojiSuggest } from "../ui/emoji-suggest";
import { FindBar } from "../ui/find-bar";
import { ShortcutHintsScope } from "../ui/editor-shortcut";
import type { FileUploadAdapter } from "../../lib/features/editor-file-upload";
import { applyUploadResult } from "../../lib/features/editor-media";
import { handleTailMouseDown } from "../../lib/features/editor-tail-click";
import type { EditorFeature } from "../../lib/features/editor-features";
import { useEditorFeatures } from "../../hooks/use-editor-features";

// Mounts its children only while the feature is on. It reads the features, so it is used inside Plate.
function FeatureLayer({ feature, children }: { feature: EditorFeature; children: ReactNode }) {
  const features = useEditorFeatures();
  return features[feature] ? children : null;
}

type EditorSurfaceProps = {
  editor: ComponentProps<typeof Plate>["editor"];
  readOnly: boolean;
  placeholder: string;
  ariaLabel?: string;
  onValueChange?: (value: EditorValue) => void;
  className: string;
  linkPreview?: LinkPreviewAdapter | null;
  mentionProvider?: MentionProvider | null;
  pageProvider?: PageProvider | null;
  onOpenPage?: ((request: PageOpenRequest) => void) | null;
  fileUpload?: FileUploadAdapter | null;
  onInsertedBelow?: (blockId: string) => void;
};

export function EditorSurface({
  editor,
  readOnly,
  placeholder,
  ariaLabel,
  onValueChange,
  className,
  linkPreview = null,
  mentionProvider = null,
  pageProvider = null,
  onOpenPage = null,
  fileUpload = null,
  onInsertedBelow,
}: EditorSurfaceProps) {
  return (
    <TooltipProvider>
      <Plate
        editor={editor}
        readOnly={readOnly}
        onValueChange={({ value }) => {
          const query = editor?.getOption(mentionUiPlugin, "query") ?? "";
          onValueChange?.(repairMentionInputs(value, query).content);
        }}
      >
        <ShortcutHintsScope>
          <MentionScope provider={mentionProvider}>
            <FileUploadScope
              adapter={fileUpload}
              onDone={(blockId, file) => {
                // Refused in read-only mode, and when the block is gone. A block with a file gets the new one (Replace).
                if (editor !== null) {
                  applyUploadResult(editor, blockId, file);
                }
              }}
            >
              <UploadEditorLink />
              <PageLinkScope provider={pageProvider} onOpenPage={onOpenPage}>
                <LinkPreviewProvider adapter={linkPreview}>
                  <PasteRepairNotice />
                  <PasteUrlMenu />
                  <FeatureLayer feature="slashMenu">
                    <SlashMenu />
                  </FeatureLayer>
                  <FeatureLayer feature="emoji">
                    <EmojiSuggest />
                  </FeatureLayer>
                  <LinkToolbar />
                  <LinkPopover />
                  <BookmarkUrlPopover />
                  <FeatureLayer feature="pageLinks">
                    <PageLinkPicker />
                  </FeatureLayer>
                  <FeatureLayer feature="selectionToolbar">
                    <SelectionToolbar />
                  </FeatureLayer>
                  <FeatureLayer feature="find">
                    <FindBar />
                  </FeatureLayer>
                  <PlateContent
                    aria-label={ariaLabel}
                    aria-readonly={readOnly ? true : undefined}
                    placeholder={readOnly ? undefined : placeholder}
                    onMouseDown={(event) =>
                      editor ? handleTailMouseDown(editor, event, readOnly) : undefined
                    }
                    // Margin is between blocks. The first block's top stays put, so the empty-document placeholder stays aligned.
                    // space-y-4 sets margin-block-end inside :where(), so its specificity is 0.
                    // The list rule is one class plus two attribute selectors, and its margin-bottom wins for a list item followed by a list item.
                    className={cn(className, "space-y-4", LIST_SIBLING_GAP_CLASS)}
                    renderPlaceholder={(placeholderProps) => (
                      <span
                        {...placeholderProps.attributes}
                        className="text-muted-foreground pointer-events-none absolute top-0 block w-full select-none"
                        style={{ ...placeholderProps.attributes.style, opacity: 1 }}
                      >
                        {placeholderProps.children}
                      </span>
                    )}
                  />
                  <BlockPlaceholders placeholder={placeholder} />
                  <BlockSelection />
                  <FeatureLayer feature="blockHandle">
                    <BlockHandle onInsertedBelow={onInsertedBelow} />
                  </FeatureLayer>
                </LinkPreviewProvider>
              </PageLinkScope>
            </FileUploadScope>
          </MentionScope>
        </ShortcutHintsScope>
      </Plate>
    </TooltipProvider>
  );
}

"use client";

import { cn } from "@/lib/utils";

import { EditorSurface } from "./editor-surface";
import { DEFAULT_PLACEHOLDER } from "../../lib/features/editor-placeholder";
import type { NotionLikeEditorBlockProps } from "../../notion-like-editor-block";
import { useNotionLikeEditor } from "../../hooks/use-notion-like-editor";

export function MemoryEditor({
  documentId,
  initialValue,
  onChange,
  readOnly = false,
  placeholder = DEFAULT_PLACEHOLDER,
  ariaLabel = "Rich text editor",
  className,
  linkPreview = null,
  mentionProvider = null,
  pageProvider = null,
  onOpenPage,
  fileUpload = null,
  options,
  features,
}: NotionLikeEditorBlockProps) {
  const { editor } = useNotionLikeEditor({ documentId, initialValue, options, features });

  return (
    <div className={cn("bg-background h-full min-h-full w-full min-w-0 px-4", className)}>
      <EditorSurface
        editor={editor}
        readOnly={readOnly}
        placeholder={placeholder}
        ariaLabel={ariaLabel}
        onValueChange={onChange}
        linkPreview={linkPreview}
        mentionProvider={mentionProvider}
        pageProvider={pageProvider}
        onOpenPage={onOpenPage}
        fileUpload={fileUpload}
        className="text-foreground caret-foreground mx-auto min-h-full w-full max-w-[var(--editor-max-width,700px)] py-8 text-base leading-relaxed wrap-break-word outline-none sm:py-12"
      />
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";

import { EditorDocumentSkeleton } from "./editor-document-skeleton";
import { EditorRecoveryNotice } from "./editor-recovery-notice";
import type { EditorPersistenceAdapter } from "../../lib/document/editor-persistence";
import { DEFAULT_PLACEHOLDER } from "../../lib/features/editor-placeholder";
import { resolveEditorOptions } from "../../lib/features/editor-options";
import type { NotionLikeEditorBlockProps } from "../../notion-like-editor-block";
import { ReadyEditor } from "./ready-editor";
import { useEditorDocument } from "../../hooks/use-editor-document";

export function PersistedEditor({
  documentId,
  initialValue,
  onChange,
  readOnly = false,
  placeholder = DEFAULT_PLACEHOLDER,
  ariaLabel = "Rich text editor",
  className,
  adapter,
  linkPreview = null,
  mentionProvider = null,
  pageProvider = null,
  onOpenPage,
  fileUpload = null,
  options,
  features,
}: NotionLikeEditorBlockProps & { adapter: EditorPersistenceAdapter }) {
  const session = useEditorDocument({
    documentId,
    adapter,
    readOnly,
    initialValue,
    debounceMs: resolveEditorOptions(options).autosave.debounceMs,
  });

  return (
    <div className={cn("bg-background h-full min-h-full w-full min-w-0 px-4", className)}>
      {session.phase === "loading" ? <EditorDocumentSkeleton /> : null}
      {session.phase === "recovery" ? (
        <EditorRecoveryNotice
          result={session.result}
          raw={session.raw}
          error={session.error}
          onStartOver={() => {
            void session.startOver();
          }}
        />
      ) : null}
      {session.phase === "ready" ? (
        <ReadyEditor
          documentId={documentId}
          initialValue={session.document.content}
          readOnly={readOnly}
          placeholder={placeholder}
          ariaLabel={ariaLabel}
          onChange={onChange}
          onContentChange={session.onContentChange}
          linkPreview={linkPreview}
          mentionProvider={mentionProvider}
          pageProvider={pageProvider}
          onOpenPage={onOpenPage}
          fileUpload={fileUpload}
          options={options}
          features={features}
          status={session.status}
          message={session.message}
          onRetry={() => {
            void session.retry();
          }}
        />
      ) : null}
    </div>
  );
}

"use client";

import { EditorSaveStatus } from "./editor-save-status";
import { EditorSurface } from "./editor-surface";
import type { AutosaveStatus } from "../../lib/document/editor-autosave";
import type { LinkPreviewAdapter } from "../../lib/features/editor-bookmark-url";
import type { FileUploadAdapter } from "../../lib/features/editor-file-upload";
import type { EditorFeatures } from "../../lib/features/editor-features";
import type { EditorOptions } from "../../lib/features/editor-options";
import type { MentionProvider } from "../../lib/features/editor-mention-node";
import type { PageOpenRequest, PageProvider } from "../../lib/features/editor-page-link";
import type { EditorValue } from "../../lib/document/editor-value";
import { useNotionLikeEditor } from "../../hooks/use-notion-like-editor";

type ReadyEditorProps = {
  documentId: string;
  initialValue: EditorValue;
  readOnly: boolean;
  placeholder: string;
  ariaLabel: string;
  onChange?: (value: EditorValue) => void;
  onContentChange: (value: EditorValue) => void;
  status: AutosaveStatus;
  message?: string;
  onRetry: () => void;
  linkPreview?: LinkPreviewAdapter | null;
  mentionProvider?: MentionProvider | null;
  pageProvider?: PageProvider | null;
  onOpenPage?: (request: PageOpenRequest) => void;
  fileUpload?: FileUploadAdapter | null;
  options?: EditorOptions;
  features?: EditorFeatures;
};

export function ReadyEditor({
  documentId,
  initialValue,
  readOnly,
  placeholder,
  ariaLabel,
  onChange,
  onContentChange,
  status,
  message,
  onRetry,
  linkPreview = null,
  mentionProvider = null,
  pageProvider = null,
  onOpenPage,
  fileUpload = null,
  options,
  features,
}: ReadyEditorProps) {
  const { editor } = useNotionLikeEditor({ documentId, initialValue, options, features });
  // The healthy states render nothing, so the row takes no space. Only the
  // failure notice appears, and it is the only thing above the editor.
  const showNotice = status === "error" || status === "conflict";

  return (
    <div className="mx-auto flex h-full min-h-full w-full max-w-[var(--editor-max-width,700px)] min-w-0 flex-col">
      {showNotice ? (
        <div className="flex justify-end pt-4">
          <EditorSaveStatus status={status} message={message} onRetry={onRetry} />
        </div>
      ) : null}
      <EditorSurface
        editor={editor}
        readOnly={readOnly}
        placeholder={placeholder}
        ariaLabel={ariaLabel}
        onValueChange={(value) => {
          onChange?.(value);
          onContentChange(value);
        }}
        linkPreview={linkPreview}
        mentionProvider={mentionProvider}
        pageProvider={pageProvider}
        onOpenPage={onOpenPage}
        fileUpload={fileUpload}
        className="text-foreground caret-foreground min-h-full w-full min-w-0 py-8 text-base leading-relaxed wrap-break-word outline-none sm:py-12"
      />
    </div>
  );
}

import { lazy, Suspense, useMemo, useRef, useState, type ReactNode } from "react";
import { Music, RefreshCw, VolumeX } from "lucide-react";
import {
  PlateElement,
  useEditorRef,
  useElement,
  useFocused,
  useReadOnly,
  useSelected,
  type PlateElementProps,
} from "platejs/react";

import type { AudioMimeType } from "@vidstack/react";

import { Skeleton } from "@/components/ui/skeleton";
import { cn } from "@/lib/utils";

import { runEditorCommand } from "../../lib/commands/editor-commands";
import { cleanAudioFields } from "../../lib/features/editor-audio";
import {
  removeAudio,
  setAudioCaption,
  setAudioSource,
} from "../../lib/features/editor-audio-commands";
import { displayFileName } from "../../lib/features/editor-file";
import { openMediaSource, selectMediaBlock } from "../../lib/plugins/editor-media-ui";
import { MediaUnavailableRow } from "../static/media-unavailable-row";
import { EditorTextButton } from "../ui/block-toolbar";
import { AudioActionPopover } from "../ui/audio-action-popover";
import { MediaSourcePopover, type MediaSourceConfig } from "../ui/media-source-popover";
import { hrElementClassName } from "./hr-element";
import { IMAGE_CAPTION_CLASS } from "./image-classes";
import { MEDIA_ICON_CLASS } from "./media-classes";
import {
  onPlayerClick,
  onPlayerKeyDown,
  onPlayerKeyUp,
  useMediaCardSelect,
  useMediaHover,
  useMediaElementEvent,
} from "./media-card";
import { MediaCaptionField } from "./media-caption";
import { MediaFailedRow, MediaPlaceholderRow, MediaUploadingRow } from "./media-rows";
import { mediaResolveState, type MediaState } from "./media-state";
import { useResolvedFileUrl, useUploadController, useUploadState } from "./file-upload-scope";

// The player (vidstack with its engines) loads the first time an audio file is
// shown, so a text-only document never downloads it.
const AudioPlayer = lazy(() =>
  import("@/components/audio-player/audio-player").then((module) => ({
    default: module.AudioPlayer,
  })),
);

// What the block shows. An upload state takes priority over the stored file's state.
type AudioPhase = MediaState | "uploading" | "failed";

const AUDIO_SOURCE_CONFIG: MediaSourceConfig = {
  label: "Add an audio file",
  accept: "audio/*",
  uploadLabel: "Upload file",
  embedPlaceholder: "Paste the audio link…",
  embedLabel: "Embed audio",
  linkLabel: "Audio link",
  invalidLinkMessage: "Enter a link that starts with http:// or https://",
};

// The audio block. Its body is one of: an upload row, the empty placeholder, a skeleton while the url
// resolves, the player, or the unavailable row. The player is a control: its clicks and keys belong to
// it, so its actions open on hover or from Enter on the selected block.
export function AudioElement(props: PlateElementProps) {
  const editor = useEditorRef();
  const element = useElement();
  const readOnly = useReadOnly();
  const selected = useSelected();
  const focused = useFocused();
  const { fields } = cleanAudioFields(element);
  const id = typeof element.id === "string" ? element.id : "";
  const controller = useUploadController();
  const upload = useUploadState(id);
  const resolved = useResolvedFileUrl(fields.url);
  const [failedUrl, setFailedUrl] = useState<string | undefined>(undefined);
  const [captionOpen, setCaptionOpen] = useState(false);
  const anchorRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);

  const src = resolved.status === "ready" ? resolved.url : undefined;
  const state = mediaResolveState(fields.url, resolved.status, src, failedUrl);
  const uploading = readOnly ? undefined : upload;
  const phase: AudioPhase = uploading?.status ?? state;
  const editable = !readOnly;
  const showReady = phase === "ready";
  const name = displayFileName(fields);
  const readAnchor = (): HTMLElement | null => anchorRef.current;

  // The player picks its engine from the type it is given, and only the audio types it knows and the browser
  // can play count. A blob url has no extension, and a stored type such as audio/wav is not one of them, so
  // every source takes audio/mpeg. The browser reads the file itself, so the file still plays. The player
  // sends no CORS request, so a link on another site plays without CORS headers.
  const playerSource = useMemo(
    () => (src === undefined ? undefined : { src, type: "audio/mpeg" as AudioMimeType }),
    [src],
  );

  // Mouse-down on the player selects the block. The player is a control.
  useMediaCardSelect(cardRef, id, editable && showReady);
  useMediaElementEvent(cardRef, "error", showReady, () => {
    setFailedUrl(src);
  });
  useMediaHover(
    anchorRef,
    id,
    editable && (phase === "ready" || phase === "unavailable") && !captionOpen,
  );

  function openSource(): void {
    selectMediaBlock(editor, id);
    openMediaSource(editor, id);
  }

  function embedLink(url: string): boolean {
    return runEditorCommand(editor, setAudioSource, { id, file: { url } });
  }

  const audioIcon = <Music aria-hidden="true" className={MEDIA_ICON_CLASS} />;

  let body: ReactNode;
  if (uploading?.status === "uploading") {
    body = (
      <MediaUploadingRow
        name={uploading.name}
        size={uploading.size}
        progress={uploading.progress}
        icon={audioIcon}
        onCancel={() => {
          controller?.cancel(id);
        }}
      />
    );
  } else if (uploading?.status === "failed") {
    body = (
      <MediaFailedRow
        message={uploading.message}
        icon={audioIcon}
        onRetry={() => {
          controller?.retry(id);
        }}
        onRemove={() => {
          runEditorCommand(editor, removeAudio, { id });
        }}
      />
    );
  } else if (state === "empty") {
    body = (
      <MediaPlaceholderRow
        label="Add an audio file"
        icon={audioIcon}
        interactive={editable}
        onActivate={openSource}
      />
    );
  } else if (state === "loading") {
    body = <Skeleton className="h-12 w-full rounded-md" />;
  } else if (state === "unavailable") {
    body = (
      <div className="flex flex-col gap-2">
        <MediaUnavailableRow
          icon={<VolumeX aria-hidden="true" className="size-4 shrink-0" />}
          label="Audio unavailable"
          name={fields.name}
        />
        {editable ? (
          <div className="flex items-center gap-1">
            <EditorTextButton
              label="Replace"
              icon={<RefreshCw aria-hidden="true" />}
              onClick={openSource}
            />
          </div>
        ) : null}
      </div>
    );
  } else {
    const captionNode = readOnly ? (
      fields.caption === undefined ? null : (
        <figcaption className={IMAGE_CAPTION_CLASS}>{fields.caption}</figcaption>
      )
    ) : fields.caption !== undefined || captionOpen ? (
      <MediaCaptionField
        key={fields.caption ?? ""}
        id={id}
        label="Audio caption"
        caption={fields.caption}
        autoFocus={captionOpen}
        onSettled={() => {
          setCaptionOpen(false);
        }}
        onCommit={(text) => {
          runEditorCommand(editor, setAudioCaption, { id, caption: text });
        }}
      />
    ) : null;

    body = (
      <figure className="flex w-full flex-col">
        <div ref={cardRef} data-audio-card="" className="w-full">
          <div
            data-media-control=""
            onClick={onPlayerClick}
            onKeyDown={(event) => {
              onPlayerKeyDown(editor, event);
            }}
            onKeyUp={onPlayerKeyUp}
          >
            {/* While the player loads, a box of the player's own height stands in, so nothing shifts. */}
            <Suspense
              fallback={
                <div
                  aria-hidden="true"
                  className="bg-muted block w-full min-w-0 rounded-full border"
                >
                  <div className="flex h-14 w-full" />
                </div>
              }
            >
              <AudioPlayer title={name} src={playerSource} crossOrigin={null} />
            </Suspense>
          </div>
        </div>
        {captionNode}
      </figure>
    );
  }

  return (
    <PlateElement
      {...props}
      className={cn("relative py-1", hrElementClassName(selected, focused, readOnly))}
    >
      <div
        ref={anchorRef}
        contentEditable={false}
        data-block-handle-anchor=""
        data-media-anchor=""
        data-audio-state={phase}
        className="relative"
      >
        {body}
        {editable ? (
          <>
            <AudioActionPopover
              id={id}
              name={name}
              href={src}
              readAnchor={readAnchor}
              onCaption={() => {
                setCaptionOpen(true);
              }}
              onReplace={openSource}
            />
            <MediaSourcePopover
              blockId={id}
              config={AUDIO_SOURCE_CONFIG}
              readAnchor={readAnchor}
              onEmbed={embedLink}
            />
          </>
        ) : null}
      </div>
      {props.children}
    </PlateElement>
  );
}

export const LIST_SIBLING_GAP_CLASS = "[&>[data-list-item]:has(+[data-list-item])]:mb-1";

export function todoTextId(blockId: string): string {
  return `todo-text-${blockId}`;
}

import { isOrderedList } from "@platejs/list";
import { KEYS } from "platejs";
import {
  PlateElement,
  useReadOnly,
  type PlateElementProps,
  type RenderNodeWrapper,
} from "platejs/react";

import { Checkbox } from "@/components/ui/checkbox";
import { cn } from "@/lib/utils";

import { writeChecked } from "../../lib/commands/editor-commands";
import { LIST_INDENTS, type ListIndent } from "../../lib/document/editor-document-schema";
import { LIST_SIBLING_GAP_CLASS, todoTextId } from "./block-list-metrics";

export { LIST_SIBLING_GAP_CLASS, todoTextId };

// Rendering only. The stored listStyleType stays "disc" or "decimal" at every depth.
const MARKER_CYCLE = {
  disc: ["disc", "circle", "square"],
  decimal: ["decimal", "lower-alpha", "lower-roman"],
} as const;

// Bullets use a 1.5rem step. Numbers use the same step with an extra 1rem so a
// two-digit marker sits in the gutter. list-style-position: outside right-aligns
// the marker to that padding, so 9 and 10 share the same text start.
const LIST_INDENT_CLASS = {
  disc: {
    1: "pl-6",
    2: "pl-12",
    3: "pl-18",
    4: "pl-24",
    5: "pl-30",
    6: "pl-36",
  },
  decimal: {
    1: "pl-10",
    2: "pl-16",
    3: "pl-22",
    4: "pl-28",
    5: "pl-34",
    6: "pl-40",
  },
} as const;

type MarkerStyle = keyof typeof MARKER_CYCLE;

function isMarkerStyle(style: string): style is MarkerStyle {
  return Object.hasOwn(MARKER_CYCLE, style);
}

function isListIndent(indent: number): indent is ListIndent {
  return LIST_INDENTS.some((level) => level === indent);
}

export function listMarker<Style extends MarkerStyle>(
  style: Style,
  indent: number,
): (typeof MARKER_CYCLE)[Style][number] {
  const cycle = MARKER_CYCLE[style];
  const level = indent >= 1 ? indent : 1;
  const marker = cycle[(level - 1) % cycle.length];
  return marker ?? cycle[0];
}

function listIndentClass(style: string, indent: number): string {
  const classes = isMarkerStyle(style) ? LIST_INDENT_CLASS[style] : LIST_INDENT_CLASS.disc;
  if (isListIndent(indent)) {
    return classes[indent];
  }

  return classes[1];
}

function listIndent(element: PlateElementProps["element"]): number {
  return typeof element.indent === "number" ? element.indent : 1;
}

function storedListStyle(element: PlateElementProps["element"]): string {
  return typeof element.listStyleType === "string" ? element.listStyleType : "disc";
}

function blockIdOf(element: PlateElementProps["element"]): string | undefined {
  if (!("id" in element) || typeof element.id !== "string" || element.id.length === 0) {
    return undefined;
  }

  return element.id;
}

function isChecked(element: PlateElementProps["element"]): boolean {
  return "checked" in element && element.checked === true;
}

// useTodoListElement prevents mousedown so the editor selection stays put
// (react/index.js). The checkbox stays focusable for Space and Enter.
function TodoCheck({
  checked,
  editor,
  element,
}: {
  checked: boolean;
  editor: PlateElementProps["editor"];
  element: PlateElementProps["element"];
}) {
  const readOnly = useReadOnly();
  const blockId = blockIdOf(element);

  return (
    <span contentEditable={false} className="absolute top-1 -left-5 flex">
      <Checkbox
        checked={checked}
        disabled={readOnly}
        aria-disabled={readOnly || undefined}
        tabIndex={readOnly ? -1 : undefined}
        className={readOnly ? "pointer-events-none" : undefined}
        aria-labelledby={blockId ? todoTextId(blockId) : undefined}
        aria-label={blockId ? undefined : "To-do"}
        onMouseDown={(event) => {
          event.preventDefault();
        }}
        onCheckedChange={(value) => {
          if (readOnly || value === "indeterminate") {
            return;
          }

          const path = editor.api.findPath(element);
          if (!path) {
            return;
          }

          writeChecked(editor, [path], value);
        }}
      />
    </span>
  );
}

// The gap between items is this sibling rule on the parent. This render reads only its own element.
export function ListParagraph({ attributes, element, ...props }: PlateElementProps) {
  const listStyleType = element.listStyleType;
  const listAttributes =
    typeof listStyleType === "string"
      ? { ...attributes, "data-list-item": listStyleType }
      : attributes;

  return <PlateElement {...props} attributes={listAttributes} element={element} />;
}

// Plate wraps each flat list item on its own. Grouping consecutive items is not a Plate API.
export const BlockList: RenderNodeWrapper = (props) => {
  if (typeof props.element.listStyleType !== "string") {
    return;
  }

  return function List(nodeProps: PlateElementProps) {
    const element = nodeProps.element;
    const stored = storedListStyle(element);
    const indent = listIndent(element);
    if (stored === KEYS.listTodo) {
      const checked = isChecked(element);
      const blockId = blockIdOf(element);

      return (
        <ul className={cn("relative m-0 list-none py-0 pr-0", listIndentClass(stored, indent))}>
          <li className="relative">
            <TodoCheck checked={checked} editor={nodeProps.editor} element={element} />
            <span
              id={blockId ? todoTextId(blockId) : undefined}
              data-checked={checked ? "" : undefined}
              className="data-checked:text-muted-foreground data-checked:line-through"
            >
              {nodeProps.children}
            </span>
          </li>
        </ul>
      );
    }

    const ordered = isOrderedList(element);
    const Tag = ordered ? "ol" : "ul";
    const listStart = element.listStart;
    const marker = isMarkerStyle(stored) ? listMarker(stored, indent) : stored;

    return (
      <Tag
        className={cn("relative m-0 list-outside py-0 pr-0", listIndentClass(stored, indent))}
        style={{ listStyleType: marker }}
        start={ordered && typeof listStart === "number" ? listStart : undefined}
      >
        <li>{nodeProps.children}</li>
      </Tag>
    );
  };
};

