import {
  EQUATION_EMPTY_PLACEHOLDER,
  closeEquationEditor,
  equationPlugin,
  loadKatex,
  openEquationEditor,
  removeEquation,
  renderEquation,
  type EquationRender,
} from "../../lib/features/editor-equation";
import {
