import { footnoteNumber, startsFootnoteRunInEditor } from "../../lib/features/editor-footnote";
import { jumpToFootnoteReference } from "../../lib/plugins/editor-footnote-ui";
import {
  FOOTNOTE_DEF_CLASS,
  FOOTNOTE_DEF_RUN_CLASS,
  FOOTNOTE_NUMBER_CLASS,
  FOOTNOTE_NUMBER_LINK_CLASS,
  FOOTNOTE_TEXT_CLASS,
} from "./footnote-classes";

export function FootnoteDefElement(props: PlateElementProps) {
  const editor = useEditorRef();
  const footnoteId = typeof props.element.footnoteId === "string" ? props.element.footnoteId : "";
  const blockId = typeof props.element.id === "string" ? props.element.id : "";
  const number = useEditorSelector(() => footnoteNumber(editor, footnoteId), [editor, footnoteId]);
  const startsRun = useEditorSelector(
    () => startsFootnoteRunInEditor(editor, blockId),
    [editor, blockId],
  );
  const referenced = number !== undefined;

  // The markers and the anchor go on the root through its attributes, as PlateElement drops other props.
  const attributes = {
    ...props.attributes,
    "data-footnote-def": "",
    "data-footnote-id": footnoteId,
    ...(referenced ? {} : { "data-footnote-unreferenced": "" }),
  };

  return (
    <PlateElement
      {...props}
      attributes={attributes}
      className={cn(FOOTNOTE_DEF_CLASS, startsRun && FOOTNOTE_DEF_RUN_CLASS)}
    >
      {referenced ? (
        <span
          contentEditable={false}
          data-footnote-number=""
          className={cn(FOOTNOTE_NUMBER_CLASS, FOOTNOTE_NUMBER_LINK_CLASS)}
          onClick={(event) => {
            event.stopPropagation();
            event.preventDefault();
            jumpToFootnoteReference(editor, footnoteId);
          }}
        >
          {number}.
        </span>
      ) : (
        <span
          contentEditable={false}
          data-footnote-number=""
          title="Not referenced"
          className={FOOTNOTE_NUMBER_CLASS}
        >
          –
        </span>
      )}
      <div className={FOOTNOTE_TEXT_CLASS}>{props.children}</div>
    </PlateElement>
  );
}

import type { MouseEvent } from "react";
import {
  PlateElement,
  useEditorRef,
  useEditorSelector,
  useFocused,
  useReadOnly,
  useSelected,
  type PlateElementProps,
} from "platejs/react";

import { footnoteIndex, footnoteNumber } from "../../lib/features/editor-footnote";
import {
  jumpToFootnoteDefinition,
  selectMissingFootnoteReference,
} from "../../lib/plugins/editor-footnote-ui";
import { blockSelectionActive } from "../../lib/plugins/editor-block-selection";
import { footnoteRefClassName } from "./footnote-classes";

export function FootnoteRefElement(props: PlateElementProps) {
  const editor = useEditorRef();
  const readOnly = useReadOnly();
  const selected = useSelected();
  const focused = useFocused();
  const footnoteId = typeof props.element.footnoteId === "string" ? props.element.footnoteId : "";
  const number = useEditorSelector(() => footnoteNumber(editor, footnoteId), [editor, footnoteId]);
  const defined = useEditorSelector(
    () => footnoteIndex(editor).definitions.has(footnoteId),
    [editor, footnoteId],
  );
  const shown = defined && number !== undefined;

  // Plain left clicks only. A modifier or a block selection leaves the click to the browser.
  function onClick(event: MouseEvent<HTMLElement>): void {
    if (
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey ||
      blockSelectionActive(editor)
    ) {
      return;
    }

    // Editable would place the caret at the clicked node after this handler, so stop it here.
    event.stopPropagation();
    event.preventDefault();

    if (!shown) {
      const path = editor.api.findPath(props.element);
      if (path !== undefined) {
        selectMissingFootnoteReference(editor, path);
      }
      return;
    }

    jumpToFootnoteDefinition(editor, footnoteId);
  }

  return (
    <PlateElement {...props} as="span" className="inline align-baseline">
      <sup
        contentEditable={false}
        role="link"
        aria-label={shown ? `Footnote ${number}` : "Footnote not found"}
        data-footnote-ref=""
        data-footnote-id={footnoteId}
        data-footnote-missing={shown ? undefined : ""}
        className={footnoteRefClassName(selected && focused && !readOnly)}
        onClick={onClick}
      >
        {shown ? number : "?"}
      </sup>
      {props.children}
    </PlateElement>
  );
}

import { PlateElement, useReadOnly, type PlateElementProps } from "platejs/react";

import { HEADING_STYLES, headingAnchorId, type HeadingTag } from "./heading-styles";

export { HEADING_STYLES, headingAnchorId, type HeadingTag };

function isHeadingTag(type: string): type is HeadingTag {
  return Object.hasOwn(HEADING_STYLES, type);
}

function headingTag(type: string): HeadingTag {
  if (isHeadingTag(type)) {
    return type;
  }

  return "h1";
}

// The DOM id is derived from the block id. It is not stored on the node.
function blockAnchor(element: PlateElementProps["element"]): string | undefined {
  if (!("id" in element)) {
    return undefined;
  }

  const id = element.id;
  return typeof id === "string" && id.length > 0 ? headingAnchorId(id) : undefined;
}

export function HeadingElement({ attributes, element, ...props }: PlateElementProps) {
  const anchorId = blockAnchor(element);
  const tag = headingTag(element.type);
  const readOnly = useReadOnly();
  // A tabindex inside the editable surface takes the click away from Slate.
  // Read-only navigation focuses the heading without moving the selection.
  const anchorAttributes =
    anchorId === undefined
      ? attributes
      : readOnly
        ? { ...attributes, id: anchorId, tabIndex: -1 }
        : { ...attributes, id: anchorId };

  return (
    <PlateElement
      {...props}
      element={element}
      attributes={anchorAttributes}
      as={tag}
      className={HEADING_STYLES[tag]}
    />
  );
}

// A plugin className cannot derive a DOM id from the block id.
const HEADING_SIZE = {
  h1: "text-3xl",
  h2: "text-2xl",
