import { useEffect, useState, type ReactNode } from "react";
import {
  PlateElement,
  useEditorRef,
  useFocused,
  usePluginOption,
  useReadOnly,
  useSelected,
  type PlateElementProps,
} from "platejs/react";

import { cn } from "@/lib/utils";

import { loadKatex } from "../../lib/features/editor-equation";
import {
  INLINE_EQUATION_EMPTY_PLACEHOLDER,
  renderInlineEquation,
} from "../../lib/features/editor-equation-render";
import {
  cancelInlineEquationEditor,
  inlineEquationUiPlugin,
  openInlineEquationEditor,
} from "../../lib/plugins/editor-inline-equation-ui";
import { InlineEquationPopover } from "../ui/inline-equation-popover";
import { INLINE_EQUATION_CLASS } from "./inline-equation-classes";

import "katex/dist/katex.min.css";

type KatexModule = Parameters<typeof renderInlineEquation>[0];

export function InlineEquationElement(props: PlateElementProps) {
  const editor = useEditorRef();
  const readOnly = useReadOnly();
  const selected = useSelected();
  const focused = useFocused();
  const id = typeof props.element.id === "string" ? props.element.id : "";
  const editingId = usePluginOption(inlineEquationUiPlugin, "editingId");
  const draft = usePluginOption(inlineEquationUiPlugin, "draft");
  const stored = typeof props.element.texExpression === "string" ? props.element.texExpression : "";
  // While the popover is open the preview shows the draft. The document keeps the stored source.
  const open = !readOnly && id.length > 0 && editingId === id;
  const expression = open ? draft : stored;
  const [katex, setKatex] = useState<KatexModule | undefined>();

  // A switch to read-only cancels the open draft. The plugin cannot see a read-only prop change
  // (no editor change happens), so this stays here. Removal is handled in the plugin's onChange.
  useEffect(() => {
    if (readOnly && editingId === id) {
      cancelInlineEquationEditor(editor);
    }
  }, [editingId, editor, id, readOnly]);

  useEffect(() => {
    let cancelled = false;
    void loadKatex().then((mod) => {
      if (!cancelled) {
        setKatex(mod);
      }
    });
    return () => {
      cancelled = true;
    };
  }, []);

  let body: ReactNode;
  if (expression.length === 0) {
    body = (
      <span data-inline-equation-empty className="text-muted-foreground">
        {INLINE_EQUATION_EMPTY_PLACEHOLDER}
      </span>
    );
  } else if (!katex) {
    // The raw source keeps the line the same width until KaTeX arrives.
    body = <span className="font-mono">{expression}</span>;
  } else {
    const rendered = renderInlineEquation(katex, expression);
    body = rendered.ok ? (
      <span
        data-inline-equation-math
        className="text-foreground"
        dangerouslySetInnerHTML={{ __html: rendered.html }}
      />
    ) : (
      <span
        data-inline-equation-error
        title={rendered.message}
        className="text-destructive font-mono"
      >
        {expression}
      </span>
    );
  }

  return (
    <PlateElement
      {...props}
      as="span"
      className={cn(
        INLINE_EQUATION_CLASS,
        selected && focused && !readOnly && "bg-muted rounded-sm",
      )}
    >
      <span
        contentEditable={false}
        data-inline-equation=""
        onClick={
          readOnly
            ? undefined
            : () => {
                openInlineEquationEditor(editor, id);
              }
        }
      >
        {body}
      </span>
      {readOnly ? null : <InlineEquationPopover id={id} />}
      {props.children}
    </PlateElement>
  );
}

// Same visual as the Kbd primitive. Inline, so the paragraph line height does not change.
export const KBD_CLASS =
  "border-border bg-muted text-foreground rounded-sm border px-1 font-sans text-[0.85em] align-baseline";

import { useEffect } from "react";
import { ExternalLink, Pencil, Unlink } from "lucide-react";
import { ElementApi, KEYS, type TElement } from "platejs";
import {
  useEditorReadOnly,
  useEditorRef,
  useEditorSelector,
  usePluginOption,
  useReadOnly,
  type PlateElementProps,
} from "platejs/react";

import { runEditorCommand } from "../../lib/commands/editor-commands";
import {
  cancelLinkHoverClose,
  linkUiPlugin,
  openInlineLink,
  openLinkPopover,
  removeInlineLink,
  scheduleLinkHoverClose,
  setLinkHover,
} from "../../lib/plugins/editor-link";
import { isExternalLinkUrl, sanitizeLinkUrl } from "../../lib/features/editor-link-url";
import { Popover, PopoverAnchor, PopoverContent } from "@/components/ui/popover";
import { anchorContext, elementRect, virtualAnchor } from "../ui/anchor-rect";
import { EditorTextButton } from "../ui/block-toolbar";

export function LinkElement({ attributes, children, element }: PlateElementProps) {
  "use no memo";

  const editor = useEditorRef();
  const readOnly = useReadOnly();
  const url = typeof element.url === "string" ? element.url : "";
  const safe = sanitizeLinkUrl(url);
  if (safe === undefined) {
    return <span {...attributes}>{children}</span>;
  }

  const external = isExternalLinkUrl(safe);
  const id = typeof element.id === "string" ? element.id : "";
  const slateClass = typeof attributes.className === "string" ? attributes.className : "";

  return (
    <a
      {...attributes}
      href={safe}
      className={`${slateClass} link-underline`.trim()}
      data-link-url={safe}
      target={external ? "_blank" : undefined}
      rel={external ? "noopener noreferrer nofollow" : undefined}
      onMouseEnter={() => {
        if (id.length > 0) {
          setLinkHover(editor, id);
        }
      }}
      onMouseLeave={(event) => {
        const next = event.relatedTarget;
        if (next instanceof Element && next.closest("[data-link-toolbar]") !== null) {
          cancelLinkHoverClose(editor);
          return;
        }

        if (editor.getOption(linkUiPlugin, "hoverId") === id) {
          scheduleLinkHoverClose(editor);
        }
      }}
      onClick={(event) => {
        if (readOnly) {
          return;
        }

        if (event.metaKey || event.ctrlKey) {
          event.preventDefault();
          window.open(safe, "_blank", "noopener,noreferrer");
          return;
        }

        event.preventDefault();
      }}
    >
      {children}
    </a>
  );
}

export function LinkToolbar() {
  "use no memo";

  const editor = useEditorRef();
  const readOnly = useEditorReadOnly();
  const mode = usePluginOption(linkUiPlugin, "mode");
  const hoverId = usePluginOption(linkUiPlugin, "hoverId");
  const selection = useEditorSelector((current) => current.selection, []);
  const virtualRef = virtualAnchor(
    () => elementRect(linkDomNode(editor, hoverId)),
    () => anchorContext(linkDomNode(editor, hoverId)),
  );
  useEffect(() => {
    if (readOnly || mode !== "closed" || hoverId.length === 0) {
      return;
    }

    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key === "Escape") {
        setLinkHover(editor, "");
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [editor, hoverId, mode, readOnly]);
  if (readOnly || mode !== "closed" || (selection === null && hoverId.length === 0)) {
    return null;
  }

  const entry = selectedOrHoveredLink(editor, hoverId);
  if (entry === undefined) {
    return null;
  }

  const url = typeof entry.url === "string" ? entry.url : "";
  const safe = sanitizeLinkUrl(url);
  if (safe === undefined) {
    return null;
  }

  return (
    <Popover open>
      <PopoverAnchor virtualRef={virtualRef} />
      <PopoverContent
        data-link-toolbar=""
        aria-label="Link actions"
        side="bottom"
        align="start"
        sideOffset={4}
        collisionPadding={8}
        hideWhenDetached
        onOpenAutoFocus={(event) => {
          event.preventDefault();
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
        }}
        className="w-auto max-w-56 gap-1 p-1 text-xs before:absolute before:inset-x-0 before:-top-2 before:h-2"
        onMouseDown={(event) => {
          event.preventDefault();
          event.stopPropagation();
        }}
        onMouseEnter={() => {
          cancelLinkHoverClose(editor);
        }}
        onMouseLeave={(event) => {
          const next = event.relatedTarget;
          if (next instanceof Element && next.closest("[data-link-url]") !== null) {
            cancelLinkHoverClose(editor);
            return;
          }

          scheduleLinkHoverClose(editor);
        }}
        onFocus={() => {
          cancelLinkHoverClose(editor);
        }}
        onBlur={(event) => {
          const next = event.relatedTarget;
          if (next instanceof Element && next.closest("[data-link-toolbar]") !== null) {
            return;
          }

          scheduleLinkHoverClose(editor);
        }}
      >
        <span
          data-link-toolbar-url=""
          className="line-clamp-2 px-1"
          style={{ overflowWrap: "anywhere" }}
        >
          {safe}
        </span>
        <EditorTextButton
          label="Open"
          icon={<ExternalLink aria-hidden="true" />}
          className="w-full justify-start"
          onClick={() => {
            runEditorCommand(editor, openInlineLink, undefined);
          }}
        />
        <EditorTextButton
          label="Edit"
          icon={<Pencil aria-hidden="true" />}
          className="w-full justify-start"
          onClick={() => {
            const hovered = editor.getOption(linkUiPlugin, "hoverId");
            const inside = editor.api.above({
              match: (node) => ElementApi.isElement(node) && node.type === KEYS.link,
            });
            if (inside === undefined && hovered.length > 0) {
              const node = editor.api.node({
                at: [],
                match: (candidate) =>
                  ElementApi.isElement(candidate) &&
                  candidate.type === KEYS.link &&
                  candidate.id === hovered,
              });
              if (node) {
                editor.tf.withoutSaving(() => {
                  editor.tf.select(node[1]);
                });
              }
            }
            openLinkPopover(editor);
          }}
        />
        <EditorTextButton
          variant="destructive"
          label="Remove link"
          icon={<Unlink aria-hidden="true" />}
          className="w-full justify-start"
          onClick={() => {
            runEditorCommand(editor, removeInlineLink, undefined);
          }}
        />
      </PopoverContent>
    </Popover>
  );
}

function linkDomNode(editor: ReturnType<typeof useEditorRef>, hoverId: string): HTMLElement | null {
  const entry = selectedOrHoveredLink(editor, hoverId);
  if (entry === undefined) {
    return null;
  }

  return editor.api.toDOMNode(entry) ?? null;
}

function selectedOrHoveredLink(
  editor: ReturnType<typeof useEditorRef>,
  hoverId: string,
): TElement | undefined {
  const selected = editor.api.above({
    match: (node) => ElementApi.isElement(node) && node.type === KEYS.link,
  });
  if (selected !== undefined && ElementApi.isElement(selected[0])) {
    return selected[0];
  }

  if (hoverId.length === 0) {
    return undefined;
  }

  const hovered = editor.api.node({
    at: [],
    match: (node) => ElementApi.isElement(node) && node.type === KEYS.link && node.id === hoverId,
  });
  if (hovered === undefined || !ElementApi.isElement(hovered[0])) {
    return undefined;
  }

  return hovered[0];
}

import { useEditorRef } from "platejs/react";
import type { SlateEditor } from "platejs";

import { cleanFileText } from "../../lib/features/editor-file-url";
import { MEDIA_CAPTION_MAX } from "../../lib/features/editor-media-layout";
import { findBlockById } from "../../lib/features/editor-synced-block";
import { mediaStringAttr } from "../ui/block-toolbar";
import { MediaTextInput } from "./media-text-input";

function storedMediaCaption(editor: SlateEditor, id: string): string | undefined {
  const entry = findBlockById(editor, id);
  return entry === undefined ? undefined : mediaStringAttr(entry[0], "caption");
}

// The caption under a media block. It is the input restyled as text. It commits on blur and on Enter,
// and Escape restores the stored caption. Keys typed here never reach the editor. `onCommit` writes
// the caption through the block's command.
export function MediaCaptionField({
  id,
  label,
  caption,
  autoFocus,
  onSettled,
  onCommit,
}: {
  id: string;
  label: string;
  caption: string | undefined;
  autoFocus: boolean;
  onSettled: () => void;
  onCommit: (text: string) => void;
}) {
  const editor = useEditorRef();
  return (
    <MediaTextInput
      label={label}
      placeholder="Write a caption…"
      maxLength={MEDIA_CAPTION_MAX}
      initial={caption ?? ""}
      autoFocus={autoFocus}
      className="text-muted-foreground mt-2 h-auto border-0 bg-transparent px-0 text-sm shadow-none focus-visible:ring-0"
      normalize={(text) => cleanFileText(text, MEDIA_CAPTION_MAX) ?? ""}
      readStored={() => storedMediaCaption(editor, id)}
      onCommit={onCommit}
      onSettled={onSettled}
    />
  );
}

import { useEffect, type MouseEvent as ReactMouseEvent, type RefObject } from "react";
import { useEditorReadOnly, useEditorRef, useEditorSelector, usePluginOption } from "platejs/react";

import type { SlateEditor } from "platejs";

import {
  cancelMediaHoverClose,
  cancelMediaOpen,
  clearMediaHover,
  closeMediaActions,
  mediaActionsBlockId,
  mediaHoverBlockId,
  mediaUiPlugin,
  scheduleMediaHover,
  scheduleMediaHoverClose,
  selectMediaBlock,
  selectedMediaId,
  type MediaPoint,
} from "../../lib/plugins/editor-media-ui";

// The pointer position of a mouse event, for the hover timers.
function pointOf(event: { clientX: number; clientY: number }): MediaPoint {
  return { x: event.clientX, y: event.clientY };
}

// Clicks and keys on these controls belong to the control, not to the media card. A player is a control:
// the block marks its player with data-media-control, so every part of it counts, including the sliders
// of the audio player and the video surface.
export function isControlTarget(target: EventTarget | null): boolean {
  return (
    target instanceof Element &&
    target.closest(
      "input, textarea, button, a, video, audio, [role='separator'], [role='slider'], [data-media-control]",
    ) !== null
  );
}

type PlayerKeyEvent = {
  key: string;
  preventDefault: () => void;
  stopPropagation: () => void;
};

// Keys pressed in a player belong to the player, so the editor never sees them. Escape also returns
// focus to the editor.
export function onPlayerKeyDown(editor: SlateEditor, event: PlayerKeyEvent): void {
  event.stopPropagation();
  if (event.key === "Escape") {
    event.preventDefault();
    editor.tf.focus();
  }
}

export function onPlayerKeyUp(event: Pick<PlayerKeyEvent, "stopPropagation">): void {
  event.stopPropagation();
}

// The editor selects a void block when its inner element is clicked. A click on the player stops here,
// so the block under the player keeps the selection it has.
export function onPlayerClick(event: { stopPropagation: () => void }): void {
  event.stopPropagation();
}

// Mouse-down on the card keeps the caret where it is, and a click selects its block. The block is not
// selected on mouse-down: selecting scrolls a row near the bottom of the editor into view, so it moves
// out from under the pointer, and the click is lost. It runs only while `active`, which is true when
// the card is rendered and the editor is writable.
export function useMediaCardSelect(
  cardRef: RefObject<HTMLDivElement | null>,
  id: string,
  active: boolean,
): void {
  const editor = useEditorRef();

  useEffect(() => {
    const node = cardRef.current;
    if (node === null || !active) {
      return;
    }

    // The browser's default mousedown moves the caret to the nearest text. A media card has no text of
    // its own, so the caret would land in a neighbouring block, the card would lose its selection, and
    // its action popover would close. The default is cancelled, so the card keeps the selection.
    const onMouseDown = (event: MouseEvent): void => {
      if (event.button !== 0 || isControlTarget(event.target)) {
        return;
      }

      event.preventDefault();
    };
    const onClick = (event: MouseEvent): void => {
      if (event.button !== 0 || isControlTarget(event.target)) {
        return;
      }

      selectMediaBlock(editor, id);
    };
    node.addEventListener("mousedown", onMouseDown);
    node.addEventListener("click", onClick);
    return () => {
      node.removeEventListener("mousedown", onMouseDown);
      node.removeEventListener("click", onClick);
    };
  }, [editor, id, active, cardRef]);
}

function isMediaElementEvent(target: EventTarget | null): boolean {
  return target instanceof Element && ["AUDIO", "VIDEO", "SOURCE"].includes(target.tagName);
}

// A media element reports its load events on itself, and most of them do not bubble. The player renders
// the element, so React does not hear them. A capture listener on the wrapper around the player does, and
// `onEvent` gets each `type` event from the element or its source while `active` is true.
export function useMediaElementEvent(
  wrapperRef: RefObject<HTMLElement | null>,
  type: "error" | "loadedmetadata",
  active: boolean,
  onEvent: (event: Event) => void,
): void {
  useEffect(() => {
    const node = wrapperRef.current;
    if (node === null || !active) {
      return;
    }

    const onMediaEvent = (event: Event): void => {
      if (isMediaElementEvent(event.target)) {
        onEvent(event);
      }
    };
    node.addEventListener(type, onMediaEvent, true);
    return () => {
      node.removeEventListener(type, onMediaEvent, true);
    };
  }, [wrapperRef, type, active, onEvent]);
}

// The action popover of a media block closes when its block loses the selection, when the editor
// turns read-only, and when the block is removed. `open` says whether this block's popover is open.
export function useMediaActionsLifecycle(id: string, open: boolean): void {
  const editor = useEditorRef();
  const readOnly = useEditorReadOnly();
  const selection = useEditorSelector((current) => current.selection, []);

  useEffect(() => {
    if (!open) {
      return;
    }

    if (readOnly || selection === null || selectedMediaId(editor) !== id) {
      closeMediaActions(editor);
    }
  }, [editor, id, open, readOnly, selection]);

  useEffect(
    () => () => {
      if (mediaActionsBlockId(editor) === id) {
        closeMediaActions(editor);
      }
    },
    [editor, id],
  );
}

// The action toolbar of a media block opens while the pointer rests on the block, and closes once the
// pointer has left both the block and the toolbar. `active` says the block has actions now. A press
// that began elsewhere does not open it; the release over the block does.
export function useMediaHover(
  anchorRef: RefObject<HTMLDivElement | null>,
  id: string,
  active: boolean,
): void {
  const editor = useEditorRef();

  useEffect(() => {
    const node = anchorRef.current;
    if (node === null || !active) {
      return;
    }

    const onEnter = (event: MouseEvent): void => {
      if (event.buttons !== 0) {
        return;
      }

      // Back over the block that is hovered, so its pending close is dropped.
      if (mediaHoverBlockId(editor) === id) {
        cancelMediaHoverClose(editor);
      }
      scheduleMediaHover(editor, id, pointOf(event));
    };
    // The browser can report the toolbar's enter before this leave, so a leave into the toolbar is ignored.
    const onLeave = (event: MouseEvent): void => {
      cancelMediaOpen(editor, id);
      const next = event.relatedTarget;
      if (next instanceof Element && next.closest("[data-media-actions]") !== null) {
        return;
      }

      scheduleMediaHoverClose(editor, pointOf(event));
    };
    // Moving over the block restarts the rest, so the open uses the pointer's latest position.
    const onMove = (event: MouseEvent): void => {
      if (event.buttons === 0 && mediaHoverBlockId(editor) !== id) {
        scheduleMediaHover(editor, id, pointOf(event));
      }
    };
    const onDown = (): void => {
      cancelMediaOpen(editor, id);
    };
    const onUp = (event: MouseEvent): void => {
      scheduleMediaHover(editor, id, pointOf(event));
    };
    node.addEventListener("mouseenter", onEnter);
    node.addEventListener("mouseleave", onLeave);
    node.addEventListener("mousemove", onMove);
    node.addEventListener("mousedown", onDown);
    node.addEventListener("mouseup", onUp);
    return () => {
      node.removeEventListener("mouseenter", onEnter);
      node.removeEventListener("mouseleave", onLeave);
      node.removeEventListener("mousemove", onMove);
      node.removeEventListener("mousedown", onDown);
      node.removeEventListener("mouseup", onUp);
      cancelMediaOpen(editor, id);
    };
  }, [editor, id, active, anchorRef]);

  // Leaving the active state, or the block, closes its hover toolbar.
  useEffect(
    () => () => {
      if (mediaHoverBlockId(editor) === id) {
        clearMediaHover(editor);
      }
    },
    [editor, id, active],
  );
}

// Whether a block's action toolbar is open. `explicit` is true when a click or a key opened it. That
// toolbar takes focus and stays open until it is dismissed. A hover toolbar takes neither.
export function useMediaActionsOpen(id: string): { open: boolean; explicit: boolean } {
  const actions = usePluginOption(mediaUiPlugin, "actions");
  const hovered = usePluginOption(mediaUiPlugin, "hoverId");
  const explicit = id.length > 0 && actions === id;
  return { open: explicit || (id.length > 0 && hovered === id), explicit };
}

// The hover handlers of an action toolbar. The toolbar is a portal, so the pointer crosses the gap to
// it: entering it cancels a pending close, and leaving it schedules one.
export function mediaActionsHoverProps(editor: SlateEditor) {
  return {
    onMouseEnter: () => {
      cancelMediaHoverClose(editor);
    },
    onMouseLeave: (event: ReactMouseEvent<HTMLElement>) => {
      scheduleMediaHoverClose(editor, pointOf(event));
    },
  };
}

