import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import {
  PlateElement,
  useEditorRef,
  useElement,
  useFocused,
  useReadOnly,
  useSelected,
  type PlateElementProps,
} from "platejs/react";

import { cn } from "@/lib/utils";

import {
  cleanPageLinkTitle,
  isStoredPageId,
  pageLinkDisplayTitle,
  sanitizePageEntity,
  storedPageLinkKind,
  type PageEntity,
  type PageLinkStatus,
  type PageOpenRequest,
  type PageProvider,
} from "../../lib/features/editor-page-link";
import {
  attachPageLinkHost,
  openPageLink,
  setPageLinkStatus,
} from "../../lib/plugins/editor-page-link";
import { PageLinkBody } from "../static/page-link-body";
import { hrElementClassName } from "./hr-element";
import { PAGE_LINK_ROW_CLASS } from "./page-link-classes";

const PAGE_LINK_RESOLVE_TIMEOUT_MS = 5000;

let resolveTimeoutMs = PAGE_LINK_RESOLVE_TIMEOUT_MS;

export function setPageLinkResolveTimeoutMs(ms: number): () => void {
  const previous = resolveTimeoutMs;
  resolveTimeoutMs = ms;
  return () => {
    resolveTimeoutMs = previous;
  };
}

type PageLinkScopeValue = {
  provider: PageProvider | null;
  onOpenPage: ((request: PageOpenRequest) => void) | null;
};

const PageLinkScopeContext = createContext<PageLinkScopeValue>({
  provider: null,
  onOpenPage: null,
});

export function PageLinkScope({
  provider,
  onOpenPage,
  children,
}: PageLinkScopeValue & { children: ReactNode }) {
  const editor = useEditorRef();
  // During render, not in an effect: child effects run first, and a row resolves in that same commit.
  attachPageLinkHost(editor, { provider, onOpenPage });
  const value = useMemo(() => ({ provider, onOpenPage }), [provider, onOpenPage]);
  return <PageLinkScopeContext.Provider value={value}>{children}</PageLinkScopeContext.Provider>;
}

type Outcome =
  { status: "ok"; page: PageEntity } | { status: "missing" | "denied" | "unavailable" };

type Resolved = { pageId: string; outcome: Outcome };

const LABELS: Partial<Record<PageLinkStatus, string>> = {
  missing: "Page not found",
  denied: "No access",
  unavailable: "Unavailable",
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

// The provider is untrusted, so anything but a well-formed answer is unavailable.
function outcomeOf(resolution: unknown): Outcome {
  if (!isRecord(resolution)) {
    return { status: "unavailable" };
  }

  if (resolution.status === "missing" || resolution.status === "denied") {
    return { status: resolution.status };
  }

  const page = resolution.page;
  if (resolution.status === "ok" && isRecord(page) && typeof page.title === "string") {
    return {
      status: "ok",
      page: sanitizePageEntity({
        pageId: typeof page.pageId === "string" ? page.pageId : "",
        title: page.title,
        icon: typeof page.icon === "string" ? page.icon : undefined,
      }),
    };
  }

  return { status: "unavailable" };
}

export function PageLinkElement(props: PlateElementProps) {
  const editor = useEditorRef();
  const element = useElement();
  const readOnly = useReadOnly();
  const selected = useSelected();
  const focused = useFocused();
  const { provider, onOpenPage } = useContext(PageLinkScopeContext);
  const id = typeof element.id === "string" ? element.id : "";
  const pageId = typeof element.pageId === "string" ? element.pageId : "";
  const pageIdValid = isStoredPageId(pageId);
  const kind = storedPageLinkKind(element.kind);
  const storedTitle = typeof element.title === "string" ? cleanPageLinkTitle(element.title) : "";
  const rowRef = useRef<HTMLDivElement>(null);
  const [resolved, setResolved] = useState<Resolved | undefined>(undefined);

  // Resolving reads only. It never writes the document, so it adds no history entry.
  useEffect(() => {
    if (provider === null || !pageIdValid) {
      return;
    }

    const controller = new AbortController();
    let active = true;
    const timer = setTimeout(() => {
      controller.abort();
    }, resolveTimeoutMs);

    const finish = (outcome: Outcome): void => {
      if (!active) {
        return;
      }

      clearTimeout(timer);
      setResolved({ pageId, outcome });
    };

    controller.signal.addEventListener("abort", () => {
      finish({ status: "unavailable" });
    });

    let pending: Promise<unknown>;
    try {
      pending = provider.resolve(pageId, controller.signal);
    } catch {
      pending = Promise.reject(new Error("resolve threw"));
    }

    void pending.then(
      (resolution) => {
        if (controller.signal.aborted) {
          return;
        }

        finish(outcomeOf(resolution));
      },
      () => {
        finish({ status: "unavailable" });
      },
    );

    return () => {
      active = false;
      clearTimeout(timer);
      controller.abort();
    };
  }, [provider, pageId, pageIdValid]);

  const current = resolved?.pageId === pageId ? resolved.outcome : undefined;
  let status: PageLinkStatus;
  if (!pageIdValid) {
    status = "missing";
  } else if (provider === null) {
    status = "fallback";
  } else if (current === undefined) {
    status = "loading";
  } else {
    status = current.status;
  }

  useEffect(() => {
    setPageLinkStatus(editor, id, status);
    return () => {
      setPageLinkStatus(editor, id, undefined);
    };
  }, [editor, id, status]);

  useEffect(() => {
    const node = rowRef.current;
    if (!node || readOnly) {
      return;
    }

    // A plain click selects the block and never opens the page in edit mode.
    const onMouseDown = (event: MouseEvent): void => {
      if (event.button !== 0) {
        return;
      }

      const path = editor.api.findPath(element);
      if (path) {
        editor.tf.select(path);
      }
    };
    node.addEventListener("mousedown", onMouseDown);
    return () => {
      node.removeEventListener("mousedown", onMouseDown);
    };
  }, [editor, element, readOnly]);

  const page = current?.status === "ok" ? current.page : undefined;
  const shownTitle = page !== undefined ? page.title : storedTitle;
  const canOpen = onOpenPage !== null && status !== "missing" && status !== "denied";
  const request: PageOpenRequest = { pageId, kind };

  return (
    <PlateElement {...props} className="relative py-1">
      <div className="relative" contentEditable={false} data-block-handle-anchor="">
        <div
          ref={rowRef}
          role={readOnly ? "link" : undefined}
          tabIndex={readOnly ? 0 : undefined}
          aria-label={readOnly ? pageLinkDisplayTitle(shownTitle) : undefined}
          aria-disabled={readOnly && !canOpen ? true : undefined}
          data-page-link=""
          data-page-id={pageId}
          data-page-kind={kind}
          data-page-status={status}
          className={cn(PAGE_LINK_ROW_CLASS, hrElementClassName(selected, focused, readOnly))}
          onClick={(event) => {
            if (!readOnly && !event.metaKey && !event.ctrlKey) {
              return;
            }

            event.preventDefault();
            openPageLink(editor, request, id);
          }}
          onKeyDown={(event) => {
            if (!readOnly || (event.key !== "Enter" && event.key !== " ")) {
              return;
            }

            event.preventDefault();
            openPageLink(editor, request, id);
          }}
        >
          <PageLinkBody
            icon={page?.icon}
            kind={kind}
            title={shownTitle}
            muted={status === "missing" || status === "denied"}
            label={LABELS[status]}
          />
        </div>
      </div>
      {props.children}
    </PlateElement>
  );
}

import { createElement, type ReactNode } from "react";
import { Copy, CornerUpLeft, Trash2 } from "lucide-react";
import { ElementApi, type Descendant, type SlateEditor, type TElement, type TText } from "platejs";
import { pipeRenderLeafStatic } from "platejs/static";
import {
  ElementProvider,
  PlateElement,
  useEditorRef,
  useEditorSelector,
  useFocused,
  useReadOnly,
  useSelected,
  type PlateElementProps,
} from "platejs/react";

import { cn } from "@/lib/utils";

import {
  SYNCED_CONVERT_LABEL,
  SYNCED_FROM_ABOVE,
  SYNCED_FROM_BELOW,
  SYNCED_GO_LABEL,
  SYNCED_INVALID_PLACEHOLDER,
  SYNCED_MISSING_PLACEHOLDER,
  SYNCED_REF_KEY,
  SYNCED_REMOVE_LABEL,
  convertSyncedRefAt,
  findBlockById,
  goToSyncedOriginal,
  removeSyncedRefAt,
  syncedDirection,
  syncedTargetStatus,
  type SyncedDirection,
  type SyncedTargetStatus,
} from "../../lib/features/editor-synced-block";
import { isStoredSyncedTargetId } from "../../lib/document/editor-document-schema";
import { BLOCK_SELECTED_CLASS } from "./hr-element";
import { MEDIA_TOOLBAR_CLASS, EditorTextButton, keepMediaSelection } from "../ui/block-toolbar";
import { ScrollFadeArea } from "../ui/editor-scroll";

// PlateStatic (static-CTmHK15f.js:599) assigns `editor.children = value`, so it
// cannot render a target inside the live editor. pluginRenderElementStatic
// (static-CTmHK15f.js:352) also skips ElementProvider, which the react renderer
// wraps at react/index.js:1799. useElement() would then see this reference.
// A nested editor has no media runtime and its own history. This walker reuses
// the main editor's element and leaf components instead.

const PREVIEW_ROOT = 1_000_000;

type PreviewProps = {
  attributes: PlateElementProps["attributes"];
  element: TElement;
  children?: ReactNode;
  path: number[];
  editor: SlateEditor;
};

type ElementRenderer = (props: PreviewProps) => ReactNode;

type PreviewView = {
  status: SyncedTargetStatus;
  node: TElement | undefined;
  direction: SyncedDirection | undefined;
};

function isText(node: Descendant): node is TText {
  return !ElementApi.isElement(node);
}

function isElementRenderer(value: unknown): value is ElementRenderer {
  return typeof value === "function";
}

function elementRenderer(editor: SlateEditor, type: string): ElementRenderer | undefined {
  // React editors index element components by node type. The static isElement
  // cache is not built for them (withSlate pluginCache.node has types, not isElement).
  const types: unknown = editor.meta.pluginCache.node.types;
  const key =
    typeof types === "object" && types !== null && type in types
      ? Reflect.get(types, type)
      : undefined;
  if (typeof key !== "string") {
    return undefined;
  }

  const component: unknown = editor.meta.components?.[key];
  if (isElementRenderer(component)) {
    return component;
  }

  const render: unknown = editor.getPlugin({ key }).render?.node;
  return isElementRenderer(render) ? render : undefined;
}

function previewTree(node: Descendant): Descendant {
  if (!ElementApi.isElement(node)) {
    return node;
  }

  const children = node.children.map((child) => previewTree(child));
  const copy: TElement = { ...node, children };
  if (
    (node.type === "h1" || node.type === "h2" || node.type === "h3") &&
    typeof node.id === "string" &&
    node.id.length > 0
  ) {
    copy.id = `preview-${node.id}`;
  }

  return copy;
}

function previewAttributes(path: number[]): PlateElementProps["attributes"] {
  return {
    "data-slate-node": "element",
    ref: () => undefined,
    "data-preview-path": path.join("."),
  };
}

function PreviewText({ editor, text, path }: { editor: SlateEditor; text: TText; path: number[] }) {
  const renderLeaf = pipeRenderLeafStatic(editor);
  const shown = text.text.length === 0 ? "\uFEFF" : text.text;
  return renderLeaf({
    attributes: { "data-slate-leaf": true },
    children: shown,
    leaf: text,
    text,
    path,
  });
}

function PreviewNode({
  editor,
  node,
  path,
}: {
  editor: SlateEditor;
  node: Descendant;
  path: number[];
}) {
  if (isText(node)) {
    return <PreviewText editor={editor} text={node} path={path} />;
  }

  if (node.type === SYNCED_REF_KEY) {
    return <p>{SYNCED_INVALID_PLACEHOLDER}</p>;
  }

  const children = node.children.map((child, index) => (
    <PreviewNode
      key={path.concat(index).join(".")}
      editor={editor}
      node={child}
      path={path.concat(index)}
    />
  ));
  const renderer = elementRenderer(editor, node.type);

  return (
    <ElementProvider element={node} entry={[node, path]} path={path}>
      {renderer === undefined ? (
        <div>{children}</div>
      ) : (
        createElement(
          renderer,
          {
            attributes: previewAttributes(path),
            editor,
            element: node,
            path,
          },
          children,
        )
      )}
    </ElementProvider>
  );
}

function SyncedPreview({ node }: { node: TElement }) {
  "use no memo";
  const editor = useEditorRef();
  const preview = previewTree(node);
  if (!ElementApi.isElement(preview)) {
    return null;
  }

  return <PreviewNode editor={editor} node={preview} path={[PREVIEW_ROOT]} />;
}

function targetId(element: PlateElementProps["element"]): string {
  return typeof element.targetBlockId === "string" ? element.targetBlockId : "";
}

function refLabel(direction: SyncedDirection | undefined): string | undefined {
  if (direction === "above") {
    return SYNCED_FROM_ABOVE;
  }

  if (direction === "below") {
    return SYNCED_FROM_BELOW;
  }

  return undefined;
}

export function SyncedRefElement(props: PlateElementProps) {
  "use no memo";
  const editor = useEditorRef();
  const readOnly = useReadOnly();
  const selected = useSelected();
  const focused = useFocused();
  const storedTargetId = targetId(props.element);
  const view = useEditorSelector((): PreviewView => {
    const refPath = editor.api.findPath(props.element);
    const found = isStoredSyncedTargetId(storedTargetId)
      ? findBlockById(editor, storedTargetId)
      : undefined;
    const status = syncedTargetStatus(found?.[0], storedTargetId);
    const direction =
      status === "live" && found && refPath ? syncedDirection(found[1], refPath) : undefined;
    return { status, node: found?.[0], direction };
  }, [storedTargetId, props.element]);
  const label = refLabel(view.direction);
  const path = editor.api.findPath(props.element);

  function selectRef(): void {
    if (!path) {
      return;
    }

    const start = editor.api.start(path);
    if (!start) {
      return;
    }

    editor.tf.withoutSaving(() => {
      editor.tf.select(start);
    });
  }

  function runOnRef(run: (refPath: number[]) => void): void {
    if (!path || readOnly) {
      return;
    }

    editor.tf.withNewBatch(() => {
      run(path);
    });
    editor.tf.setSplittingOnce(true);
  }

  return (
    <PlateElement
      {...props}
      className={cn(
        "group border-border relative my-2 max-w-full min-w-0 rounded-md border-s ps-3",
        selected && focused && !readOnly && BLOCK_SELECTED_CLASS,
      )}
    >
      <div
        contentEditable={false}
        data-synced-ref=""
        data-synced-state={view.status}
        onMouseDown={selectRef}
      >
        {label === undefined ? null : (
          <p data-synced-label className="text-muted-foreground text-xs">
            {label}
          </p>
        )}
        {view.status === "live" && view.node ? (
          <ScrollFadeArea
            data-synced-preview
            orientation="horizontal"
            className="pointer-events-none max-w-full min-w-0"
          >
            <SyncedPreview node={view.node} />
          </ScrollFadeArea>
        ) : (
          <p className="text-muted-foreground text-sm">
            {view.status === "missing" ? SYNCED_MISSING_PLACEHOLDER : SYNCED_INVALID_PLACEHOLDER}
          </p>
        )}
        {readOnly ? null : (
          <div
            data-synced-toolbar
            className={cn(MEDIA_TOOLBAR_CLASS, selected && "pointer-events-auto opacity-100")}
            onMouseDown={(event) => {
              // Selecting the void here replaces these buttons before click fires.
              event.stopPropagation();
            }}
            onClick={(event) => {
              event.stopPropagation();
            }}
          >
            {view.status === "live" ? (
              <EditorTextButton
                label={SYNCED_GO_LABEL}
                icon={<CornerUpLeft aria-hidden="true" />}
                onMouseDown={keepMediaSelection}
                onClick={() => {
                  if (path) {
                    goToSyncedOriginal(editor, path);
                  }
                }}
              />
            ) : null}
            {view.status === "live" ? (
              <EditorTextButton
                label={SYNCED_CONVERT_LABEL}
                icon={<Copy aria-hidden="true" />}
                onMouseDown={keepMediaSelection}
                onClick={() => {
                  runOnRef((refPath) => {
                    convertSyncedRefAt(editor, refPath);
                  });
                }}
              />
            ) : null}
            <EditorTextButton
              variant="destructive"
              label={SYNCED_REMOVE_LABEL}
              icon={<Trash2 aria-hidden="true" />}
              onMouseDown={keepMediaSelection}
              onClick={() => {
                runOnRef((refPath) => {
                  removeSyncedRefAt(editor, refPath);
                });
              }}
            />
          </div>
        )}
      </div>
    </PlateElement>
  );
}

import {
  createContext,
  useContext,
  useLayoutEffect,
  useRef,
  useState,
  type Dispatch,
  type SetStateAction,
} from "react";
import { ElementApi, KEYS, type TElement } from "platejs";
import {
  PlateElement,
  useEditorRef,
  useEditorSelector,
  useElement,
  useReadOnly,
  type PlateElementProps,
} from "platejs/react";
import { useIsCellSelected, useSelectedCells } from "@platejs/table/react";

import { Table, TableBody, TableCell, TableHead, TableRow } from "@/components/ui/table";
import { cn } from "@/lib/utils";

import { runEditorCommand } from "../../lib/commands/editor-commands";
import { setTableColumnWidth } from "../../lib/commands/editor-table-commands";
import {
  tableCoverage,
  TABLE_MAX_COLUMN_WIDTH,
  TABLE_MIN_COLUMN_WIDTH,
} from "../../lib/features/editor-table-grid";
import { TableControls } from "../ui/table-controls";

// The slate table node stays a PlateElement div. Table renders the real table
// plus its scroll container, so the node attributes cannot sit on the table.
// Each grid line is drawn once: the first row and column add the outer top and
// left, and every cell draws its right and bottom edge. TableHead has no background.
const CELL_BORDER_CLASS = "min-w-12 border-r border-b border-border";

type CellGridEdge = { row: number; column: number };

type SelectionBox = { left: number; top: number; width: number; height: number };

type TableResizeContextValue = {
  readOnly: boolean;
  startWidth: (column: number) => number;
  commitWidth: (column: number, width: number | null) => void;
  setPreview: Dispatch<SetStateAction<ReadonlyMap<number, number>>>;
  gridEdges: ReadonlyMap<string, CellGridEdge>;
};

const TableResizeContext = createContext<TableResizeContextValue | null>(null);

const FALLBACK_COLUMN_WIDTH = 160;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function nodeRecord(node: TElement): Record<string, unknown> {
  const record: Record<string, unknown> = {};
  for (const key of Object.keys(node)) {
    record[key] = node[key];
  }

  return record;
}

function storedWidths(node: TElement, columnCount: number): (number | null)[] {
  const raw = node.colSizes;
  const source = Array.isArray(raw) ? raw : [];
  return Array.from({ length: columnCount }, (_, index) => {
    const value = source[index];
    return typeof value === "number" ? value : null;
  });
}

function spanAttribute(value: unknown): number | undefined {
  return typeof value === "number" && Number.isInteger(value) && value > 1 ? value : undefined;
}

function clampWidth(width: number): number {
  return Math.min(TABLE_MAX_COLUMN_WIDTH, Math.max(TABLE_MIN_COLUMN_WIDTH, Math.round(width)));
}

function columnRightEdges(table: HTMLTableElement): number[] {
  const rows = Array.from(table.rows);
  const coverage: (HTMLTableCellElement | undefined)[][] = [];
  for (const row of rows) {
    const line: (HTMLTableCellElement | undefined)[] = [];
    coverage.push(line);
    let column = 0;
    for (const cell of Array.from(row.cells)) {
      while (line[column]) {
        column += 1;
      }

      const colSpan = cell.colSpan || 1;
      const rowSpan = cell.rowSpan || 1;
      for (let rowOffset = 0; rowOffset < rowSpan; rowOffset += 1) {
        const target = coverage[coverage.length - 1 + rowOffset] ?? [];
        coverage[coverage.length - 1 + rowOffset] = target;
        for (let columnOffset = 0; columnOffset < colSpan; columnOffset += 1) {
          target[column + columnOffset] = cell;
        }
      }
      column += colSpan;
    }
  }

  const columnCount = coverage.reduce((count, line) => Math.max(count, line.length), 0);
  const origin = table.getBoundingClientRect().left;
  const edges: number[] = [];
  for (let column = 0; column < columnCount; column += 1) {
    let edge = 0;
    for (const line of coverage) {
      const cell = line[column];
      if (!cell || (column > 0 && line[column - 1] === cell)) {
        continue;
      }

      if ((cell.colSpan || 1) !== 1) {
        continue;
      }

      edge = cell.getBoundingClientRect().right - origin;
      break;
    }
    edges.push(edge);
  }

  return edges;
}

function columnPixelWidths(table: HTMLTableElement): number[] {
  const edges = columnRightEdges(table);
  return edges.map((edge, index) => {
    const previous = index === 0 ? 0 : (edges[index - 1] ?? 0);
    return edge > previous ? edge - previous : 0;
  });
}

function cellGridEdges(element: TElement): ReadonlyMap<string, CellGridEdge> {
  const map = new Map<string, CellGridEdge>();
  for (const covered of tableCoverage(nodeRecord(element)).cells) {
    const rowNode = element.children[covered.rowIndex];
    if (!ElementApi.isElement(rowNode)) {
      continue;
    }

    const cellNode = rowNode.children[covered.cellIndex];
    if (!ElementApi.isElement(cellNode) || typeof cellNode.id !== "string") {
      continue;
    }

    map.set(cellNode.id, { row: covered.row, column: covered.column });
  }

  return map;
}

function sameBox(current: SelectionBox | null, next: SelectionBox | null): boolean {
  if (current === next) {
    return true;
  }
  if (!current || !next) {
    return false;
  }

  return (
    current.left === next.left &&
    current.top === next.top &&
    current.width === next.width &&
    current.height === next.height
  );
}

function borderWidth(element: Element, side: "top" | "right" | "bottom" | "left"): number {
  const parsed = Number.parseFloat(
    getComputedStyle(element).getPropertyValue(`border-${side}-width`),
  );
  return Number.isFinite(parsed) ? parsed : 0;
}

// A cell draws its own right and bottom line. The left and top lines belong to
// the neighbour, unless this cell is in the first column or first row.
function outsideGridLine(cell: HTMLElement, edge: "left" | "top"): number {
  if (borderWidth(cell, edge) > 0) {
    return 0;
  }

  const rect = cell.getBoundingClientRect();
  const table = cell.closest("table");
  if (!table) {
    return 0;
  }

  const neighborSide = edge === "left" ? "right" : "bottom";
  for (const other of table.querySelectorAll<HTMLElement>("td, th")) {
    if (other === cell) {
      continue;
    }

    const otherRect = other.getBoundingClientRect();
    const touches =
      edge === "left"
        ? Math.abs(otherRect.right - rect.left) <= 0.6 &&
          otherRect.bottom > rect.top + 0.5 &&
          otherRect.top < rect.bottom - 0.5
        : Math.abs(otherRect.bottom - rect.top) <= 0.6 &&
          otherRect.right > rect.left + 0.5 &&
          otherRect.left < rect.right - 0.5;
    if (touches) {
      return borderWidth(other, neighborSide);
    }
  }

  return 0;
}

function selectionBox(plate: HTMLElement): SelectionBox | null {
  const cells = plate.querySelectorAll<HTMLElement>("[data-cell-selected='true']");
  if (cells.length === 0) {
    return null;
  }

  const plateRect = plate.getBoundingClientRect();
  let left = Number.POSITIVE_INFINITY;
  let top = Number.POSITIVE_INFINITY;
  let right = Number.NEGATIVE_INFINITY;
  let bottom = Number.NEGATIVE_INFINITY;
  for (const cell of cells) {
    const rect = cell.getBoundingClientRect();
    left = Math.min(left, rect.left);
    top = Math.min(top, rect.top);
    right = Math.max(right, rect.right);
    bottom = Math.max(bottom, rect.bottom);
  }

  let extraLeft = 0;
  let extraTop = 0;
  for (const cell of cells) {
    const rect = cell.getBoundingClientRect();
    if (Math.abs(rect.left - left) <= 0.6) {
      extraLeft = Math.max(extraLeft, outsideGridLine(cell, "left"));
    }
    if (Math.abs(rect.top - top) <= 0.6) {
      extraTop = Math.max(extraTop, outsideGridLine(cell, "top"));
    }
  }
  left -= extraLeft;
  top -= extraTop;

  const scroller = plate.querySelector("[data-slot='table-container']");
  if (scroller instanceof HTMLElement) {
    const view = scroller.getBoundingClientRect();
    left = Math.max(left, view.left);
    top = Math.max(top, view.top);
    right = Math.min(right, view.left + scroller.clientWidth);
    bottom = Math.min(bottom, view.top + scroller.clientHeight);
  }

  const width = right - left;
  const height = bottom - top;
  if (!(width > 0) || !(height > 0)) {
    return null;
  }

  return { left: left - plateRect.left, top: top - plateRect.top, width, height };
}

function TableSelectionFrame({ watch, multi }: { watch: unknown; multi: boolean }) {
  const frameRef = useRef<HTMLDivElement>(null);
  const [box, setBox] = useState<SelectionBox | null>(null);
  const selectionKey = useEditorSelector((instance) => {
    const range = instance.selection;
    if (!range) {
      return "";
    }

    return `${range.anchor.path.join(".")}:${range.anchor.offset}-${range.focus.path.join(".")}:${range.focus.offset}`;
  }, []);

  useLayoutEffect(() => {
    const frame = frameRef.current;
    const plate = frame?.parentElement;
    if (!frame || !plate) {
      return;
    }

    const place = (): void => {
      const next = selectionBox(plate);
      setBox((current) => (sameBox(current, next) ? current : next));
    };
    place();

    const scroller = plate.querySelector("[data-slot='table-container']");
    const table = plate.querySelector("table");
    const Observer = globalThis.ResizeObserver;
    const observer = typeof Observer === "function" ? new Observer(place) : undefined;
    if (observer) {
      if (table) {
        observer.observe(table);
      }
      if (scroller instanceof HTMLElement) {
        observer.observe(scroller);
      }
    }
    scroller?.addEventListener("scroll", place, { passive: true });
    window.addEventListener("resize", place);

    return () => {
      observer?.disconnect();
      scroller?.removeEventListener("scroll", place);
      window.removeEventListener("resize", place);
    };
  }, [selectionKey, watch]);

  return (
    <div
      ref={frameRef}
      contentEditable={false}
      data-table-selection={multi ? "range" : "cell"}
      aria-hidden="true"
      hidden={box === null}
      // The box already covers the 1px grid line. A 1px border sits on that line,
      // with the same outer halo as a focused input. A range keeps the 2px stroke.
      className={cn(
        "pointer-events-none absolute box-border border-solid",
        multi ? "border-primary border-2" : "border-ring ring-ring/50 border ring-3",
      )}
      style={
        box === null
          ? undefined
          : { left: box.left, top: box.top, width: box.width, height: box.height }
      }
    />
  );
}

export function TableElement(props: PlateElementProps) {
  const editor = useEditorRef();
  const element = useElement();
  const readOnly = useReadOnly();
  const path = editor.api.findPath(element);
  const tableRef = useRef<HTMLTableElement>(null);
  const coverage = tableCoverage(nodeRecord(element));
  const widths = storedWidths(element, coverage.columnCount);
  const [preview, setPreview] = useState<ReadonlyMap<number, number>>(() => new Map());
  const [edges, setEdges] = useState<number[]>([]);
  useSelectedCells();

  useLayoutEffect(() => {
    const table = tableRef.current;
    if (!table) {
      return;
    }

    setEdges(columnRightEdges(table));
  }, [element, preview, readOnly]);

  const displayed = widths.map((width, index) => preview.get(index) ?? width);
  const explicit = displayed.every((width) => typeof width === "number");
  const tableWidth = explicit
    ? displayed.reduce<number>((sum, width) => sum + (width ?? 0), 0)
    : undefined;
  const gridEdges = cellGridEdges(element);
  const tableId = typeof element.id === "string" ? element.id : "";
  const multi = useEditorSelector(
    (instance) => {
      const selection = instance.selection;
      if (!selection || instance.api.isCollapsed() || tableId.length === 0) {
        return false;
      }

      let count = 0;
      for (const [node, cellPath] of instance.api.nodes({
        at: selection,
        match: (candidate) =>
          ElementApi.isElement(candidate) &&
          (candidate.type === KEYS.td || candidate.type === KEYS.th),
      })) {
        if (!ElementApi.isElement(node) || cellPath.length < 2) {
          continue;
        }

        const tableNode = instance.api.node(cellPath.slice(0, -2))?.[0];
        if (!ElementApi.isElement(tableNode) || tableNode.id !== tableId) {
          continue;
        }

        count += 1;
        if (count > 1) {
          return true;
        }
      }

      return false;
    },
    [tableId],
  );

  function measureFit(): { tablePath: number[]; available: number; widths: number[] } | undefined {
    const table = tableRef.current;
    if (!table || path === undefined) {
      return undefined;
    }

    const container = table.parentElement;
    if (!(container instanceof HTMLElement)) {
      return undefined;
    }

    const live = columnPixelWidths(table);
    const measured = widths.map((width, index) => {
      if (typeof width === "number" && Number.isFinite(width) && width > 0) {
        return width;
      }

      const pixel = live[index] ?? 0;
      return pixel > 0 ? Math.round(pixel) : TABLE_MIN_COLUMN_WIDTH;
    });

    return {
      tablePath: path,
      available: container.clientWidth,
      widths: measured,
    };
  }

  function commitWidth(column: number, width: number | null): void {
    if (path === undefined) {
      return;
    }

    runEditorCommand(editor, setTableColumnWidth, { tablePath: path, column, width });
  }

  function startWidth(column: number): number {
    const node = path === undefined ? undefined : editor.api.node(path)?.[0];
    const raw = isRecord(node) && Array.isArray(node.colSizes) ? node.colSizes[column] : undefined;
    if (typeof raw === "number" && Number.isFinite(raw)) {
      return raw;
    }

    const previous = column === 0 ? 0 : edges[column - 1];
    const edge = edges[column];
    if (previous !== undefined && edge !== undefined && edge > previous) {
      return edge - previous;
    }

    return FALLBACK_COLUMN_WIDTH;
  }

  return (
    <PlateElement
      {...props}
      className={cn(
        "group [&_[data-slot=table-container]]:scroll-fade-x relative my-2 max-w-full",
        multi && "[&_*::selection]:bg-transparent [&_*::selection]:text-current",
      )}
    >
      {readOnly || path === undefined ? null : (
        <TableControls element={element} measureFit={measureFit} />
      )}
      <TableResizeContext.Provider
        value={{ readOnly, startWidth, commitWidth, setPreview, gridEdges }}
      >
        <Table
          ref={tableRef}
          className="border-separate border-spacing-0"
          style={
            tableWidth === undefined
              ? undefined
              : { width: tableWidth, minWidth: tableWidth, borderCollapse: "separate" }
          }
        >
          <colgroup>
            {displayed.map((width, index) => (
              <col key={index} style={typeof width === "number" ? { width } : undefined} />
            ))}
          </colgroup>
          <TableBody>{props.children}</TableBody>
        </Table>
      </TableResizeContext.Provider>
      {readOnly ? null : <TableSelectionFrame watch={preview} multi={multi} />}
    </PlateElement>
  );
}

function columnInFirstRow(
  editor: ReturnType<typeof useEditorRef>,
  element: TElement,
): number | undefined {
  const path = editor.api.findPath(element);
  if (!path || path.length < 3) {
    return undefined;
  }

  const rowIndex = path[path.length - 2];
  const cellIndex = path[path.length - 1];
  if (rowIndex !== 0 || typeof cellIndex !== "number") {
    return undefined;
  }

  const rowEntry = editor.api.node(path.slice(0, -1));
  if (rowEntry === undefined || !ElementApi.isElement(rowEntry[0])) {
    return undefined;
  }

  const ownSpan = spanAttribute(element.colSpan) ?? 1;
  if (ownSpan !== 1) {
    return undefined;
  }

  let column = 0;
  for (let index = 0; index < cellIndex; index += 1) {
    const child = rowEntry[0].children[index];
    const span =
      typeof child === "object" &&
      child !== null &&
      "colSpan" in child &&
      typeof child.colSpan === "number"
        ? child.colSpan
        : 1;
    column += span > 1 ? span : 1;
  }

  return column;
}

function ColumnResizeHandle({ column }: { column: number }) {
  const resize = useContext(TableResizeContext);
  if (!resize || resize.readOnly) {
    return null;
  }

  const current = resize.startWidth(column);
  return (
    <div
      role="separator"
      aria-orientation="vertical"
      aria-valuemin={TABLE_MIN_COLUMN_WIDTH}
      aria-valuemax={TABLE_MAX_COLUMN_WIDTH}
      aria-valuenow={current}
      aria-label={`Resize column ${column + 1}`}
      tabIndex={0}
      contentEditable={false}
      data-column={column}
      className="absolute inset-y-0 right-0 z-10 w-2 cursor-col-resize"
      onPointerDown={(event) => {
        if (event.button !== 0) {
          return;
        }

        event.preventDefault();
        event.stopPropagation();
        const handle = event.currentTarget;
        const originX = event.clientX;
        const initial = resize.startWidth(column);
        let latest = initial;
        const move = (pointer: PointerEvent): void => {
          latest = clampWidth(initial + pointer.clientX - originX);
          resize.setPreview((currentPreview) => {
            const next = new Map(currentPreview);
            next.set(column, latest);
            return next;
          });
        };
        const stop = (): void => {
          handle.removeEventListener("pointermove", move);
          handle.removeEventListener("pointerup", stop);
          handle.removeEventListener("pointercancel", stop);
          resize.setPreview((currentPreview) => {
            const next = new Map(currentPreview);
            next.delete(column);
            return next;
          });
          if (latest !== initial) {
            resize.commitWidth(column, latest);
          }
        };
        handle.addEventListener("pointermove", move);
        handle.addEventListener("pointerup", stop);
        handle.addEventListener("pointercancel", stop);
        if (event.isTrusted) {
          handle.setPointerCapture(event.pointerId);
        }
      }}
      onDoubleClick={(event) => {
        event.preventDefault();
        event.stopPropagation();
        resize.commitWidth(column, null);
      }}
      onKeyDown={(event) => {
        if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") {
          return;
        }

        event.preventDefault();
        event.stopPropagation();
        const delta = event.key === "ArrowRight" ? 8 : -8;
        resize.commitWidth(column, clampWidth(resize.startWidth(column) + delta));
      }}
    />
  );
}

export function TableRowElement({ attributes, children }: PlateElementProps) {
  const { className, ...slateProps } = attributes;
  return (
    <TableRow
      {...slateProps}
      className={cn(
        className,
        "border-0 bg-transparent hover:bg-transparent data-[state=selected]:bg-transparent",
      )}
    >
      {children}
    </TableRow>
  );
}

export function TableCellElement(props: PlateElementProps) {
  const editor = useEditorRef();
  const readOnly = useReadOnly();
  const selected = useIsCellSelected(props.element);
  const cellId = typeof props.element.id === "string" ? props.element.id : "";
  const editing = useEditorSelector(
    (instance) => {
      const selection = instance.selection;
      if (!selection || cellId.length === 0) {
        return false;
      }

      const match = instance.api.above({
        at: selection,
        match: (node) => ElementApi.isElement(node) && node.id === cellId,
      });
      return match !== undefined;
    },
    [cellId],
  );
  const active = selected || editing;
  const header = props.element.type === KEYS.th;
  const colSpan = spanAttribute(props.element.colSpan);
  const rowSpan = spanAttribute(props.element.rowSpan);
  const column = readOnly ? undefined : columnInFirstRow(editor, props.element);
  const edge = useContext(TableResizeContext)?.gridEdges.get(cellId);
  const { className, ...slateProps } = props.attributes;
  const cellClass = cn(
    className,
    CELL_BORDER_CLASS,
    edge?.column === 0 && "border-l",
    edge?.row === 0 && "border-t",
    column !== undefined && "relative",
  );
  const handle = column === undefined ? null : <ColumnResizeHandle column={column} />;

  if (header) {
    return (
      <TableHead
        {...slateProps}
        colSpan={colSpan}
        rowSpan={rowSpan}
        className={cellClass}
        data-cell-selected={active ? "true" : undefined}
      >
        {props.children}
        {handle}
      </TableHead>
    );
  }

  return (
    <TableCell
      {...slateProps}
      colSpan={colSpan}
      rowSpan={rowSpan}
      className={cellClass}
      data-cell-selected={active ? "true" : undefined}
    >
      {props.children}
      {handle}
    </TableCell>
  );
}

import { type KeyboardEvent as ReactKeyboardEvent } from "react";
import {
  PlateElement,
  useEditorRef,
  useEditorSelector,
  useFocused,
  useReadOnly,
  useSelected,
  type PlateElementProps,
} from "platejs/react";

import { ChevronDown, Trash2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";

import {
  TOC_EMPTY_PLACEHOLDER,
  TOC_UNTITLED,
  activateTocEntry,
  isTocDepth,
  removeToc,
  setTocDepth,
  shallowestDepth,
  storedTocDepth,
  tocEntries,
  type TocEntry,
} from "../../lib/features/editor-toc";
import { BLOCK_SELECTED_CLASS } from "./hr-element";
import { MENU_ITEM_ACTIVE_CHECKED } from "../../lib/features/editor-menu-active";
import {
  MEDIA_TOOLBAR_CLASS,
  EditorMenuTrigger,
  EditorTextButton,
  keepMediaSelection,
} from "../ui/block-toolbar";

const TOC_DEPTH_LABEL = {
  1: "H1 only",
  2: "H1–H2",
  3: "H1–H3",
} as const;

const TOC_INDENT_CLASS = ["ps-0", "ps-4", "ps-8"] as const;

function indentClass(level: number): string {
  if (level === 1) {
    return TOC_INDENT_CLASS[1];
  }
  if (level >= 2) {
    return TOC_INDENT_CLASS[2];
  }
  return TOC_INDENT_CLASS[0];
}

export function TocElement(props: PlateElementProps) {
  const editor = useEditorRef();
  const readOnly = useReadOnly();
  const selected = useSelected();
  const focused = useFocused();
  const depth = storedTocDepth(props.element);
  const depthLabel = isTocDepth(depth) ? TOC_DEPTH_LABEL[depth] : TOC_DEPTH_LABEL[3];
  const entries = useEditorSelector(() => tocEntries(editor, depth), [depth]);
  const shallowest = shallowestDepth(entries);
  const path = editor.api.findPath(props.element);

  function runOnToc(run: () => void): void {
    if (!path) {
      return;
    }
    const start = editor.api.start(path);
    editor.tf.withNewBatch(() => {
      if (start) {
        editor.tf.select(start);
      }
      run();
    });
    editor.tf.setSplittingOnce(true);
  }

  function activate(entry: TocEntry): void {
    activateTocEntry(editor, entry, readOnly);
  }

  function onKeyDown(event: ReactKeyboardEvent<HTMLButtonElement>, entry: TocEntry): void {
    if (event.key !== "Enter" && event.key !== " ") {
      return;
    }
    event.preventDefault();
    activate(entry);
  }

  return (
    <PlateElement
      {...props}
      className={cn(
        "group relative my-2 rounded-md",
        selected && focused && !readOnly && BLOCK_SELECTED_CLASS,
      )}
    >
      <div contentEditable={false}>
        {entries.length === 0 ? (
          readOnly ? null : (
            <p data-toc-empty className="text-muted-foreground text-sm">
              {TOC_EMPTY_PLACEHOLDER}
            </p>
          )
        ) : (
          <nav aria-label="Table of contents" data-toc-depth={depth}>
            <ol className="m-0 list-none space-y-1 p-0">
              {entries.map((entry) => {
                const untitled = entry.title.length === 0;
                const label = untitled ? TOC_UNTITLED : entry.title;
                return (
                  <li key={entry.id} className={indentClass(entry.depth - shallowest)}>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      aria-label={label}
                      data-toc-target={entry.id}
                      data-toc-indent={entry.depth - shallowest}
                      data-toc-untitled={untitled ? "true" : undefined}
                      className={cn(
                        "h-auto w-full justify-start px-1 whitespace-normal",
                        untitled && "text-muted-foreground",
                      )}
                      onMouseDown={keepMediaSelection}
                      onClick={() => {
                        activate(entry);
                      }}
                      onKeyDown={(event) => {
                        onKeyDown(event, entry);
                      }}
                    >
                      {label}
                    </Button>
                  </li>
                );
              })}
            </ol>
          </nav>
        )}
        {readOnly || !path ? null : (
          <div
            data-toc-toolbar
            className={cn(MEDIA_TOOLBAR_CLASS, selected && "pointer-events-auto opacity-100")}
          >
            <DropdownMenu modal={false}>
              <EditorMenuTrigger
                label="Table of contents depth"
                accessibleName={`Table of contents depth, current: ${depthLabel}`}
                text={depthLabel}
                icon={<ChevronDown aria-hidden="true" />}
                onMouseDown={keepMediaSelection}
              />
              <DropdownMenuContent
                align="end"
                collisionPadding={8}
                hideWhenDetached
                onCloseAutoFocus={(event) => {
                  event.preventDefault();
                }}
              >
                <DropdownMenuRadioGroup
                  value={String(isTocDepth(depth) ? depth : 3)}
                  onValueChange={(value) => {
                    if (value !== "1" && value !== "2" && value !== "3") {
                      return;
                    }
                    const choice = Number(value) as 1 | 2 | 3;
                    runOnToc(() => {
                      setTocDepth(editor, path, choice);
                    });
                  }}
                >
                  {([1, 2, 3] as const).map((choice) => (
                    <DropdownMenuRadioItem
                      key={choice}
                      value={String(choice)}
                      className={MENU_ITEM_ACTIVE_CHECKED}
                      onMouseDown={keepMediaSelection}
                    >
                      {TOC_DEPTH_LABEL[choice]}
                    </DropdownMenuRadioItem>
                  ))}
                </DropdownMenuRadioGroup>
              </DropdownMenuContent>
            </DropdownMenu>
            <EditorTextButton
              variant="destructive"
              label="Delete"
              icon={<Trash2 aria-hidden="true" />}
              onMouseDown={keepMediaSelection}
              onClick={() => {
                runOnToc(() => {
                  removeToc(editor, path);
                });
              }}
            />
          </div>
        )}
      </div>
      {props.children}
    </PlateElement>
  );
}

