const ADD_LABEL = "Add block below";

// The two handle controls are plain buttons, not the shadcn Button, so they can
// be 24 px tall. Colours mirror the shadcn ghost variant.
const HANDLE_BUTTON_CLASS =
  "inline-flex shrink-0 items-center justify-center rounded-sm p-0 text-muted-foreground outline-none transition-colors hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring dark:hover:bg-muted/50 aria-expanded:bg-muted aria-expanded:text-foreground data-[state=open]:bg-muted data-[state=open]:text-foreground dark:aria-expanded:bg-muted/50 dark:data-[state=open]:bg-muted/50";

type BlockHandleProps = {
  onInsertedBelow?: (blockId: string) => void;
};

function keepEditorSelection(event: { preventDefault: () => void }): void {
  event.preventDefault();
}

// renderToString throws on a portal. The menu stays mounted on the client even
// when the grip is not painted, so a shortcut can open it.
function useClientPortal(): boolean {
  return useSyncExternalStore(
    () => () => undefined,
    () => true,
    () => false,
  );
}

export function BlockHandle({ onInsertedBelow }: BlockHandleProps) {
  const client = useClientPortal();
  // A read-only editor paints no handle, so it should not mount the drag layer
  // (and its body portal) either.
  const readOnly = useEditorReadOnly();
  const apiRef = useRef<BlockDragHandlers | null>(null);
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: DRAG_ACTIVATION_DISTANCE_PX },
    }),
  );
  const onDragStart = useCallback((event: DragStartEvent) => {
    apiRef.current?.onDragStart(event);
  }, []);
  const onDragMove = useCallback((event: DragMoveEvent) => {
    apiRef.current?.onDragMove(event);
  }, []);
  const onDragEnd = useCallback((event: DragEndEvent) => {
    apiRef.current?.onDragEnd(event);
  }, []);
  const onDragCancel = useCallback((event: DragCancelEvent) => {
    void event;
    apiRef.current?.onDragCancel();
  }, []);

  if (!client || readOnly) {
    return null;
  }

  return createPortal(
    <DndContext
      sensors={sensors}
      autoScroll
      onDragStart={onDragStart}
      onDragMove={onDragMove}
      onDragEnd={onDragEnd}
      onDragCancel={onDragCancel}
    >
      <BlockHandleContent onInsertedBelow={onInsertedBelow} apiRef={apiRef} />
    </DndContext>,
    document.body,
  );
}

function BlockHandleContent({
  onInsertedBelow,
  apiRef,
}: {
  onInsertedBelow?: (blockId: string) => void;
  apiRef: RefObject<BlockDragHandlers | null>;
}) {
  const editor = useEditorRef();
  const handle = useBlockHandle({ onInsertedBelow });
  const {
    paint,
    setMeasuredSize,
    shown,
    suppressed,
    onHandleFocus,
    onHandleBlur,
    holdMenu,
    rehover,
  } = handle;
  const rowRef = useRef<HTMLDivElement>(null);
  const gripRef = useRef<HTMLButtonElement>(null);
  const savedSelection = useRef(editor.selection);
  const [addOpen, setAddOpen] = useState(false);
  // The block the Add menu was opened for. The insert must land below it even
  // when the pointer sits over another row as the item is chosen.
  const addTarget = useRef<BlockHandleHit | null>(null);
  const openMenu = useRef<(target: BlockHandleHit) => void>(() => undefined);
  const closeMenu = useRef<() => void>(() => undefined);
  const bindOpener = useCallback((open: (target: BlockHandleHit) => void) => {
    openMenu.current = open;
  }, []);
  const bindCloser = useCallback((close: () => void) => {
    closeMenu.current = close;
  }, []);
  const drag = useBlockDrag({
    target: paint?.target ?? null,
    closeMenu: () => closeMenu.current(),
    clearPointer: handle.clearPointer,
    rehover: handle.rehover,
    apiRef,
  });

  useLayoutEffect(() => {
    const row = rowRef.current;
    if (!row) {
      return;
    }
    setMeasuredSize(row.offsetWidth, row.offsetHeight);
  }, [paint, setMeasuredSize]);

  // The Add menu owns the handle while it is open, through the same lock the
  // block menu uses. The target is frozen at open so the pointer cannot move
  // the handle (and its anchored menu) as it sweeps the rows the menu covers.
  const openAddMenu = useCallback(() => {
    const target = paint?.target ?? null;
    addTarget.current = target;
    savedSelection.current = editor.selection;
    if (target) {
      holdMenu(target.id);
    }
    setAddOpen(true);
  }, [editor, holdMenu, paint]);

  const closeAddMenu = useCallback(() => {
    setAddOpen(false);
    holdMenu(null);
    // Resolve the handle from where the pointer is now, by the normal hover
    // rule. A block below may have moved, so a cached paint would be stale.
    rehover();
  }, [holdMenu, rehover]);

  // Closing the menu releases the lock. If its block leaves the frame the
  // handle unmounts first; the lock has to drop with it so the two hide
  // together instead of the handle staying locked with no anchor to follow.
  useLayoutEffect(() => {
    if (addOpen && !paint) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- detach teardown, not a render loop
      closeAddMenu();
    }
  }, [addOpen, closeAddMenu, paint]);

  const chooseAdd = useCallback(
    (item: BlockPickerItem) => {
      const path = addTarget.current?.path;
      if (!path) {
        return;
      }
      const insertedId = insertPickedBlock(editor, path, item);
      if (insertedId !== null) {
        onInsertedBelow?.(insertedId);
      }
    },
    [editor, onInsertedBelow],
  );

  if (suppressed) {
    return null;
  }

  const addItems = paint ? blockPickerAddItems(editor, paint.target.path) : [];
  const menu = (
    <BlockMenu
      gripRef={gripRef}
      holdMenu={handle.holdMenu}
      bindOpener={bindOpener}
      bindCloser={bindCloser}
    />
  );
  // Stop at the block edge. A pixel inside the box covers a control that sits
  // on that edge, such as the toggle chevron.
  const gutterWidth = paint ? Math.max(0, paint.blockLeft - (paint.left + paint.width)) : 0;
  const gutterTop = paint ? paint.blockTop - paint.top : 0;
  const gutterHeight = paint ? Math.max(paint.height, paint.blockBottom - paint.blockTop) : 0;
  const visible = shown && !drag.dragging;

  return (
    <>
      {paint ? (
        <div
          data-block-handle=""
          data-block-handle-for={paint.target.id}
          data-visible={visible ? "true" : "false"}
          className={cn(
            "fixed z-20 transition-opacity duration-150 ease-out motion-reduce:transition-none",
            visible ? "pointer-events-auto opacity-100" : "pointer-events-none opacity-0",
            "[@media(hover:none)]:hidden",
          )}
          style={{ top: paint.top, left: paint.left }}
          onFocus={onHandleFocus}
          onBlur={(event) => {
            onHandleBlur(event.relatedTarget);
          }}
        >
          <div ref={rowRef} className="flex items-center gap-0">
            <DropdownMenu
              open={addOpen}
              modal={false}
              onOpenChange={(open) => {
                if (open) {
                  openAddMenu();
                } else {
                  closeAddMenu();
                }
              }}
            >
              <Tooltip>
                <TooltipTrigger asChild>
                  <DropdownMenuTrigger asChild>
                    <button
                      type="button"
                      className={cn(HANDLE_BUTTON_CLASS, "size-6")}
                      aria-label={ADD_LABEL}
                      data-block-handle-add=""
                      onMouseDown={keepEditorSelection}
                    >
                      <Plus aria-hidden="true" className="size-4" />
                    </button>
                  </DropdownMenuTrigger>
                </TooltipTrigger>
                <TooltipContent data-block-handle-tooltip="">{ADD_LABEL}</TooltipContent>
              </Tooltip>
              <DropdownMenuContent
                data-block-add-menu=""
                align="start"
                side="bottom"
                sideOffset={4}
                collisionPadding={8}
                hideWhenDetached
                className="max-h-[var(--radix-dropdown-menu-content-available-height)] w-64 overflow-hidden"
                onCloseAutoFocus={(event) => {
                  event.preventDefault();
                  const selection = savedSelection.current;
                  retainScroll(() => {
                    editor.tf.withoutSaving(() => {
                      editor.tf.focus();
                      if (selection) {
                        editor.tf.deselect();
                        editor.tf.select(selection);
                      }
                    });
                  });
                }}
              >
                <MenuScrollArea>
                  <BlockPickerGroups items={addItems} onChoose={chooseAdd} />
                </MenuScrollArea>
              </DropdownMenuContent>
            </DropdownMenu>
            <Tooltip>
              <TooltipTrigger asChild>
                <button
                  ref={(node) => {
                    gripRef.current = node;
                    drag.setNodeRef(node);
                  }}
                  type="button"
                  className={cn(
                    HANDLE_BUTTON_CLASS,
                    "h-6 w-[18px] cursor-grab active:cursor-grabbing",
                  )}
                  aria-label={BLOCK_MENU_GRIP_LABEL}
                  data-block-handle-grip=""
                  {...drag.attributes}
                  {...drag.listeners}
                  onMouseDown={keepEditorSelection}
                  onClick={(event) => {
                    if (drag.consumeClick()) {
                      return;
                    }
                    if (!paint) {
                      return;
                    }
                    const selected = blockSelectionIds(editor);
                    if (event.shiftKey && selected.length > 0) {
                      const anchor = selected[0] ?? paint.target.id;
                      setBlockSelection(editor, [anchor, paint.target.id], {
                        anchorId: anchor,
                        focusId: paint.target.id,
                      });
                      return;
                    }
                    if (!selected.includes(paint.target.id) || selected.length < 2) {
                      setBlockSelection(editor, [paint.target.id]);
                    }
                    openMenu.current(paint.target);
                  }}
                >
                  <GripVertical aria-hidden="true" className="size-4" />
                </button>
              </TooltipTrigger>
              <TooltipContent data-block-handle-tooltip="">
                <ShortcutLabel label={BLOCK_MENU_GRIP_LABEL} shortcut="blockMenu" />
              </TooltipContent>
            </Tooltip>
          </div>
          <div
            data-block-handle-gutter=""
            aria-hidden="true"
            className="absolute"
            style={{ left: "100%", top: gutterTop, width: gutterWidth, height: gutterHeight }}
          />
        </div>
      ) : null}
      {drag.indicator ? <BlockDropIndicator line={drag.indicator} /> : null}
      {/* No drop animation: on release the preview disappears at once and the
          block is simply at its new position (no fly-back to the old slot). */}
      <DragOverlay dropAnimation={null}>{drag.overlay}</DragOverlay>
      {menu}
    </>
  );
}

