type AnchorBox = {
  top: number;
  left: number;
  width: number;
  height: number;
};

type MenuSession = {
  target: BlockHandleHit;
  anchor: AnchorBox;
};

const CONTROL_SELECTOR =
  "button, input, textarea, select, [role='menu'], [role='menuitem'], [data-block-handle], [data-block-menu], [data-block-menu-portal]";

const PAGE_CONTROL_SELECTOR =
  "a, button, input, textarea, select, summary, [role='tab'], [role='button']";

function cloneRange(selection: SlateEditor["selection"]) {
  if (!selection) {
    return null;
  }
  return {
    anchor: { path: [...selection.anchor.path], offset: selection.anchor.offset },
    focus: { path: [...selection.focus.path], offset: selection.focus.offset },
  };
}

function editableOf(editor: SlateEditor): HTMLElement | null {
  const first = editor.children[0];
  if (!first || !ElementApi.isElement(first)) {
    return null;
  }
  const dom = editor.api.toDOMNode(first);
  const editable = dom?.closest("[data-slate-editor]");
  return editable instanceof HTMLElement ? editable : null;
}

function boxOf(rect: DOMRect): AnchorBox {
  return { top: rect.top, left: rect.left, width: rect.width, height: rect.height };
}

function blockBox(editor: SlateEditor, id: string): AnchorBox | null {
  const entry = findBlockById(editor, id);
  if (!entry) {
    return null;
  }
  const dom = editor.api.toDOMNode(entry[0]);
  if (!(dom instanceof HTMLElement)) {
    return null;
  }
  const rect = dom.getBoundingClientRect();
  if (rect.width <= 0 && rect.height <= 0) {
    return null;
  }
  return { top: rect.top, left: rect.left, width: 0, height: 0 };
}

function slateLink(editor: SlateEditor, target: Element): boolean {
  let current: Element | null = target;
  while (current) {
    if (current.tagName === "A" || current.hasAttribute("data-link-url")) {
      return true;
    }
    if (current.hasAttribute("data-slate-node")) {
      const slate = editor.api.toSlateNode(current);
      if (ElementApi.isElement(slate) && slate.type === KEYS.link) {
        return true;
      }
    }
    current = current.parentElement;
  }
  return false;
}

function contextProbe(editor: SlateEditor, event: MouseEvent): NativeMenuProbe {
  const target = event.target instanceof Element ? event.target : null;
  const slateSelection = editor.selection;
  const selectionCollapsed = slateSelection === null || RangeApi.isCollapsed(slateSelection);
  let pointInsideSelection = false;
  const domSelection = window.getSelection();
  if (
    !selectionCollapsed &&
    domSelection !== null &&
    !domSelection.isCollapsed &&
    domSelection.rangeCount > 0 &&
    event.target instanceof Node
  ) {
    pointInsideSelection = domSelection.getRangeAt(0).intersectsNode(event.target);
  }

  const code = target?.closest("code") ?? null;

  return {
    selectionCollapsed,
    pointInsideSelection,
    insideLink: target !== null && slateLink(editor, target),
    insideTableCell: target?.closest("td, th") !== null,
    insideCodeText: code !== null && code.parentElement?.tagName === "PRE",
    insideControl: target?.closest(CONTROL_SELECTOR) !== null,
    hasBlockTarget: target !== null && blockHandleTarget(chainFromDom(editor, target)) !== null,
  };
}

function MenuHint({ text }: { text: string | undefined }) {
  return text === undefined ? null : <DropdownMenuShortcut>{text}</DropdownMenuShortcut>;
}

function BlockMenuItems({ target, onActed }: { target: BlockHandleHit; onActed: () => void }) {
  const editor = useEditorRef();
  const platform = useShortcutPlatform();
  const located = findBlockById(editor, target.id);
  const path = located?.[1];
  const turnItems = path === undefined ? [] : blockPickerTurnItems(editor, path);
  const currentTurn = turnItems.find((item) => item.checked)?.id ?? "";

  function turn(item: BlockPickerItem): void {
    if (!path || item.kind === undefined) {
      return;
    }
    onActed();
    runEditorCommand(editor, turnBlockInto, { path: [...path], kind: item.kind });
  }

  function duplicate(): void {
    if (multi) {
      onActed();
      duplicateSelectedBlocks(editor);
      return;
    }
    if (!path) {
      return;
    }
    onActed();
    runEditorCommand(editor, duplicateBlock, { path: [...path] });
  }

  function remove(): void {
    if (multi) {
      onActed();
      deleteSelectedBlocks(editor);
      return;
    }
    if (!path) {
      return;
    }
    onActed();
    runEditorCommand(editor, deleteBlock, { path: [...path] });
  }

  function move(direction: "up" | "down"): void {
    if (multi) {
      onActed();
      const scroll = captureEditorScroll();
      moveSelectedBlocks(editor, direction);
      settleMovedBlock(editor, scroll);
      return;
    }
    const located = findBlockById(editor, target.id);
    const at = located?.[1];
    if (!at) {
      return;
    }
    const step = siblingMove(editor.children, at, direction);
    if (!step.ok) {
      return;
    }
    onActed();
    const scroll = captureEditorScroll();
    runEditorCommand(editor, moveBlock, { from: [...at], to: step.to });
    settleMovedBlock(editor, scroll);
  }

  const selectedIds = blockSelectionIds(editor);
  // The block shortcuts act on the block selection, so a row shows its hint only when this block is selected.
  function hint(id: EditorShortcutId): string | undefined {
    return platform !== null && selectedIds.includes(target.id)
      ? shortcutText(id, platform)
      : undefined;
  }
  const multi =
    path !== undefined && selectedIds.length > 1 && selectedIds.includes(target.id)
      ? blockRun(editor, selectedIds)
      : null;
  const up = multi
    ? runMoveTarget(editor, multi, "up")
    : path === undefined
      ? null
      : siblingMove(editor.children, path, "up");
  const down = multi
    ? runMoveTarget(editor, multi, "down")
    : path === undefined
      ? null
      : siblingMove(editor.children, path, "down");
  const view = path === undefined ? null : menuBlockView(editor, path);
  const columns = view ? columnGroupMenu(view) : null;

  function selectGroup(): void {
    if (!path) {
      return;
    }
    const start = editor.api.start([...path, 0, 0]);
    if (start) {
      editor.tf.select(start);
    }
  }

  function setCount(count: 2 | 3): void {
    if (!path) {
      return;
    }
    onActed();
    selectGroup();
    runEditorCommand(editor, setColumnCountCommand, count);
  }

  function unwrap(): void {
    if (!path) {
      return;
    }
    onActed();
    selectGroup();
    runEditorCommand(editor, unwrapColumnsCommand, undefined);
  }

  if (multi) {
    return (
      <>
        <DropdownMenuLabel data-block-menu-count="">{`${multi.ids.length} blocks`}</DropdownMenuLabel>
        <BlockColorMenu ids={multi.ids} onActed={onActed} />
        <DropdownMenuItem
          onSelect={() => {
            duplicate();
          }}
        >
          <Copy aria-hidden="true" />
          Duplicate
          <MenuHint text={hint("duplicateBlocks")} />
        </DropdownMenuItem>
        <DropdownMenuItem
          disabled={up === null || !up.ok}
          data-block-menu-move="up"
          onSelect={() => {
            move("up");
          }}
        >
          <ArrowUp aria-hidden="true" />
          <span className="flex min-w-0 flex-col items-start">
            <span>Move up</span>
            {up !== null && !up.ok ? (
              <span className="text-muted-foreground text-xs whitespace-normal">{up.reason}</span>
            ) : null}
          </span>
          <MenuHint text={hint("moveBlocksUp")} />
        </DropdownMenuItem>
        <DropdownMenuItem
          disabled={down === null || !down.ok}
          data-block-menu-move="down"
          onSelect={() => {
            move("down");
          }}
        >
          <ArrowDown aria-hidden="true" />
          <span className="flex min-w-0 flex-col items-start">
            <span>Move down</span>
            {down !== null && !down.ok ? (
              <span className="text-muted-foreground text-xs whitespace-normal">{down.reason}</span>
            ) : null}
          </span>
          <MenuHint text={hint("moveBlocksDown")} />
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          variant="destructive"
          onSelect={() => {
            remove();
          }}
        >
          <Trash2 aria-hidden="true" />
          Delete
          <MenuHint text={hint("deleteBlocks")} />
        </DropdownMenuItem>
      </>
    );
  }

  // A definition offers no Turn into and no Color. Its other actions stay.
  const offersTurn = footnoteMenuOffersTurn(target.type);
  return (
    <>
      {offersTurn ? (
        <DropdownMenuSub>
          <DropdownMenuSubTrigger data-block-menu-turn-into="">
            <ArrowRightLeft aria-hidden="true" />
            Turn into
          </DropdownMenuSubTrigger>
          <DropdownMenuPortal>
            <DropdownMenuSubContent
              data-block-menu-portal=""
              data-block-turn-into-menu=""
              collisionPadding={8}
              hideWhenDetached
              className="max-h-[var(--radix-dropdown-menu-content-available-height)] w-64 overflow-hidden"
            >
              <MenuScrollArea>
                <BlockPickerGroups
                  items={turnItems}
                  value={currentTurn}
                  radio
                  shortcuts
                  onChoose={turn}
                />
              </MenuScrollArea>
            </DropdownMenuSubContent>
          </DropdownMenuPortal>
        </DropdownMenuSub>
      ) : null}
      {columns ? (
        <>
          <DropdownMenuSub>
            <DropdownMenuSubTrigger data-block-menu-columns="">
              <Columns2 aria-hidden="true" />
              Columns
            </DropdownMenuSubTrigger>
            <DropdownMenuPortal>
              <DropdownMenuSubContent
                data-block-menu-portal=""
                data-block-columns-menu=""
                collisionPadding={8}
                hideWhenDetached
              >
                <DropdownMenuRadioGroup value={String(columns.count)}>
                  <DropdownMenuRadioItem
                    value="2"
                    className={MENU_ITEM_ACTIVE_CHECKED}
                    data-column-count="2"
                    onSelect={() => {
                      setCount(2);
                    }}
                  >
                    2 columns
                  </DropdownMenuRadioItem>
                  <DropdownMenuRadioItem
                    value="3"
                    className={MENU_ITEM_ACTIVE_CHECKED}
                    data-column-count="3"
                    onSelect={() => {
                      setCount(3);
                    }}
                  >
                    3 columns
                  </DropdownMenuRadioItem>
                </DropdownMenuRadioGroup>
              </DropdownMenuSubContent>
            </DropdownMenuPortal>
          </DropdownMenuSub>
          <DropdownMenuItem
            data-block-menu-unwrap=""
            onSelect={() => {
              unwrap();
            }}
          >
            <Ungroup aria-hidden="true" />
            Turn into blocks
          </DropdownMenuItem>
        </>
      ) : null}
      {offersTurn ? <BlockColorMenu ids={[target.id]} onActed={onActed} /> : null}
      <DropdownMenuItem
        onSelect={() => {
          duplicate();
        }}
      >
        <Copy aria-hidden="true" />
        Duplicate
        <MenuHint text={hint("duplicateBlocks")} />
      </DropdownMenuItem>
      <DropdownMenuItem
        disabled={up === null || !up.ok}
        data-block-menu-move="up"
        onSelect={() => {
          move("up");
        }}
      >
        <ArrowUp aria-hidden="true" />
        <span className="flex min-w-0 flex-col items-start">
          <span>Move up</span>
          {up !== null && !up.ok ? (
            <span className="text-muted-foreground text-xs whitespace-normal">{up.reason}</span>
          ) : null}
        </span>
        <MenuHint text={hint("moveBlocksUp")} />
      </DropdownMenuItem>
      <DropdownMenuItem
        disabled={down === null || !down.ok}
        data-block-menu-move="down"
        onSelect={() => {
          move("down");
        }}
      >
        <ArrowDown aria-hidden="true" />
        <span className="flex min-w-0 flex-col items-start">
          <span>Move down</span>
          {down !== null && !down.ok ? (
            <span className="text-muted-foreground text-xs whitespace-normal">{down.reason}</span>
          ) : null}
        </span>
        <MenuHint text={hint("moveBlocksDown")} />
      </DropdownMenuItem>
      <DropdownMenuSeparator />
      <DropdownMenuItem
        variant="destructive"
        onSelect={() => {
          remove();
        }}
      >
        <Trash2 aria-hidden="true" />
        Delete
        <MenuHint text={hint("deleteBlocks")} />
      </DropdownMenuItem>
    </>
  );
}

export function BlockMenu({
  gripRef,
  holdMenu,
  bindOpener,
  bindCloser,
}: {
  gripRef: RefObject<HTMLButtonElement | null>;
  holdMenu: (id: string | null) => void;
  bindOpener: (open: (target: BlockHandleHit) => void) => void;
  bindCloser: (close: () => void) => void;
}) {
  const editor = useEditorRef();
  const [session, setSession] = useState<MenuSession | null>(null);
  const savedSelection = useRef(editor.selection);
  const acted = useRef(false);
  const sessionRef = useRef<MenuSession | null>(null);
  const pending = useRef<BlockHandleHit | null>(null);
  const frame = useRef(0);

  const close = useCallback(() => {
    pending.current = null;
    cancelAnimationFrame(frame.current);
    sessionRef.current = null;
    setSession(null);
    holdMenu(null);
  }, [holdMenu]);

  const openAt = useCallback(
    (target: BlockHandleHit, anchor: AnchorBox) => {
      const entry = findBlockById(editor, target.id);
      if (!entry || typeof entry[0].type !== "string") {
        return;
      }
      savedSelection.current = cloneRange(editor.selection);
      acted.current = false;
      pending.current = null;
      // Opening focuses the menu. Put the scroll ports back after that focus.
      retainScroll(() => undefined);
      cancelAnimationFrame(frame.current);
      holdMenu(target.id);
      const next = {
        target: { id: target.id, type: entry[0].type, path: [...entry[1]] },
        anchor,
      };
      sessionRef.current = next;
      setSession(next);
    },
    [editor, holdMenu],
  );

  const openFromGrip = useCallback(
    (target: BlockHandleHit) => {
      if (sessionRef.current?.target.id === target.id) {
        close();
        return;
      }
      const grip = gripRef.current?.getBoundingClientRect();
      const anchor = grip && grip.width > 0 ? boxOf(grip) : blockBox(editor, target.id);
      if (!anchor) {
        return;
      }
      openAt(target, anchor);
    },
    [close, editor, gripRef, openAt],
  );

  useLayoutEffect(() => {
    bindOpener(openFromGrip);
    bindCloser(close);
  }, [bindCloser, bindOpener, close, openFromGrip]);

  useEffect(() => {
    return () => {
      cancelAnimationFrame(frame.current);
    };
  }, []);

  useLayoutEffect(() => {
    const editable = editableOf(editor);
    if (!editable) {
      return;
    }

    const onContextMenu = (event: MouseEvent): void => {
      if (keepNativeContextMenu(contextProbe(editor, event))) {
        return;
      }
      const target = event.target instanceof Element ? event.target : null;
      const picked = target ? blockHandleTarget(chainFromDom(editor, target)) : null;
      if (!picked) {
        return;
      }
      const entry = findBlockById(editor, picked.id);
      if (!entry) {
        return;
      }
      event.preventDefault();
      const selected = blockSelectionIds(editor);
      if (!(selected.length > 1 && selected.includes(picked.id))) {
        setBlockSelection(editor, [picked.id]);
      }
      openAt(
        { id: picked.id, type: picked.type, path: [...entry[1]] },
        { top: event.clientY, left: event.clientX, width: 0, height: 0 },
      );
    };

    const onKeyDown = (event: KeyboardEvent): void => {
      if (!isBlockMenuShortcut(event) || event.isComposing) {
        return;
      }
      const eventTarget = event.target instanceof Element ? event.target : null;
      if (
        eventTarget?.closest(
          "input, textarea, select, [role='menu'], [data-block-menu], [data-block-menu-portal]",
        )
      ) {
        return;
      }
      const selected = blockSelectionIds(editor);
      const selection = editor.selection;
      const hit = selected[0]
        ? (() => {
            const located = findBlockById(editor, selected[0]);
            return located ? { id: selected[0], type: "", path: [...located[1]] } : null;
          })()
        : selection
          ? targetBlockAtPath(editor, selection.anchor.path)
          : null;
      if (!hit) {
        return;
      }
      event.preventDefault();
      event.stopPropagation();
      const grip = gripRef.current?.getBoundingClientRect();
      if (grip && grip.width > 0) {
        openAt(hit, boxOf(grip));
        return;
      }
      pending.current = hit;
      holdMenu(hit.id);
      cancelAnimationFrame(frame.current);
      // The handle paints on the next layout. A second frame sees the grip, or the block.
      frame.current = requestAnimationFrame(() => {
        frame.current = requestAnimationFrame(() => {
          const waiting = pending.current;
          if (!waiting) {
            return;
          }
          const shown = gripRef.current?.getBoundingClientRect();
          const anchor = shown && shown.width > 0 ? boxOf(shown) : blockBox(editor, waiting.id);
          if (anchor) {
            openAt(waiting, anchor);
          }
        });
      });
    };

    editable.addEventListener("contextmenu", onContextMenu);
    editable.addEventListener("keydown", onKeyDown, true);
    return () => {
      editable.removeEventListener("contextmenu", onContextMenu);
      editable.removeEventListener("keydown", onKeyDown, true);
    };
  }, [editor, gripRef, holdMenu, openAt]);

  useEffect(() => {
    if (!session) {
      return;
    }
    // A click on the page chrome must not move the caret. Real controls still receive it.
    const onPointerDown = (event: PointerEvent): void => {
      const target = event.target instanceof Element ? event.target : null;
      if (
        !target ||
        target.closest(
          "[data-block-menu], [data-block-menu-portal], [data-block-menu-anchor], [data-block-handle]",
        )
      ) {
        return;
      }
      const editable = editableOf(editor);
      if (editable?.contains(target) || target.closest(PAGE_CONTROL_SELECTOR)) {
        return;
      }
      event.preventDefault();
    };
    document.addEventListener("pointerdown", onPointerDown, true);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown, true);
    };
  }, [editor, session]);

  if (!session) {
    return null;
  }

  return (
    <DropdownMenu
      open
      modal={false}
      onOpenChange={(next) => {
        if (!next) {
          close();
        }
      }}
    >
      <Tooltip>
        <TooltipTrigger asChild>
          <DropdownMenuTrigger asChild>
            <Button
              type="button"
              size="icon"
              variant="ghost"
              aria-label="Block menu"
              tabIndex={-1}
              data-block-menu-anchor=""
              className="pointer-events-none fixed p-0 opacity-0"
              style={{
                top: session.anchor.top,
                left: session.anchor.left,
                width: session.anchor.width,
                height: session.anchor.height,
              }}
            >
              <Type aria-hidden="true" />
            </Button>
          </DropdownMenuTrigger>
        </TooltipTrigger>
        <TooltipContent>Block menu</TooltipContent>
      </Tooltip>
      <DropdownMenuContent
        align="start"
        side="bottom"
        sideOffset={4}
        collisionPadding={8}
        hideWhenDetached
        data-block-menu=""
        data-block-menu-for={session.target.id}
        className="w-64"
        onCloseAutoFocus={(event) => {
          event.preventDefault();
          const selection = cloneRange(acted.current ? editor.selection : savedSelection.current);
          // Chrome places the caret under the pointer when focus returns from a click.
          // Deselect first so the saved range is written, then again after that placement.
          const restore = (): void => {
            editor.tf.withoutSaving(() => {
              editor.tf.focus();
              if (!selection) {
                return;
              }
              editor.tf.deselect();
              editor.tf.select(selection);
            });
          };
          retainScroll(restore);
          requestAnimationFrame(() => {
            retainScroll(restore);
          });
        }}
      >
        <BlockMenuItems
          target={session.target}
          onActed={() => {
            acted.current = true;
          }}
        />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { Fragment } from "react";

import {
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";

import { BLOCK_PICKER_GROUPS, type BlockPickerItem } from "../../lib/features/editor-block-picker";
import {
  itemShortcutId,
  shortcutText,
  type ShortcutPlatform,
} from "../../lib/features/editor-shortcuts";
import { MENU_ITEM_ACTIVE_CHECKED } from "../../lib/features/editor-menu-active";
import { useShortcutPlatform } from "./editor-shortcut";

function ItemLabel({ item, shortcut }: { item: BlockPickerItem; shortcut?: string }) {
  const Icon = item.icon;
  return (
    <>
      <Icon aria-hidden="true" />
      <span className="flex min-w-0 flex-col items-start">
        <span>{item.label}</span>
        {item.reason === undefined ? null : (
          <span className="text-muted-foreground text-xs whitespace-normal">{item.reason}</span>
        )}
      </span>
      {shortcut === undefined ? null : <DropdownMenuShortcut>{shortcut}</DropdownMenuShortcut>}
    </>
  );
}

function itemShortcut(
  item: BlockPickerItem,
  platform: ShortcutPlatform | null,
): string | undefined {
  const id = itemShortcutId(item.id);
  return id !== undefined && platform !== null ? shortcutText(id, platform) : undefined;
}

// One shared renderer for the grouped block list, used by both the "+" Add menu
// and the "Turn into" submenu so the two cannot drift. `radio` renders the
// conversion items as a checked radio group; otherwise they are plain actions.
export function BlockPickerGroups({
  items,
  onChoose,
  value,
  radio = false,
  shortcuts = false,
}: {
  items: readonly BlockPickerItem[];
  onChoose: (item: BlockPickerItem) => void;
  value?: string;
  radio?: boolean;
  shortcuts?: boolean;
}) {
  // Only the Turn into submenu shows hints. Its shortcuts convert the current block, as the item does.
  const devicePlatform = useShortcutPlatform();
  const platform = shortcuts ? devicePlatform : null;
  const groups = BLOCK_PICKER_GROUPS.filter((group) => items.some((item) => item.group === group));

  const rows = groups.map((group, index) => (
    <Fragment key={group}>
      {index > 0 ? <DropdownMenuSeparator /> : null}
      <DropdownMenuGroup>
        <DropdownMenuLabel>{group}</DropdownMenuLabel>
        {items
          .filter((item) => item.group === group)
          .map((item) =>
            radio ? (
              <DropdownMenuRadioItem
                key={item.id}
                value={item.id}
                disabled={item.disabled}
                data-block-picker-item={item.id}
                className={cn(item.checked && MENU_ITEM_ACTIVE_CHECKED)}
              >
                <ItemLabel item={item} shortcut={itemShortcut(item, platform)} />
              </DropdownMenuRadioItem>
            ) : (
              <DropdownMenuItem
                key={item.id}
                disabled={item.disabled}
                data-block-picker-item={item.id}
                onSelect={() => {
                  if (!item.disabled) {
                    onChoose(item);
                  }
                }}
              >
                <ItemLabel item={item} shortcut={itemShortcut(item, platform)} />
              </DropdownMenuItem>
            ),
          )}
      </DropdownMenuGroup>
    </Fragment>
  ));

  if (!radio) {
    return <>{rows}</>;
  }

  return (
    <DropdownMenuRadioGroup
      value={value ?? ""}
      onValueChange={(next) => {
        const item = items.find((candidate) => candidate.id === next);
        if (item && !item.disabled) {
          onChoose(item);
        }
      }}
    >
      {rows}
    </DropdownMenuRadioGroup>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { useEditorReadOnly, useEditorRef, useEditorSelector, usePluginOption } from "platejs/react";

import { listItemUnit } from "../../lib/features/editor-block-drop";
import {
  applySelectionMarks,
  isSideMarginPoint,
  marqueeBlockIds,
  MARQUEE_THRESHOLD_PX,
} from "../../lib/features/editor-block-selection";
import {
  blockSelectionPlugin,
  clearBlockSelection,
  setBlockSelection,
} from "../../lib/plugins/editor-block-selection";
import { findBlockById } from "../../lib/features/editor-synced-block";

type Marquee = { left: number; top: number; width: number; height: number };

// Painted on the selected blocks themselves. A fixed overlay measured from
// getBoundingClientRect drifts inside a transformed preview frame.
const SELECTION_STYLE = [
  "[data-block-selection-count], [data-block-selection-count] * { caret-color: transparent; }",
  "[data-block-selection-count] *::selection { background: transparent; }",
  "[data-block-selected] {",
  "border-radius: 0.375rem;",
  "background-color: color-mix(in oklab, var(--primary) 10%, transparent);",
  "box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 10%, transparent);",
  "}",
  "body[data-block-dragging] [data-block-selected] { background-color: transparent; box-shadow: none; }",
].join(" ");

const CONTROL =
  "[data-block-handle], [data-block-menu], [data-block-menu-portal], [data-block-add-menu], button, a, input, textarea, select, [role='menu']";

function unitIds(editor: ReturnType<typeof useEditorRef>, ids: readonly string[]): string[] {
  const selected = new Set(ids);
  const marked: string[] = [];
  let cursor = 0;
  while (cursor < editor.children.length) {
    const [start, end] = listItemUnit(editor.children, cursor);
    if (start !== cursor || end <= start) {
      cursor += 1;
      continue;
    }
    const head = editor.children[start];
    const headId = head && "id" in head && typeof head.id === "string" ? head.id : "";
    if (headId.length > 0 && selected.has(headId)) {
      for (let index = start; index < end; index += 1) {
        const node = editor.children[index];
        if (node && "id" in node && typeof node.id === "string") {
          marked.push(node.id);
        }
      }
    }
    cursor = end;
  }
  return marked.length > 0 ? marked : [...ids];
}

function editorElement(): HTMLElement | null {
  const found = document.querySelector("[data-slate-editor]");
  return found instanceof HTMLElement ? found : null;
}

function topLevelBoxes(
  editor: ReturnType<typeof useEditorRef>,
): { id: string; top: number; bottom: number }[] {
  const boxes: { id: string; top: number; bottom: number }[] = [];
  let cursor = 0;
  while (cursor < editor.children.length) {
    const [start, end] = listItemUnit(editor.children, cursor);
    if (start !== cursor || end <= start) {
      cursor += 1;
      continue;
    }
    const node = editor.children[start];
    if (!node || !("id" in node) || typeof node.id !== "string") {
      cursor = end;
      continue;
    }
    const entry = findBlockById(editor, node.id);
    const dom: unknown = entry ? editor.api.toDOMNode(entry[0]) : null;
    if (dom instanceof HTMLElement) {
      const rect = dom.getBoundingClientRect();
      let bottom = rect.bottom;
      for (let index = start + 1; index < end; index += 1) {
        const nested = editor.children[index];
        if (!nested || !("id" in nested) || typeof nested.id !== "string") {
          continue;
        }
        const nestedEntry = findBlockById(editor, nested.id);
        const nestedDom: unknown = nestedEntry ? editor.api.toDOMNode(nestedEntry[0]) : null;
        if (nestedDom instanceof HTMLElement) {
          bottom = Math.max(bottom, nestedDom.getBoundingClientRect().bottom);
        }
      }
      boxes.push({ id: node.id, top: rect.top, bottom });
    }
    cursor = end;
  }
  return boxes;
}

export function BlockSelection() {
  const editor = useEditorRef();
  const readOnly = useEditorReadOnly();
  const ids = usePluginOption(blockSelectionPlugin, "ids");
  const revision = useEditorSelector((instance) => instance.operations.length, []);
  const [marquee, setMarquee] = useState<Marquee | null>(null);
  const [announce, setAnnounce] = useState("");
  const previousCount = useRef(0);
  const idsRef = useRef(ids);
  useEffect(() => {
    idsRef.current = ids;
  }, [ids]);

  useEffect(() => {
    const count = ids.length;
    if (count === previousCount.current) {
      return;
    }
    const previous = previousCount.current;
    previousCount.current = count;
    const frame = requestAnimationFrame(() => {
      if (count === 0) {
        if (previous > 0) {
          setAnnounce("Selection cleared");
        }
        return;
      }
      setAnnounce(count === 1 ? "1 block selected" : `${count} blocks selected`);
    });
    return () => {
      cancelAnimationFrame(frame);
    };
  }, [ids]);

  useEffect(() => {
    const editable = editorElement();
    if (!editable) {
      return;
    }
    if (readOnly || ids.length === 0) {
      if (readOnly && ids.length > 0) {
        clearBlockSelection(editor, false);
      }
      // Marks are only ever written with the count attribute, so without it there
      // is nothing to clear. A typing pass returns here without scanning the blocks.
      if (!readOnly && !editable.hasAttribute("data-block-selection-count")) {
        return;
      }
      editable.removeAttribute("data-block-selection-count");
      for (const node of editable.querySelectorAll("[data-block-selected]")) {
        node.removeAttribute("data-block-selected");
      }
      return;
    }
    applySelectionMarks(editable, unitIds(editor, ids));
  }, [editor, ids, readOnly, revision]);

  useEffect(() => {
    if (readOnly) {
      return;
    }

    const contentEdges = (
      editable: HTMLElement,
    ): {
      left: number;
      right: number;
      top: number;
      bottom: number;
    } | null => {
      let left = Number.POSITIVE_INFINITY;
      let right = Number.NEGATIVE_INFINITY;
      let top = Number.POSITIVE_INFINITY;
      let bottom = Number.NEGATIVE_INFINITY;
      for (const node of editable.querySelectorAll("[data-block-id]")) {
        if (!(node instanceof HTMLElement) || node.closest("[data-preview-path]")) {
          continue;
        }
        const rect = node.getBoundingClientRect();
        if (rect.width <= 0 || rect.height <= 0) {
          continue;
        }
        left = Math.min(left, rect.left);
        right = Math.max(right, rect.right);
        top = Math.min(top, rect.top);
        bottom = Math.max(bottom, rect.bottom);
      }
      if (!Number.isFinite(left)) {
        return null;
      }
      return { left, right, top, bottom };
    };

    let startX = 0;
    let startY = 0;
    let active = false;
    let frameId = 0;
    let listening = false;

    const paint = (clientX: number, clientY: number): void => {
      const left = Math.min(startX, clientX);
      const top = Math.min(startY, clientY);
      const next = {
        left,
        top,
        width: Math.abs(clientX - startX),
        height: Math.abs(clientY - startY),
      };
      setMarquee(next);
      const hits = marqueeBlockIds(topLevelBoxes(editor), top, top + next.height);
      setBlockSelection(editor, hits);
      const editable = editorElement();
      const frameBox =
        editable?.closest("[data-block-viewport]") instanceof HTMLElement
          ? (editable.closest("[data-block-viewport]") as HTMLElement)
          : editable;
      if (!frameBox) {
        return;
      }
      const frameRect = frameBox.getBoundingClientRect();
      if (clientY < frameRect.top + 28) {
        frameBox.scrollTop -= 16;
      } else if (clientY > frameRect.bottom - 28) {
        frameBox.scrollTop += 16;
      }
    };

    const finish = (): void => {
      if (!listening) {
        return;
      }
      listening = false;
      document.removeEventListener("pointermove", onMove);
      document.removeEventListener("pointerup", finish);
      document.removeEventListener("pointercancel", finish);
      if (frameId !== 0) {
        cancelAnimationFrame(frameId);
        frameId = 0;
      }
      active = false;
      setMarquee(null);
    };

    const onMove = (event: PointerEvent): void => {
      const dx = event.clientX - startX;
      const dy = event.clientY - startY;
      if (!active) {
        if (dx * dx + dy * dy < MARQUEE_THRESHOLD_PX * MARQUEE_THRESHOLD_PX) {
          return;
        }
        active = true;
      }
      if (frameId !== 0) {
        cancelAnimationFrame(frameId);
      }
      frameId = requestAnimationFrame(() => {
        frameId = 0;
        paint(event.clientX, event.clientY);
      });
    };

    const onDown = (event: PointerEvent): void => {
      if (event.pointerType === "touch" || event.button !== 0 || listening) {
        return;
      }
      const editable = editorElement();
      const target = event.target;
      if (!editable || !(target instanceof Element)) {
        return;
      }
      const frame =
        editable.closest("[data-block-viewport]") ??
        editable.closest("[data-editor-scroll]") ??
        editable.parentElement ??
        editable;
      if (!frame.contains(target)) {
        return;
      }
      if (
        idsRef.current.length > 0 &&
        target.closest("[data-block-id]") &&
        !target.closest(CONTROL)
      ) {
        clearBlockSelection(editor, false);
        return;
      }
      const edges = contentEdges(editable);
      if (!edges) {
        return;
      }
      const onControl =
        target.closest(
          "[data-block-handle], [data-block-handle-gutter], button, a, input, textarea, select, [role='menu'], [data-block-menu]",
        ) !== null;
      if (
        !isSideMarginPoint({
          clientX: event.clientX,
          clientY: event.clientY,
          contentLeft: edges.left,
          contentRight: edges.right,
          contentTop: edges.top,
          contentBottom: edges.bottom,
          inFrame: true,
          onControl,
        })
      ) {
        return;
      }
      startX = event.clientX;
      startY = event.clientY;
      active = false;
      listening = true;
      document.addEventListener("pointermove", onMove);
      document.addEventListener("pointerup", finish);
      document.addEventListener("pointercancel", finish);
    };

    const onFocusOut = (event: FocusEvent): void => {
      if (idsRef.current.length === 0) {
        return;
      }
      const next = event.relatedTarget;
      if (
        next instanceof Element &&
        next.closest(
          "[data-slate-editor], [data-block-handle], [data-block-menu], [data-block-menu-portal]",
        )
      ) {
        return;
      }
      clearBlockSelection(editor, false);
    };

    document.addEventListener("pointerdown", onDown, true);
    document.addEventListener("focusout", onFocusOut);
    return () => {
      document.removeEventListener("pointerdown", onDown, true);
      document.removeEventListener("focusout", onFocusOut);
      finish();
    };
  }, [editor, readOnly]);

  if (readOnly) {
    return null;
  }

  return (
    <>
      <style>{SELECTION_STYLE}</style>
      <div className="sr-only" aria-live="polite">
        {announce}
      </div>
      {marquee
        ? createPortal(
            <div
              data-block-marquee=""
              aria-hidden="true"
              className="bg-primary/10 pointer-events-none fixed z-30 rounded-sm"
              style={{
                top: marquee.top,
                left: marquee.left,
                width: marquee.width,
                height: marquee.height,
              }}
            />,
            document.body,
          )
        : null}
    </>
  );
}

import {
  createElement,
  Fragment,
  type ComponentProps,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
} from "react";
import type { TElement } from "platejs";

import { Button } from "@/components/ui/button";
import { DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";

import { ariaKeyShortcuts, type EditorShortcutId } from "../../lib/features/editor-shortcuts";
import { ShortcutLabel, useShortcutPlatform } from "./editor-shortcut";

// Editor controls (DEV-142):
// Every clickable control is Button, Toggle or ToggleGroup for on/off state,
// or a menu item. Text actions use size sm. Icon-only actions use size icon.
// A row of actions on a block or selection uses ghost inside a bordered toolbar.
// Standalone actions in a popover or card use outline.
// Save, Done, Apply, and Insert use default.
// Remove and delete use destructive, with Trash2, or Unlink when removing a link.
// Action buttons in toolbars, menus, popovers, and cards have a lucide icon,
// before the label when the label is visible.
// Navigation entries, such as table-of-contents items, do not.
// An icon-only button has an aria-label and a Tooltip with the same text.
// Fields use Input, InputGroup, or Textarea. Choosers use Select, DropdownMenu, or Command.

export const MEDIA_TOOLBAR_CLASS =
  "absolute top-1 right-1 z-10 flex max-w-full flex-wrap items-center gap-1 rounded-md border border-border bg-background p-1 opacity-0 pointer-events-none group-hover:pointer-events-auto group-hover:opacity-100 group-focus-within:pointer-events-auto group-focus-within:opacity-100 [@media(hover:none)]:pointer-events-auto [@media(hover:none)]:opacity-100";

// The chosen option of a row of toggles, such as the align buttons. The same tint as a selection mark.
export const TOOLBAR_PRESSED_CLASS = "aria-pressed:bg-muted";

type EditorButtonVariant = "default" | "outline" | "ghost" | "destructive";

type EditorTextButtonProps = Omit<
  ComponentProps<typeof Button>,
  "size" | "variant" | "children" | "aria-label"
> & {
  label: string;
  icon: ReactNode;
  variant?: EditorButtonVariant;
};

type EditorIconButtonProps = Omit<
  ComponentProps<typeof Button>,
  "size" | "variant" | "children" | "aria-label"
> & {
  label: string;
  icon: ReactNode;
  variant?: EditorButtonVariant;
  shortcut?: EditorShortcutId;
};

function inlineIcon(icon: ReactNode): ReactNode {
  return createElement("span", { "data-icon": "inline-start", className: "inline-flex" }, icon);
}

export function editorControlLabel(icon: ReactNode, label: string): ReactNode {
  return createElement(Fragment, null, inlineIcon(icon), label);
}

export function EditorTextButton({
  label,
  icon,
  variant = "ghost",
  type = "button",
  className,
  ...props
}: EditorTextButtonProps) {
  return (
    <Button
      {...props}
      type={type}
      size="sm"
      variant={variant}
      aria-label={label}
      className={className}
    >
      {editorControlLabel(icon, label)}
    </Button>
  );
}

export function EditorIconButton({
  label,
  icon,
  variant = "ghost",
  type = "button",
  shortcut,
  ...props
}: EditorIconButtonProps) {
  const platform = useShortcutPlatform();
  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            {...props}
            type={type}
            size="icon"
            variant={variant}
            aria-label={label}
            aria-keyshortcuts={
              shortcut !== undefined && platform !== null
                ? ariaKeyShortcuts(shortcut, platform)
                : undefined
            }
          >
            {icon}
          </Button>
        </TooltipTrigger>
        <TooltipContent>
          {shortcut === undefined ? label : <ShortcutLabel label={label} shortcut={shortcut} />}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

export function EditorMenuTrigger({
  label,
  accessibleName,
  icon,
  text,
  onMouseDown,
  onPointerDown,
}: {
  label: string;
  accessibleName?: string;
  icon?: ReactNode;
  text?: string;
  onMouseDown?: ComponentProps<typeof Button>["onMouseDown"];
  onPointerDown?: ComponentProps<typeof Button>["onPointerDown"];
}) {
  const trigger = (
    <DropdownMenuTrigger asChild>
      <Button
        type="button"
        size={text === undefined ? "icon" : "sm"}
        variant="ghost"
        aria-label={accessibleName ?? label}
        onMouseDown={onMouseDown}
        onPointerDown={onPointerDown}
      >
        {text === undefined || icon === undefined ? icon : editorControlLabel(icon, text)}
      </Button>
    </DropdownMenuTrigger>
  );

  if (text !== undefined) {
    return trigger;
  }

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>{trigger}</TooltipTrigger>
        <TooltipContent>{label}</TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

export function keepMediaSelection(event: { preventDefault: () => void }): void {
  event.preventDefault();
}

type ScrollPoint = {
  node: HTMLElement;
  top: number;
  left: number;
};

function scrollableNodes(): HTMLElement[] {
  const found: HTMLElement[] = [];
  const seen = new Set<HTMLElement>();
  const add = (node: Element | null): void => {
    if (!(node instanceof HTMLElement) || seen.has(node)) {
      return;
    }
    seen.add(node);
    found.push(node);
  };

  add(document.querySelector("[data-block-viewport]"));
  const editor = document.querySelector("[data-slate-editor]");
  let parent = editor instanceof HTMLElement ? editor.parentElement : null;
  while (parent) {
    const style = getComputedStyle(parent);
    const overflows =
      parent.scrollHeight > parent.clientHeight + 1 || parent.scrollWidth > parent.clientWidth + 1;
    if (overflows && /(auto|scroll|overlay)/.test(`${style.overflowX}${style.overflowY}`)) {
      add(parent);
    }
    parent = parent.parentElement;
  }

  return found;
}

// Menus and popovers restore the caret with focus() and select(). A bare focus
// scrolls the editor element to the top of the viewport. Capture the scroll
// ports first, then put them back after Slate's selection effect.
export function retainScroll(run: () => void): void {
  const points: ScrollPoint[] = scrollableNodes().map((node) => ({
    node,
    top: node.scrollTop,
    left: node.scrollLeft,
  }));
  const x = window.scrollX;
  const y = window.scrollY;
  run();
  const apply = (): void => {
    for (const point of points) {
      point.node.scrollTop = point.top;
      point.node.scrollLeft = point.left;
    }
    window.scrollTo(x, y);
  };
  apply();
  queueMicrotask(apply);
  requestAnimationFrame(() => {
    apply();
    requestAnimationFrame(apply);
  });
}

export function focusEditorWithoutScroll(editorRoot: Element | null): void {
  if (editorRoot instanceof HTMLElement) {
    editorRoot.focus({ preventScroll: true });
  }
}

export function mediaStringAttr(element: TElement, key: string): string | undefined {
  const value: unknown = Reflect.get(element, key);
  return typeof value === "string" ? value : undefined;
}

// Arrow keys, Home and End move focus between the controls of an action popover.
export function moveActionFocus(event: ReactKeyboardEvent<HTMLDivElement>): void {
  if (
    event.key !== "ArrowDown" &&
    event.key !== "ArrowUp" &&
    event.key !== "ArrowRight" &&
    event.key !== "ArrowLeft" &&
    event.key !== "Home" &&
    event.key !== "End"
  ) {
    return;
  }

  const items = Array.from(
    event.currentTarget.querySelectorAll<HTMLElement>('button, a[href], [role="menuitem"]'),
  ).filter((item) => item.getAttribute("aria-disabled") !== "true");
  if (items.length === 0) {
    return;
  }

  const current = items.indexOf(document.activeElement as HTMLElement);
  let next = current;
  if (event.key === "Home") {
    next = 0;
  } else if (event.key === "End") {
    next = items.length - 1;
  } else if (event.key === "ArrowDown" || event.key === "ArrowRight") {
    next = current < 0 ? 0 : (current + 1) % items.length;
  } else if (event.key === "ArrowUp" || event.key === "ArrowLeft") {
    next = current < 0 ? items.length - 1 : (current - 1 + items.length) % items.length;
  }

  event.preventDefault();
  items[next]?.focus();
}

import { useEffect } from "react";
import { ExternalLink, RefreshCw, Trash2, Type } from "lucide-react";
import { ElementApi } from "platejs";
import { useEditorReadOnly, useEditorRef, useEditorSelector, usePluginOption } from "platejs/react";

import { Button } from "@/components/ui/button";
import { Popover, PopoverAnchor, PopoverContent } from "@/components/ui/popover";

import { runEditorCommand } from "../../lib/commands/editor-commands";
import { convertBookmarkToText, removeBookmark } from "../../lib/features/editor-bookmark";
import {
  bookmarkToolbarBlockId,
  bookmarkToolbarOpen,
  bookmarkToolbarPlugin,
  bookmarkToolbarSelectionOn,
  closeBookmarkToolbar,
} from "../../lib/plugins/editor-bookmark-toolbar";
import { onPopoverHistoryKey } from "../../lib/plugins/editor-popover-history";
import { anchorContext, elementRect, virtualAnchor } from "./anchor-rect";
import {
  EditorIconButton,
  EditorTextButton,
  editorControlLabel,
  moveActionFocus,
} from "./block-toolbar";

// One row of actions, opened by a click on the card (or Enter on the selected
// void). It follows the inline link popover: anchored to the card, side bottom.
export function BookmarkToolbarPopover({
  id,
  url,
  showRefresh,
  onRefresh,
}: {
  id: string;
  url: string;
  showRefresh: boolean;
  onRefresh: () => void;
}) {
  "use no memo";

  const editor = useEditorRef();
  const readOnly = useEditorReadOnly();
  const open = usePluginOption(bookmarkToolbarPlugin, "open") === true;
  const blockId = usePluginOption(bookmarkToolbarPlugin, "blockId");
  const selection = useEditorSelector((current) => current.selection, []);
  const mine = open && blockId === id;
  const virtualRef = virtualAnchor(
    () => elementRect(bookmarkCardNode(editor, id)),
    () => anchorContext(bookmarkCardNode(editor, id)),
  );

  // Leaving the editor, moving the selection to another block, entering a block
  // selection, or removing the block all close the popover.
  useEffect(() => {
    if (!mine) {
      return;
    }

    if (readOnly || selection === null || !bookmarkToolbarSelectionOn(editor, id)) {
      closeBookmarkToolbar(editor);
    }
  }, [editor, id, mine, readOnly, selection]);

  useEffect(() => {
    if (!mine || readOnly) {
      return;
    }

    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key !== "Escape") {
        return;
      }

      event.preventDefault();
      closeBookmarkToolbar(editor);
      editor.tf.focus();
    };
    const onPointerDown = (event: PointerEvent): void => {
      const target = event.target;
      if (target instanceof Element) {
        if (target.closest("[data-bookmark-toolbar-popover]") !== null) {
          return;
        }
        // A second click on the card keeps the popover open.
        if (target.closest("[data-bookmark-card]") !== null) {
          return;
        }
      }

      closeBookmarkToolbar(editor);
    };
    document.addEventListener("keydown", onKeyDown);
    document.addEventListener("pointerdown", onPointerDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.removeEventListener("pointerdown", onPointerDown);
    };
  }, [editor, mine, readOnly]);

  // The block was removed while its popover was open.
  useEffect(
    () => () => {
      if (bookmarkToolbarBlockId(editor) === id && bookmarkToolbarOpen(editor)) {
        closeBookmarkToolbar(editor);
      }
    },
    [editor, id],
  );

  if (readOnly || !mine) {
    return null;
  }

  return (
    <Popover open>
      <PopoverAnchor virtualRef={virtualRef} />
      <PopoverContent
        data-bookmark-toolbar-popover=""
        aria-label="Bookmark actions"
        side="bottom"
        align="start"
        sideOffset={4}
        collisionPadding={8}
        hideWhenDetached
        className="w-auto gap-1 p-1 text-xs whitespace-nowrap"
        onOpenAutoFocus={(event) => {
          const target = event.currentTarget as HTMLElement | null;
          const first = target?.querySelector<HTMLElement>('button, a[href], [role="menuitem"]');
          if (first) {
            event.preventDefault();
            first.focus();
          }
        }}
        onMouseDown={(event) => {
          event.preventDefault();
        }}
        onKeyDown={(event) => {
          if (onPopoverHistoryKey(editor, event)) {
            return;
          }
          moveActionFocus(event);
        }}
      >
        <div className="flex flex-nowrap items-center gap-1">
          <Button asChild size="sm" variant="ghost">
            <a
              href={url}
              target="_blank"
              rel="noopener noreferrer nofollow"
              aria-label="Open"
              data-bookmark-action="open"
              onClick={() => {
                closeBookmarkToolbar(editor);
              }}
            >
              {editorControlLabel(<ExternalLink aria-hidden="true" />, "Open")}
            </a>
          </Button>
          {showRefresh ? (
            <EditorTextButton
              label="Refresh preview"
              icon={<RefreshCw aria-hidden="true" />}
              onClick={() => {
                onRefresh();
              }}
            />
          ) : null}
          <EditorTextButton
            label="Convert to text"
            icon={<Type aria-hidden="true" />}
            onClick={() => {
              closeBookmarkToolbar(editor);
              runEditorCommand(editor, convertBookmarkToText, id);
              editor.tf.focus();
            }}
          />
          <EditorIconButton
            variant="destructive"
            label="Delete"
            icon={<Trash2 aria-hidden="true" />}
            onClick={() => {
              closeBookmarkToolbar(editor);
              runEditorCommand(editor, removeBookmark, id);
              editor.tf.focus();
            }}
          />
        </div>
      </PopoverContent>
    </Popover>
  );
}

function bookmarkCardNode(editor: ReturnType<typeof useEditorRef>, id: string): HTMLElement | null {
  const entry = editor.api.node({
    at: [],
    match: (node) => ElementApi.isElement(node) && node.id === id,
  });
  if (entry === undefined) {
    return null;
  }

  const dom: unknown = editor.api.toDOMNode(entry[0]);
  if (!(dom instanceof HTMLElement)) {
    return null;
  }

  return dom.querySelector("[data-bookmark-card]");
}

import { useEffect, useId, useRef, useState } from "react";
import { useEditorReadOnly, useEditorRef, usePluginOption } from "platejs/react";

import { Bookmark } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Popover, PopoverAnchor, PopoverContent } from "@/components/ui/popover";

import { EditorTextButton, retainScroll } from "./block-toolbar";
import { anchorContext, rangeContextElement, rangeRect, virtualAnchor } from "./anchor-rect";
import {
  bookmarkUrlAnchorPoint,
  bookmarkUrlPlugin,
  cancelBookmarkUrl,
  submitBookmarkUrl,
} from "../../lib/plugins/editor-bookmark-popover";

export function BookmarkUrlPopover() {
  "use no memo";

  const editor = useEditorRef();
  const readOnly = useEditorReadOnly();
  const open = usePluginOption(bookmarkUrlPlugin, "open");
  const error = usePluginOption(bookmarkUrlPlugin, "error");

  useEffect(() => {
    if (!open || !readOnly) {
      return;
    }
    retainScroll(() => {
      cancelBookmarkUrl(editor);
    });
  }, [editor, open, readOnly]);

  if (!open || readOnly) {
    return null;
  }

  return <BookmarkUrlForm editor={editor} error={error} />;
}

function bookmarkDomRange(editor: ReturnType<typeof useEditorRef>): Range | null {
  const point = bookmarkUrlAnchorPoint(editor);
  if (point === null) {
    return null;
  }

  try {
    return editor.api.toDOMRange({ anchor: point, focus: point }) ?? null;
  } catch {
    return null;
  }
}

function BookmarkUrlForm({
  editor,
  error,
}: {
  editor: ReturnType<typeof useEditorRef>;
  error: string;
}) {
  "use no memo";

  const [url, setUrl] = useState("");
  const fieldRef = useRef<HTMLInputElement>(null);
  const errorId = useId();
  const invalid = error.length > 0;
  const virtualRef = virtualAnchor(
    () => rangeRect(bookmarkDomRange(editor)),
    () => anchorContext(rangeContextElement(bookmarkDomRange(editor))),
  );

  useEffect(() => {
    const focusField = (): void => {
      fieldRef.current?.focus();
    };
    focusField();
    const frame = requestAnimationFrame(focusField);
    return () => {
      cancelAnimationFrame(frame);
    };
  }, []);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key !== "Escape") {
        return;
      }
      event.preventDefault();
      retainScroll(() => {
        cancelBookmarkUrl(editor);
      });
    };
    const onPointerDown = (event: PointerEvent): void => {
      const target = event.target;
      if (target instanceof Element && target.closest("[data-bookmark-url-popover]") !== null) {
        return;
      }
      event.preventDefault();
      retainScroll(() => {
        cancelBookmarkUrl(editor);
      });
    };
    document.addEventListener("keydown", onKeyDown);
    document.addEventListener("pointerdown", onPointerDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.removeEventListener("pointerdown", onPointerDown);
    };
  }, [editor]);

  return (
    <Popover open>
      <PopoverAnchor virtualRef={virtualRef} />
      <PopoverContent
        data-bookmark-url-popover=""
        aria-label="Bookmark link"
        side="bottom"
        align="start"
        sideOffset={4}
        collisionPadding={8}
        hideWhenDetached
        onOpenAutoFocus={(event) => {
          event.preventDefault();
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
        }}
        className="w-72 gap-2 p-2"
      >
        <form
          noValidate
          className="flex flex-col gap-2"
          onSubmit={(event) => {
            event.preventDefault();
            retainScroll(() => {
              submitBookmarkUrl(editor, url);
            });
          }}
        >
          <Input
            ref={fieldRef}
            aria-label="Bookmark URL"
            aria-invalid={invalid}
            aria-describedby={invalid ? errorId : undefined}
            value={url}
            placeholder="Paste a link"
            type="text"
            inputMode="url"
            autoCapitalize="none"
            autoCorrect="off"
            spellCheck={false}
            autoFocus
            onChange={(event) => {
              setUrl(event.target.value);
              if (error.length > 0) {
                editor.setOption(bookmarkUrlPlugin, "error", "");
              }
            }}
          />
          {invalid ? (
            <p id={errorId} role="alert" className="text-destructive text-xs">
              {error}
            </p>
          ) : null}
          <EditorTextButton
            type="submit"
            variant="default"
            label="Add bookmark"
            icon={<Bookmark aria-hidden="true" />}
          />
        </form>
      </PopoverContent>
    </Popover>
  );
}

import type { ComponentProps, ReactNode } from "react";

import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";

type ScrollFadeAreaProps = Omit<ComponentProps<typeof ScrollArea>, "children"> & {
  children: ReactNode;
  orientation?: "vertical" | "horizontal";
};

// The one scroll region for editor content: the app's shadcn ScrollArea with the
// scroll-fade mask on the element that actually scrolls (its viewport). No
// native `overflow-*-auto` class is left on the scrolling element, so the OS
// scrollbar never shows.
export function ScrollFadeArea({
  children,
  className,
  orientation = "vertical",
  ...props
}: ScrollFadeAreaProps) {
  return (
    <ScrollArea
      {...props}
      className={cn(
        // The viewport is the scroller. It inherits the root's max-height and
        // sizes to its content, so a max-height root scrolls instead of the
        // viewport overflowing it.
        "[&>[data-slot=scroll-area-viewport]]:h-auto [&>[data-slot=scroll-area-viewport]]:max-h-[inherit]",
        orientation === "horizontal"
          ? "[&>[data-slot=scroll-area-viewport]]:scroll-fade-x"
          : "[&>[data-slot=scroll-area-viewport]]:scroll-fade-y",
        className,
      )}
    >
      {children}
      {orientation === "horizontal" ? <ScrollBar orientation="horizontal" /> : null}
    </ScrollArea>
  );
}

// A dropdown menu's scroll region: capped by Radix's available-height variable
// and faded at the edge that has more content.
export function MenuScrollArea({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  return (
    <ScrollFadeArea
      className={cn("max-h-[var(--radix-dropdown-menu-content-available-height)]", className)}
    >
      {children}
    </ScrollFadeArea>
  );
}

import { createContext, useContext, useSyncExternalStore, type ReactNode } from "react";

import { Kbd, KbdGroup } from "@/components/ui/kbd";

import { useEditorOptions } from "../../hooks/use-editor-options";
import {
  EDITOR_SHORTCUTS,
  formatShortcutKeys,
  shortcutPlatformOf,
  type EditorShortcutId,
  type ShortcutPlatform,
} from "../../lib/features/editor-shortcuts";

const FINE_POINTER = "(any-pointer: fine)";
const HOVER = "(any-hover: hover)";

function mediaList(query: string): MediaQueryList | null {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
    return null;
  }

  return window.matchMedia(query);
}

// A device with no fine pointer and no hover is touch-only, and shows no hints.
// Without matchMedia, the device is treated as a keyboard device.
function getSnapshot(): ShortcutPlatform | null {
  const fine = mediaList(FINE_POINTER);
  const hover = mediaList(HOVER);
  if (fine === null || hover === null) {
    return shortcutPlatformOf(navigator);
  }

  return fine.matches || hover.matches ? shortcutPlatformOf(navigator) : null;
}

function subscribe(onChange: () => void): () => void {
  const lists = [mediaList(FINE_POINTER), mediaList(HOVER)];
  for (const list of lists) {
    list?.addEventListener("change", onChange);
  }

  return () => {
    for (const list of lists) {
      list?.removeEventListener("change", onChange);
    }
  };
}

// The editor's shortcutHints option. A component outside an editor has no option,
// so its hints stay on.
const ShortcutHintsContext = createContext(true);

// Sits inside Plate, so the hints of every component in the editor follow the option.
export function ShortcutHintsScope({ children }: { children: ReactNode }) {
  const { shortcutHints } = useEditorOptions();
  return (
    <ShortcutHintsContext.Provider value={shortcutHints}>{children}</ShortcutHintsContext.Provider>
  );
}

// null on the server and in the first client render, so both render the same markup.
// null also when the editor turns hints off, which hides every hint and aria-keyshortcuts.
export function useShortcutPlatform(): ShortcutPlatform | null {
  const hints = useContext(ShortcutHintsContext);
  const platform = useSyncExternalStore(subscribe, getSnapshot, () => null);
  return hints ? platform : null;
}

// The hint keys, one Kbd per key. Renders nothing on touch-only devices.
export function ShortcutKbd({ id }: { id: EditorShortcutId }) {
  const platform = useShortcutPlatform();
  if (platform === null) {
    return null;
  }

  return (
    <KbdGroup>
      {formatShortcutKeys(EDITOR_SHORTCUTS[id], platform).map((label, index) => (
        <Kbd key={`${index}-${label}`}>{label}</Kbd>
      ))}
    </KbdGroup>
  );
}

// A tooltip line: the label, then its shortcut hint with a small gap.
export function ShortcutLabel({ label, shortcut }: { label: string; shortcut: EditorShortcutId }) {
  return (
    <span className="inline-flex items-center gap-2">
      {label}
      <ShortcutKbd id={shortcut} />
    </span>
  );
}

