// The link popover of one embed block. It takes only a YouTube or Vimeo link, so it has no upload tab.
// It renders while this block's source popover is open, and only in an editable editor.
export function EmbedLinkPopover({
  blockId,
  readAnchor,
}: {
  blockId: string;
  readAnchor: () => HTMLElement | null;
}) {
  "use no memo";

  const readOnly = useEditorReadOnly();
  const open = usePluginOption(mediaUiPlugin, "source") === blockId;
  if (!open || readOnly) {
    return null;
  }

  return <EmbedLinkForm blockId={blockId} readAnchor={readAnchor} />;
}

function EmbedLinkForm({
  blockId,
  readAnchor,
}: {
  blockId: string;
  readAnchor: () => HTMLElement | null;
}) {
  "use no memo";

  const anchor = virtualAnchor(
    () => elementRect(readAnchor()),
    () => anchorContext(readAnchor()),
  );
  const editor = useEditorRef();
  const errorId = useId();
  const [link, setLink] = useState("");
  const [invalid, setInvalid] = useState(false);

  function close(): void {
    closeMediaSource(editor);
    editor.tf.focus();
  }

  // The command reads the link. A link that is not YouTube or Vimeo changes nothing.
  function submitLink(): void {
    if (!runEditorCommand(editor, setEmbedSource, { id: blockId, file: { url: link.trim() } })) {
      setInvalid(true);
      return;
    }

    close();
  }

  return (
    <Popover open>
      <PopoverAnchor virtualRef={anchor} />
      <PopoverContent
        data-embed-link-popover=""
        aria-label="Embed link"
        side="bottom"
        align="start"
        sideOffset={4}
        collisionPadding={8}
        hideWhenDetached
        className="w-80 gap-2 p-2"
        onOpenAutoFocus={(event) => {
          event.preventDefault();
          const first = event.currentTarget as HTMLElement | null;
          first?.querySelector<HTMLElement>("[data-embed-link-first]")?.focus();
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
        }}
        onPointerDownOutside={() => {
          closeMediaSource(editor);
        }}
        onKeyDown={(event) => {
          // Keys typed here never reach the editor. Escape closes the popover and returns to the editor.
          event.stopPropagation();
          if (onPopoverHistoryKey(editor, event)) {
            return;
          }
          if (event.key === "Escape") {
            event.preventDefault();
            close();
          }
        }}
      >
        <form
          noValidate
          className="flex flex-col gap-2"
          onSubmit={(event) => {
            event.preventDefault();
            submitLink();
          }}
        >
          <Input
            aria-label="Video link"
            aria-invalid={invalid}
            aria-describedby={invalid ? errorId : undefined}
            data-embed-link-first=""
            data-embed-link-input=""
            value={link}
            placeholder="Paste a YouTube or Vimeo link…"
            type="text"
            inputMode="url"
            autoCapitalize="none"
            autoCorrect="off"
            spellCheck={false}
            onChange={(event) => {
              setLink(event.target.value);
              setInvalid(false);
            }}
          />
          {invalid ? (
            <p id={errorId} role="alert" className="text-destructive text-xs">
              Enter a YouTube or Vimeo link
            </p>
          ) : null}
          <Button type="submit" size="sm" className="w-full" data-embed-submit="">
            Embed video
          </Button>
        </form>
      </PopoverContent>
    </Popover>
  );
}

import { useEffect } from "react";
import { useEditorReadOnly, useEditorRef, usePluginOption } from "platejs/react";

import { Popover, PopoverAnchor, PopoverContent } from "@/components/ui/popover";
import { cn } from "@/lib/utils";

import { readEmojiSession } from "../../lib/features/editor-emoji";
import { pointAtBlockOffset } from "../../lib/features/editor-slash";
import {
  chooseEmojiSuggestion,
  closeEmojiMenu,
  emojiMenuItems,
  emojiUiPlugin,
} from "../../lib/plugins/editor-emoji";
import { anchorContext, rangeContextElement, rangeRect, virtualAnchor } from "./anchor-rect";

export function EmojiSuggest() {
  const editor = useEditorRef();
  const readOnly = useEditorReadOnly();
  const open = usePluginOption(emojiUiPlugin, "open");
  const activeIndex = usePluginOption(emojiUiPlugin, "activeIndex");
  // Re-renders on every token change and when the emoji data finishes loading.
  // Rows are still read from the document at render time, never stored.
  usePluginOption(emojiUiPlugin, "query");
  usePluginOption(emojiUiPlugin, "ready");
  const items = open ? emojiMenuItems(editor) : [];
  const active = items.length === 0 ? -1 : Math.min(activeIndex, items.length - 1);
  const virtualRef = virtualAnchor(
    () => rangeRect(colonRange(editor)),
    () => anchorContext(rangeContextElement(colonRange(editor))),
  );

  useEffect(() => {
    if (!open || !readOnly) {
      return;
    }
    closeEmojiMenu(editor);
  }, [editor, open, readOnly]);

  if (!open || items.length === 0) {
    return null;
  }

  return (
    <Popover open modal={false}>
      <PopoverAnchor virtualRef={virtualRef} />
      <PopoverContent
        data-emoji-suggest=""
        aria-label="Emoji suggestions"
        side="bottom"
        align="start"
        sideOffset={4}
        collisionPadding={8}
        hideWhenDetached
        className="w-auto min-w-44 gap-0 p-1"
        onOpenAutoFocus={(event) => {
          event.preventDefault();
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
        }}
        onMouseDown={(event) => {
          event.preventDefault();
        }}
      >
        <div role="listbox" aria-label="Emoji suggestions" className="flex flex-col">
          {items.map((item, index) => (
            <div
              key={item.name}
              role="option"
              aria-selected={index === active}
              data-emoji-option={item.name}
              className={cn(
                "flex cursor-default items-center gap-2 rounded-sm px-2 py-1 text-sm",
                index === active && "bg-accent text-accent-foreground",
              )}
              onMouseDown={(event) => {
                event.preventDefault();
              }}
              onMouseEnter={() => {
                editor.setOption(emojiUiPlugin, "activeIndex", index);
              }}
              onClick={() => {
                chooseEmojiSuggestion(editor, item.emoji);
              }}
            >
              <span aria-hidden="true">{item.emoji}</span>
              <span className="text-muted-foreground font-mono text-xs">:{item.name}:</span>
            </div>
          ))}
        </div>
      </PopoverContent>
    </Popover>
  );
}

// The anchor is the colon, so the popover sits under the trigger like the slash menu.
function colonRange(editor: ReturnType<typeof useEditorRef>): Range | null {
  const session = readEmojiSession(editor);
  if (session === null) {
    return null;
  }
  const start = pointAtBlockOffset(editor, session.blockPath, session.colon);
  const end = pointAtBlockOffset(editor, session.blockPath, session.colon + 1);
  if (start === null || end === null) {
    return null;
  }
  try {
    return editor.api.toDOMRange({ anchor: start, focus: end }) ?? null;
  } catch {
    return null;
  }
}

