  cancelLinkPopover,
  closeLinkPopover,
  commitLinkPopover,
  linkAnchorRange,
  linkUiPlugin,
  openInlineLink,
  removeInlineLink,
} from "../../lib/plugins/editor-link";

export function LinkPopover() {
  "use no memo";

  const editor = useEditorRef();
  const readOnly = useEditorReadOnly();
  const mode = usePluginOption(linkUiPlugin, "mode");
  const error = usePluginOption(linkUiPlugin, "error");
  const draftUrl = usePluginOption(linkUiPlugin, "draftUrl");
  const draftLabel = usePluginOption(linkUiPlugin, "draftLabel");

  if (readOnly || mode === "closed") {
    return null;
  }

  return (
    <LinkPopoverForm
      editor={editor}
      mode={mode}
      error={error}
      draftUrl={draftUrl}
      draftLabel={draftLabel}
    />
  );
}

function linkDomRange(editor: ReturnType<typeof useEditorRef>): Range | null {
  const slateRange = linkAnchorRange(editor);
  if (!slateRange) {
    return null;
  }

  return editor.api.toDOMRange(slateRange) ?? null;
}

function LinkPopoverForm({
  editor,
  mode,
  error,
  draftUrl,
  draftLabel,
}: {
  editor: ReturnType<typeof useEditorRef>;
  mode: string;
  error: string;
  draftUrl: string;
  draftLabel: string;
}) {
  "use no memo";

  const [url, setUrl] = useState(draftUrl);
  const [label, setLabel] = useState(draftLabel);
  const editing = mode === "edit";
  const needsLabel = mode === "label" || editing;
  const virtualRef = virtualAnchor(
    () => rangeRect(linkDomRange(editor)),
    () => anchorContext(rangeContextElement(linkDomRange(editor))),
  );

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key === "Escape") {
        cancelLinkPopover(editor);
      }
    };
    const onPointerDown = (event: PointerEvent): void => {
      const target = event.target;
      if (target instanceof Element && target.closest("[data-link-popover]") !== null) {
        return;
      }

      closeLinkPopover(editor);
    };
    document.addEventListener("keydown", onKeyDown);
    document.addEventListener("pointerdown", onPointerDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.removeEventListener("pointerdown", onPointerDown);
    };
  }, [editor]);

  return (
    <Popover open>
      <PopoverAnchor virtualRef={virtualRef} />
      <PopoverContent
        data-link-popover=""
        aria-label="Link"
        data-link-mode={mode}
        side="bottom"
        align="start"
        sideOffset={4}
        collisionPadding={8}
        hideWhenDetached
        onOpenAutoFocus={(event) => {
          event.preventDefault();
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
        }}
        className="w-72 gap-2 p-2"
      >
        <form
          className="flex flex-col gap-2"
          onSubmit={(event) => {
            event.preventDefault();
            commitLinkPopover(editor, url, needsLabel ? label : "");
          }}
        >
          <Input
            aria-label="URL"
            value={url}
            placeholder="https://example.com"
            autoFocus
            onChange={(event) => {
              setUrl(event.target.value);
            }}
            onKeyDown={(event) => {
              if (event.nativeEvent.isComposing || event.key === "Escape") {
                return;
              }
            }}
          />
          {needsLabel ? (
            <Input
              aria-label="Label"
              value={label}
              placeholder="Label"
              onChange={(event) => {
                setLabel(event.target.value);
              }}
            />
          ) : null}
          {error.length > 0 ? (
            <p role="alert" className="text-destructive text-xs">
              {error}
            </p>
          ) : null}
          <div className="flex flex-wrap gap-1">
            <EditorTextButton
              type="submit"
              variant="default"
              label="Save"
              icon={<Save aria-hidden="true" />}
            />
            {editing ? (
              <EditorTextButton
                variant="outline"
                label="Open"
                icon={<ExternalLink aria-hidden="true" />}
                onMouseDown={(event) => {
                  event.preventDefault();
                }}
                onClick={() => {
                  runEditorCommand(editor, openInlineLink, undefined);
                }}
              />
            ) : null}
            {editing ? (
              <EditorTextButton
                variant="destructive"
                label="Remove link"
                icon={<Unlink aria-hidden="true" />}
                onMouseDown={(event) => {
                  event.preventDefault();
                }}
                onClick={() => {
                  cancelLinkPopover(editor);
                  runEditorCommand(editor, removeInlineLink, undefined);
                }}
              />
            ) : null}
          </div>
        </form>
      </PopoverContent>
    </Popover>
  );
}

import { Download } from "lucide-react";

import { Button } from "@/components/ui/button";

import { isHttpFileUrl } from "../../lib/features/editor-file-url";
import { editorControlLabel } from "./block-toolbar";

// The Download action of a file, video or audio block. A cross-origin file cannot be downloaded in
// place, so an http or https link opens in a new tab. Any other link downloads under `name`.
export function MediaDownloadButton({
  kind,
  href,
  name,
  onDownload,
}: {
  kind: "file" | "video" | "audio";
  href: string | undefined; // the resolved url; undefined while it resolves or when unavailable
  name: string | undefined;
  onDownload: () => void;
}) {
  const external = href !== undefined && isHttpFileUrl(href);
  const attr =
    kind === "file"
      ? { "data-file-action": "download" }
      : kind === "video"
        ? { "data-video-action": "download" }
        : { "data-audio-action": "download" };
  return (
    <Button
      asChild
      size="sm"
      variant="ghost"
      className="aria-disabled:pointer-events-none aria-disabled:opacity-50"
    >
      <a
        href={href}
        download={href === undefined ? undefined : name}
        target={external ? "_blank" : undefined}
        rel={external ? "noopener noreferrer nofollow" : undefined}
        aria-disabled={href === undefined ? true : undefined}
        {...attr}
        onClick={() => {
          onDownload();
        }}
      >
        {editorControlLabel(<Download aria-hidden="true" />, "Download")}
      </a>
    </Button>
  );
}

import { useId, useRef, useState } from "react";
import { usePluginOption, useEditorReadOnly, useEditorRef } from "platejs/react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Popover, PopoverAnchor, PopoverContent } from "@/components/ui/popover";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

import { isHttpFileUrl, sanitizeStoredFileUrl } from "../../lib/features/editor-file-url";
import { closeMediaSource, mediaUiPlugin } from "../../lib/plugins/editor-media-ui";
import { onPopoverHistoryKey } from "../../lib/plugins/editor-popover-history";
import { useFileUploadAdapter, useUploadController } from "../elements/file-upload-scope";
import { anchorContext, elementRect, virtualAnchor } from "./anchor-rect";
import { useEditorFeatures } from "../../hooks/use-editor-features";

// The words and limits one media block shows in its source popover.
export type MediaSourceConfig = {
  label: string; // aria-label of the popover
  accept?: string; // the file input's accept list. Absent means any file.
  uploadLabel: string;
  embedPlaceholder: string;
  embedLabel: string;
  linkLabel: string; // accessible name of the link field
  invalidLinkMessage: string;
};

// A stored link must be http or https. The result is trimmed and checked the way the document checks it.
function embedLinkOf(raw: string): string | null {
  const clean = sanitizeStoredFileUrl(raw.trim());
  return clean !== null && isHttpFileUrl(clean) ? clean : null;
}

// The "choose a source" popover of one media block. It shows the upload tab when an adapter is set,
// and the embed link form always. It renders only while this block's source popover is open.
export function MediaSourcePopover({
  blockId,
  config,
  readAnchor,
  onEmbed,
}: {
  blockId: string;
  config: MediaSourceConfig;
  readAnchor: () => HTMLElement | null;
  onEmbed: (url: string) => boolean;
}) {
  "use no memo";

  const readOnly = useEditorReadOnly();
  const open = usePluginOption(mediaUiPlugin, "source") === blockId;
  if (!open || readOnly) {
    return null;
  }

  return (
    <MediaSourceForm blockId={blockId} config={config} readAnchor={readAnchor} onEmbed={onEmbed} />
  );
}

function MediaSourceForm({
  blockId,
  config,
  readAnchor,
  onEmbed,
}: {
  blockId: string;
  config: MediaSourceConfig;
  readAnchor: () => HTMLElement | null;
  onEmbed: (url: string) => boolean;
}) {
  "use no memo";

  const anchor = virtualAnchor(
    () => elementRect(readAnchor()),
    () => anchorContext(readAnchor()),
  );
  const editor = useEditorRef();
  const controller = useUploadController();
  const adapter = useFileUploadAdapter();
  const mediaOn = useEditorFeatures().media;
  const canUpload = mediaOn && adapter !== null && controller !== null;
  const fileRef = useRef<HTMLInputElement>(null);
  const errorId = useId();
  const [link, setLink] = useState("");
  const [invalid, setInvalid] = useState(false);

  function close(): void {
    closeMediaSource(editor);
    editor.tf.focus();
  }

  function chooseFile(file: File): void {
    if (controller === null) {
      return;
    }

    closeMediaSource(editor);
    editor.tf.focus();
    controller.start(blockId, file);
  }

  function submitLink(): void {
    const url = embedLinkOf(link);
    if (url === null || !onEmbed(url)) {
      setInvalid(true);
      return;
    }

    close();
  }

  const embedForm = (
    <form
      noValidate
      className="flex flex-col gap-2"
      onSubmit={(event) => {
        event.preventDefault();
        submitLink();
      }}
    >
      <Input
        aria-label={config.linkLabel}
        aria-invalid={invalid}
        aria-describedby={invalid ? errorId : undefined}
        data-media-embed-input=""
        data-media-source-first={canUpload ? undefined : ""}
        value={link}
        placeholder={config.embedPlaceholder}
        type="text"
        inputMode="url"
        autoCapitalize="none"
        autoCorrect="off"
        spellCheck={false}
        onChange={(event) => {
          setLink(event.target.value);
          setInvalid(false);
        }}
      />
      {invalid ? (
        <p id={errorId} role="alert" className="text-destructive text-xs">
          {config.invalidLinkMessage}
        </p>
      ) : null}
      <Button type="submit" size="sm" className="w-full" data-media-embed-submit="">
        {config.embedLabel}
      </Button>
    </form>
  );

  return (
    <Popover open>
      <PopoverAnchor virtualRef={anchor} />
      <PopoverContent
        data-media-source-popover=""
        aria-label={config.label}
        side="bottom"
        align="start"
        sideOffset={4}
        collisionPadding={8}
        hideWhenDetached
        className="w-80 gap-2 p-2"
        onOpenAutoFocus={(event) => {
          event.preventDefault();
          const first = event.currentTarget as HTMLElement | null;
          first?.querySelector<HTMLElement>("[data-media-source-first]")?.focus();
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
        }}
        onPointerDownOutside={() => {
          closeMediaSource(editor);
        }}
        onKeyDown={(event) => {
          // Keys typed here never reach the editor. Escape closes the popover and returns to the editor.
          event.stopPropagation();
          if (onPopoverHistoryKey(editor, event)) {
            return;
          }
          if (event.key === "Escape") {
            event.preventDefault();
            close();
          }
        }}
      >
        {canUpload ? (
          <Tabs defaultValue="upload" className="gap-2">
            <TabsList className="w-full">
              <TabsTrigger value="upload">Upload</TabsTrigger>
              <TabsTrigger value="embed">Embed link</TabsTrigger>
            </TabsList>
            <TabsContent value="upload" className="flex flex-col gap-2">
              <Button
                type="button"
                size="sm"
                className="w-full"
                data-media-source-first=""
                data-media-upload=""
                onClick={() => {
                  fileRef.current?.click();
                }}
              >
                {config.uploadLabel}
              </Button>
              <input
                ref={fileRef}
                type="file"
                accept={config.accept}
                hidden
                data-media-file-input=""
                onChange={(event) => {
                  const file = event.currentTarget.files?.[0];
                  event.currentTarget.value = "";
                  if (file !== undefined) {
                    chooseFile(file);
                  }
                }}
              />
            </TabsContent>
            <TabsContent value="embed">{embedForm}</TabsContent>
          </Tabs>
        ) : (
          embedForm
        )}
      </PopoverContent>
    </Popover>
  );
}

import { useEffect, useId, useRef, useState, type KeyboardEvent } from "react";
import { useEditorReadOnly, useEditorRef, usePluginOption } from "platejs/react";
import { FileText } from "lucide-react";

import { Input } from "@/components/ui/input";
import { Popover, PopoverAnchor, PopoverContent } from "@/components/ui/popover";
import { cn } from "@/lib/utils";

import { PAGE_LINK_ICON_CLASS } from "../elements/page-link-classes";
import { retainScroll } from "./block-toolbar";
import { anchorContext, rangeContextElement, rangeRect, virtualAnchor } from "./anchor-rect";
import {
  PAGE_LINK_SEARCH_SLOW_MS,
  pageLinkDisplayTitle,
  pagesFromSearch,
  type PageEntity,
  type PageProvider,
} from "../../lib/features/editor-page-link";
import { pageLinkProvider } from "../../lib/plugins/editor-page-link";
import {
  cancelPageLinkPicker,
  choosePageLink,
  pageLinkPickerAnchorPoint,
  pageLinkPickerOpen,
  pageLinkPickerPlugin,
} from "../../lib/plugins/editor-page-link-picker";

export function PageLinkPicker() {
  "use no memo";

  const editor = useEditorRef();
  const readOnly = useEditorReadOnly();
  const open = usePluginOption(pageLinkPickerPlugin, "open");

  useEffect(() => {
    if (!open || !readOnly) {
      return;
    }
    retainScroll(() => {
      cancelPageLinkPicker(editor);
    });
  }, [editor, open, readOnly]);

  const provider = pageLinkProvider(editor);
  if (!open || readOnly || provider === null || !pageLinkPickerOpen(editor)) {
    return null;
  }

  return <PageLinkPickerForm editor={editor} provider={provider} />;
}

type SearchResult = { query: string; pages: PageEntity[] | null };

function pickerDomRange(editor: ReturnType<typeof useEditorRef>): Range | null {
  const point = pageLinkPickerAnchorPoint(editor);
  if (point === null) {
    return null;
  }

  try {
    return editor.api.toDOMRange({ anchor: point, focus: point }) ?? null;
  } catch {
    return null;
  }
}

function PageLinkPickerForm({
  editor,
  provider,
}: {
  editor: ReturnType<typeof useEditorRef>;
  provider: PageProvider;
}) {
  "use no memo";

  const [query, setQuery] = useState("");
  const [activeRow, setActiveRow] = useState(0);
  const [result, setResult] = useState<SearchResult | null>(null);
  const [slowQuery, setSlowQuery] = useState<string | null>(null);
  const fieldRef = useRef<HTMLInputElement>(null);
  const listId = useId();
  const virtualRef = virtualAnchor(
    () => rangeRect(pickerDomRange(editor)),
    () => anchorContext(rangeContextElement(pickerDomRange(editor))),
  );

  // Each query aborts the previous search. A result for an older query is ignored.
  useEffect(() => {
    const controller = new AbortController();
    let live = true;
    const slowTimer = setTimeout(() => {
      if (live) {
        setSlowQuery(query);
      }
    }, PAGE_LINK_SEARCH_SLOW_MS);

    let pending: Promise<unknown>;
    try {
      pending = provider.search(query, controller.signal);
    } catch {
      pending = Promise.reject(new Error("search threw"));
    }
    void pending.then(
      (value) => {
        if (!live) {
          return;
        }
        clearTimeout(slowTimer);
        setResult({ query, pages: pagesFromSearch(value) });
      },
      () => {
        if (!live) {
          return;
        }
        clearTimeout(slowTimer);
        setResult({ query, pages: null });
      },
    );

    return () => {
      live = false;
      clearTimeout(slowTimer);
      controller.abort();
    };
  }, [provider, query]);

  useEffect(() => {
    const focusField = (): void => {
      fieldRef.current?.focus();
    };
    focusField();
    const frame = requestAnimationFrame(focusField);
    return () => {
      cancelAnimationFrame(frame);
    };
  }, []);

  useEffect(() => {
    const onPointerDown = (event: PointerEvent): void => {
      const target = event.target;
      if (target instanceof Element && target.closest("[data-page-link-picker]") !== null) {
        return;
      }

      event.preventDefault();
      retainScroll(() => {
        cancelPageLinkPicker(editor);
      });
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
    };
  }, [editor]);

  const settled = result !== null && result.query === query ? result : null;
  const pages = settled?.pages ?? [];
  const failed = settled !== null && settled.pages === null;
  const searching = settled === null && slowQuery === query;
  const current = pages.length === 0 ? -1 : Math.min(activeRow, pages.length - 1);
  let message = "";
  if (failed) {
    message = "Could not load pages";
  } else if (settled !== null && pages.length === 0) {
    message = "No pages found";
  } else if (searching) {
    message = "Searching…";
  }

  const optionId = (index: number): string => `${listId}-option-${index}`;

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>): void => {
    // Keys typed here never reach the editor.
    event.stopPropagation();
    if (event.nativeEvent.isComposing) {
      return;
    }

    if (event.key === "Escape") {
      event.preventDefault();
      retainScroll(() => {
        cancelPageLinkPicker(editor);
      });
      return;
    }

    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      if (pages.length === 0) {
        return;
      }
      const step = event.key === "ArrowDown" ? 1 : -1;
      setActiveRow((Math.max(current, 0) + step + pages.length) % pages.length);
      return;
    }

    if (event.key === "Enter") {
      event.preventDefault();
      const page = pages[current];
      if (page === undefined) {
        return;
      }
      retainScroll(() => {
        choosePageLink(editor, page);
      });
    }
  };

  return (
    <Popover open>
      <PopoverAnchor virtualRef={virtualRef} />
      <PopoverContent
        data-page-link-picker=""
        aria-label="Page search"
        side="bottom"
        align="start"
        sideOffset={4}
        collisionPadding={8}
        hideWhenDetached
        onOpenAutoFocus={(event) => {
          event.preventDefault();
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
        }}
        className="w-72 gap-2 p-2"
      >
        <Input
          ref={fieldRef}
          role="combobox"
          aria-label="Search pages"
          aria-expanded={pages.length > 0}
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={current >= 0 ? optionId(current) : undefined}
          placeholder="Search pages"
          type="text"
          autoComplete="off"
          autoCapitalize="none"
          autoCorrect="off"
          spellCheck={false}
          value={query}
          onChange={(event) => {
            setQuery(event.target.value);
            setActiveRow(0);
          }}
          onKeyDown={onKeyDown}
        />
        <div role="listbox" id={listId} aria-label="Pages" className="flex flex-col">
          {pages.map((page, index) => (
            <div
              key={`${page.pageId}-${index}`}
              id={optionId(index)}
              role="option"
              aria-selected={index === current}
              data-page-option={page.pageId}
              className={cn(
                "flex cursor-default items-center gap-2 rounded-sm px-2 py-1 text-sm",
                index === current && "bg-accent text-accent-foreground",
              )}
              onMouseDown={(event) => {
                event.preventDefault();
              }}
              onClick={() => {
                retainScroll(() => {
                  choosePageLink(editor, page);
                });
              }}
            >
              {page.icon !== undefined ? (
                <span aria-hidden="true" className={PAGE_LINK_ICON_CLASS}>
                  {page.icon}
                </span>
              ) : (
                <FileText aria-hidden="true" className={PAGE_LINK_ICON_CLASS} />
              )}
              <span className="min-w-0 truncate">{pageLinkDisplayTitle(page.title)}</span>
            </div>
          ))}
        </div>
        <p
          data-page-link-status=""
          aria-live="polite"
          className="text-muted-foreground px-2 py-1.5 text-sm"
        >
          {message}
        </p>
      </PopoverContent>
    </Popover>
  );
}

