import { useEffect, type ReactNode } from "react";
import { Bookmark, Link, SquarePlay } from "lucide-react";
import { useEditorReadOnly, useEditorRef, usePluginOption } from "platejs/react";

import { Popover, PopoverAnchor, PopoverContent } from "@/components/ui/popover";

import { anchorContext, rangeContextElement, rangeRect, virtualAnchor } from "./anchor-rect";
import { EditorTextButton } from "./block-toolbar";

import { runEditorCommand } from "../../lib/commands/editor-commands";
import {
  applyPasteUrlAction,
  clearPasteUrlOffer,
  pasteUrlActionsFor,
  pasteUrlPlugin,
} from "../../lib/paste/editor-paste-url";

export function PasteUrlMenu() {
  const editor = useEditorRef();
  const readOnly = useEditorReadOnly();
  const offer = usePluginOption(pasteUrlPlugin, "offer");
  const actions = offer === undefined ? [] : pasteUrlActionsFor(editor, offer.url);
  const virtualRef = virtualAnchor(
    () => rangeRect(pasteDomRange(editor)),
    () => anchorContext(rangeContextElement(pasteDomRange(editor))),
  );

  useEffect(() => {
    if (readOnly && offer !== undefined) {
      clearPasteUrlOffer(editor);
    }
  }, [editor, offer, readOnly]);

  useEffect(() => {
    if (readOnly || offer === undefined) {
      return;
    }

    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key === "Escape") {
        clearPasteUrlOffer(editor);
      }
    };
    const onPointerDown = (event: PointerEvent): void => {
      const target = event.target;
      if (target instanceof Element && target.closest("[data-paste-url-menu]") !== null) {
        return;
      }

      clearPasteUrlOffer(editor);
    };
    document.addEventListener("keydown", onKeyDown);
    document.addEventListener("pointerdown", onPointerDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.removeEventListener("pointerdown", onPointerDown);
    };
  }, [editor, offer, readOnly]);

  if (readOnly || offer === undefined || actions.length === 0) {
    return null;
  }

  return (
    <Popover open>
      <PopoverAnchor virtualRef={virtualRef} />
      <PopoverContent
        data-paste-url-menu=""
        aria-label="Paste options"
        side="bottom"
        align="start"
        sideOffset={4}
        collisionPadding={8}
        hideWhenDetached
        onOpenAutoFocus={(event) => {
          event.preventDefault();
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
        }}
        className="w-auto gap-1 p-1"
      >
        {actions.map((action) => (
          <EditorTextButton
            key={action.id}
            variant="outline"
            label={action.label}
            icon={pasteActionIcon(action.id)}
            className="w-full justify-start"
            onMouseDown={(event) => {
              event.preventDefault();
            }}
            onClick={() => {
              runEditorCommand(editor, applyPasteUrlAction, action.id);
            }}
          />
        ))}
        <EditorTextButton
          variant="outline"
          label="Keep as link"
          icon={<Link aria-hidden="true" />}
          data-default="true"
          className="w-full justify-start"
          onMouseDown={(event) => {
            event.preventDefault();
          }}
          onClick={() => {
            clearPasteUrlOffer(editor);
          }}
        />
      </PopoverContent>
    </Popover>
  );
}

function pasteDomRange(editor: ReturnType<typeof useEditorRef>): Range | null {
  if (!editor.selection) {
    return null;
  }

  return editor.api.toDOMRange(editor.selection) ?? null;
}

function pasteActionIcon(id: string): ReactNode {
  if (id === "bookmark") {
    return <Bookmark aria-hidden="true" />;
  }

  if (id === "embed") {
    return <SquarePlay aria-hidden="true" />;
  }

  return <Link aria-hidden="true" />;
}

import { useEffect, useState } from "react";

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Spinner } from "@/components/ui/spinner";

import { loadPdfPreview } from "../../lib/features/editor-pdf-preview";
import { MediaDownloadButton } from "./media-download-button";

const FAILED_MESSAGE = "This PDF can't be previewed.";

function ignore(): void {}

type Preview = { status: "ready"; objectUrl: string } | { status: "failed" };

// A PDF opened in the browser's viewer. Nothing is fetched until the dialog is open. Closing aborts
// the fetch and revokes the object URL. The parent gives each open a new key, so every open starts
// in the loading state and never shows the result of an earlier open.
export function PdfPreviewDialog({
  name,
  url,
  open,
  onOpenChange,
  returnFocus,
}: {
  name: string;
  url: string; // the resolved url of the file
  open: boolean;
  onOpenChange: (open: boolean) => void;
  returnFocus: () => void; // where focus goes when the dialog closes
}) {
  const [preview, setPreview] = useState<Preview | undefined>(undefined);

  useEffect(() => {
    if (!open) {
      return;
    }

    const controller = new AbortController();
    let objectUrl: string | undefined;
    loadPdfPreview(url, controller.signal).then(
      (result) => {
        if (controller.signal.aborted) {
          return;
        }
        if (!result.ok) {
          setPreview({ status: "failed" });
          return;
        }
        objectUrl = URL.createObjectURL(result.blob);
        setPreview({ status: "ready", objectUrl });
      },
      () => {
        if (!controller.signal.aborted) {
          setPreview({ status: "failed" });
        }
      },
    );
    return () => {
      controller.abort();
      if (objectUrl !== undefined) {
        URL.revokeObjectURL(objectUrl);
      }
    };
  }, [open, url]);

  const state = preview?.status ?? "loading";

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="h-[85vh] grid-rows-[auto_minmax(0,1fr)] sm:max-w-4xl"
        onKeyDown={(event) => {
          // Keys typed in the dialog never reach the editor.
          event.stopPropagation();
        }}
        onCloseAutoFocus={(event) => {
          // Radix would return focus to a DialogTrigger, and this dialog has none, so focus would
          // fall to the body. The parent says where it goes.
          event.preventDefault();
          returnFocus();
        }}
      >
        <DialogHeader className="flex-row items-center gap-2 pr-10">
          <DialogTitle className="min-w-0 flex-1 truncate">{name}</DialogTitle>
          <DialogDescription className="sr-only">PDF preview</DialogDescription>
          <MediaDownloadButton kind="file" href={url} name={name} onDownload={ignore} />
        </DialogHeader>
        <div data-pdf-preview-state={state} className="min-h-0">
          {preview?.status === "ready" ? (
            // No sandbox attribute: a sandboxed frame disables the browser's PDF viewer. The frame
            // only ever holds the object URL of a blob that loadPdfPreview checked as a PDF.
            <iframe title={name} src={preview.objectUrl} className="size-full border-0" />
          ) : preview?.status === "failed" ? (
            <div className="text-muted-foreground flex h-full items-center justify-center text-sm">
              {FAILED_MESSAGE}
            </div>
          ) : (
            <div className="flex h-full items-center justify-center">
              <Spinner aria-label="Loading the PDF" />
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState, type CSSProperties } from "react";
import { Baseline, Check } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

import { PALETTE_TOKENS, type PaletteToken } from "../../lib/document/editor-document-schema";
import type { HighlightState, TextColorState } from "../../lib/commands/editor-commands";
export const COLUMNS = 5;

export function tokenLabel(token: string): string {
  return token.charAt(0).toUpperCase() + token.slice(1);
}

function colorControlLabel(
  textColor: PaletteToken | null | "mixed",
  highlight: PaletteToken | null | "mixed",
): string {
  if (textColor === "mixed" || highlight === "mixed") {
    return "Color: mixed";
  }
  if (textColor === null && highlight === null) {
    return "Color: Default";
  }

  const parts: string[] = [];
  if (textColor) {
    parts.push(`${tokenLabel(textColor)} text`);
  }
  if (highlight) {
    parts.push(`${tokenLabel(highlight)} highlight`);
  }

  return `Color: ${parts.join(", ")}`;
}

function colorControlStyle(
  textColor: PaletteToken | null | "mixed",
  highlight: PaletteToken | null | "mixed",
): CSSProperties {
  const style: CSSProperties = {};
  if (textColor && textColor !== "mixed") {
    style.color = `var(--editor-text-${textColor})`;
  }
  if (highlight && highlight !== "mixed") {
    style.backgroundColor = `var(--editor-bg-${highlight})`;
  }

  return style;
}

function keepSelection(event: { preventDefault: () => void }): void {
  event.preventDefault();
}

export function SelectionColorMenu({
  textColor,
  highlight,
  disabled,
  reason,
  tabIndex,
  onTextColor,
  onHighlight,
  onOpenChange,
  onRestore,
}: {
  textColor: TextColorState;
  highlight: HighlightState;
  disabled: boolean;
  reason?: string;
  tabIndex?: number;
  onTextColor: (token: PaletteToken | null) => void;
  onHighlight: (token: PaletteToken | null) => void;
  onOpenChange: (open: boolean) => void;
  onRestore?: () => void;
}) {
  const [open, setOpen] = useState(false);
  const summary = colorControlLabel(textColor, highlight);

  function setOpenState(next: boolean): void {
    setOpen(next);
    onOpenChange(next);
  }

  return (
    <Popover open={open} onOpenChange={setOpenState} modal={false}>
      <Tooltip>
        <TooltipTrigger asChild>
          <PopoverTrigger asChild>
            <Button
              type="button"
              size="icon"
              variant="ghost"
              aria-label="Color"
              disabled={disabled}
              tabIndex={tabIndex}
              data-toolbar-control="color"
              data-color-summary={summary}
              className="disabled:pointer-events-auto"
              style={colorControlStyle(textColor, highlight)}
              onMouseDown={keepSelection}
            >
              <Baseline aria-hidden="true" />
            </Button>
          </PopoverTrigger>
        </TooltipTrigger>
        <TooltipContent>{disabled && reason ? reason : summary}</TooltipContent>
      </Tooltip>
      <PopoverContent
        data-selection-toolbar-portal=""
        data-selection-color-menu=""
        aria-label="Text and highlight color"
        side="bottom"
        align="start"
        sideOffset={8}
        collisionPadding={8}
        hideWhenDetached
        onOpenAutoFocus={(event) => {
          event.preventDefault();
          const content = event.currentTarget;
          if (!(content instanceof HTMLElement)) {
            return;
          }
          const first = content.querySelector("[data-color-swatch]");
          if (first instanceof HTMLElement) {
            first.focus();
          }
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
          onRestore?.();
        }}
        onKeyDown={moveSwatchFocus}
        className="w-auto gap-2 p-2"
      >
        <SwatchSection label="Text color" kind="text" current={textColor} onChoose={onTextColor} />
        <SwatchSection
          label="Highlight"
          kind="highlight"
          current={highlight}
          onChoose={onHighlight}
        />
      </PopoverContent>
    </Popover>
  );
}

function SwatchSection({
  label,
  kind,
  current,
  onChoose,
}: {
  label: string;
  kind: "text" | "highlight";
  current: PaletteToken | null | "mixed";
  onChoose: (token: PaletteToken | null) => void;
}) {
  return (
    <div role="group" aria-label={label} className="grid grid-cols-5 gap-1">
      <p className="text-muted-foreground col-span-5 text-xs">{label}</p>
      <Swatch
        label={kind === "text" ? "Default text color" : "Default highlight"}
        pressed={current === null}
        kind={kind}
        token={null}
        onChoose={onChoose}
      />
      {PALETTE_TOKENS.map((token) => (
        <Swatch
          key={token}
          label={kind === "text" ? `${tokenLabel(token)} text` : `${tokenLabel(token)} highlight`}
          pressed={current === token}
          kind={kind}
          token={token}
          onChoose={onChoose}
        />
      ))}
    </div>
  );
}

function Swatch({
  label,
  pressed,
  kind,
  token,
  onChoose,
}: {
  label: string;
  pressed: boolean;
  kind: "text" | "highlight";
  token: PaletteToken | null;
  onChoose: (token: PaletteToken | null) => void;
}) {
  const color = token === null ? undefined : `var(--editor-text-${token})`;
  const background = token === null ? undefined : `var(--editor-bg-${token})`;

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span className="inline-flex">
          <Button
            type="button"
            size="icon"
            variant="ghost"
            aria-label={label}
            aria-pressed={pressed}
            data-color-swatch=""
            data-color-kind={kind}
            data-color-token={token ?? "default"}
            className={cn(
              "relative",
              kind === "highlight" && token === null && "border-border border bg-transparent",
              pressed && "ring-ring ring-offset-popover ring-2 ring-offset-2",
            )}
            style={kind === "text" ? { color } : { backgroundColor: background }}
            onMouseDown={keepSelection}
            onClick={() => {
              onChoose(token);
            }}
          >
            A
            {pressed ? (
              <Check
                aria-hidden="true"
                data-color-check=""
                className="absolute top-0.5 right-0.5 size-2.5"
              />
            ) : null}
          </Button>
        </span>
      </TooltipTrigger>
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  );
}

export function moveSwatchFocus(event: React.KeyboardEvent<HTMLElement>): void {
  if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.key)) {
    return;
  }

  const buttons = Array.from(
    event.currentTarget.querySelectorAll<HTMLElement>("[data-color-swatch]"),
  );
  const index = buttons.indexOf(document.activeElement as HTMLElement);
  if (index < 0) {
    return;
  }

  event.preventDefault();
  const delta =
    event.key === "ArrowRight"
      ? 1
      : event.key === "ArrowLeft"
        ? -1
        : event.key === "ArrowDown"
          ? COLUMNS
          : -COLUMNS;
  const next = buttons[index + delta];
  next?.focus();
}

import { type ReactNode } from "react";
import { AlignCenter, AlignJustify, AlignLeft, AlignRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { TEXT_ALIGNS, type TextAlign } from "../../lib/document/editor-document-schema";
import { MENU_ITEM_ACTIVE_CHECKED } from "../../lib/features/editor-menu-active";
import type { selectionToolbarModel } from "../../lib/features/editor-selection-toolbar";
