export type CalloutIcon = (typeof CALLOUT_ICONS)[number];

export const CALLOUT_DEFAULT_ICON: CalloutIcon = "lightbulb";

// Stored languages. Absence means plaintext, so plaintext is not a stored value.
export const CODE_LANGS = [
  "typescript",
  "tsx",
  "javascript",
  "jsx",
  "json",
  "html",
  "css",
  "bash",
  "python",
  "go",
  "rust",
  "sql",
  "markdown",
  "yaml",
  "diff",
] as const;

export type CodeLang = (typeof CODE_LANGS)[number];

// A simple table, not a database. 50×20 is the stored cap shared by validate, normalize, and paste.
export const TABLE_MAX_ROWS = 50;
export const TABLE_MAX_COLUMNS = 20;

export const CODE_LANG_LABELS = {
  plaintext: "Plain text",
  typescript: "TypeScript",
  tsx: "TSX",
  javascript: "JavaScript",
  jsx: "JSX",
  json: "JSON",
  html: "HTML",
  css: "CSS",
  bash: "Bash",
  python: "Python",
  go: "Go",
  rust: "Rust",
  sql: "SQL",
  markdown: "Markdown",
  yaml: "YAML",
  diff: "Diff",
} as const satisfies Record<CodeLang | "plaintext", string>;

// Paste and insert class tokens. Stored names that are not listed here stay themselves.
const CODE_LANG_ALIASES = {
  ts: "typescript",
  js: "javascript",
  sh: "bash",
  shell: "bash",
  py: "python",
  yml: "yaml",
  xml: "html",
  html: "html",
  md: "markdown",
} as const satisfies Record<string, CodeLang>;

function aliasCodeLang(token: string): CodeLang | undefined {
  for (const [alias, lang] of Object.entries(CODE_LANG_ALIASES)) {
    if (alias === token) {
      return lang;
    }
  }

  return undefined;
}

export function codeLangFromToken(token: string): CodeLang | null {
  const normalized = token.trim().toLowerCase();
  if (normalized.length === 0 || normalized === "plaintext") {
    return null;
  }

  const alias = aliasCodeLang(normalized);
  if (alias !== undefined) {
    return alias;
  }

  const stored = CODE_LANGS.find((lang) => lang === normalized);
  return stored ?? null;
}

// Plain indent is the same integer as list depth. It is stored only in the 1..6 range.
const headingElementRule = {
  attrs: ["id", "align", "indent", "textTone", "backgroundTone"],
  attrValues: {
    align: TEXT_ALIGNS,
    indent: LIST_INDENTS,
    textTone: PALETTE_TOKENS,
    backgroundTone: PALETTE_TOKENS,
  },
} as const;

export const EQUATION_EXPRESSION_MAX = 4000;

// Length is UTF-16 code units. Tab and newline are the only allowed controls.
export function isStoredEquationExpression(value: unknown): value is string {
  if (typeof value !== "string" || value.length > EQUATION_EXPRESSION_MAX) {
    return false;
  }

  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code === 0x09 || code === 0x0a) {
      continue;
    }
    if (code <= 0x1f || code === 0x7f) {
      return false;
    }
  }

  return true;
}

function checkEquationNode(
  node: Record<string, unknown>,
  path: number[],
): readonly TableGridIssue[] {
  if ("texExpression" in node && isStoredEquationExpression(node.texExpression)) {
    return [];
  }

  return [
    {
      path,
      message: `${formatBlockLabel(path)} has an unsupported texExpression. Restore from a backup or remove the block.`,
    },
  ];
}

// A stored inline date is a real calendar date, YYYY-MM-DD. See editor-date-value.ts.
function checkDateNode(node: Record<string, unknown>, path: number[]): readonly TableGridIssue[] {
  if ("date" in node && isStoredDate(node.date)) {
    return [];
  }

  return [
    {
      path,
      message: `${formatBlockLabel(path)} has an unsupported date. Restore from a backup or remove the block.`,
    },
  ];
}

// Footnote nodes. The reference is an inline void, the definition a top-level block. Numbers are derived.
export const FOOTNOTE_REF_KEY = "footnote_ref";
export const FOOTNOTE_DEF_KEY = "footnote_def";

function checkFootnoteRefNode(
  node: Record<string, unknown>,
  path: number[],
): readonly TableGridIssue[] {
  if (isFootnoteId(node.footnoteId)) {
    return [];
  }

  return [
    {
      path,
      message: `${formatBlockLabel(path)} has an unsupported footnoteId. Restore from a backup or remove the block.`,
    },
  ];
}

export const SYNCED_REF_KEY = "synced_ref";

export const SYNCED_TARGET_ID_MAX = 200;

// A target id is a stable block id. It is not a copy of the target.
export function isStoredSyncedTargetId(value: unknown): value is string {
  if (typeof value !== "string" || value.length === 0 || value.length > SYNCED_TARGET_ID_MAX) {
    return false;
  }

  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code <= 0x1f || code === 0x7f) {
      return false;
    }
  }

  return true;
}

function checkSyncedRefNode(
  node: Record<string, unknown>,
  path: number[],
): readonly TableGridIssue[] {
  if ("targetBlockId" in node && isStoredSyncedTargetId(node.targetBlockId)) {
    return [];
  }

  return [
    {
      path,
      message: `${formatBlockLabel(path)} has an unsupported targetBlockId. Restore from a backup or remove the block.`,
    },
  ];
}

function checkBookmarkNode(
  node: Record<string, unknown>,
  path: number[],
): readonly TableGridIssue[] {
  const issues: TableGridIssue[] = [];
  if (storedBookmarkUrl(node.url) === undefined) {
    issues.push({
      path,
      message: `${formatBlockLabel(path)} has an unsupported url. Restore from a backup or remove the block.`,
    });
  }

  bookmarkTextIssue(issues, node, path, "title", BOOKMARK_TITLE_MAX);
  bookmarkTextIssue(issues, node, path, "description", BOOKMARK_DESCRIPTION_MAX);
  bookmarkTextIssue(issues, node, path, "siteName", BOOKMARK_SITE_NAME_MAX);

  if ("imageUrl" in node) {
    const imageUrl = node.imageUrl;
    if (typeof imageUrl !== "string" || normalizeBookmarkImageUrl(imageUrl) !== imageUrl) {
      issues.push({
        path,
        message: `${formatBlockLabel(path)} has an unsupported imageUrl. Restore from a backup or remove the attribute.`,
      });
    }
  }

  if ("fetchedAt" in node && !isBookmarkFetchedAt(node.fetchedAt)) {
    issues.push({
      path,
      message: `${formatBlockLabel(path)} has an unsupported fetchedAt. Restore from a backup or remove the attribute.`,
    });
  }

  return issues;
}

function bookmarkTextIssue(
  issues: TableGridIssue[],
  node: Record<string, unknown>,
  path: number[],
  key: string,
  limit: number,
): void {
  if (!(key in node) || isStoredBookmarkText(node[key], limit)) {
    return;
  }

  issues.push({
    path,
    message: `${formatBlockLabel(path)} has an unsupported ${key}. Restore from a backup or remove the attribute.`,
  });
}

export const EDITOR_ELEMENT_RULES = [
  {
    type: "p",
    attrs: [
      "id",
      "align",
      "lineHeight",
      "indent",
      "listStyleType",
      "listStart",
      "listRestart",
      "listRestartPolite",
      "checked",
      "textTone",
      "backgroundTone",
    ],
    attrValues: {
      align: TEXT_ALIGNS,
      lineHeight: LINE_HEIGHTS,
      indent: LIST_INDENTS,
      listStyleType: LIST_STYLES,
      checked: [true, false],
      textTone: PALETTE_TOKENS,
      backgroundTone: PALETTE_TOKENS,
    },
    attrRanges: {
      listStart: LIST_NUMBER_RANGE,
      listRestart: LIST_NUMBER_RANGE,
      listRestartPolite: LIST_NUMBER_RANGE,
    },
    // indent is a list depth with listStyleType, and a plain block indent without it.
    // Numbering attrs are kept only on decimal items. checked is kept only on todo items.
    // Plate deletes listStart on disc and leaves listRestart, so a disc item would not
    // round-trip those attrs.
    attrRequires: {
      listStart: { attr: "listStyleType", values: ["decimal"] },
      listRestart: { attr: "listStyleType", values: ["decimal"] },
      listRestartPolite: { attr: "listStyleType", values: ["decimal"] },
      checked: { attr: "listStyleType", values: ["todo"] },
    },
  },
  // Headings do not take lineHeight. Their leading is fixed by the heading component.
  { type: "h1", ...headingElementRule },
  { type: "h2", ...headingElementRule },
  { type: "h3", ...headingElementRule },
  // Alignment and line height stay on the child paragraphs. A quote stores its id, plain indent,
  // and tones. Tones and indent are block attrs on the quote itself. Child paragraphs keep their own.
  {
    type: KEYS.blockquote,
    attrs: ["id", "indent", "textTone", "backgroundTone"],
    attrValues: { indent: LIST_INDENTS, textTone: PALETTE_TOKENS, backgroundTone: PALETTE_TOKENS },
    childTypes: [KEYS.p],
  },
  // A divider is a void. It stores only its id, never align, line height, or list attrs.
  {
    type: KEYS.hr,
    attrs: ["id"],
    isVoid: true,
  },
  // Custom void. Plate has no bookmark plugin. The url is the link. The other
  // fields are a sanitized preview cache and can be missing without losing it.
  {
    type: BOOKMARK_KEY,
    attrs: ["id", "url", "title", "description", "siteName", "imageUrl", "fetchedAt"],
    isVoid: true,
    validateChildren: (node, path) => checkBookmarkNode(node, path),
  },
  // Custom void, like the bookmark. A file or embed link with its own width, alignment and caption.
  // An invalid attribute is dropped with a repair, so the block stays. A bad url makes a placeholder.
  {
    type: IMAGE_KEY,
    attrs: ["id", "url", "name", "size", "mime", "width", "align", "caption"],
    isVoid: true,
    repairAttrs: ["url", "name", "size", "mime", "width", "align", "caption"],
  },
  // Custom void, like the image without its width, alignment or caption. A bad url makes a placeholder.
  {
    type: FILE_KEY,
    attrs: ["id", "url", "name", "size", "mime"],
    isVoid: true,
    repairAttrs: ["url", "name", "size", "mime"],
  },
  // Custom void, like the image: a video file or embed link with the same width, alignment and caption.
  {
    type: VIDEO_KEY,
    attrs: ["id", "url", "name", "size", "mime", "width", "align", "caption"],
    isVoid: true,
    repairAttrs: ["url", "name", "size", "mime", "width", "align", "caption"],
  },
  // Custom void, like the file with a caption and no width or alignment.
  {
    type: AUDIO_KEY,
    attrs: ["id", "url", "name", "size", "mime", "caption"],
    isVoid: true,
    repairAttrs: ["url", "name", "size", "mime", "caption"],
  },
  // Custom void, like the video: a YouTube or Vimeo link. Its source is read as one, so a bad provider,
  // id or hash clears it, and any other bad field is dropped. The validator does that, not repairAttrs.
  {
    type: EMBED_KEY,
    attrs: ["id", ...EMBED_FIELD_KEYS],
    isVoid: true,
    repairAttrs: EMBED_FIELD_KEYS,
  },
  // A link to a page the host resolves. title is the fallback shown while or when the page
  // cannot be resolved, and kind (link or child) only picks the icon. Same places as a bookmark.
  {
    type: PAGE_LINK_KEY,
    attrs: ["id", "pageId", "title", "kind"],
    attrValues: { kind: PAGE_LINK_KINDS },
    isVoid: true,
    validateChildren: (node, path) => checkPageLinkNode(node, path),
  },
  // Plate's toc node (@platejs/toc 53.0.0, key "toc") is a void. The outline is
  // derived on render. maxDepth is 1, 2, or 3, and absence means 3.
  {
    type: KEYS.toc,
    attrs: ["id", "maxDepth"],
    attrValues: { maxDepth: [1, 2, 3] },
    isVoid: true,
  },
  // @platejs/math 53.3.12 BaseEquationPlugin: key KEYS.equation ("equation"),
  // void, and texExpression is the only stored expression. Rendered HTML is
  // derived. html, rendered, and displayMode are not attributes.
  {
    type: KEYS.equation,
    attrs: ["id", "texExpression"],
    isVoid: true,
    validateChildren: (node, path) => checkEquationNode(node, path),
  },
  // Same-document reference. The target is stored once. targetBlockId is that
  // block's id. A copy of the target content is not an attribute.
  {
    type: SYNCED_REF_KEY,
    attrs: ["id", "targetBlockId"],
    isVoid: true,
    validateChildren: (node, path) => checkSyncedRefNode(node, path),
  },
  // Plate's callout attrs are icon and variant. Paragraphs keep their own attrs,
  // so a list inside a callout stays a list. backgroundColor is not stored.
  {
    type: KEYS.callout,
    attrs: ["id", "icon", "variant"],
    attrValues: {
      icon: CALLOUT_ICONS,
      variant: CALLOUT_TONES,
    },
    childTypes: [KEYS.p],
  },
  // Own container, not @platejs/toggle: its flat indent model collides with indent → listStyleType.
  {
    type: KEYS.toggle,
    attrs: ["id"],
    childTypes: [
      KEYS.p,
      KEYS.toggle,
      KEYS.blockquote,
      KEYS.callout,
      KEYS.hr,
      BOOKMARK_KEY,
      IMAGE_KEY,
      FILE_KEY,
      VIDEO_KEY,
      AUDIO_KEY,
      EMBED_KEY,
      PAGE_LINK_KEY,
      KEYS.codeBlock,
      KEYS.table,
      KEYS.toc,
      KEYS.equation,
      SYNCED_REF_KEY,
    ],
    firstChildTypes: [KEYS.p, KEYS.h1, KEYS.h2, KEYS.h3],
    firstChildForbiddenAttrs: ["listStyleType", "indent", "checked"],
    maxNesting: 3,
    reportParent: "first",
    reportedFirstChild: {
      [KEYS.h1]: "toggle-h1",
      [KEYS.h2]: "toggle-h2",
      [KEYS.h3]: "toggle-h3",
    },
  },
  // Plate's code block. lang is absent for plaintext. Tokens are decorations, not children.
  {
    type: KEYS.codeBlock,
    attrs: ["id", "lang"],
    attrValues: { lang: CODE_LANGS },
    repairAttrs: ["lang"],
    childTypes: [KEYS.codeLine],
  },
  {
    type: KEYS.codeLine,
    attrs: ["id"],
    marks: false,
    reportContainer: true,
  },
  // Plate's table > tr > td|th > p. colSizes is one width per grid column.
  // null in that array is an automatic column. Absence of the array means every
  // column is automatic. Spans are Plate's colSpan and rowSpan. Absence means 1.
  // A table is not a list, indent, align, or line-height target. Paragraphs inside cells are.
  {
    type: KEYS.table,
    attrs: ["id", "colSizes"],
    childTypes: [KEYS.tr],
    maxChildren: TABLE_MAX_ROWS,
    maxNesting: 1,
    validateChildren: (node, path) =>
      checkTableGrid(node, path, { maxRows: TABLE_MAX_ROWS, maxColumns: TABLE_MAX_COLUMNS }).issues,
  },
  {
    type: KEYS.tr,
    attrs: ["id"],
    childTypes: [KEYS.td, KEYS.th],
    maxChildren: TABLE_MAX_COLUMNS,
  },
  {
    type: KEYS.td,
    attrs: ["id", "colSpan", "rowSpan"],
    childTypes: [KEYS.p],
  },
  {
    type: KEYS.th,
    attrs: ["id", "colSpan", "rowSpan"],
    childTypes: [KEYS.p],
  },
  // Plate column_group (@platejs/layout 53.0.0). Two or three columns, top-level only.
  // A one-column group is unwrapped before this rule runs. Width lives on each column.
  {
    type: KEYS.columnGroup,
    attrs: ["id"],
    childTypes: [KEYS.column],
    maxChildren: 3,
    maxNesting: 1,
  },
  // width is the percent string Plate stores ("50%", "33.33%"). No allowlist: a bad
  // value is rewritten by the column repair, and an unknown attribute still fails closed.
  {
    type: KEYS.column,
    attrs: ["id", "width"],
    childTypes: [
      KEYS.p,
      KEYS.h1,
      KEYS.h2,
      KEYS.h3,
      KEYS.blockquote,
      KEYS.callout,
      KEYS.toggle,
      KEYS.hr,
      KEYS.codeBlock,
      BOOKMARK_KEY,
      IMAGE_KEY,
      FILE_KEY,
      VIDEO_KEY,
      AUDIO_KEY,
      EMBED_KEY,
      PAGE_LINK_KEY,
      KEYS.table,
      KEYS.toc,
      KEYS.equation,
      SYNCED_REF_KEY,
    ],
  },
  // Inline link. target and rel are chosen at render and are not stored.
  {
    type: KEYS.link,
    attrs: ["id", "url"],
    repairAttrs: ["url"],
  },
  // Inline mention. Plate stores value (display text) and key (item id).
  // This document stores label, entityId, and entityType. value and key are not attributes.
  {
    type: KEYS.mention,
    attrs: ["id", "entityType", "entityId", "label"],
    isVoid: true,
    validateChildren: (node, path) => checkMentionNode(node, path),
  },
  // Inline equation. Same stored expression as the block equation. Lives where the
  // mention lives. Its own type, so the block equation's rules do not change.
  {
    type: KEYS.inlineEquation,
    attrs: ["id", "texExpression"],
    isVoid: true,
    validateChildren: (node, path) => checkEquationNode(node, path),
  },
  // Inline date. A calendar date only. Lives where the inline equation and mention live.
  {
    type: KEYS.date,
    attrs: ["id", "date"],
    isVoid: true,
    validateChildren: (node, path) => checkDateNode(node, path),
  },
  // Inline footnote reference. Lives where the inline date lives. The number is derived, not stored.
  {
    type: FOOTNOTE_REF_KEY,
    attrs: ["id", "footnoteId"],
    isVoid: true,
    validateChildren: (node, path) => checkFootnoteRefNode(node, path),
  },
  // Top-level footnote definition. It holds inline text, with no tone, indent, or alignment.
  // The footnote repair moves a definition anywhere else into a paragraph before this rule runs.
  {
    type: FOOTNOTE_DEF_KEY,
    attrs: ["id", "footnoteId"],
  },
] as const satisfies readonly EditorElementRule[];

export const EDITOR_MARK_RULES: readonly EditorMarkRule[] = [
  { type: KEYS.bold },
  { type: KEYS.italic },
  { type: KEYS.underline },
  { type: KEYS.strikethrough },
  { type: KEYS.code },
  { type: KEYS.sup },
  { type: KEYS.sub },
  { type: KEYS.kbd },
  { type: KEYS.color, values: PALETTE_TOKENS },
  { type: KEYS.backgroundColor, values: PALETTE_TOKENS },
  { type: KEYS.fontSize, values: FONT_SIZES },
  { type: KEYS.fontFamily, values: FONT_FAMILIES },
];

export const CLEARABLE_MARK_KEYS: readonly string[] = EDITOR_MARK_RULES.map((rule) => rule.type);

// Only valid inside a parent. The document root may not hold these. A bare column is not
// listed: the column repair unwraps it before the validator checks the root.
const CHILD_ONLY_ELEMENT_TYPES: ReadonlySet<string> = new Set<string>([
  KEYS.codeLine,
  KEYS.tr,
  KEYS.td,
  KEYS.th,
]);

export function isChildOnlyElementType(type: string): boolean {
  return CHILD_ONLY_ELEMENT_TYPES.has(type);
}

// Inline elements. Slate needs a text leaf before and after each one, and between two of them.
export const INLINE_ELEMENT_TYPES: readonly string[] = [
  KEYS.link,
  KEYS.mention,
  KEYS.inlineEquation,
  KEYS.date,
  FOOTNOTE_REF_KEY,
];

const elementAttrs = new Map<string, ReadonlySet<string>>(
  EDITOR_ELEMENT_RULES.map((rule) => [rule.type, new Set<string>(rule.attrs)]),
);

const elementAttrValues = ruleMaps<readonly (string | number | boolean)[]>((rule) =>
  "attrValues" in rule ? rule.attrValues : undefined,
);

const elementAttrRanges = ruleMaps<IntegerAttrRange>((rule) =>
  "attrRanges" in rule ? rule.attrRanges : undefined,
);

const elementAttrRequires = ruleMaps<AttrRequirement>((rule) =>
  "attrRequires" in rule ? rule.attrRequires : undefined,
);

const elementChildTypes = new Map<string, readonly string[]>(
  EDITOR_ELEMENT_RULES.flatMap((rule) =>
    "childTypes" in rule && rule.childTypes !== undefined ? [[rule.type, rule.childTypes]] : [],
  ),
);

const elementFirstChildTypes = new Map<string, readonly string[]>(
  EDITOR_ELEMENT_RULES.flatMap((rule) =>
    "firstChildTypes" in rule && rule.firstChildTypes !== undefined
      ? [[rule.type, rule.firstChildTypes]]
      : [],
  ),
);

const elementReportedFirstChild = new Map<string, Readonly<Record<string, string>>>(
  EDITOR_ELEMENT_RULES.flatMap((rule) =>
    "reportedFirstChild" in rule && rule.reportedFirstChild !== undefined
      ? [[rule.type, rule.reportedFirstChild]]
      : [],
  ),
);

const elementFirstChildForbiddenAttrs = new Map<string, readonly string[]>(
  EDITOR_ELEMENT_RULES.flatMap((rule) =>
    "firstChildForbiddenAttrs" in rule && rule.firstChildForbiddenAttrs !== undefined
      ? [[rule.type, rule.firstChildForbiddenAttrs]]
      : [],
  ),
);

const elementMaxNesting = new Map<string, number>(
  EDITOR_ELEMENT_RULES.flatMap((rule) =>
    "maxNesting" in rule && rule.maxNesting !== undefined ? [[rule.type, rule.maxNesting]] : [],
  ),
);

const elementMaxChildren = new Map<string, number>(
  EDITOR_ELEMENT_RULES.flatMap((rule) =>
    "maxChildren" in rule && rule.maxChildren !== undefined ? [[rule.type, rule.maxChildren]] : [],
  ),
);

const elementChildValidators = new Map<
  string,
  (node: Record<string, unknown>, path: number[]) => readonly TableGridIssue[]
>(
  EDITOR_ELEMENT_RULES.flatMap((rule) =>
    "validateChildren" in rule && rule.validateChildren !== undefined
      ? [[rule.type, rule.validateChildren]]
      : [],
  ),
);

const elementReportParent = new Map<string, "all" | "first">(
  EDITOR_ELEMENT_RULES.flatMap((rule) =>
    "reportParent" in rule && rule.reportParent !== undefined
      ? [[rule.type, rule.reportParent]]
      : [],
  ),
);

const noForbiddenAttrs: readonly string[] = [];

const voidElementTypes = new Set<string>(
  EDITOR_ELEMENT_RULES.flatMap((rule) => ("isVoid" in rule && rule.isVoid ? [rule.type] : [])),
);

const elementsWithoutMarks = new Set<string>(
  EDITOR_ELEMENT_RULES.flatMap((rule) =>
    "marks" in rule && rule.marks === false ? [rule.type] : [],
  ),
);

const elementRepairAttrs = new Map<string, readonly string[]>(
  EDITOR_ELEMENT_RULES.flatMap((rule) =>
    "repairAttrs" in rule && rule.repairAttrs !== undefined ? [[rule.type, rule.repairAttrs]] : [],
  ),
);

const containerReportingElements = new Set<string>(
  EDITOR_ELEMENT_RULES.flatMap((rule) =>
    "reportContainer" in rule && rule.reportContainer ? [rule.type] : [],
  ),
);

export function allowedChildTypes(type: string): readonly string[] | undefined {
  return elementChildTypes.get(type);
}

export function firstChildTypes(type: string): readonly string[] | undefined {
  return elementFirstChildTypes.get(type);
}

/** The default label type. Existing callers use this when a label must be inserted. */
export function firstChildType(type: string): string | undefined {
  return firstChildTypes(type)?.[0];
}

export function allowsFirstChild(parentType: string, childType: string): boolean {
  const labels = firstChildTypes(parentType);
  return labels !== undefined && labels.some((type) => type === childType);
}

export function reportedFirstChild(parentType: string, childType: string): string | undefined {
  return elementReportedFirstChild.get(parentType)?.[childType];
}

export function reportedFirstChildNames(parentType: string): readonly string[] {
  const reported = elementReportedFirstChild.get(parentType);
  return reported === undefined ? [] : Object.values(reported);
}

export function firstChildForbiddenAttrs(type: string): readonly string[] {
  return elementFirstChildForbiddenAttrs.get(type) ?? noForbiddenAttrs;
}

export function maxNesting(type: string): number | undefined {
  return elementMaxNesting.get(type);
}

export function maxChildren(type: string): number | undefined {
  return elementMaxChildren.get(type);
}

export function elementChildIssues(
  type: string,
  node: Record<string, unknown>,
  path: number[],
): readonly TableGridIssue[] {
  const validate = elementChildValidators.get(type);
  return validate === undefined ? [] : validate(node, path);
}

export function reportsParentFromFirstChild(type: string): boolean {
  return elementReportParent.get(type) === "first";
}

export function isVoidElementType(type: string): boolean {
  return voidElementTypes.has(type);
}

export function elementAllowsMarks(type: string): boolean {
  return !elementsWithoutMarks.has(type);
}

export function repairAttrKeys(type: string): readonly string[] {
  return elementRepairAttrs.get(type) ?? noForbiddenAttrs;
}

export function reportsContainer(type: string): boolean {
  return containerReportingElements.has(type);
}

// The child type a container stores text in. That type is not itself a container.
export function containerContentType(type: string): string | undefined {
  const childTypes = allowedChildTypes(type);
  return childTypes?.find((childType) => allowedChildTypes(childType) === undefined);
}

function ruleMaps<T>(
  pick: (rule: (typeof EDITOR_ELEMENT_RULES)[number]) => Readonly<Record<string, T>> | undefined,
): ReadonlyMap<string, ReadonlyMap<string, T>> {
  const maps = new Map<string, ReadonlyMap<string, T>>();
  for (const rule of EDITOR_ELEMENT_RULES) {
    maps.set(rule.type, declaredMap(pick(rule)));
  }

  return maps;
}

function declaredMap<T>(declared: Readonly<Record<string, T>> | undefined): ReadonlyMap<string, T> {
  const map = new Map<string, T>();
  if (declared === undefined) {
    return map;
  }

  for (const [key, value] of Object.entries(declared)) {
    map.set(key, value);
  }

  return map;
}

export function isWithinAttrRange(value: unknown, range: IntegerAttrRange): boolean {
  return (
    typeof value === "number" && Number.isInteger(value) && value >= range.min && value <= range.max
  );
}

const allowedMarks = new Set<string>(CLEARABLE_MARK_KEYS);

const markValues = new Map<string, readonly string[]>(
  EDITOR_MARK_RULES.flatMap((rule) =>
    rule.values === undefined ? [] : [[rule.type, rule.values]],
  ),
);

export function allowedElementAttrs(type: string): ReadonlySet<string> | undefined {
  return elementAttrs.get(type);
}

export function requiredAttr(type: string, dependent: string): string | undefined {
  return elementAttrRequires.get(type)?.get(dependent)?.attr;
}

// Dependent keys that are present while the attribute they require is missing or not allowed.
export function unsatisfiedDependentAttrs(type: string, node: Record<string, unknown>): string[] {
  const requires = elementAttrRequires.get(type);
  if (requires === undefined) {
    return [];
  }

  const unsatisfied: string[] = [];
  for (const [dependent, requirement] of requires) {
    if (!(dependent in node)) {
      continue;
    }

    const required = requirement.attr;
    if (!(required in node) || !isAllowedElementAttrValue(type, required, node[required])) {
      unsatisfied.push(dependent);
      continue;
    }

    const allowedValues = "values" in requirement ? requirement.values : undefined;
    if (
      allowedValues !== undefined &&
      !allowedValues.some((allowed) => allowed === node[required])
    ) {
      unsatisfied.push(dependent);
    }
  }

  return unsatisfied;
}

export function allowedElementAttrValues(
  type: string,
  attr: string,
): readonly (string | number | boolean)[] | undefined {
  return elementAttrValues.get(type)?.get(attr);
}

export function isAllowedElementAttrValue(type: string, attr: string, value: unknown): boolean {
  if (type === IMAGE_KEY) {
    return isStoredImageAttr(attr, value);
  }

  if (type === FILE_KEY) {
    return isStoredFileAttr(attr, value);
  }

  if (type === VIDEO_KEY) {
    return isStoredVideoAttr(attr, value);
  }

  if (type === EMBED_KEY) {
    return isStoredEmbedAttr(attr, value);
  }

  if (type === AUDIO_KEY) {
    return isStoredAudioAttr(attr, value);
  }

  if (type === KEYS.link && attr === "url") {
    return typeof value === "string" && sanitizeLinkUrl(value) === value;
  }

  const values = allowedElementAttrValues(type, attr);
  if (values !== undefined && !isAllowedValue(value, values)) {
    return false;
  }

  const range = elementAttrRanges.get(type)?.get(attr);
  if (range !== undefined && !isWithinAttrRange(value, range)) {
    return false;
  }

  return true;
}

export function isAllowedMark(mark: string): boolean {
  return allowedMarks.has(mark);
}

export function allowedMarkValues(mark: string): readonly string[] | undefined {
  return markValues.get(mark);
}

export function isAllowedMarkValue(mark: string, value: unknown): boolean {
  const values = allowedMarkValues(mark);
  if (values === undefined) {
    return true;
  }

  return isAllowedValue(value, values);
}

export function isAllowedValue<T extends string | number | boolean>(
  value: unknown,
  values: readonly T[],
): value is T {
  return (
    (typeof value === "string" || typeof value === "number" || typeof value === "boolean") &&
    values.some((allowed) => allowed === value)
  );
}

export function isPaletteToken(value: unknown): value is PaletteToken {
  return isAllowedValue(value, PALETTE_TOKENS);
}

import { ElementApi, KEYS, TextApi, nanoid, type Descendant } from "platejs";

import {
  EDITOR_DOCUMENT_LIMITS,
  EDITOR_SCHEMA_VERSION,
  editorDocumentSchema,
  formatBlockLabel,
  type EditorDocument,
} from "./editor-document";
import { normalizeBlockIds, type Repair } from "./editor-document-ids";
import {
  INLINE_ELEMENT_TYPES,
  allowedChildTypes,
  allowedElementAttrs,
  allowsFirstChild,
  firstChildForbiddenAttrs,
  firstChildTypes,
  elementAllowsMarks,
  isAllowedElementAttrValue,
  isAllowedMark,
  isAllowedMarkValue,
  isChildOnlyElementType,
  isVoidElementType,
  elementChildIssues,
  maxChildren,
  maxNesting,
  repairAttrKeys,
  requiredAttr,
  unsatisfiedDependentAttrs,
} from "./editor-document-schema";
import { isEditorValue, repairColumnContent } from "./editor-column-repair";
import { AUDIO_KEY, AUDIO_URL_REMOVED } from "../features/editor-audio";
import { FILE_KEY, FILE_URL_REMOVED } from "../features/editor-file";
import { IMAGE_KEY, IMAGE_URL_REMOVED } from "../features/editor-image";
import { VIDEO_KEY, VIDEO_URL_REMOVED } from "../features/editor-video";
import {
  EMBED_ATTRS_CLEANED,
  EMBED_KEY,
  EMBED_SOURCE_REMOVED,
  applyCleanedEmbed,
  cleanEmbedFields,
} from "../features/editor-embed";
import { isMediaBlockType } from "../features/editor-media-source";
import { repairMentionInputs } from "../features/editor-mention-node";
import { repairPageLinkContent } from "../features/editor-page-link";
import { repairFootnoteContent } from "../features/editor-footnote-repair";
import { syncedRefRepairs } from "../features/editor-synced-repair";
import type { EditorValue } from "./editor-value";

type Issue = {
  path: number[];
  message: string;
};

export type ParseResult =
  | { status: "ok"; document: EditorDocument; repairs: Repair[] }
  | { status: "invalid"; issues: Issue[]; raw: unknown }
  | { status: "unsupported"; issues: Issue[]; raw: unknown }
  | { status: "future-version"; schemaVersion: number; raw: unknown };

type WalkState = {
  nodes: number;
  invalid: Issue | undefined;
  unsupported: Issue[];
  repairs: Repair[];
};

const textEncoder = new TextEncoder();

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isUnknownArray(value: unknown): value is unknown[] {
  return Array.isArray(value);
}

function invalidResult(raw: unknown, path: number[], message: string): ParseResult {
  return {
    status: "invalid",
    issues: [{ path, message }],
    raw,
  };
}

function reject(state: WalkState, path: number[], message: string): void {
  state.invalid = { path, message };
}

function jsonByteLength(raw: unknown): number | undefined {
  try {
    const json = JSON.stringify(raw);
    if (typeof json !== "string") {
      return 0;
    }

    return textEncoder.encode(json).length;
  } catch {
    return undefined;
  }
}

function createPlateId(): string {
  return nanoid(10);
}

function countNode(state: WalkState, path: number[]): boolean {
  state.nodes += 1;
  if (state.nodes > EDITOR_DOCUMENT_LIMITS.maxNodes) {
    reject(
      state,
      path,
      `This document has more than ${EDITOR_DOCUMENT_LIMITS.maxNodes} blocks. Restore from a backup or remove content.`,
    );
    return false;
  }

  return true;
}

function walkText(
  value: Record<string, unknown>,
  path: number[],
  state: WalkState,
  parentType: string | undefined,
): void {
  if (!countNode(state, path)) {
    return;
  }

  if (typeof value.text !== "string") {
    reject(
      state,
      path,
      `${formatBlockLabel(path)} has text that is not a string. Restore from a backup or retype that block.`,
    );
    return;
  }

  for (const key of Object.keys(value)) {
    if (key === "text") {
      continue;
    }

    if (parentType !== undefined && !elementAllowsMarks(parentType)) {
      state.unsupported.push({
        path,
        message: `${formatBlockLabel(path)} has an unsupported mark "${key}". Restore from a backup or remove the mark.`,
      });
      continue;
    }

    if (!isAllowedMark(key)) {
      state.unsupported.push({
        path,
        message: `${formatBlockLabel(path)} has an unsupported mark "${key}". Restore from a backup or remove the mark.`,
      });
      continue;
    }

    if (isAllowedMarkValue(key, value[key])) {
      continue;
    }

    state.unsupported.push({
      path,
      message: `${formatBlockLabel(path)} has an unsupported ${key} "${markValueLabel(value[key])}". Restore from a backup or remove the mark.`,
    });
  }
}

function markValueLabel(value: unknown): string {
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }

  return "value";
}

function isTextChild(value: unknown): boolean {
  return (
    isRecord(value) && "text" in value && !("children" in value) && typeof value.type !== "string"
  );
}

function structuralChildType(value: unknown): string | undefined {
  if (!isRecord(value) || isTextChild(value)) {
    return undefined;
  }

  if ("children" in value || "type" in value) {
    return typeof value.type === "string" ? value.type : "";
  }

  return undefined;
}

// A void's only legal child is one empty text leaf with no marks. Anything else is
// unsupported: the type is known, and the raw document stays intact.
function isEmptyUnmarkedText(children: unknown[]): boolean {
  const only = children.length === 1 ? children[0] : undefined;
  if (!isRecord(only) || only.text !== "" || "children" in only || "type" in only) {
    return false;
  }

  return Object.keys(only).length === 1 && Object.hasOwn(only, "text");
}

function parentAllowsInlineLink(parentType: string): boolean {
  return (
    parentType !== KEYS.link && !isVoidElementType(parentType) && elementAllowsMarks(parentType)
  );
}

function childIsAllowed(parentType: string, child: unknown): boolean {
  const childTypes = allowedChildTypes(parentType);
  const childType = structuralChildType(child);
  if (childTypes === undefined) {
    if (childType === undefined) {
      return true;
    }

    return (
      INLINE_ELEMENT_TYPES.some((type) => type === childType) && parentAllowsInlineLink(parentType)
    );
  }

  return childType !== undefined && childTypes.some((type) => type === childType);
}

const emptyNesting = new Map<string, number>();

function walkElement(
  value: Record<string, unknown>,
  path: number[],
  state: WalkState,
  nesting: ReadonlyMap<string, number> = emptyNesting,
): void {
  if (path.length > EDITOR_DOCUMENT_LIMITS.maxDepth) {
    reject(
      state,
      path,
      `${formatBlockLabel(path)} is nested deeper than ${EDITOR_DOCUMENT_LIMITS.maxDepth} levels. Restore from a backup or remove the extra nesting.`,
    );
    return;
  }

  if (!countNode(state, path)) {
    return;
  }

  if (!isUnknownArray(value.children) || value.children.length === 0) {
    reject(
      state,
      path,
      `${formatBlockLabel(path)} has no children. Restore from a backup or remove the block.`,
    );
    return;
  }

  const type = value.type;
  if (typeof type !== "string" || type.length === 0) {
    reject(
      state,
      path,
      `${formatBlockLabel(path)} has no block type. Restore from a backup or remove the block.`,
    );
    return;
  }

  const allowed = allowedElementAttrs(type);
  if (allowed === undefined) {
    state.unsupported.push({
      path,
      message: `${formatBlockLabel(path)} uses an unsupported block type "${type}". Restore from a backup or remove the block.`,
    });
  }

  // An embed is cleaned as one block. A bad source clears it, and any other bad field is dropped.
  if (type === EMBED_KEY) {
    const cleaned = cleanEmbedFields(value);
    if (cleaned.cleared) {
      state.repairs.push({ path, message: EMBED_SOURCE_REMOVED });
    } else if (cleaned.dropped) {
      state.repairs.push({ path, message: EMBED_ATTRS_CLEANED });
    }
  }

  const unsatisfied = new Set(unsatisfiedDependentAttrs(type, value));
  const attrKeys = type === EMBED_KEY ? [] : Object.keys(value);

  for (const key of attrKeys) {
    if (key === "type" || key === "children" || key === "id") {
      continue;
    }

    const attr = value[key];
    // An unknown block is already unsupported. A known block with a blob or data url stays invalid.
    // A media block is the exception: its bad url is repaired to a placeholder, like any bad attribute.
    if (
      allowed !== undefined &&
      type !== KEYS.link &&
      !isMediaBlockType(type) &&
      (key === "url" || key === "src") &&
      typeof attr === "string" &&
      (attr.startsWith("blob:") || attr.startsWith("data:"))
    ) {
      const scheme = attr.startsWith("blob:") ? "blob:" : "data:";
      reject(
        state,
        path,
        `${formatBlockLabel(path)} has a ${key} that starts with ${scheme}. Restore from a backup or replace that file.`,
      );
      return;
    }

    if (allowed !== undefined && allowed.has(key)) {
      if (!isAllowedElementAttrValue(type, key, attr)) {
        if (repairAttrKeys(type).some((name) => name === key)) {
          state.repairs.push({
            path,
            message: repairAttrMessage(path, type, key, attr),
          });
          continue;
        }

        state.unsupported.push({
          path,
          message: `${formatBlockLabel(path)} has an unsupported ${key} "${markValueLabel(attr)}". Restore from a backup or remove the attribute.`,
        });
        continue;
      }

      const required = requiredAttr(type, key);
      if (required !== undefined && unsatisfied.has(key)) {
        const requiredPresent =
          required in value && isAllowedElementAttrValue(type, required, value[required]);
        const detail = requiredPresent ? key : `${key} without ${required}`;
        state.unsupported.push({
          path,
          message: `${formatBlockLabel(path)} has an unsupported ${detail}. Restore from a backup or remove the attribute.`,
        });
      }
      continue;
    }

    state.unsupported.push({
      path,
      message: `${formatBlockLabel(path)} has an unsupported attribute "${key}". Restore from a backup or remove the attribute.`,
    });
  }

  for (const issue of elementChildIssues(type, value, path)) {
    state.unsupported.push(issue);
  }

  const voidBlock = isVoidElementType(type);
  if (voidBlock && !isEmptyUnmarkedText(value.children)) {
    state.unsupported.push({
      path,
      message: `${formatBlockLabel(path)} must contain one empty text node. Restore from a backup or remove the block.`,
    });
  }

  const childLimit = allowed === undefined ? undefined : maxChildren(type);
  if (childLimit !== undefined && value.children.length > childLimit) {
    state.unsupported.push({
      path,
      message: `${formatBlockLabel(path)} has ${value.children.length} children. At most ${childLimit} are supported. Restore from a backup or remove the extra blocks.`,
    });
  }

  const nestingLimit = allowed === undefined ? undefined : maxNesting(type);
  let childNesting: ReadonlyMap<string, number> = nesting;
  if (nestingLimit !== undefined) {
    const depth = (nesting.get(type) ?? 0) + 1;
    if (depth > nestingLimit) {
      state.unsupported.push({
        path,
        message: `${formatBlockLabel(path)} is nested deeper than ${nestingLimit} ${type} levels. Restore from a backup or remove the extra nesting.`,
      });
    }

    const nextNesting = new Map(nesting);
    nextNesting.set(type, depth);
    childNesting = nextNesting;
  }

  const labelTypes = allowed === undefined ? undefined : firstChildTypes(type);
  if (labelTypes !== undefined) {
    const first = value.children[0];
    const firstStructuralType = structuralChildType(first);
    if (firstStructuralType !== undefined && !allowsFirstChild(type, firstStructuralType)) {
      state.unsupported.push({
        path,
        message: `${formatBlockLabel(path)} has an unsupported first child type "${firstStructuralType}". Restore from a backup or remove the block.`,
      });
    } else if (
      firstStructuralType !== undefined &&
      allowsFirstChild(type, firstStructuralType) &&
      isRecord(first)
    ) {
      for (const key of firstChildForbiddenAttrs(type)) {
        if (key in first) {
          state.unsupported.push({
            path,
            message: `${formatBlockLabel(path)} has an unsupported label ${key}. Restore from a backup or remove the attribute.`,
          });
        }
      }
    }
  }

  for (let index = 0; index < value.children.length; index += 1) {
    const child = value.children[index];
    const structuralType = structuralChildType(child);
    const allowedLabel =
      index === 0 && structuralType !== undefined && allowsFirstChild(type, structuralType);
    if (!voidBlock && !allowedLabel && !childIsAllowed(type, child)) {
      const childType = structuralChildType(child);
      const detail =
        childType === undefined ? "inline children" : `an unsupported child type "${childType}"`;
      state.unsupported.push({
        path,
        message: `${formatBlockLabel(path)} has ${detail}. Restore from a backup or remove the block.`,
      });
    }

    walkDescendant(child, [...path, index], state, childNesting, type);
    if (state.invalid) {
      return;
    }
  }
}

function repairAttrMessage(path: number[], type: string, key: string, value: unknown): string {
  const label = markValueLabel(value);
  if (type === IMAGE_KEY && key === "url") {
    return IMAGE_URL_REMOVED;
  }
  if (type === FILE_KEY && key === "url") {
    return FILE_URL_REMOVED;
  }
  if (type === VIDEO_KEY && key === "url") {
    return VIDEO_URL_REMOVED;
  }
  if (type === AUDIO_KEY && key === "url") {
    return AUDIO_URL_REMOVED;
  }

  if (key === "lang" && value === "plaintext") {
    return `${formatBlockLabel(path)} stores lang "plaintext". Plaintext is the default, so the language was cleared.`;
  }

  if (key === "lang") {
    return `${formatBlockLabel(path)} has an unsupported lang "${label}". Invalid/unknown language fallback plaintext.`;
  }

  if (key === "url") {
    return `${formatBlockLabel(path)} has an unsafe link URL. The link is shown as text.`;
  }

  return `${formatBlockLabel(path)} has an unsupported ${key} "${label}". The value was removed.`;
}

function nodeAt(content: unknown, path: readonly number[]): Record<string, unknown> | undefined {
  let current: unknown = content;
  for (const index of path) {
    if (Array.isArray(current)) {
      current = current[index];
      continue;
    }

    if (!isRecord(current) || !Array.isArray(current.children)) {
      return undefined;
    }

    current = current.children[index];
  }

  return isRecord(current) ? current : undefined;
}

function dropRepairedAttrs(content: EditorValue, repairs: readonly Repair[]): EditorValue {
  if (repairs.length === 0) {
    return content;
  }

  const copy = structuredClone(content);
  for (const repair of repairs) {
    const node = nodeAt(copy, repair.path);
    if (node === undefined || typeof node.type !== "string") {
      continue;
    }

    if (node.type === EMBED_KEY) {
      applyCleanedEmbed(node);
      continue;
    }

    for (const key of repairAttrKeys(node.type)) {
      if (key in node && !isAllowedElementAttrValue(node.type, key, node[key])) {
        Reflect.deleteProperty(node, key);
      }
    }
  }

  return copy;
}

function walkDescendant(
  value: unknown,
  path: number[],
  state: WalkState,
  nesting: ReadonlyMap<string, number> = emptyNesting,
  parentType?: string,
): void {
  if (!isRecord(value)) {
    reject(
      state,
      path,
      `${formatBlockLabel(path)} is not a block. Restore from a backup or remove the block.`,
    );
    return;
  }

  if ("children" in value || "type" in value) {
    walkElement(value, path, state, nesting);
    return;
  }

  if ("text" in value) {
    walkText(value, path, state, parentType);
    return;
  }

  reject(
    state,
    path,
    `${formatBlockLabel(path)} is not a block. Restore from a backup or remove the block.`,
  );
}

function walkTopLevel(
  value: unknown,
  path: number[],
  state: WalkState,
  nesting: ReadonlyMap<string, number> = emptyNesting,
): void {
  if (!isRecord(value) || !("children" in value || "type" in value)) {
    reject(
      state,
      path,
      `${formatBlockLabel(path)} is not a block. Restore from a backup or remove the block.`,
    );
    return;
  }

  if (typeof value.type === "string" && isChildOnlyElementType(value.type)) {
    state.unsupported.push({
      path,
      message: `${formatBlockLabel(path)} has an unsupported top-level type "${value.type}". Restore from a backup or remove the block.`,
    });
  }

  walkElement(value, path, state, nesting);
}

function isInlineNode(node: Descendant): boolean {
  return ElementApi.isElement(node) && INLINE_ELEMENT_TYPES.some((type) => type === node.type);
}

// Slate needs a text leaf before and after each inline element, and between two of them.
// Adds the empty leaves a stored document already has. Void elements keep their own leaf.
// Input is not checked yet, so anything that is not an element with a children array is returned as it is.
function spaceInlineChildren(node: Descendant): Descendant {
  if (!ElementApi.isElement(node) || isVoidElementType(node.type)) {
    return node;
  }

  let changed = false;
  const children: Descendant[] = [];
  for (const child of node.children) {
    const last = children.at(-1);
    if (isInlineNode(child) && (last === undefined || !TextApi.isText(last))) {
      children.push({ text: "" });
      changed = true;
    }

    const spaced = spaceInlineChildren(child);
    if (spaced !== child) {
      changed = true;
    }
    children.push(spaced);
  }

  const last = children.at(-1);
  if (last !== undefined && isInlineNode(last)) {
    children.push({ text: "" });
    changed = true;
  }

  return changed ? { ...node, children } : node;
}

// Returns the same array when no block needs a leaf.
function spaceInlineContent(content: EditorValue): EditorValue {
  const spaced: Descendant[] = content.map((block) => spaceInlineChildren(block));
  if (spaced.every((block, index) => block === content[index]) || !isEditorValue(spaced)) {
    return content;
  }

  return spaced;
}

export function parseEditorDocument(raw: unknown): ParseResult {
  if (
    isRecord(raw) &&
    typeof raw.schemaVersion === "number" &&
    Number.isFinite(raw.schemaVersion) &&
    raw.schemaVersion > EDITOR_SCHEMA_VERSION
  ) {
    return {
      status: "future-version",
      schemaVersion: raw.schemaVersion,
      raw,
    };
  }

  const bytes = jsonByteLength(raw);
  if (bytes === undefined) {
    return invalidResult(raw, [], "This document cannot be saved as JSON. Restore from a backup.");
  }

  if (bytes > EDITOR_DOCUMENT_LIMITS.maxBytes) {
    return invalidResult(
      raw,
      [],
      `This document is larger than ${EDITOR_DOCUMENT_LIMITS.maxBytes} bytes. Restore from a backup or remove content.`,
    );
  }

  const envelope = editorDocumentSchema.safeParse(raw);
  if (!envelope.success) {
    return invalidResult(
      raw,
      [],
      "This document is missing a schema version, document id, revision, or content. Restore from a backup.",
    );
  }

  const state: WalkState = {
    nodes: 0,
    invalid: undefined,
    unsupported: [],
    repairs: [],
  };
  // Leaves go in before any repair, so the walk and every repair path match the returned content.
  const footnotes = repairFootnoteContent(spaceInlineContent(envelope.data.content));
  const structurally = repairColumnContent(footnotes.content);
  const mentions = repairMentionInputs(structurally.content);
  const pageLinks = repairPageLinkContent(mentions.content);
  const content = pageLinks.content;

  for (let index = 0; index < content.length; index += 1) {
    walkTopLevel(content[index], [index], state);
    if (state.invalid) {
      return {
        status: "invalid",
        issues: [state.invalid],
        raw,
      };
    }
  }

  if (state.unsupported.length > 0) {
    return {
      status: "unsupported",
      issues: state.unsupported,
      raw,
    };
  }

  const normalized = normalizeBlockIds(dropRepairedAttrs(content, state.repairs), createPlateId);

  return {
    status: "ok",
    document: {
      schemaVersion: envelope.data.schemaVersion,
      documentId: envelope.data.documentId,
      revision: envelope.data.revision,
      content: normalized.content,
    },
    repairs: [
      ...footnotes.repairs,
      ...structurally.repairs,
      ...mentions.repairs,
      ...pageLinks.repairs,
      ...state.repairs,
      ...normalized.repairs,
      ...syncedRefRepairs(normalized.content),
    ],
  };
}

import { z } from "zod";

import { EMPTY_EDITOR_VALUE, type EditorValue } from "./editor-value";

export const EDITOR_SCHEMA_VERSION = 1;

export const EDITOR_DOCUMENT_LIMITS = {
  maxDepth: 32,
  maxNodes: 20_000,
  maxBytes: 2_000_000,
} as const;

export const editorDocumentSchema = z.object({
  schemaVersion: z.literal(EDITOR_SCHEMA_VERSION),
  documentId: z.string().min(1),
  revision: z.number().int().nonnegative(),
  content: z.custom<EditorValue>((value): value is EditorValue => Array.isArray(value)),
});

export type EditorDocument = z.infer<typeof editorDocumentSchema>;

export function formatBlockLabel(path: readonly number[]): string {
  return `Block ${path.map((index) => String(index + 1)).join(".")}`;
}

export function createEditorDocument(
  documentId: string,
  content: EditorValue = EMPTY_EDITOR_VALUE,
): EditorDocument {
  return {
    schemaVersion: EDITOR_SCHEMA_VERSION,
    documentId,
    revision: 0,
    content,
  };
}

export function serializeEditorDocument(document: EditorDocument): string {
  return JSON.stringify({
    schemaVersion: document.schemaVersion,
    documentId: document.documentId,
    revision: document.revision,
    content: document.content,
  });
}

import type { EditorValue } from "./editor-value";

export type SaveRequest = {
  documentId: string;
  schemaVersion: number;
  baseRevision: number;
  content: EditorValue;
};

export type SaveResult =
  | { status: "saved"; revision: number }
  | { status: "conflict"; currentRevision: number }
  | {
      status: "error";
      reason: "quota" | "unavailable" | "unknown";
      message: string;
    };

export type RecoverySnapshot = {
  documentId: string;
  revision: number;
  savedAt: string;
  content: EditorValue;
  reason: "conflict" | "save-failed" | "replaced-invalid";
  raw?: unknown;
};

export type EditorPersistenceAdapter = {
  load: (documentId: string) => Promise<unknown | null>;
  save: (request: SaveRequest) => Promise<SaveResult>;
  saveRecovery: (snapshot: RecoverySnapshot) => Promise<void>;
  subscribe?: (documentId: string, onExternalRevision: (revision: number) => void) => () => void;
};

import type { Value } from "platejs";

export type EditorValue = Value;

export const EMPTY_EDITOR_VALUE = [
  {
    type: "p",
    children: [{ text: "" }],
  },
] satisfies EditorValue;

import { EDITOR_SCHEMA_VERSION, serializeEditorDocument } from "./editor-document";
import type { EditorPersistenceAdapter, SaveRequest, SaveResult } from "./editor-persistence";

const QUOTA_MESSAGE =
  "Browser storage is full. Delete unused data or copy your document before closing this tab.";
const UNAVAILABLE_MESSAGE =
  "Browser storage is unavailable. Copy your document before closing this tab.";

type LocalStorageAdapterOptions = {
  storage?: Storage;
  keyPrefix?: string;
  target?: Pick<Window, "addEventListener" | "removeEventListener">;
};

function isQuotaError(error: unknown): boolean {
  if (typeof error !== "object" || error === null) {
    return false;
  }

  if ("name" in error && error.name === "QuotaExceededError") {
    return true;
  }

  return "code" in error && error.code === 22;
}

function storageFailure(error: unknown): SaveResult {
  if (isQuotaError(error)) {
    return { status: "error", reason: "quota", message: QUOTA_MESSAGE };
  }

  return { status: "error", reason: "unavailable", message: UNAVAILABLE_MESSAGE };
}

function storedRevision(raw: string): number | undefined {
  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== "object" || parsed === null || !("revision" in parsed)) {
      return undefined;
    }

    const revision = parsed.revision;
    if (typeof revision !== "number" || !Number.isInteger(revision) || revision < 0) {
      return undefined;
    }

    return revision;
  } catch {
    return undefined;
  }
}

function revisionFromStorageEvent(event: Event, documentKey: string): number | undefined {
  if (!("key" in event) || !("newValue" in event)) {
    return undefined;
  }

  const { key, newValue } = event;
  if (key !== documentKey || typeof newValue !== "string") {
    return undefined;
  }

  return storedRevision(newValue);
}

export function createLocalStorageAdapter(
  options?: LocalStorageAdapterOptions,
): EditorPersistenceAdapter {
  const keyPrefix = options?.keyPrefix ?? "notion-like-editor";
  const target = options?.target ?? window;

  // Touched only inside a method. A blocked `localStorage` getter throws, and
  // reading it while constructing the adapter would crash the demo during render.
  function openStorage(): Storage {
    return options?.storage ?? window.localStorage;
  }

  function documentKey(documentId: string): string {
    return `${keyPrefix}:${documentId}`;
  }

  function recoveryKey(documentId: string, reason: string): string {
    return `${keyPrefix}:${documentId}:recovery:${reason}`;
  }

  return {
    async load(documentId) {
      const raw = openStorage().getItem(documentKey(documentId));
      if (raw === null) {
        return null;
      }

      try {
        const parsed: unknown = JSON.parse(raw);
        return parsed;
      } catch {
        return raw;
      }
    },

    async save(request: SaveRequest): Promise<SaveResult> {
      const key = documentKey(request.documentId);
      let storage: Storage;
      let raw: string | null;

      try {
        storage = openStorage();
        raw = storage.getItem(key);
      } catch (error) {
        return storageFailure(error);
      }

      // A missing or unreadable value has no revision. The first write uses base 0 and replaces it.
      const current = raw === null ? undefined : storedRevision(raw);
      if (current === undefined) {
        if (request.baseRevision !== 0) {
          return { status: "conflict", currentRevision: 0 };
        }
      } else if (current !== request.baseRevision) {
        return { status: "conflict", currentRevision: current };
      }

      const revision = request.baseRevision + 1;
      const payload = serializeEditorDocument({
        schemaVersion: EDITOR_SCHEMA_VERSION,
        documentId: request.documentId,
        revision,
        content: request.content,
      });

      try {
        storage.setItem(key, payload);
      } catch (error) {
        return storageFailure(error);
      }

      return { status: "saved", revision };
    },

    async saveRecovery(snapshot) {
      openStorage().setItem(
        recoveryKey(snapshot.documentId, snapshot.reason),
        JSON.stringify(snapshot),
      );
    },

    subscribe(documentId, onExternalRevision) {
      const key = documentKey(documentId);
      const listener: EventListener = (event) => {
        const revision = revisionFromStorageEvent(event, key);
        if (revision === undefined) {
          return;
        }

        onExternalRevision(revision);
      };

      target.addEventListener("storage", listener);
      return () => {
        target.removeEventListener("storage", listener);
      };
    },
  };
}

// Demo documents used to share `notion-like-editor:demo`. Drop that key and
// older `demo-*` copies so a new showcase is not hidden. Recovery snapshots
// stay, and documents that are not demos stay.
export function removeStaleDemoDocuments(storage: Storage, currentDocumentId: string): void {
  const prefix = "notion-like-editor";
  const currentKey = `${prefix}:${currentDocumentId}`;
  const legacyKey = `${prefix}:demo`;
  const versionedPrefix = `${prefix}:demo-`;

  try {
    const keys: string[] = [];
    for (let index = 0; index < storage.length; index += 1) {
      const key = storage.key(index);
      if (key !== null) {
        keys.push(key);
      }
    }

    for (const key of keys) {
      if (key.includes(":recovery:") || key === currentKey) {
        continue;
      }

      const suffix = key.startsWith(versionedPrefix) ? key.slice(versionedPrefix.length) : null;
      const outdatedDemo = suffix !== null && !suffix.includes(":");
      if (key === legacyKey || outdatedDemo) {
        storage.removeItem(key);
      }
    }
  } catch {
    // Storage can throw when it is blocked. The current demo still opens.
  }
}

import type { EditorCommand } from "../commands/editor-commands";
import { AUDIO_KEY } from "./editor-audio";
import { embedUrlSource } from "./editor-media-source";
import {
  createMediaCaptionCommand,
  createMediaClearSourceCommand,
  createMediaInsertCommand,
  createMediaRemoveCommand,
  createMediaSetSourceCommand,
} from "./editor-media-commands";

// The audio commands. The shared ones are built by editor-media-commands.ts. A url-only value is an
// embed link and must be http or https.

export const insertAudio: EditorCommand<{ id: string }> = createMediaInsertCommand(AUDIO_KEY);

export const setAudioSource = createMediaSetSourceCommand(AUDIO_KEY, embedUrlSource);

export const clearAudioSource = createMediaClearSourceCommand(AUDIO_KEY);

export const setAudioCaption = createMediaCaptionCommand(AUDIO_KEY);

// Removes the block. An empty document gets an empty paragraph, as the bookmark remove does.
export const removeAudio = createMediaRemoveCommand(AUDIO_KEY);

import type { TElement } from "platejs";

import {
  MEDIA_MIME_PREFIXES,
  cleanMediaSourceFields,
  isStoredMediaAttr,
  type MediaSource,
} from "./editor-media-source";
import { cleanMediaCaptionField, isMediaCaption } from "./editor-media-layout";

// The audio block: a compact player for an audio file, with a caption under it. It has no width or
// alignment. The shared source fields are in editor-media-source.ts. The commands are in
// editor-audio-commands.ts. This module imports no command code, so the static renderer can use it.

export const AUDIO_KEY = "audio";

export const AUDIO_URL_REMOVED =
  "An audio file has an unsupported url. The audio was cleared to an empty placeholder.";
export const AUDIO_ATTRS_CLEANED =
  "An audio file lost an attribute that is not valid. The audio was kept.";

type AudioFields = Partial<MediaSource> & { caption?: string };

type CleanedAudio = {
  fields: AudioFields;
  dropped: boolean; // true when a field was present and removed
};

// A literal list. The audio fields are written in this order.
const AUDIO_FIELD_KEYS = [
  "url",
  "name",
  "size",
  "mime",
  "caption",
] as const satisfies readonly (keyof AudioFields)[];

// The check for one stored audio attribute. A mime type must start with audio/.
export function isStoredAudioAttr(attr: string, value: unknown): boolean {
  switch (attr) {
    case "caption":
      return isMediaCaption(value);
    default:
      return isStoredMediaAttr(attr, value, MEDIA_MIME_PREFIXES.audio);
  }
}

// Cleans each field of a raw audio block, the way paste does. A stored audio comes out unchanged.
// A field that cannot be cleaned is left out and sets `dropped`.
export function cleanAudioFields(raw: Record<string, unknown>): CleanedAudio {
  const shared = cleanMediaSourceFields(raw, MEDIA_MIME_PREFIXES.audio);
  const caption = cleanMediaCaptionField(raw);
  const fields: AudioFields = { ...shared.fields, ...caption.fields };
  return { fields, dropped: shared.dropped || caption.dropped };
}

export function audioElement(fields: AudioFields, id?: string): TElement {
  const node: TElement = { type: AUDIO_KEY, children: [{ text: "" }] };
  if (id !== undefined) {
    node.id = id;
  }

  for (const key of AUDIO_FIELD_KEYS) {
    const value = fields[key];
    if (value !== undefined) {
      node[key] = value;
    }
  }
  return node;
}

import {
  ElementApi,
  KEYS,
  nanoid,
  type Descendant,
  type SlateEditor,
  type TElement,
} from "platejs";

import { containerContentType, maxNesting } from "../document/editor-document-schema";
import { targetBlockAtPath } from "./editor-block-handle";
import { blockPlacementRefusal } from "./editor-block-menu";
import { SYNCED_REF_KEY, findBlockById } from "./editor-synced-block";

const BLOCK_DRAG_THRESHOLD_PX = 4;

export const MOVE_ALREADY_FIRST = "This block is already first.";
export const MOVE_ALREADY_LAST = "This block is already last.";

const INTO_SELF = "A block cannot be dropped into itself.";
const TOGGLE_NESTING = "Toggles can only nest three levels deep.";

const UNMOVABLE = new Set<string>([KEYS.td, KEYS.th, KEYS.tr, KEYS.column, KEYS.codeLine]);

type BlockDropDecision = {
  allowed: boolean;
  noop: boolean;
  reason?: string;
  unit: readonly [number, number];
};

type SiblingMove = { ok: true; to: number[] } | { ok: false; reason: string };

// A rendered block box, cached at drag start. Falling back to these means the
// slot comes from the pointer's vertical position, not from a hit-test, so a
// drag that stays in the gutter still resolves a target.
export type DropRect = {
  path: number[];
  top: number;
  bottom: number;
  left: number;
  right: number;
};

// The normal vertical gap between blocks (Tailwind space-y-4). A line before the
// first or after the last block sits half a gap outside.
const BLOCK_GAP_PX = 16;

export type DropIndicator = {
  top: number;
  left: number;
  width: number;
  to: number[];
  noop: boolean;
};

type ScrollSnap = {
  viewport: HTMLElement | null;
  top: number;
  left: number;
  windowX: number;
  windowY: number;
};

const refusedUnit: readonly [number, number] = [0, 0];

function refuse(reason: string, unit: readonly [number, number] = refusedUnit): BlockDropDecision {
  return { allowed: false, noop: false, reason, unit };
}

function elementId(node: TElement): string {
  const id: unknown = Reflect.get(node, "id");
  return typeof id === "string" ? id : "";
}

function listIndent(node: TElement): number | null {
  if (node.type !== KEYS.p) {
    return null;
  }
  const style: unknown = Reflect.get(node, "listStyleType");
  if (typeof style !== "string" || style.length === 0) {
    return null;
  }
  const indent: unknown = Reflect.get(node, "indent");
  if (typeof indent !== "number" || !Number.isInteger(indent)) {
    return 1;
  }
  return indent;
}

function elementAt(roots: readonly Descendant[], path: readonly number[]): TElement | null {
  let current: Descendant | undefined;
  let list: readonly Descendant[] = roots;
  for (const index of path) {
    current = list[index];
    if (!current || !ElementApi.isElement(current)) {
      return null;
    }
    list = current.children;
  }
  if (!current || !ElementApi.isElement(current)) {
    return null;
  }
  return current;
}

function childrenAt(
  roots: readonly Descendant[],
  parentPath: readonly number[],
): readonly Descendant[] | null {
  if (parentPath.length === 0) {
    return roots;
  }
  const parent = elementAt(roots, parentPath);
  return parent ? parent.children : null;
}

function samePath(left: readonly number[], right: readonly number[]): boolean {
  if (left.length !== right.length) {
    return false;
  }
  for (let index = 0; index < left.length; index += 1) {
    if (left[index] !== right[index]) {
      return false;
    }
  }
  return true;
}

function startsWithPath(path: readonly number[], prefix: readonly number[]): boolean {
  if (prefix.length > path.length) {
    return false;
  }
  for (let index = 0; index < prefix.length; index += 1) {
    if (path[index] !== prefix[index]) {
      return false;
    }
  }
  return true;
}

// A list item is a paragraph with listStyleType. Plate stores nested items as
// the following siblings whose indent is greater. A non-list, or an item at an
// equal or smaller indent, ends the run. Headings are not list items.
export function listItemUnit(
  siblings: readonly Descendant[],
  index: number,
): readonly [number, number] {
  const node = siblings[index];
  if (!node || !ElementApi.isElement(node)) {
    return [index, index];
  }
  const base = listIndent(node);
  if (base === null) {
    return [index, index + 1];
  }
  let end = index + 1;
  while (end < siblings.length) {
    const next = siblings[end];
    if (!next || !ElementApi.isElement(next)) {
      break;
    }
    const indent = listIndent(next);
    if (indent === null || indent <= base) {
      break;
    }
    end += 1;
  }
  return [index, end];
}

function dropParentRefusal(parentType: string | null, toIndex: number): string | undefined {
  if (parentType === null) {
    return undefined;
  }
  if (parentType === KEYS.td || parentType === KEYS.th) {
    return "A table cell cannot hold a dropped block.";
  }
  if (parentType === KEYS.tr || parentType === KEYS.table) {
    return "A table moves as one block.";
  }
  if (parentType === KEYS.codeBlock || parentType === KEYS.codeLine) {
    return "A code block cannot hold a dropped block.";
  }
  if (parentType === KEYS.columnGroup) {
    return "Drop inside a column.";
  }
  if (parentType === SYNCED_REF_KEY) {
    return "A synced block cannot hold a dropped block.";
  }
  if (parentType === KEYS.toggle && toIndex === 0) {
    return "A toggle's label cannot be a drop target.";
  }
  return undefined;
}

function sourceRefusal(
  node: TElement,
  index: number,
  parentType: string | null,
): string | undefined {
  if (UNMOVABLE.has(node.type)) {
    return "This block cannot be moved.";
  }
  // A cell's paragraph is not a drag target. The table moves as one block.
  if (parentType === KEYS.td || parentType === KEYS.th) {
    return "This block cannot be moved.";
  }
  if (parentType === KEYS.toggle && index === 0) {
    return "A toggle label stays with its toggle.";
  }
  return undefined;
}

function toggleDepth(node: TElement): number {
  let nested = 0;
  for (const child of node.children) {
    if (!ElementApi.isElement(child)) {
      continue;
    }
    nested = Math.max(nested, toggleDepth(child));
  }
  return (node.type === KEYS.toggle ? 1 : 0) + nested;
}

function toggleLevel(roots: readonly Descendant[], parentPath: readonly number[]): number {
  let count = 0;
  for (let depth = 1; depth <= parentPath.length; depth += 1) {
    const node = elementAt(roots, parentPath.slice(0, depth));
    if (node?.type === KEYS.toggle) {
      count += 1;
    }
  }
  return count;
}

function insideMovedUnit(
  toParent: readonly number[],
  toIndex: number,
  fromParent: readonly number[],
  unit: readonly [number, number],
): boolean {
  const [start, end] = unit;
  for (let index = start; index < end; index += 1) {
    const unitPath = [...fromParent, index];
    if (samePath(toParent, unitPath) || startsWithPath(toParent, unitPath)) {
      return true;
    }
  }
  return samePath(toParent, fromParent) && toIndex > start && toIndex < end;
}

export function blockDropDecision(
  roots: readonly Descendant[],
  from: readonly number[],
  toParent: readonly number[],
  toIndex: number,
  span?: readonly [number, number],
): BlockDropDecision {
  if (from.length === 0 || !Number.isInteger(toIndex) || toIndex < 0) {
    return refuse("This block cannot be moved.");
  }

  const fromParent = from.slice(0, -1);
  const fromIndex = from[from.length - 1] ?? 0;
  const siblings = childrenAt(roots, fromParent);
  const source = siblings?.[fromIndex];
  if (!siblings || !source || !ElementApi.isElement(source)) {
    return refuse("This block cannot be moved.");
  }

  const fromParentType =
    fromParent.length === 0 ? null : (elementAt(roots, fromParent)?.type ?? null);
  const unit = span ?? listItemUnit(siblings, fromIndex);
  if (
    span !== undefined &&
    (span[0] < 0 || span[1] > siblings.length || span[1] <= span[0] || span[0] !== fromIndex)
  ) {
    return refuse("This block cannot be moved.", unit);
  }
  const refusalIndexes =
    span === undefined
      ? [fromIndex]
      : Array.from({ length: span[1] - span[0] }, (_, offset) => span[0] + offset);
  for (const index of refusalIndexes) {
    const node = siblings[index];
    if (!node || !ElementApi.isElement(node)) {
      return refuse("This block cannot be moved.", unit);
    }
    const blocked = sourceRefusal(node, index, fromParentType);
    if (blocked !== undefined) {
      return refuse(blocked, unit);
    }
  }

  const destination = childrenAt(roots, toParent);
  if (!destination || toIndex > destination.length) {
    return refuse("This block cannot be dropped here.", unit);
  }

  const toParentType = toParent.length === 0 ? null : (elementAt(roots, toParent)?.type ?? null);
  const parentReason = dropParentRefusal(toParentType, toIndex);
  if (parentReason !== undefined) {
    return refuse(parentReason, unit);
  }

  if (insideMovedUnit(toParent, toIndex, fromParent, unit)) {
    return refuse(INTO_SELF, unit);
  }

  if (samePath(toParent, fromParent) && (toIndex === unit[0] || toIndex === unit[1])) {
    return { allowed: true, noop: true, unit };
  }

  for (let index = unit[0]; index < unit[1]; index += 1) {
    const node = siblings[index];
    if (!node || !ElementApi.isElement(node)) {
      return refuse("This block cannot be moved.", unit);
    }
    const reason = blockPlacementRefusal(
      toParentType,
      toIndex,
      node.type,
      listIndent(node) !== null,
    );
    if (reason !== undefined) {
      return refuse(reason, unit);
    }
  }

  let movedDepth = 0;
  for (let index = unit[0]; index < unit[1]; index += 1) {
    const node = siblings[index];
    if (node && ElementApi.isElement(node)) {
      movedDepth = Math.max(movedDepth, toggleDepth(node));
    }
  }
  const limit = maxNesting(KEYS.toggle) ?? 3;
  if (toggleLevel(roots, toParent) + movedDepth > limit) {
    return refuse(TOGGLE_NESTING, unit);
  }

  return { allowed: true, noop: false, unit };
}

function previousRange(
  siblings: readonly Descendant[],
  unitStart: number,
): readonly [number, number] | null {
  if (unitStart <= 0) {
    return null;
  }
  for (let index = 0; index < unitStart; index += 1) {
    const range = listItemUnit(siblings, index);
    if (range[0] === index && range[1] === unitStart) {
      return range;
    }
  }
  return [unitStart - 1, unitStart];
}

function nextRange(
  siblings: readonly Descendant[],
  unitEnd: number,
): readonly [number, number] | null {
  if (unitEnd >= siblings.length) {
    return null;
  }
  return listItemUnit(siblings, unitEnd);
}

// Stops at the parent's first and last sibling. Dragging can cross containers;
// this step does not.
export function siblingMove(
  roots: readonly Descendant[],
  from: readonly number[],
  direction: "up" | "down",
): SiblingMove {
  if (from.length === 0) {
    return { ok: false, reason: "This block cannot be moved." };
  }
  const parent = from.slice(0, -1);
  const index = from[from.length - 1] ?? 0;
  const siblings = childrenAt(roots, parent);
  if (!siblings) {
    return { ok: false, reason: "This block cannot be moved." };
  }
  const unit = listItemUnit(siblings, index);
  const destination =
    direction === "up" ? previousRange(siblings, unit[0]) : nextRange(siblings, unit[1]);
  if (!destination) {
    return { ok: false, reason: direction === "up" ? MOVE_ALREADY_FIRST : MOVE_ALREADY_LAST };
  }
  const toIndex = direction === "up" ? destination[0] : destination[1];
  const decision = blockDropDecision(roots, from, parent, toIndex);
  if (!decision.allowed || decision.noop) {
    const edge = direction === "up" ? MOVE_ALREADY_FIRST : MOVE_ALREADY_LAST;
    // The label is not a sibling the body can trade places with.
    if (decision.reason === "A toggle's label cannot be a drop target.") {
      return { ok: false, reason: edge };
    }
    return { ok: false, reason: decision.reason ?? edge };
  }
  return { ok: true, to: [...parent, toIndex] };
}

function findByPath(rects: readonly DropRect[], path: readonly number[]): DropRect | null {
  for (const rect of rects) {
    if (samePath(rect.path, path)) {
      return rect;
    }
  }
  return null;
}

function rectDistance(rect: DropRect, y: number): number {
  if (y < rect.top) {
    return rect.top - y;
  }
  if (y > rect.bottom) {
    return y - rect.bottom;
  }
  return 0;
}

// Candidate blocks nearest the pointer first, innermost on a tie. This mirrors
// the old topmost-element order while reading only cached numbers.
function orderCandidates(rects: readonly DropRect[], y: number): DropRect[] {
  return [...rects].sort((left, right) => {
    const byDistance = rectDistance(left, y) - rectDistance(right, y);
    if (byDistance !== 0) {
      return byDistance;
    }
    return right.path.length - left.path.length;
  });
}

// "Below A" and "above B" are the same slot, so the line is the midpoint
// between A's bottom and B's top. Before the first and after the last block the
// line sits half a normal gap outside.
function indicatorSlot(
  rects: readonly DropRect[],
  to: number[],
  noop: boolean,
): DropIndicator | null {
  const toIndex = to[to.length - 1];
  if (toIndex === undefined) {
    return null;
  }
  const parent = to.slice(0, -1);
  const previous = findByPath(rects, [...parent, toIndex - 1]);
  const next = findByPath(rects, [...parent, toIndex]);
  if (!previous && !next) {
    return null;
  }
  if (previous && next) {
    const top = (previous.bottom + next.top) / 2;
    const left = Math.min(previous.left, next.left);
    const width = Math.max(previous.right, next.right) - left;
    return { top, left, width, to, noop };
  }
  const anchor = previous ?? next;
  if (!anchor) {
    return null;
  }
  const top = previous ? previous.bottom + BLOCK_GAP_PX / 2 : (next?.top ?? 0) - BLOCK_GAP_PX / 2;
  return { top, left: anchor.left, width: anchor.right - anchor.left, to, noop };
}

export function resolveDropIndicator(
  roots: readonly Descendant[],
  from: readonly number[],
  rects: readonly DropRect[],
  pointerY: number,
  span?: readonly [number, number],
): DropIndicator | null {
  for (const rect of orderCandidates(rects, pointerY)) {
    const index = rect.path[rect.path.length - 1] ?? 0;
    const parent = rect.path.slice(0, -1);
    const above = pointerY < rect.top + (rect.bottom - rect.top) / 2;
    const toIndex = above ? index : index + 1;
    const decision = blockDropDecision(roots, from, parent, toIndex, span);
    if (decision.allowed) {
      const slot = indicatorSlot(rects, [...parent, toIndex], decision.noop);
      if (slot) {
        return slot;
      }
    }
    if (decision.reason === INTO_SELF) {
      const fromParent = from.slice(0, -1);
      const [start, end] = decision.unit;
      const first = findByPath(rects, [...fromParent, start]);
      const last = findByPath(rects, [...fromParent, end - 1]);
      if (first && last) {
        const boundaryAbove = pointerY < (first.top + last.bottom) / 2;
        const boundaryIndex = boundaryAbove ? start : end;
        const boundary = blockDropDecision(roots, from, fromParent, boundaryIndex, span);
        if (boundary.allowed) {
          const slot = indicatorSlot(rects, [...fromParent, boundaryIndex], boundary.noop);
          if (slot) {
            return slot;
          }
        }
      }
    }
  }
  return null;
}

export function dragPastThreshold(dx: number, dy: number): boolean {
  return dx * dx + dy * dy > BLOCK_DRAG_THRESHOLD_PX * BLOCK_DRAG_THRESHOLD_PX;
}

export function blockMoveDirection(event: {
  key: string;
  metaKey: boolean;
  ctrlKey: boolean;
  altKey: boolean;
  shiftKey: boolean;
}): "up" | "down" | null {
  if (event.metaKey === event.ctrlKey || !event.altKey || !event.shiftKey) {
    return null;
  }
  if (event.key === "ArrowUp") {
    return "up";
  }
  if (event.key === "ArrowDown") {
    return "down";
  }
  return null;
}

export function blockMoveTarget(editor: SlateEditor): number[] | null {
  const selection = editor.selection;
  if (!selection) {
    return null;
  }
  const hit = targetBlockAtPath(editor, selection.focus.path);
  return hit ? [...hit.path] : null;
}

function freshId(editor: SlateEditor): string {
  const seen = new Set<string>();
  const visit = (node: Descendant): void => {
    if (!ElementApi.isElement(node)) {
      return;
    }
    const id = elementId(node);
    if (id.length > 0) {
      seen.add(id);
    }
    for (const child of node.children) {
      visit(child);
    }
  };
  for (const child of editor.children) {
    visit(child);
  }
  let id = nanoid(10);
  let suffix = 1;
  while (id.length === 0 || seen.has(id)) {
    id = `${nanoid(10)}-${suffix}`;
    suffix += 1;
  }
  return id;
}

function repairEmptyContainer(editor: SlateEditor, parentPath: number[]): void {
  if (parentPath.length === 0) {
    return;
  }
  const parent = editor.api.node(parentPath);
  const node = parent?.[0];
  if (!parent || !ElementApi.isElement(node) || typeof node.type !== "string") {
    return;
  }
  if (node.children.length !== 0) {
    return;
  }
  const content = containerContentType(node.type);
  if (content === undefined) {
    return;
  }
  const child: TElement = { type: content, id: freshId(editor), children: [{ text: "" }] };
  editor.tf.insertNodes(child, { at: [...parentPath, 0] });
}

function selectMoved(editor: SlateEditor, id: string): void {
  if (id.length === 0) {
    return;
  }
  const landed = findBlockById(editor, id);
  if (!landed) {
    return;
  }
  const point = editor.api.start(landed[1]);
  if (point) {
    editor.tf.select(point);
  }
}

export function moveBlockAt(
  editor: SlateEditor,
  from: number[],
  to: number[],
  span?: readonly [number, number],
): boolean {
  const toParent = to.slice(0, -1);
  const toIndex = to[to.length - 1];
  if (toIndex === undefined) {
    return false;
  }
  const decision = blockDropDecision(editor.children, from, toParent, toIndex, span);
  if (!decision.allowed || decision.noop) {
    return false;
  }

  const fromParent = from.slice(0, -1);
  const [start, end] = decision.unit;
  const moving: TElement[] = [];
  for (let index = start; index < end; index += 1) {
    const entry = editor.api.node([...fromParent, index]);
    const node = entry?.[0];
    if (!entry || !ElementApi.isElement(node)) {
      return false;
    }
    moving.push(node);
  }
  if (moving.length === 0) {
    return false;
  }

  // The remove operation keeps the node for undo. Insert a copy so that snapshot stays put.
  const copies = moving.map((node) => structuredClone(node));
  const first = copies[0];
  if (!first) {
    return false;
  }
  const movedId = elementId(first);
  const destRef = editor.api.pathRef([...toParent, toIndex]);
  let inserted = false;
  editor.tf.withoutNormalizing(() => {
    for (let index = end - 1; index >= start; index -= 1) {
      editor.tf.removeNodes({ at: [...fromParent, index] });
    }
    repairEmptyContainer(editor, fromParent);
    const at = destRef.current;
    if (!at) {
      return;
    }
    let cursor = [...at];
    for (const copy of copies) {
      editor.tf.insertNodes(copy, { at: cursor });
      inserted = true;
      const next = [...cursor];
      const last = next[next.length - 1];
      if (last === undefined) {
        return;
      }
      next[next.length - 1] = last + 1;
      cursor = next;
    }
  });
  destRef.unref();
  if (!inserted) {
    return false;
  }
  selectMoved(editor, movedId);
  return true;
}

function movedElement(editor: SlateEditor): HTMLElement | null {
  const selection = editor.selection;
  if (!selection) {
    return null;
  }
  const target = targetBlockAtPath(editor, selection.anchor.path);
  if (!target) {
    return null;
  }
  const entry = editor.api.node(target.path);
  if (!entry || !ElementApi.isElement(entry[0])) {
    return null;
  }
  const dom: unknown = editor.api.toDOMNode(entry[0]);
  return dom instanceof HTMLElement ? dom : null;
}

export function captureEditorScroll(): ScrollSnap {
  const found = document.querySelector("[data-block-viewport]");
  const viewport = found instanceof HTMLElement ? found : null;
  return {
    viewport,
    top: viewport ? viewport.scrollTop : 0,
    left: viewport ? viewport.scrollLeft : 0,
    windowX: window.scrollX,
    windowY: window.scrollY,
  };
}

function outsideFrame(editor: SlateEditor, viewport: HTMLElement | null): boolean {
  const dom = movedElement(editor);
  if (!dom) {
    return false;
  }
  const rect = dom.getBoundingClientRect();
  if (viewport) {
    const frame = viewport.getBoundingClientRect();
    return rect.bottom <= frame.top + 1 || rect.top >= frame.bottom - 1;
  }
  return rect.bottom <= 0 || rect.top >= window.innerHeight;
}

export function settleMovedBlock(editor: SlateEditor, snap: ScrollSnap): void {
  if (outsideFrame(editor, snap.viewport)) {
    const dom = movedElement(editor);
    const frame = snap.viewport?.getBoundingClientRect();
    if (!dom || !snap.viewport || !frame) {
      dom?.scrollIntoView({ block: "nearest" });
      return;
    }
    const rect = dom.getBoundingClientRect();
    const delta = rect.top < frame.top ? rect.top - frame.top : rect.bottom - frame.bottom;
    snap.viewport.scrollTop += delta;
    return;
  }
  if (snap.viewport) {
    snap.viewport.scrollTop = snap.top;
    snap.viewport.scrollLeft = snap.left;
  }
  window.scrollTo(snap.windowX, snap.windowY);
}

import { ElementApi, KEYS, type SlateEditor } from "platejs";

import { FOOTNOTE_DEF_KEY } from "../document/editor-document-schema";
import { BOOKMARK_KEY } from "./editor-bookmark-url";
import { AUDIO_KEY } from "./editor-audio";
import { EMBED_KEY } from "./editor-embed";
import { FILE_KEY } from "./editor-file";
import { IMAGE_KEY } from "./editor-image";
import { VIDEO_KEY } from "./editor-video";
import { PAGE_LINK_KEY } from "./editor-page-link";
import { SYNCED_REF_KEY, findBlockById } from "./editor-synced-block";

export const BLOCK_HANDLE_GAP = 12;
const BLOCK_HANDLE_PAD = 8;
export const BLOCK_HANDLE_WIDTH = 42;
export const BLOCK_HANDLE_HEIGHT = 24;

const ELIGIBLE = new Set<string>([
  KEYS.p,
  KEYS.h1,
  KEYS.h2,
  KEYS.h3,
  KEYS.blockquote,
  KEYS.callout,
  KEYS.toggle,
  KEYS.hr,
  BOOKMARK_KEY,
  IMAGE_KEY,
  FILE_KEY,
  VIDEO_KEY,
  AUDIO_KEY,
  EMBED_KEY,
  PAGE_LINK_KEY,
  KEYS.toc,
  KEYS.equation,
  SYNCED_REF_KEY,
  KEYS.codeBlock,
  KEYS.table,
  KEYS.columnGroup,
  FOOTNOTE_DEF_KEY,
]);

// The handle is vertically centred on the block's visible content. A block that
// pads around that content marks it with `data-block-handle-anchor`; placement
// reads that marker and otherwise uses the block element. There is no per-type
// list. `placeBlockHandle` is the one pure placement rule.

// One vertical band per rendered target block. The bands are how the handle
// keeps a target in the gaps between blocks, where no element is hit. `depth`
// is the target's nesting depth so an inner row wins over the container that
// encloses it at the same Y.
export type HandleBand = {
  id: string;
  path: number[];
  top: number;
  bottom: number;
  depth?: number;
};

function bandContains(band: HandleBand, y: number): boolean {
  return y >= band.top && y <= band.bottom;
}

function bandDistance(band: HandleBand, y: number): number {
  if (y < band.top) {
    return band.top - y;
  }
  if (y > band.bottom) {
    return y - band.bottom;
  }
  return 0;
}

function bandWins(candidate: HandleBand, incumbent: HandleBand, y: number): boolean {
  const candidateInside = bandContains(candidate, y);
  const incumbentInside = bandContains(incumbent, y);
  if (candidateInside !== incumbentInside) {
    return candidateInside;
  }
  const candidateDepth = candidate.depth ?? 0;
  const incumbentDepth = incumbent.depth ?? 0;
  if (candidateDepth !== incumbentDepth) {
    return candidateDepth > incumbentDepth;
  }
  const candidateDistance = bandDistance(candidate, y);
  const incumbentDistance = bandDistance(incumbent, y);
  if (candidateDistance !== incumbentDistance) {
    return candidateDistance < incumbentDistance;
  }
  return candidate.top > incumbent.top;
}

// The target block for a pointer Y inside the editor. The target is a function
// of Y alone: the innermost band containing Y wins, so a container's padding,
// border and the gutter to its left resolve to the same row as the text at that
// Y. Below all bands, the nearest band wins, ties going to the block below. The
// current target is kept within `hysteresisPx` of its band so crossing the
// boundary does not flicker.
export function pickHandleBandAtY(
  bands: readonly HandleBand[],
  y: number,
  currentId: string | null,
  hysteresisPx = 6,
): HandleBand | null {
  if (bands.length === 0) {
    return null;
  }
  if (currentId !== null) {
    const held = bands.find((band) => band.id === currentId);
    if (held && y >= held.top - hysteresisPx && y <= held.bottom + hysteresisPx) {
      return held;
    }
  }
  let best: HandleBand | null = null;
  for (const band of bands) {
    if (best === null || bandWins(band, best, y)) {
      best = band;
    }
  }
  return best;
}

// Reorder the target list so the input order does not matter for the outcome.
export function sortHandleBands(bands: readonly HandleBand[]): HandleBand[] {
  return [...bands].sort((left, right) => left.top - right.top);
}

export type HandleChainNode = {
  type: string;
  id: string;
  index: number;
  parentType: string | null;
};

type BlockHandleTarget = {
  id: string;
  type: string;
};

export type BlockHandleHit = BlockHandleTarget & {
  path: number[];
};

export type BlockHandlePaint = {
  target: BlockHandleHit;
  top: number;
  left: number;
  width: number;
  height: number;
  blockLeft: number;
  blockTop: number;
  blockBottom: number;
};

// A container's first child row stands for the whole container. A toggle's
// summary row, a callout's first row and a blockquote's first line all target
// the container, so grabbing the grip there drags the container with all its
// children. Later children target themselves.
const SUMMARY_ROW_PARENTS = new Set<string>([KEYS.toggle, KEYS.callout, KEYS.blockquote]);

function isSummaryRow(node: HandleChainNode): boolean {
  return node.index === 0 && node.parentType !== null && SUMMARY_ROW_PARENTS.has(node.parentType);
}

// Innermost eligible block under the pointer.
// Top-level blocks qualify. So do blocks inside containers: list items, toggle
// content, callout content, quote content, and column content.
// A toggle's first child is its summary row, so that row targets the toggle.
// A callout's first child shares the icon's line, so that row targets the callout.
// Later children target themselves. A later child inside a callout uses the
// callout's left edge for the gutter, so the handle stays outside the icon column.
// Hovering a container's own chrome (icon, chevron, padding, column gap) targets
// that block.
// The handle and its pointer bridge stay clear of document controls: the callout
// icon, the toggle chevron, a to-do checkbox, and block toolbars.
// A table cell or row targets the table. A code line targets the code block.
// A column is structural; hovering it targets the column group.
// The caller drops synced-block preview copies before building the chain.
export function blockHandleTarget(chain: readonly HandleChainNode[]): BlockHandleTarget | null {
  const table = chain.find((node) => node.type === KEYS.table);
  if (table) {
    return { id: table.id, type: table.type };
  }

  const code = chain.find((node) => node.type === KEYS.codeBlock);
  if (code) {
    return { id: code.id, type: code.type };
  }

  for (const node of chain) {
    if (isSummaryRow(node)) {
      continue;
    }
    if (!ELIGIBLE.has(node.type)) {
      continue;
    }
    return { id: node.id, type: node.type };
  }

  return null;
}

// Containers whose left border the handle must stay outside of. A block nested
// in one of these anchors to the container's left edge, so the buttons never sit
// on the container's border, background edge, icon, chevron or checkbox.
const GUTTER_CONTAINERS = new Set<string>([KEYS.blockquote, KEYS.callout, KEYS.toggle]);

// Horizontal anchor for the gutter. The handle controls `targetId`. A block
// nested in a quote, callout or toggle anchors to the left edge of its
// **outermost** such container, so a paragraph in a callout in a quote is also
// outside the quote. A column is the exception: a block in a column anchors to
// the column's left edge (the page gutter is not next to the right column), and
// that wins even when the column itself sits inside a quote/callout/toggle.
// The chain is innermost-first, so the last container seen is the outermost and
// the first column seen is the innermost column the target sits in.
export function blockHandleGutterId(chain: readonly HandleChainNode[], targetId: string): string {
  let anchorId = targetId;
  for (const node of chain) {
    if (node.type === KEYS.column) {
      return node.id;
    }
    if (GUTTER_CONTAINERS.has(node.type)) {
      anchorId = node.id;
    }
  }
  return anchorId;
}

export function chainAtPath(editor: SlateEditor, path: number[]): HandleChainNode[] {
  const chain: HandleChainNode[] = [];
  let depth = path.length;
  const located = editor.api.node(path);
  if (!located || !ElementApi.isElement(located[0])) {
    depth -= 1;
  }

  for (; depth >= 1; depth -= 1) {
    const at = path.slice(0, depth);
    const entry = editor.api.node(at);
    if (!entry || !ElementApi.isElement(entry[0])) {
      continue;
    }

    const node = entry[0];
    if (typeof node.type !== "string" || typeof node.id !== "string" || node.id.length === 0) {
      continue;
    }

    const parentPath = at.slice(0, -1);
    let parentType: string | null = null;
    if (parentPath.length > 0) {
      const parent = editor.api.node(parentPath);
      if (parent && ElementApi.isElement(parent[0]) && typeof parent[0].type === "string") {
        parentType = parent[0].type;
      }
    }

    chain.push({
      type: node.type,
      id: node.id,
      index: at[at.length - 1] ?? 0,
      parentType,
    });
  }

  return chain;
}

export function targetBlockAtPath(editor: SlateEditor, path: number[]): BlockHandleHit | null {
  const target = blockHandleTarget(chainAtPath(editor, path));
  if (!target) {
    return null;
  }

  const entry = findBlockById(editor, target.id);
  if (!entry) {
    return null;
  }

  return { id: target.id, type: target.type, path: entry[1] };
}

function inPreview(element: Element): boolean {
  return element.closest("[data-preview-path]") !== null;
}

export function chainFromDom(editor: SlateEditor, start: Element): HandleChainNode[] {
  const chain: HandleChainNode[] = [];
  let current: Element | null = start;
  while (current) {
    if (current.hasAttribute("data-block-id") && !inPreview(current)) {
      const id = current.getAttribute("data-block-id");
      const entry = id === null || id.length === 0 ? undefined : findBlockById(editor, id);
      if (entry && typeof entry[0].type === "string" && typeof entry[0].id === "string") {
        const path = entry[1];
        const parentPath = path.slice(0, -1);
        let parentType: string | null = null;
        if (parentPath.length > 0) {
          const parent = editor.api.node(parentPath);
          if (parent && ElementApi.isElement(parent[0]) && typeof parent[0].type === "string") {
            parentType = parent[0].type;
          }
        }
        chain.push({
          type: entry[0].type,
          id: entry[0].id,
          index: path[path.length - 1] ?? 0,
          parentType,
        });
      }
    }
    current = current.parentElement;
  }

  return chain;
}

const TEXT_EDIT_KEYS = new Set(["Backspace", "Delete", "Enter"]);

export function isTypingKey(event: {
  key: string;
  metaKey: boolean;
  ctrlKey: boolean;
  altKey: boolean;
  isComposing?: boolean;
}): boolean {
  if (event.isComposing === true) {
    return true;
  }
  if (event.metaKey || event.ctrlKey || event.altKey) {
    return false;
  }
  if (TEXT_EDIT_KEYS.has(event.key)) {
    return true;
  }
  return event.key.length === 1;
}

export const BLOCK_HANDLE_ANCHOR = "data-block-handle-anchor";

// A block with no anchor is centred on up to this height; a taller one uses its
// first line instead.
export const BLOCK_HANDLE_CENTER_MAX = 48;
// A marked anchor is centred on up to this height; a taller one (media) keeps
// the handle at its top.
export const BLOCK_HANDLE_ANCHOR_CENTER_MAX = 64;

// The three placement values. The defaults are the constants above, so a caller
// that passes nothing gets the same placement.
export type BlockHandleOptions = {
  gap: number;
  centerMax: number;
  anchorCenterMax: number;
};

const BLOCK_HANDLE_DEFAULT_OPTIONS: BlockHandleOptions = {
  gap: BLOCK_HANDLE_GAP,
  centerMax: BLOCK_HANDLE_CENTER_MAX,
  anchorCenterMax: BLOCK_HANDLE_ANCHOR_CENTER_MAX,
};

// Handle top for a block, given the handle's measured height. A "center" anchor
// (the divider rule) centres the handle on the rule. A marked anchor is centred
// up to options.anchorCenterMax, else the handle goes to its top. With no
// anchor, the block is centred up to options.centerMax, else on its first line.
export function blockHandleContentTop(
  block: HTMLElement,
  handleHeight: number,
  options: BlockHandleOptions = BLOCK_HANDLE_DEFAULT_OPTIONS,
): number {
  let anchorRect: DOMRect | null = null;
  const anchor = block.querySelector(`[${BLOCK_HANDLE_ANCHOR}]`);
  if (anchor instanceof HTMLElement) {
    const rect = anchor.getBoundingClientRect();
    if (rect.height > 0) {
      if (anchor.getAttribute(BLOCK_HANDLE_ANCHOR) === "center") {
        return rect.top + rect.height / 2 - handleHeight / 2;
      }
      anchorRect = rect;
    }
  }

  if (anchorRect) {
    if (anchorRect.height <= options.anchorCenterMax) {
      return anchorRect.top + (anchorRect.height - handleHeight) / 2;
    }
    return anchorRect.top;
  }
  const blockRect = block.getBoundingClientRect();
  if (blockRect.height <= options.centerMax) {
    return blockRect.top + (blockRect.height - handleHeight) / 2;
  }
  return firstLineTop(block, handleHeight);
}

// Centres the handle on the first line box of a block. The line height comes
// from the computed style; `normal` does not parse, so the line top is used.
function firstLineTop(block: HTMLElement, handleHeight: number): number {
  const style = getComputedStyle(block);
  const paddingTop = parseFloat(style.paddingTop) || 0;
  const borderTop = parseFloat(style.borderTopWidth) || 0;
  const lineHeight = parseFloat(style.lineHeight);
  const lineTop = block.getBoundingClientRect().top + paddingTop + borderTop;
  if (!Number.isFinite(lineHeight) || lineHeight <= 0) {
    return lineTop;
  }
  return lineTop + Math.max(0, (lineHeight - handleHeight) / 2);
}

// The target block's box, in viewport coordinates. `blockTop` is the handle's
// top (the visible content); `blockLeft` is the horizontal anchor (the gutter
// anchor for a nested block). `blockBottom` is only used for the visibility test.
type HandleBlockBox = {
  blockTop: number;
  blockBottom: number;
  blockLeft: number;
};

export type HandleFrame = {
  top: number;
  right: number;
  bottom: number;
  left: number;
};

type HandleViewport = {
  width: number;
  height: number;
};

type HandleSize = {
  width: number;
  height: number;
};

type PlacedHandle = {
  top: number;
  left: number;
};

// Handle top = `blockTop`, the content top from blockHandleContentTop. The handle
// is placed in the gutter: `options.gap` before the block's left edge.
export function placeBlockHandle(
  block: HandleBlockBox,
  handle: HandleSize,
  viewport: HandleViewport,
  frame: HandleFrame | null,
  options: BlockHandleOptions = BLOCK_HANDLE_DEFAULT_OPTIONS,
): PlacedHandle | null {
  const top = block.blockTop;
  const left = block.blockLeft - options.gap - handle.width;
  const right = left + handle.width;
  const bottom = top + handle.height;

  if (left < BLOCK_HANDLE_PAD || top < BLOCK_HANDLE_PAD) {
    return null;
  }
  if (right > viewport.width - BLOCK_HANDLE_PAD || bottom > viewport.height - BLOCK_HANDLE_PAD) {
    return null;
  }
  if (right > block.blockLeft - 1) {
    return null;
  }

  if (frame) {
    const blockVisible = block.blockBottom > frame.top && block.blockTop < frame.bottom;
    if (!blockVisible) {
      return null;
    }
    if (top < frame.top || bottom > frame.bottom || left < frame.left || right > frame.right) {
      return null;
    }
  }

  return { top, left };
}

export function handleCoversForeignBlock(
  hitId: string | null,
  chainIds: readonly string[],
): boolean {
  if (hitId === null || hitId.length === 0) {
    return false;
  }
  return !chainIds.includes(hitId);
}

export type HandleUiState = {
  typing: boolean;
  pointerId: string | null;
  pointerOutside: boolean;
  caretId: string | null;
  engagedId: string | null;
  readOnly: boolean;
  hoverNone: boolean;
};

type HandleUiEvent =
  | { type: "pointer-move"; id: string | null; engagedId: string | null; outside?: boolean }
  | { type: "caret"; id: string | null }
  | { type: "typing"; typing: boolean }
  | { type: "engage"; id: string | null }
  | { type: "read-only"; value: boolean }
  | { type: "hover-none"; value: boolean };

export function initialHandleUi(readOnly = false, hoverNone = false): HandleUiState {
  return {
    typing: false,
    pointerId: null,
    pointerOutside: false,
    caretId: null,
    engagedId: null,
    readOnly,
    hoverNone,
  };
}

export function reduceHandleUi(state: HandleUiState, event: HandleUiEvent): HandleUiState {
  switch (event.type) {
    case "pointer-move": {
      const outside = event.outside ?? false;
      if (
        state.pointerId === event.id &&
        state.engagedId === event.engagedId &&
        state.pointerOutside === outside &&
        state.typing === false
      ) {
        return state;
      }
      return {
        ...state,
        typing: false,
        pointerId: event.id,
        pointerOutside: outside,
        engagedId: event.engagedId,
      };
    }
    case "caret":
      if (state.caretId === event.id) {
        return state;
      }
      return { ...state, caretId: event.id };
    case "typing":
      if (state.typing === event.typing) {
        return state;
      }
      return { ...state, typing: event.typing };
    case "engage":
      if (state.engagedId === event.id) {
        return state;
      }
      return { ...state, engagedId: event.id };
    case "read-only":
      if (state.readOnly === event.value) {
        return state;
      }
      return { ...state, readOnly: event.value };
    case "hover-none":
      if (state.hoverNone === event.value) {
        return state;
      }
      return { ...state, hoverNone: event.value };
    default:
      return state;
  }
}

// Set for the whole grip press, including the pixels before the drag threshold.
// Pointer moves in that window must not retarget the handle.
let blockDragArmed = false;

export function setBlockDragArmed(armed: boolean): void {
  blockDragArmed = armed;
}

export function isBlockDragArmed(): boolean {
  return blockDragArmed;
}

export function visibleHandleId(state: HandleUiState): string | null {
  if (state.readOnly || state.hoverNone) {
    return null;
  }
  if (state.engagedId) {
    return state.engagedId;
  }
  if (state.typing) {
    return null;
  }
  // The pointer owns the target for as long as it is over the editor. Leaving
  // the editor hides the handle rather than falling back to the model caret.
  if (state.pointerOutside) {
    return null;
  }
  return state.pointerId ?? state.caretId;
}

import { KEYS } from "platejs";

import { LIST_INDENTS, type ListIndent } from "../document/editor-document-schema";

// Kept free of editor and command imports: the static renderer imports this module.
// Plain indent is the native `indent` attr. A list paragraph reads it as list depth.
export const BLOCK_INDENT_TYPES: readonly string[] = [
  KEYS.p,
  KEYS.h1,
  KEYS.h2,
  KEYS.h3,
  KEYS.blockquote,
];

export const BLOCK_INDENT_MAX = 6;

const BLOCK_INDENT_STEP_PX = 24;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

export function isListParagraph(node: unknown): boolean {
  return isRecord(node) && node.type === KEYS.p && typeof node.listStyleType === "string";
}

// A list item without a stored indent is depth 1.
export function listIndentOf(node: unknown): number {
  if (!isRecord(node) || !("indent" in node)) {
    return 1;
  }

  return typeof node.indent === "number" ? node.indent : 1;
}

function isListIndent(value: unknown): value is ListIndent {
  return LIST_INDENTS.some((level) => level === value);
}

// 0 when absent or invalid. An invalid stored value renders nothing and counts as unset.
export function blockIndentOf(node: unknown): number {
  const value: unknown = isRecord(node) ? node.indent : undefined;
  return isListIndent(value) ? value : 0;
}

// Plain blocks only. A list paragraph keeps the step the list markup draws.
export function blockIndentNodeProps() {
  return {
    transformProps: ({
      element,
      props,
    }: {
      element?: unknown;
      props: Record<string, unknown>;
    }): Record<string, unknown> => {
      const indent = blockIndentOf(element);
      if (indent === 0 || isListParagraph(element)) {
        return props;
      }

      const style: Record<string, unknown> = { ...(isRecord(props.style) ? props.style : {}) };
      style.marginInlineStart = `${indent * BLOCK_INDENT_STEP_PX}px`;
      return { ...props, "data-block-indent": String(indent), style };
    },
  };
}

// Plate's IndentPlugin injects margin-left on any paragraph that has indent. Plain blocks
// get their own margin here, so that injection is limited to list paragraphs.
export function listIndentInjects({ nodeProps }: { nodeProps: { element?: unknown } }): boolean {
  return isListParagraph(nodeProps.element);
}

import { setIndent } from "@platejs/indent";
import { ElementApi, KEYS, type SlateEditor } from "platejs";

import type { EditorCommand } from "../commands/editor-commands";
import { firstChildForbiddenAttrs } from "../document/editor-document-schema";
import { blockSelectionActive, blockSelectionIds } from "../plugins/editor-block-selection";
import {
  BLOCK_INDENT_MAX,
  BLOCK_INDENT_TYPES,
  blockIndentOf,
  isListParagraph,
  listIndentOf,
} from "./editor-block-indent-style";

export { BLOCK_INDENT_MAX, BLOCK_INDENT_TYPES } from "./editor-block-indent-style";

// A plain block type that can carry indent. A toggle's first child cannot.
export function blockIndentAllowed(editor: SlateEditor, path: number[]): boolean {
  const node = editor.api.node(path)?.[0];
  if (!ElementApi.isElement(node) || !BLOCK_INDENT_TYPES.includes(node.type)) {
    return false;
  }

  const index = path[path.length - 1];
  if (index !== 0 || path.length < 2) {
    return true;
  }

  const parent = editor.api.node(path.slice(0, -1))?.[0];
  return !(
    ElementApi.isElement(parent) && firstChildForbiddenAttrs(parent.type).includes("indent")
  );
}

// Rule: a block selection targets the selected blocks. A text selection targets the lowest
// blocks it touches, so a paragraph inside a quote, callout or cell moves itself. A quote
// moves only when it is block-selected. Code lines are blocks and are refused.
export function blockIndentTargets(editor: SlateEditor): number[][] {
  const paths: number[][] = [];
  if (blockSelectionActive(editor)) {
    const wanted = new Set(blockSelectionIds(editor));
    for (const [, path] of editor.api.nodes({
      at: [],
      match: (candidate) =>
        ElementApi.isElement(candidate) &&
        typeof candidate.id === "string" &&
        wanted.has(candidate.id),
    })) {
      if (blockIndentAllowed(editor, path)) {
        paths.push([...path]);
      }
    }
    return paths;
  }

  if (!editor.selection) {
    return paths;
  }

  for (const [, path] of editor.api.nodes({
    at: editor.selection,
    mode: "lowest",
    match: (candidate) => ElementApi.isElement(candidate) && editor.api.isBlock(candidate),
  })) {
    if (blockIndentAllowed(editor, path)) {
      paths.push([...path]);
    }
  }
  return paths;
}

function canMove(node: unknown, step: 1 | -1): boolean {
  if (isListParagraph(node)) {
    return step < 0 || listIndentOf(node) < BLOCK_INDENT_MAX;
  }

  return step > 0 ? blockIndentOf(node) < BLOCK_INDENT_MAX : blockIndentOf(node) > 0;
}

function movableTargets(editor: SlateEditor, step: 1 | -1): number[][] {
  return blockIndentTargets(editor).filter((path) => canMove(editor.api.node(path)?.[0], step));
}

function stepBlockIndent(editor: SlateEditor, step: 1 | -1): void {
  const targets = movableTargets(editor, step);
  editor.tf.withoutNormalizing(() => {
    for (const path of targets) {
      const node = editor.api.node(path)?.[0];
      if (isListParagraph(node)) {
        // The same list step as Tab and Shift+Tab. Outdent at depth 1 drops the list style.
        setIndent(editor, {
          offset: step,
          getNodesOptions: { at: path, match: (candidate) => isListParagraph(candidate) },
          unsetNodesProps: step < 0 ? [KEYS.listType, KEYS.listChecked] : [],
        });
        continue;
      }

      const next = blockIndentOf(node) + step;
      if (next <= 0) {
        editor.tf.unsetNodes("indent", { at: path });
      } else {
        editor.tf.setNodes({ indent: next }, { at: path });
      }
    }
  });
}

function disabledReasonFor(editor: SlateEditor, step: 1 | -1): string | undefined {
  if (blockIndentTargets(editor).length === 0) {
    return "Indent is not available here.";
  }

  return step > 0 ? "Already at the deepest level." : "Not indented.";
}

function blockIndentCommand(id: string, label: string, step: 1 | -1): EditorCommand {
  return {
    id,
    label,
    group: "format",
    isEnabled: (editor) => movableTargets(editor, step).length > 0,
    disabledReason: (editor) => disabledReasonFor(editor, step),
    run: (editor) => {
      stepBlockIndent(editor, step);
    },
  };
}

export const indentBlocks: EditorCommand = blockIndentCommand("block.indent", "Indent", 1);

export const outdentBlocks: EditorCommand = blockIndentCommand("block.outdent", "Outdent", -1);

