    if (editor.dom.readOnly === true) {
      return;
    }

    const normalized = normalizeBookmarkUrl(url);
    if (normalized === undefined) {
      setPasteRepairs(editor, [{ path: [], message: BOOKMARK_INVALID_URL }]);
      return;
    }

    placeBookmark(editor, normalized);
  },
