    editor.tf.removeNodes({ at: entry[1] });
    if (editor.children.length === 0) {
      editor.tf.insertNodes(
        { type: KEYS.p, id: nanoid(), children: [{ text: "" }] },
        { at: [0], select: true },
      );
    }
  },
};

// Cached preview metadata is not a user edit. Undo still removes the insert that created the block.
export function applyBookmarkPreview(
  editor: SlateEditor,
  blockId: string,
  url: string,
  preview: LinkPreview,
): boolean {
  const entry = writableBookmark(editor, blockId);
  if (entry === undefined || entry[0].url !== url) {
    return false;
  }

  const fields = bookmarkPreviewFields(preview);
  const props: Record<string, string> = { fetchedAt: new Date().toISOString() };
  if (fields.title !== undefined) {
    props.title = fields.title;
  }
  if (fields.description !== undefined) {
    props.description = fields.description;
  }
  if (fields.siteName !== undefined) {
    props.siteName = fields.siteName;
  }
  if (fields.imageUrl !== undefined) {
    props.imageUrl = fields.imageUrl;
  }

  const [, path] = entry;
  const drop = METADATA_KEYS.filter((key) => !(key in props));
  editor.tf.withoutSaving(() => {
    editor.tf.setNodes(props, { at: path });
    if (drop.length > 0) {
      editor.tf.unsetNodes([...drop], { at: path });
    }
  });
  return true;
}

function placeBookmark(editor: SlateEditor, url: string): void {
  const entry = editor.api.block({ highest: true });
  if (entry === undefined || !ElementApi.isElement(entry[0])) {
    return;
  }

  const [node, path] = entry;
  const element = bookmarkElement({ url }, nanoid());
  const replaceEmpty =
    node.type === KEYS.p && editor.api.string(node).length === 0 && path.length === 1;
  if (replaceEmpty) {
    editor.tf.removeNodes({ at: path });
    editor.tf.insertNodes(element, { at: path, select: true });
    return;
  }

  const at = PathApi.next(path);
  if (at === undefined) {
    return;
  }

  editor.tf.insertNodes(element, { at, select: true });
}

function writableBookmark(editor: SlateEditor, id: string): [TElement, number[]] | undefined {
  if (editor.dom.readOnly === true) {
    return undefined;
  }

  for (const [node, path] of editor.api.nodes({
    at: [],
    match: (candidate) =>
      ElementApi.isElement(candidate) && candidate.type === BOOKMARK_KEY && candidate.id === id,
  })) {
    if (ElementApi.isElement(node)) {
      return [node, path];
    }
  }

  return undefined;
}

import type { LanguageFn } from "highlight.js";
import plaintext from "highlight.js/lib/languages/plaintext";
import { createLowlight } from "lowlight";
import { KEYS, TextApi, type SlateEditor, type TElement } from "platejs";

import { CODE_LANGS, codeLangFromToken, type CodeLang } from "../document/editor-document-schema";

// Empty lowlight. plaintext is the only grammar in this module. Every other
// grammar is a dynamic import the first time a block uses that language.
const codeLowlight = createLowlight();
codeLowlight.register("plaintext", plaintext);

const LANGUAGE_LOADERS = {
  typescript: () => import("highlight.js/lib/languages/typescript"),
  tsx: () => import("highlight.js/lib/languages/typescript"),
  javascript: () => import("highlight.js/lib/languages/javascript"),
  jsx: () => import("highlight.js/lib/languages/javascript"),
  json: () => import("highlight.js/lib/languages/json"),
  html: () => import("highlight.js/lib/languages/xml"),
  css: () => import("highlight.js/lib/languages/css"),
  bash: () => import("highlight.js/lib/languages/bash"),
  python: () => import("highlight.js/lib/languages/python"),
  go: () => import("highlight.js/lib/languages/go"),
  rust: () => import("highlight.js/lib/languages/rust"),
  sql: () => import("highlight.js/lib/languages/sql"),
  markdown: () => import("highlight.js/lib/languages/markdown"),
  yaml: () => import("highlight.js/lib/languages/yaml"),
  diff: () => import("highlight.js/lib/languages/diff"),
} as const satisfies Record<CodeLang, () => Promise<{ default: LanguageFn }>>;

const loadingLanguages = new Map<CodeLang, Promise<void>>();

export { codeLowlight };

export function ensureCodeLanguage(lang: string): Promise<void> {
  const stored = CODE_LANGS.find((item) => item === lang);
  if (stored === undefined || codeLowlight.registered(stored)) {
    return Promise.resolve();
  }

  const pending = loadingLanguages.get(stored);
  if (pending !== undefined) {
    return pending;
  }

  const task = LANGUAGE_LOADERS[stored]().then((loaded) => {
    if (!codeLowlight.registered(stored)) {
      codeLowlight.register(stored, loaded.default);
    }
  });
  loadingLanguages.set(stored, task);
  return task;
}

function isHtmlElement(node: unknown): node is HTMLElement {
  return (
    typeof node === "object" &&
    node !== null &&
    "nodeType" in node &&
    node.nodeType === Node.ELEMENT_NODE &&
    "tagName" in node &&
    typeof node.tagName === "string" &&
    "childNodes" in node
  );
}

function codeClassToken(element: HTMLElement): string | undefined {
  const nested = element.querySelector("code");
  const source = nested ?? element;
  const className = source.getAttribute("class") ?? "";
  const match = /(?:^|\s)(?:language|lang)-(\S+)/.exec(className);
  return match?.[1];
}

// textContent drops <br>, so a walked tree keeps one newline per break.
function codeElementText(element: HTMLElement): string {
  let text = "";
  for (const child of Array.from(element.childNodes)) {
    if (child.nodeType === Node.TEXT_NODE) {
      text += child.textContent ?? "";
      continue;
    }

    if (!isHtmlElement(child)) {
      continue;
    }

    if (child.tagName === "BR") {
      text += "\n";
      continue;
    }

    text += codeElementText(child);
  }

  return text;
}

// Plate's PRE parser does not read language-*. This one maps the class, then
// omits lang for plaintext and for any token outside the allowlist.
export const codeBlockHtmlDeserializer = {
  rules: [{ validNodeName: "PRE" }],
  parse({ element }: { element: HTMLElement }) {
    const text = codeElementText(element);
    const lines = text.split("\n");
    const token = codeClassToken(element);
    const lang = token === undefined ? null : codeLangFromToken(token);
    const node: TElement = {
      type: KEYS.codeBlock,
      children: (lines.length > 0 ? lines : [""]).map((line) => ({
        type: KEYS.codeLine,
        children: [{ text: line }],
      })),
    };
    if (lang !== null) {
      node.lang = lang;
    }

    return node;
  },
};

// Inside a code block the clipboard is literal text. text/plain wins. A
// text/html-only payload is inserted as the raw string, so "&amp;" stays "&amp;".
export function codeClipboardText(data: DataTransfer): string {
  const plain = data.getData("text/plain");
  if (plain.length > 0) {
    return plain;
  }

  return data.getData("text/html");
}

export function insertCodeText(editor: SlateEditor, text: string): void {
  const lines = text.split("\n");
  const first = lines[0] ?? "";
  if (first.length > 0) {
    editor.tf.insertText(first);
  }

  const rest = lines.slice(1);
  if (rest.length === 0) {
    return;
  }

  const codeLine = editor.getType(KEYS.codeLine);
  editor.tf.insertNodes(
    rest.map((line) => ({
      type: codeLine,
      children: [{ text: line }],
    })),
  );
}

export function selectionInCodeBlock(editor: SlateEditor): boolean {
  return editor.api.above({ match: { type: editor.getType(KEYS.codeBlock) } }) !== undefined;
}

export function caretInCodeMark(editor: SlateEditor): boolean {
  const selection = editor.selection;
  if (!selection || !editor.api.isCollapsed()) {
    return false;
  }

  const entry = editor.api.node(selection.anchor.path);
  return entry !== undefined && TextApi.isText(entry[0]) && entry[0][KEYS.code] === true;
}

export function htmlToPlainText(html: string): string {
  if (html.length === 0) {
    return "";
  }

  const body = new DOMParser().parseFromString(html, "text/html").body;
  return body.textContent ?? "";
}

// Pure date helpers for the inline date. No React, no Plate, so the static renderer can import them.
// A stored date is a calendar date only: "YYYY-MM-DD", with no time and no zone. Every conversion
// below reads and writes plain Y-M-D numbers, so no Date is ever parsed from a string.

type StoredDateParts = { year: number; month: number; day: number };

const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

// Plain arithmetic, not Date.UTC: Date.UTC maps years 0-99 to 1900-1999.
function daysInMonth(year: number, month: number): number {
  if (month === 2) {
    return isLeapYear(year) ? 29 : 28;
  }

  return month === 4 || month === 6 || month === 9 || month === 11 ? 30 : 31;
}

export function parseStoredDate(value: unknown): StoredDateParts | null {
  if (typeof value !== "string") {
    return null;
  }

  const match = ISO_DATE.exec(value);
  if (match === null) {
    return null;
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (year < 1 || month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
    return null;
  }

  return { year, month, day };
}

export function isStoredDate(value: unknown): value is string {
  return parseStoredDate(value) !== null;
}

// Returns the stored form for valid calendar parts, or null for anything else.
export function toStoredDate(year: number, month: number, day: number): string | null {
  if (!Number.isInteger(year) || !Number.isInteger(month) || !Number.isInteger(day)) {
    return null;
  }

  const text = `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
  return isStoredDate(text) ? text : null;
}

// The absolute label, e.g. "Oct 12, 2026". The date is built in UTC from its parts, so no
// timezone can shift it. setUTCFullYear keeps years 1-99 from being read as 1900-1999.
export function formatStoredDate(value: unknown): string {
  const parts = parseStoredDate(value);
  if (parts === null) {
    return "Invalid date";
  }

  const date = new Date(0);
  date.setUTCFullYear(parts.year, parts.month - 1, parts.day);
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  }).format(date);
}

// The user's local calendar day, as a stored date.
export function todayStoredDate(now: Date = new Date()): string {
  const year = String(now.getFullYear()).padStart(4, "0");
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

// react-day-picker works in local calendar days: a picked day is the Date whose local Y/M/D
// is the day the user clicked. So a stored date becomes a local Date at noon (no DST edge at
// midnight), and a picked Date is read back with its local Y/M/D. The result is the same in any TZ.
export function storedDateToCalendarDate(value: unknown): Date | undefined {
  const parts = parseStoredDate(value);
  if (parts === null) {
    return undefined;
  }

  const date = new Date(2000, 0, 1, 12);
  date.setFullYear(parts.year, parts.month - 1, parts.day);
  return date;
}

export function calendarDateToStoredDate(date: Date): string | null {
  return toStoredDate(date.getFullYear(), date.getMonth() + 1, date.getDate());
}

import type { EditorCommand } from "../commands/editor-commands";
import { EMBED_KEY, embedFieldsOf, EMBED_SOURCE_ATTRS } from "./editor-embed";
import { parseEmbedUrl } from "./editor-embed-url";
import type { UploadedFile } from "./editor-file-upload";
import {
  createMediaAlignCommand,
  createMediaCaptionCommand,
  createMediaInsertCommand,
  createMediaRemoveCommand,
  createMediaWidthCommand,
  writableMediaBlock,
} from "./editor-media-commands";

// The embed commands. A link that is not YouTube or Vimeo is refused. The layout commands are the
// shared ones the video block uses.

export const insertEmbed: EditorCommand<{ id: string }> = createMediaInsertCommand(EMBED_KEY);

// Stores the provider, id, hash, start and normalized link of a YouTube or Vimeo link. Only the url of
// the file is read. Any other link gives false and changes nothing.
export const setEmbedSource: EditorCommand<{ id: string; file: UploadedFile }> = {
  id: "block.embed.set-source",
  label: "Set embed",
  group: "action",
  run: (editor, { id, file }) => {
    const entry = writableMediaBlock(editor, id, EMBED_KEY);
    const parsed = parseEmbedUrl(file.url);
    if (entry === undefined || parsed === undefined) {
      return false;
    }

    const fields = embedFieldsOf(parsed);
    const props: Record<string, string | number> = {
      provider: parsed.provider,
      videoId: parsed.videoId,
      url: parsed.sourceUrl,
    };
    if (fields.hash !== undefined) {
      props.hash = fields.hash;
    }
    if (fields.startSeconds !== undefined) {
      props.startSeconds = fields.startSeconds;
    }

    const drop = EMBED_SOURCE_ATTRS.filter((key) => !(key in props));
    editor.tf.setNodes(props, { at: entry[1] });
    if (drop.length > 0) {
      editor.tf.unsetNodes([...drop], { at: entry[1] });
    }
    return true;
  },
};

export const setEmbedCaption = createMediaCaptionCommand(EMBED_KEY);

// null removes the width, which means the natural size.
export const setEmbedWidth = createMediaWidthCommand(EMBED_KEY);

export const setEmbedAlign = createMediaAlignCommand(EMBED_KEY);

// Removes the block. An empty document gets an empty paragraph, as the bookmark remove does.
export const removeEmbed = createMediaRemoveCommand(EMBED_KEY);

// Parses a YouTube or Vimeo link into the provider and id the embed block stores. Only these hosts
// are read. The frame src is built here from the provider, id, hash and start time, never from the
// stored url, so no other site can be framed.

export const EMBED_URL_MAX = 2048;

const YOUTUBE_ID = /^[A-Za-z0-9_-]{11}$/;
const VIMEO_ID = /^\d{1,12}$/;
const VIMEO_HASH = /^[0-9a-f]{6,20}$/;

const YOUTUBE_HOSTS = new Set([
  "youtube.com",
  "www.youtube.com",
  "m.youtube.com",
  "music.youtube.com",
  "youtu.be",
  "www.youtu.be",
  "m.youtu.be",
  "youtube-nocookie.com",
  "www.youtube-nocookie.com",
  "m.youtube-nocookie.com",
]);

const VIMEO_HOSTS = new Set([
  "vimeo.com",
  "www.vimeo.com",
  "m.vimeo.com",
  "player.vimeo.com",
  "www.player.vimeo.com",
  "m.player.vimeo.com",
]);

export const EMBED_IFRAME_ALLOW =
  "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; fullscreen";

export const EMBED_SANDBOX =
  "allow-scripts allow-same-origin allow-presentation allow-popups allow-popups-to-escape-sandbox";

export type EmbedProvider = "youtube" | "vimeo";

export type ParsedEmbed = {
  provider: EmbedProvider;
  videoId: string;
  hash?: string;
  startSeconds?: number;
  sourceUrl: string; // the normalized https link, without credentials or port
};

export function parseEmbedUrl(input: string): ParsedEmbed | undefined {
  const trimmed = input.trim();
  if (trimmed.length === 0 || trimmed.length > EMBED_URL_MAX) {
    return undefined;
  }

  let url: URL;
  try {
    url = new URL(trimmed);
  } catch {
    return undefined;
  }

  if (url.protocol !== "http:" && url.protocol !== "https:") {
    return undefined;
  }

  if (url.username.length > 0 || url.password.length > 0 || url.port.length > 0) {
    return undefined;
  }

  const host = url.hostname.toLowerCase();
  const start = readStart(url);
  if (!start.ok) {
    return undefined;
  }

  const parsed = YOUTUBE_HOSTS.has(host)
    ? parseYouTube(url, host)
    : VIMEO_HOSTS.has(host)
      ? parseVimeo(url, host)
      : undefined;
  if (parsed === undefined) {
    return undefined;
  }

  const sourceUrl = normalizedHttps(url);
  if (sourceUrl.length > EMBED_URL_MAX) {
    return undefined;
  }

  const embed: ParsedEmbed = {
    provider: parsed.provider,
    videoId: parsed.videoId,
    sourceUrl,
  };
  const hash = "hash" in parsed ? parsed.hash : undefined;
  if (hash !== undefined) {
    embed.hash = hash;
  }
  if (start.seconds !== undefined) {
    embed.startSeconds = start.seconds;
  }

  return embed;
}

export function isYouTubeShort(sourceUrl: string): boolean {
  let url: URL;
  try {
    url = new URL(sourceUrl);
  } catch {
    return false;
  }

  const [first] = pathSegments(url);
  return first === "shorts";
}

export function embedTitle(provider: EmbedProvider): string {
  return provider === "youtube" ? "YouTube video" : "Vimeo video";
}

export function embedProviderLabel(provider: EmbedProvider): string {
  return provider === "youtube" ? "YouTube" : "Vimeo";
}

// The page a viewer can open, built from the provider and id only.
export function embedWatchUrl(provider: EmbedProvider, videoId: string): string {
  return provider === "youtube"
    ? `https://www.youtube.com/watch?v=${videoId}`
    : `https://vimeo.com/${videoId}`;
}

export function embedFrameSrc(
  embed: Pick<ParsedEmbed, "provider" | "videoId" | "hash" | "startSeconds">,
  autoplay: boolean,
): string {
  const params = new URLSearchParams();
  if (embed.provider === "youtube") {
    if (embed.startSeconds !== undefined) {
      params.set("start", String(embed.startSeconds));
    }
  } else if (embed.hash !== undefined) {
    params.set("h", embed.hash);
  }
  if (autoplay) {
    params.set("autoplay", "1");
  }
  const query = params.toString();
  const suffix = query.length > 0 ? `?${query}` : "";

  if (embed.provider === "youtube") {
    return `https://www.youtube-nocookie.com/embed/${embed.videoId}${suffix}`;
  }

  const time = embed.startSeconds !== undefined ? `#t=${String(embed.startSeconds)}s` : "";
  return `https://player.vimeo.com/video/${embed.videoId}${suffix}${time}`;
}

export function isEmbedVideoId(provider: EmbedProvider, videoId: string): boolean {
  return provider === "youtube" ? YOUTUBE_ID.test(videoId) : VIMEO_ID.test(videoId);
}

export function isEmbedHash(hash: string): boolean {
  return VIMEO_HASH.test(hash);
}

function parseYouTube(
  url: URL,
  host: string,
): { provider: "youtube"; videoId: string } | undefined {
  const parts = pathSegments(url);
  const shortHost = host === "youtu.be" || host === "www.youtu.be" || host === "m.youtu.be";
  if (shortHost) {
    const id = parts.length === 1 ? parts[0] : undefined;
    return youtubeId(id);
  }

  const nocookie =
    host === "youtube-nocookie.com" ||
    host === "www.youtube-nocookie.com" ||
    host === "m.youtube-nocookie.com";
  if (nocookie) {
    return parts.length === 2 && parts[0] === "embed" ? youtubeId(parts[1]) : undefined;
  }

  const music = host === "music.youtube.com";
  if (music) {
    return parts.length === 1 && parts[0] === "watch"
      ? youtubeId(url.searchParams.get("v"))
      : undefined;
  }

  if (parts.length === 1 && parts[0] === "watch") {
    return youtubeId(url.searchParams.get("v"));
  }

  if (
    parts.length === 2 &&
    (parts[0] === "shorts" || parts[0] === "embed" || parts[0] === "live")
  ) {
    return youtubeId(parts[1]);
  }

  return undefined;
}

function parseVimeo(
  url: URL,
  host: string,
): { provider: "vimeo"; videoId: string; hash?: string } | undefined {
  const parts = pathSegments(url);
  const player =
    host === "player.vimeo.com" || host === "www.player.vimeo.com" || host === "m.player.vimeo.com";
  if (player) {
    if (parts.length !== 2 || parts[0] !== "video") {
      return undefined;
    }
    return vimeoId(parts[1], url.searchParams.get("h"));
  }

  if (parts.length === 1) {
    return vimeoId(parts[0], null);
  }

  if (parts.length === 2 && parts[1] !== undefined && isEmbedHash(parts[1].toLowerCase())) {
    return vimeoId(parts[0], parts[1]);
  }

  return undefined;
}

function youtubeId(
  id: string | null | undefined,
): { provider: "youtube"; videoId: string } | undefined {
  if (id === undefined || id === null || !YOUTUBE_ID.test(id)) {
    return undefined;
  }

  return { provider: "youtube", videoId: id };
}

function vimeoId(
  id: string | undefined,
  hash: string | null,
): { provider: "vimeo"; videoId: string; hash?: string } | undefined {
  if (id === undefined || !VIMEO_ID.test(id)) {
    return undefined;
  }

  if (hash === null || hash.length === 0) {
    return { provider: "vimeo", videoId: id };
  }

  const normalized = hash.toLowerCase();
  if (!isEmbedHash(normalized)) {
    return undefined;
  }

  return { provider: "vimeo", videoId: id, hash: normalized };
}

function pathSegments(url: URL): string[] {
  return url.pathname.split("/").filter((part) => part.length > 0);
}

function readStart(url: URL): { ok: true; seconds?: number } | { ok: false } {
  const raw = firstTime(url);
  if (raw === undefined) {
    return { ok: true };
  }

  const seconds = parseClock(raw);
  if (seconds === undefined) {
    return { ok: false };
  }

  return { ok: true, seconds };
}

// The first of t, start, or a #t= fragment. The query wins over the fragment.
function firstTime(url: URL): string | undefined {
  if (url.searchParams.has("t")) {
    return url.searchParams.get("t") ?? "";
  }

  if (url.searchParams.has("start")) {
    return url.searchParams.get("start") ?? "";
  }

  if (url.hash.length > 1) {
    const params = new URLSearchParams(url.hash.slice(1));
    if (params.has("t")) {
      return params.get("t") ?? "";
    }
  }

  return undefined;
}

// Plain seconds, or 1h2m3s in any part. Anything else is not a start time.
function parseClock(value: string): number | undefined {
  if (/^\d{1,9}$/.test(value)) {
    return Number(value);
  }

  const match = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/i.exec(value);
  if (match === null) {
    return undefined;
  }

  const hours = match[1];
  const minutes = match[2];
  const seconds = match[3];
  if (hours === undefined && minutes === undefined && seconds === undefined) {
    return undefined;
  }

  const total = Number(hours ?? 0) * 3600 + Number(minutes ?? 0) * 60 + Number(seconds ?? 0);
  if (!Number.isSafeInteger(total)) {
    return undefined;
  }

  return total;
}

function normalizedHttps(url: URL): string {
  const copy = new URL(url.href);
  copy.protocol = "https:";
  copy.username = "";
  copy.password = "";
  copy.port = "";
  return copy.href;
}

import type { TElement } from "platejs";

import {
  cleanMediaLayoutFields,
  isMediaAlign,
  isMediaCaption,
  isMediaWidth,
  type MediaLayoutFields,
} from "./editor-media-layout";
import {
  isEmbedHash,
  isEmbedVideoId,
  parseEmbedUrl,
  type EmbedProvider,
  type ParsedEmbed,
} from "./editor-embed-url";

// The embed block: a YouTube or Vimeo video that plays from its link. It has the video block's width,
// alignment and caption. The commands are in editor-embed-commands.ts. This module imports no command
// code, so the static renderer can use it.

export const EMBED_KEY = "embed";

export const EMBED_SOURCE_REMOVED =
  "An embed has a provider, video id or hash that is not valid. The embed was cleared to an empty placeholder.";
export const EMBED_ATTRS_CLEANED =
  "An embed lost an attribute that is not valid. The embed was kept.";

// The attributes that make up the video. A bad one clears the block, so they are read together.
export const EMBED_SOURCE_ATTRS = ["provider", "videoId", "hash", "startSeconds", "url"] as const;

// A literal list. The embed fields are written in this order.
export const EMBED_FIELD_KEYS = [
  "provider",
  "videoId",
  "hash",
  "startSeconds",
  "url",
  "width",
  "align",
  "caption",
] as const;

type EmbedFields = MediaLayoutFields & {
  provider?: EmbedProvider;
  videoId?: string;
  hash?: string;
  startSeconds?: number;
  url?: string; // the normalized https link the embed came from, for Open original
};

type CleanedEmbed = {
  fields: EmbedFields;
  dropped: boolean; // true when a field was present and removed
  cleared: boolean; // true when the source was not valid, so the block is a placeholder
};

// The check for one stored embed attribute. A url must parse as a YouTube or Vimeo link.
export function isStoredEmbedAttr(attr: string, value: unknown): boolean {
  switch (attr) {
    case "provider":
      return value === "youtube" || value === "vimeo";
    case "videoId":
      return (
        typeof value === "string" &&
        (isEmbedVideoId("youtube", value) || isEmbedVideoId("vimeo", value))
      );
    case "hash":
      return typeof value === "string" && isEmbedHash(value);
    case "startSeconds":
      return isStartSeconds(value);
    case "url":
      return typeof value === "string" && parseEmbedUrl(value) !== undefined;
    case "width":
      return isMediaWidth(value);
    case "align":
      return isMediaAlign(value);
    case "caption":
      return isMediaCaption(value);
    default:
      return false;
  }
}

function isStartSeconds(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

// The provider, id and hash together. A hash is only valid for Vimeo, and a key that is present must
// be valid. Undefined means the source is not valid.
function embedCore(
  raw: Record<string, unknown>,
): { provider: EmbedProvider; videoId: string; hash?: string } | undefined {
  const { provider, videoId } = raw;
  if (
    (provider !== "youtube" && provider !== "vimeo") ||
    typeof videoId !== "string" ||
    !isEmbedVideoId(provider, videoId)
  ) {
    return undefined;
  }

  if (!("hash" in raw)) {
    return { provider, videoId };
  }

  const hash = raw.hash;
  return provider === "vimeo" && typeof hash === "string" && isEmbedHash(hash)
    ? { provider, videoId, hash }
    : undefined;
}

// A url is kept only when it is a YouTube or Vimeo link for the same provider and id.
function sameSource(url: string, core: { provider: EmbedProvider; videoId: string }): boolean {
  const parsed = parseEmbedUrl(url);
  return (
    parsed !== undefined && parsed.provider === core.provider && parsed.videoId === core.videoId
  );
}

// Cleans each field of a raw embed block, the way the validator and paste do. A stored embed comes out
// unchanged. A bad provider, id or hash clears the source, and the layout stays. Any other bad field is
// left out and sets `dropped`. Keys the embed does not have are dropped too.
export function cleanEmbedFields(raw: Record<string, unknown>): CleanedEmbed {
  const layout = cleanMediaLayoutFields(raw);
  const touched = EMBED_SOURCE_ATTRS.some((key) => key in raw);
  const core = embedCore(raw);
  if (touched && core === undefined) {
    return { fields: layout.fields, dropped: true, cleared: true };
  }

  const fields: EmbedFields = { ...layout.fields };
  let dropped = layout.dropped;
  if (core !== undefined) {
    fields.provider = core.provider;
    fields.videoId = core.videoId;
    if (core.hash !== undefined) {
      fields.hash = core.hash;
    }
  }

  if ("startSeconds" in raw) {
    if (isStartSeconds(raw.startSeconds)) {
      fields.startSeconds = raw.startSeconds;
    } else {
      dropped = true;
    }
  }

  if ("url" in raw) {
    const url = raw.url;
    if (core !== undefined && typeof url === "string" && sameSource(url, core)) {
      fields.url = url;
    } else {
      dropped = true;
    }
  }

  const known = new Set<string>(["id", "type", "children", ...EMBED_FIELD_KEYS]);
  if (Object.keys(raw).some((key) => !known.has(key))) {
    dropped = true;
  }

  return { fields, dropped, cleared: false };
}

// The fields of a parsed link, as the block stores them.
export function embedFieldsOf(parsed: ParsedEmbed): EmbedFields {
  const fields: EmbedFields = { provider: parsed.provider, videoId: parsed.videoId };
  if (parsed.hash !== undefined) {
    fields.hash = parsed.hash;
  }
  if (parsed.startSeconds !== undefined) {
    fields.startSeconds = parsed.startSeconds;
  }
  fields.url = parsed.sourceUrl;
  return fields;
}

export function embedElement(fields: EmbedFields, id?: string): TElement {
  const node: TElement = { type: EMBED_KEY, children: [{ text: "" }] };
  if (id !== undefined) {
    node.id = id;
  }

  for (const key of EMBED_FIELD_KEYS) {
    const value = fields[key];
    if (value !== undefined) {
      node[key] = value;
    }
  }
  return node;
}

// Rewrites a raw embed block to its cleaned fields. Its id and children stay.
export function applyCleanedEmbed(node: Record<string, unknown>): void {
  const cleaned = cleanEmbedFields(node);
  for (const key of Object.keys(node)) {
    if (key !== "id" && key !== "type" && key !== "children") {
      Reflect.deleteProperty(node, key);
    }
  }
  Object.assign(node, cleaned.fields);
}

import { ElementApi, KEYS, NodeApi, type SlateEditor } from "platejs";

import { editorIsComposing } from "../plugins/editor-mention";
import { selectionInCodeBlock } from "./editor-code";
import { blockTextOffset } from "./editor-slash";
import type { EmojiEntry } from "./emoji-data";
import { featureEnabled } from "../plugins/editor-config";

export const EMOJI_SUGGEST_LIMIT = 8;

// The colon must start the block or follow whitespace, so 10:30, http://x and a:sm never match.
const TRIGGER_PATTERN = /(^|\s):([a-z0-9_+-]{2,})$/i;
const CLOSING_PATTERN = /(^|\s):([a-z0-9_+-]{2,}):$/i;

type EmojiSession = {
  blockId: string;
  blockPath: number[];
  // Block text offsets of the colon and of the caret. The token is the text between them, without the colon.
  colon: number;
  caret: number;
  token: string;
};

export type EmojiReplacement = {
  emoji: string;
  blockPath: number[];
  start: number;
  end: number;
};

let loadedEntries: readonly EmojiEntry[] | null = null;
let pendingLoad: Promise<readonly EmojiEntry[]> | null = null;

// The data is a dynamic import, so the editor's first-load chunk does not carry it.
export function loadedEmojiEntries(): readonly EmojiEntry[] | null {
  return loadedEntries;
}

// Test hook: forget the loaded data so a test can observe a late load.
export function resetEmojiDataForTests(): void {
  loadedEntries = null;
  pendingLoad = null;
}

export function loadEmojiEntries(): Promise<readonly EmojiEntry[]> {
  if (pendingLoad === null) {
    pendingLoad = import("./emoji-data").then(({ EMOJI_ENTRIES }) => {
      loadedEntries = EMOJI_ENTRIES;
      return EMOJI_ENTRIES;
    });
  }
  return pendingLoad;
}

function emojiMatchRank(entry: EmojiEntry, needle: string): number | null {
  if (entry.name === needle) {
    return 0;
  }
  if (entry.name.startsWith(needle)) {
    return 1;
  }
  if (entry.keywords.some((keyword) => keyword.startsWith(needle))) {
    return 2;
  }
  if (entry.name.includes(needle)) {
    return 3;
  }
  return null;
}

export function searchEmoji(
  entries: readonly EmojiEntry[],
  query: string,
  limit: number = EMOJI_SUGGEST_LIMIT,
): EmojiEntry[] {
  const needle = query.toLowerCase();
  if (needle.length < 2) {
    return [];
  }

  const ranked: { entry: EmojiEntry; rank: number; order: number }[] = [];
  entries.forEach((entry, order) => {
    const rank = emojiMatchRank(entry, needle);
    if (rank !== null) {
      ranked.push({ entry, rank, order });
    }
  });
  return ranked
    .sort((left, right) => left.rank - right.rank || left.order - right.order)
    .slice(0, limit)
    .map((item) => item.entry);
}

// Shared gate for the trigger and the closing colon. Read-only, composition, code blocks,
// mention input and void blocks never convert text. Links and code marks do not block.
function readEmojiBlock(
  editor: SlateEditor,
): { blockId: string; blockPath: number[]; caret: number; before: string } | null {
  if (
    editor.dom.readOnly === true ||
    editor.selection === null ||
    !editor.api.isCollapsed() ||
    editorIsComposing(editor)
  ) {
    return null;
  }
  if (
    selectionInCodeBlock(editor) ||
    editor.api.above({ match: { type: editor.getType(KEYS.mentionInput) } }) !== undefined
  ) {
    return null;
  }
  // The lowest block above the caret, read from its ancestors. `api.block()` would walk
  // the document from its root to the caret.
  const block = editor.api.above({ block: true });
  if (!block || !ElementApi.isElement(block[0]) || typeof block[0].id !== "string") {
    return null;
  }
  if (editor.api.isVoid(block[0])) {
    return null;
  }
  const caret = blockTextOffset(editor, block[1], editor.selection.anchor);
  if (caret === null) {
    return null;
  }
  return {
    blockId: block[0].id,
    blockPath: block[1],
    caret,
    before: NodeApi.string(block[0]).slice(0, caret),
  };
}

export function readEmojiSession(editor: SlateEditor): EmojiSession | null {
  if (!featureEnabled(editor, "emoji")) {
    return null;
  }
  const block = readEmojiBlock(editor);
  if (block === null) {
    return null;
  }
  const match = TRIGGER_PATTERN.exec(block.before);
  const token = match?.[2];
  if (token === undefined) {
    return null;
  }
  return {
    blockId: block.blockId,
    blockPath: block.blockPath,
    colon: block.caret - token.length - 1,
    caret: block.caret,
    token,
  };
}

// The closing colon converts only an exact entry name, so :+1: and :Smile: stay text.
export function readClosingEmoji(
  editor: SlateEditor,
  entries: readonly EmojiEntry[],
): EmojiReplacement | null {
  const block = readEmojiBlock(editor);
  if (block === null) {
    return null;
  }
  const name = CLOSING_PATTERN.exec(block.before)?.[2];
  if (name === undefined) {
    return null;
  }
  const entry = entries.find((item) => item.name === name);
  if (entry === undefined) {
    return null;
  }
  return {
    emoji: entry.emoji,
    blockPath: block.blockPath,
    start: block.caret - name.length - 2,
    end: block.caret,
  };
}

import type { KatexOptions } from "katex";

export const EQUATION_EMPTY_PLACEHOLDER = "Add an equation";

export const EQUATION_KATEX_OPTIONS = {
  displayMode: true,
  throwOnError: true,
  trust: false,
  strict: "ignore",
  maxSize: 10,
  maxExpand: 1000,
  output: "htmlAndMathml",
} as const satisfies KatexOptions;

type KatexModule = {
  renderToString: (expression: string, options: KatexOptions) => string;
};

export const INLINE_EQUATION_EMPTY_PLACEHOLDER = "New equation";

const INLINE_EQUATION_KATEX_OPTIONS = {
  ...EQUATION_KATEX_OPTIONS,
  displayMode: false,
} as const satisfies KatexOptions;

export type EquationRender = { ok: true; html: string } | { ok: false; message: string };

export function renderEquation(katex: KatexModule, expression: string): EquationRender {
  try {
    return { ok: true, html: katex.renderToString(expression, EQUATION_KATEX_OPTIONS) };
  } catch (error) {
    const message = error instanceof Error ? error.message : "This equation could not be rendered.";
    return { ok: false, message };
  }
}

export function renderInlineEquation(katex: KatexModule, expression: string): EquationRender {
  try {
    return { ok: true, html: katex.renderToString(expression, INLINE_EQUATION_KATEX_OPTIONS) };
  } catch (error) {
    const message = error instanceof Error ? error.message : "This equation could not be rendered.";
    return { ok: false, message };
  }
}

import {
  ElementApi,
  KEYS,
  PathApi,
  createSlatePlugin,
  nanoid,
  type SlateEditor,
  type TElement,
} from "platejs";
import type { KatexOptions } from "katex";

import type { EditorCommand } from "../commands/editor-commands";

export {
  EQUATION_EMPTY_PLACEHOLDER,
  EQUATION_KATEX_OPTIONS,
  renderEquation,
  type EquationRender,
} from "./editor-equation-render";

type KatexModule = {
  renderToString: (expression: string, options: KatexOptions) => string;
};

let katexModule: Promise<KatexModule> | undefined;

// The public @platejs/math entries import katex statically. Loading it on the
// first equation keeps that library off the first paint.
export function loadKatex(): Promise<KatexModule> {
  katexModule ??= import("katex").then((mod) => mod.default);
  return katexModule;
}

// The native plugin is not registered: its react entry imports katex statically, which would put KaTeX in the first-load bundle.
export const equationPlugin = createSlatePlugin({
  key: KEYS.equation,
  node: { isElement: true, isVoid: true },
  options: { editingId: "" },
});

export function equationEditingId(editor: SlateEditor): string {
  const value: unknown = editor.getOption(equationPlugin, "editingId");
  return typeof value === "string" ? value : "";
}

export function openEquationEditor(editor: SlateEditor, id: string): void {
  editor.setOption(equationPlugin, "editingId", id);
}

export function closeEquationEditor(editor: SlateEditor): void {
  if (equationEditingId(editor).length === 0) {
    return;
  }
  editor.setOption(equationPlugin, "editingId", "");
}

type EquationKeyEvent = {
  key: string;
  shiftKey: boolean;
  metaKey: boolean;
  ctrlKey: boolean;
  altKey: boolean;
  defaultPrevented: boolean;
  preventDefault: () => void;
};

// Enter on the selected void opens the editor. A paragraph is not inserted.
export function onEquationKeyDown(editor: SlateEditor, event: EquationKeyEvent): void {
  if (
    event.defaultPrevented ||
    event.key !== "Enter" ||
    event.shiftKey ||
    event.metaKey ||
    event.ctrlKey ||
    event.altKey
  ) {
    return;
  }

  const block = editor.api.block();
  if (!block || !ElementApi.isElement(block[0]) || block[0].type !== KEYS.equation) {
    return;
  }

  const id = block[0].id;
  if (typeof id !== "string" || id.length === 0) {
    return;
  }

  event.preventDefault();
  openEquationEditor(editor, id);
}

function equationNode(id: string): TElement {
  return {
    type: KEYS.equation,
    id,
    texExpression: "",
    children: [{ text: "" }],
  };
}

function insertEquationBlock(editor: SlateEditor): void {
  const id = nanoid();
  const current = editor.api.block({ highest: true });
  if (!current) {
    editor.tf.insertNodes(equationNode(id), { at: [0], select: true });
  } else {
    const at = PathApi.next(current[1]);
    if (!at) {
      return;
    }
    editor.tf.insertNodes(equationNode(id), { at, select: true });
  }

  openEquationEditor(editor, id);
}

// Insert an equation as the next sibling of `path`, inside its container. The
// block menu only converts; the Add picker needs a path-targeted insert.
export function insertEquationBelow(editor: SlateEditor, path: readonly number[]): string | null {
  const at = PathApi.next([...path]);
  if (!at) {
    return null;
  }
  const id = nanoid();
  editor.tf.insertNodes(equationNode(id), { at, select: true });
  openEquationEditor(editor, id);
  return id;
}

export function removeEquation(editor: SlateEditor, path: number[]): void {
  closeEquationEditor(editor);
  editor.tf.removeNodes({ at: path, voids: true });
  if (editor.children.length === 0) {
    editor.tf.insertNodes({ type: KEYS.p, children: [{ text: "" }] }, { at: [0] });
  }
}

export const insertEquation: EditorCommand = {
  id: "block.insert.equation",
  label: "Equation",
  group: "insert",
  run: (editor) => {
    insertEquationBlock(editor);
  },
};

function selectedEquation(editor: SlateEditor): [TElement, number[]] | undefined {
  for (const entry of editor.api.nodes({
    match: (node) => ElementApi.isElement(node) && node.type === KEYS.equation,
    voids: true,
    mode: "lowest",
  })) {
    if (ElementApi.isElement(entry[0])) {
      return [entry[0], entry[1]];
    }
  }
  return undefined;
}

export const removeEquationCommand: EditorCommand = {
  id: "block.equation.remove",
  label: "Delete",
  group: "action",
  isEnabled: (editor) => selectedEquation(editor) !== undefined,
  run: (editor) => {
    const entry = selectedEquation(editor);
    if (!entry) {
      return;
    }
    removeEquation(editor, entry[1]);
  },
};

import { KEYS } from "platejs";

import { AUDIO_KEY } from "./editor-audio";
import { BOOKMARK_KEY } from "./editor-bookmark-url";
import { EMBED_KEY } from "./editor-embed";
import { FILE_KEY } from "./editor-file";
import { IMAGE_KEY } from "./editor-image";
import { PAGE_LINK_KEY } from "./editor-page-link";
import { VIDEO_KEY } from "./editor-video";
import { FOOTNOTE_DEF_KEY, FOOTNOTE_REF_KEY } from "../document/editor-document-schema";

// The feature groups a host can turn off. Each one names what it hides in README.md, "Features".
export const EDITOR_FEATURES = [
  "media",
  "embeds",
  "tables",
  "columns",
  "code",
  "equations",
  "mentions",
  "pageLinks",
  "footnotes",
  "dates",
  "emoji",
  "toc",
  "find",
  "slashMenu",
  "selectionToolbar",
  "blockHandle",
] as const;

export type EditorFeature = (typeof EDITOR_FEATURES)[number];

// What a host passes. A feature is on unless it is set to false.
export type EditorFeatures = Partial<Record<EditorFeature, boolean>>;

export type ResolvedEditorFeatures = Record<EditorFeature, boolean>;

export const DEFAULT_EDITOR_FEATURES: ResolvedEditorFeatures = {
  media: true,
  embeds: true,
  tables: true,
  columns: true,
  code: true,
  equations: true,
  mentions: true,
  pageLinks: true,
  footnotes: true,
  dates: true,
  emoji: true,
  toc: true,
  find: true,
  slashMenu: true,
  selectionToolbar: true,
  blockHandle: true,
};

// Only the boolean false turns a feature off. Anything else, and any unknown key, is ignored.
// A value that is not an object gives the defaults.
export function resolveEditorFeatures(features?: EditorFeatures): ResolvedEditorFeatures {
  const source: unknown = features;
  const resolved: ResolvedEditorFeatures = { ...DEFAULT_EDITOR_FEATURES };
  if (typeof source !== "object" || source === null) {
    return resolved;
  }

  for (const feature of EDITOR_FEATURES) {
    if (Reflect.get(source, feature) === false) {
      resolved[feature] = false;
    }
  }
  return resolved;
}

// Two resolved values with the same flags have the same key, in the order of EDITOR_FEATURES.
export function editorFeaturesKey(resolved: ResolvedEditorFeatures): string {
  return JSON.stringify(EDITOR_FEATURES.map((feature) => resolved[feature]));
}

// Slash and picker item ids that a feature gates. An item not listed here is always available.
const ITEM_FEATURES = new Map<string, EditorFeature>([
  ["image", "media"],
  ["video", "media"],
  ["audio", "media"],
  ["file", "media"],
  ["embed", "embeds"],
  ["bookmark", "embeds"],
  ["table", "tables"],
  ["columns", "columns"],
  ["code", "code"],
  ["toc", "toc"],
  ["equation", "equations"],
  ["mention", "mentions"],
  ["page-link", "pageLinks"],
  ["footnote", "footnotes"],
]);

export function itemFeature(itemId: string): EditorFeature | undefined {
  return ITEM_FEATURES.get(itemId);
}

// The feature that gates a paste node type, or undefined when no feature does. A pasted node of a
// gated type with its feature off is read as its text, or as a dropped media label. It never
// becomes a node of that type. This is a function, not a table, so the key constants are read
// on each call and an import cycle cannot make them undefined.
export function nodeFeature(type: string): EditorFeature | undefined {
  switch (type) {
    case IMAGE_KEY:
    case FILE_KEY:
    case VIDEO_KEY:
    case AUDIO_KEY:
      return "media";
    case EMBED_KEY:
    case BOOKMARK_KEY:
      return "embeds";
    case KEYS.table:
    case KEYS.tr:
    case KEYS.td:
    case KEYS.th:
      return "tables";
    case KEYS.columnGroup:
    case KEYS.column:
      return "columns";
    case KEYS.codeBlock:
      return "code";
    case KEYS.equation:
    case KEYS.inlineEquation:
      return "equations";
    case KEYS.mention:
      return "mentions";
    case PAGE_LINK_KEY:
      return "pageLinks";
    case FOOTNOTE_REF_KEY:
    case FOOTNOTE_DEF_KEY:
      return "footnotes";
    case KEYS.date:
      return "dates";
    case KEYS.toc:
      return "toc";
    default:
      return undefined;
  }
}

import type { SlateEditor, TElement } from "platejs";

import type { EditorCommand } from "../commands/editor-commands";
import { FILE_KEY, fileElement, fileNameFromUrl } from "./editor-file";
import { cleanFileName, isHttpFileUrl, sanitizeStoredFileUrl } from "./editor-file-url";
import type { UploadedFile } from "./editor-file-upload";
import {
  createMediaClearSourceCommand,
  createMediaInsertCommand,
  createMediaRemoveCommand,
  createMediaSetSourceCommand,
  writableMediaBlock,
} from "./editor-media-commands";
import { isStoredMediaUrl, placeNewMediaBlocks, type MediaSource } from "./editor-media-source";

// A link is http or https only. Its name is the file name in the url, unless one is given.
function linkSource(file: UploadedFile): MediaSource | null {
  const url = sanitizeStoredFileUrl(file.url);
  if (url === null || !isHttpFileUrl(url) || !isStoredMediaUrl(url)) {
    return null;
  }

  const name = fileNameFromUrl(url);
  return name === undefined ? { url } : { url, name };
}

function writableFile(editor: SlateEditor, id: string): [TElement, number[]] | undefined {
  return writableMediaBlock(editor, id, FILE_KEY);
}

// One file block with this id. The id must be new.
export const insertFile: EditorCommand<{ id: string }> = createMediaInsertCommand(FILE_KEY);

// One file block per id, in order, as one undo step. Ids must be new and unique. With
// `replaceSelection`, an expanded selection is deleted first, in the same step.
export const insertFiles: EditorCommand<{ ids: string[]; replaceSelection?: boolean }> = {
  id: "block.insert.files",
  label: "File",
  group: "insert",
  run: (editor, { ids, replaceSelection = false }) =>
    placeNewMediaBlocks(
      editor,
      ids.map((id) => ({ id, element: fileElement({}, id) })),
      replaceSelection,
    ),
};

// A url-only value is a link and must be http or https. Any other value is an upload result, and
// its name, size and mime type are kept when they are valid.
export const setFileSource = createMediaSetSourceCommand(FILE_KEY, linkSource);

// Back to the empty placeholder. The name, size and mime type are removed with the url.
export const clearFileSource = createMediaClearSourceCommand(FILE_KEY);

// The name is cleaned the way paste cleans names, so it is never empty and at most 255 characters.
// A file with no url has no name to change, so it is refused.
export const renameFile: EditorCommand<{ id: string; name: string }> = {
  id: "block.file.rename",
  label: "Rename file",
  group: "action",
  run: (editor, { id, name }) => {
    const entry = writableFile(editor, id);
    if (entry === undefined || typeof entry[0].url !== "string" || typeof name !== "string") {
      return false;
    }

    const clean = cleanFileName(name);
    if (clean === undefined || clean.length === 0) {
      return false;
    }

    editor.tf.setNodes({ name: clean }, { at: entry[1] });
    return true;
  },
};

// Removes the block. An empty document gets an empty paragraph, as the bookmark remove does.
export const removeFile: EditorCommand<{ id: string }> = createMediaRemoveCommand(FILE_KEY);

