function blockPlaceable(editor: SlateEditor, session: SlashSession, type: string): boolean {
  const index = session.blockPath[session.blockPath.length - 1];
  if (index === undefined) {
    return false;
  }

  const parentPath = session.blockPath.slice(0, -1);
  let parentType: string | null = null;
  if (parentPath.length > 0) {
    const parent = editor.api.node([...parentPath]);
    if (!parent || !ElementApi.isElement(parent[0]) || typeof parent[0].type !== "string") {
      return false;
    }
    parentType = parent[0].type;
  }

  const toIndex = session.replaceInPlace ? index : index + 1;
  return blockPlacementRefusal(parentType, toIndex, type, false) === undefined;
}

function slashBlockItem(item: BlockPickerItem): SlashItem {
  return {
    id: item.id,
    label: item.label,
    description: item.description,
    keywords: item.keywords,
    icon: item.icon,
    group: item.group,
    block: item,
  };
}

function inlineItemEnabled(editor: SlateEditor, inline: SlashItem["inline"]): boolean {
  if (inline === "mention") {
    return insertMention.isEnabled?.(editor) === true;
  }
  if (inline === "link") {
    return insertInlineLink.isEnabled?.(editor) === true && editor.api.isCollapsed();
  }
  if (inline === "footnote") {
    return footnoteInsertAllowed(editor) && editor.api.isCollapsed();
  }
  return false;
}

function replacesInPlace(
  node: TElement,
  text: string,
  slashOffset: number,
  caretOffset: number,
): boolean {
  if (node.type !== KEYS.p || !node.children.every((child) => TextApi.isText(child))) {
    return false;
  }
  return slashOffset === 0 && caretOffset === text.length;
}

function charBeforeCaretIsBoundary(editor: SlateEditor): boolean {
  const selection = editor.selection;
  if (selection === null) {
    return false;
  }
  const block = editor.api.block();
  if (!block) {
    return false;
  }
  const start = editor.api.start(block[1]);
  if (
    start &&
    PathApi.equals(selection.anchor.path, start.path) &&
    selection.anchor.offset === start.offset
  ) {
    return true;
  }
  const before = editor.api.before(selection.anchor, { unit: "character" });
  if (!before || !pointInBlock(block[1], before.path)) {
    return true;
  }
  const between = editor.api.string({ anchor: before, focus: selection.anchor });
  return between.length === 0 || /^\s+$/.test(between);
}

function pointInBlock(blockPath: readonly number[], path: readonly number[]): boolean {
  return blockPath.every((value, index) => path[index] === value);
}

function isSubsequence(needle: string, haystack: string): boolean {
  let index = 0;
  for (const character of needle) {
    const found = haystack.indexOf(character, index);
    if (found < 0) {
      return false;
    }
    index = found + 1;
  }
  return true;
}

import {
  ElementApi,
  KEYS,
  PathApi,
  nanoid,
  type Descendant,
  type SlateEditor,
  type TElement,
} from "platejs";

import type { EditorCommand } from "../commands/editor-commands";
import { formatBlockLabel } from "../document/editor-document";
import type { Repair } from "../document/editor-document-ids";
import { SYNCED_REF_KEY, isStoredSyncedTargetId } from "../document/editor-document-schema";
import { syncedTargetStatus } from "./editor-synced-repair";

export { syncedRefRepairs } from "./editor-synced-repair";
export type { SyncedTargetStatus } from "./editor-synced-repair";
import { prefersReducedMotion } from "./editor-toc";
import { toggleOpen } from "../plugins/editor-toggle";
import type { EditorValue } from "../document/editor-value";

export { SYNCED_REF_KEY };

export const SYNCED_FROM_ABOVE = "Synced from above";
export const SYNCED_FROM_BELOW = "Synced from below";
export const SYNCED_INVALID_PLACEHOLDER = "Invalid reference";
export const SYNCED_MISSING_PLACEHOLDER = "The original block was deleted.";
const SYNCED_CREATE_LABEL = "Create synced copy";
export const SYNCED_GO_LABEL = "Go to original";
export const SYNCED_CONVERT_LABEL = "Convert to copy";
export const SYNCED_REMOVE_LABEL = "Delete";
export const SYNCED_SELECT_REASON = "Select a block to sync.";
export const SYNCED_REJECT_REASON = "This block cannot be synced.";

export type SyncedDirection = "above" | "below";

type BlockEntry = [TElement, number[]];

function elementId(node: TElement): string | undefined {
  return typeof node.id === "string" && node.id.length > 0 ? node.id : undefined;
}

function isElement(node: Descendant): node is TElement {
  return ElementApi.isElement(node);
}

export { syncedTargetStatus };

export function syncedDirection(targetPath: number[], refPath: number[]): SyncedDirection {
  return PathApi.compare(targetPath, refPath) < 0 ? "above" : "below";
}

function indexElements(value: readonly Descendant[]): Map<string, TElement> {
  const index = new Map<string, TElement>();

  const visit = (node: Descendant): void => {
    if (!isElement(node)) {
      return;
    }

    const id = elementId(node);
    if (id !== undefined && !index.has(id)) {
      index.set(id, node);
    }

    for (const child of node.children) {
      visit(child);
    }
  };

  for (const node of value) {
    visit(node);
  }

  return index;
}

function freshId(used: Set<string>): string {
  let id = nanoid();
  let suffix = 1;
  while (id.length === 0 || used.has(id)) {
    id = `${nanoid()}-${String(suffix)}`;
    suffix += 1;
  }

  used.add(id);
  return id;
}

function cloneWithFreshIds(node: TElement, used: Set<string>): TElement {
  const children = node.children.map((child) =>
    isElement(child) ? cloneWithFreshIds(child, used) : { ...child },
  );

  return { ...node, id: freshId(used), children };
}

function emptyParagraph(used: Set<string>): TElement {
  return { type: KEYS.p, id: freshId(used), children: [{ text: "" }] };
}

function targetIdOf(node: TElement): string {
  return typeof node.targetBlockId === "string" ? node.targetBlockId : "";
}

function materializeElement(
  node: TElement,
  path: number[],
  index: Map<string, TElement>,
  used: Set<string>,
  losses: Repair[],
): TElement {
  if (node.type === SYNCED_REF_KEY) {
    const targetId = targetIdOf(node);
    const target = isStoredSyncedTargetId(targetId) ? index.get(targetId) : undefined;
    const status = syncedTargetStatus(target, targetId);
    if (status !== "live" || target === undefined) {
      losses.push({
        path,
        message:
          status === "missing"
            ? `${formatBlockLabel(path)} points at a block that is not in the document. The reference was removed.`
            : `${formatBlockLabel(path)} points at a block that cannot be synced. The reference was removed.`,
      });
      return emptyParagraph(used);
    }

    return cloneWithFreshIds(target, used);
  }

  let changed = false;
  const children = node.children.map((child, childIndex) => {
    if (!isElement(child)) {
      return child;
    }

    const next = materializeElement(child, [...path, childIndex], index, used, losses);
    if (next !== child) {
      changed = true;
    }

    return next;
  });

  if (!changed) {
    return node;
  }

  return { ...node, children };
}

// The future exporter and read-only renderer (DEV-128) must call this before writing the document out.
export function materializeSyncedRefs(value: EditorValue): {
  value: EditorValue;
  losses: Repair[];
} {
  const index = indexElements(value);
  const used = new Set(index.keys());
  const losses: Repair[] = [];
  let changed = false;
  const next = value.map((node, nodeIndex) => {
    const materialized = materializeElement(node, [nodeIndex], index, used, losses);
    if (materialized !== node) {
      changed = true;
    }

    return materialized;
  });

  return { value: changed ? next : value, losses };
}

export function findBlockById(editor: SlateEditor, id: string): BlockEntry | undefined {
  for (const entry of editor.api.nodes({
    at: [],
    match: (node) => ElementApi.isElement(node) && node.id === id,
    voids: true,
  })) {
    if (ElementApi.isElement(entry[0])) {
      return [entry[0], entry[1]];
    }
  }

  return undefined;
}

function nodeAt(editor: SlateEditor, path: number[]): BlockEntry | undefined {
  const entry = editor.api.node(path);
  if (!entry || !ElementApi.isElement(entry[0])) {
    return undefined;
  }

  return [entry[0], entry[1]];
}

function selectedSyncedRef(editor: SlateEditor): BlockEntry | undefined {
  for (const entry of editor.api.nodes({
    match: (node) => ElementApi.isElement(node) && node.type === SYNCED_REF_KEY,
    voids: true,
    mode: "lowest",
  })) {
    if (ElementApi.isElement(entry[0])) {
      return [entry[0], entry[1]];
    }
  }

  return undefined;
}

function isEditable(editor: SlateEditor): boolean {
  return editor.dom.readOnly !== true;
}

function isSyncableBlock(node: TElement): boolean {
  const id = elementId(node);
  if (id === undefined) {
    return false;
  }

  return syncedTargetStatus(node, id) === "live";
}

function createSyncedRefReason(editor: SlateEditor): string | undefined {
  const current = editor.api.block({ highest: true });
  if (!current || !ElementApi.isElement(current[0]) || elementId(current[0]) === undefined) {
    return SYNCED_SELECT_REASON;
  }

  if (!isSyncableBlock(current[0])) {
    return SYNCED_REJECT_REASON;
  }

  return undefined;
}

function syncedRefNode(id: string, targetBlockId: string): TElement {
  return {
    type: SYNCED_REF_KEY,
    id,
    targetBlockId,
    children: [{ text: "" }],
  };
}

function insertSyncedRef(editor: SlateEditor): boolean {
  if (!isEditable(editor) || createSyncedRefReason(editor) !== undefined) {
    return false;
  }

  const current = editor.api.block({ highest: true });
  if (!current || !ElementApi.isElement(current[0])) {
    return false;
  }

  const targetId = elementId(current[0]);
  const at = PathApi.next(current[1]);
  if (targetId === undefined || !at) {
    return false;
  }

  editor.tf.insertNodes(syncedRefNode(nanoid(), targetId), { at, select: true });
  return true;
}

function openAncestorToggles(editor: SlateEditor, path: readonly number[]): void {
  for (let length = 1; length < path.length; length += 1) {
    const parent = editor.api.node(path.slice(0, length));
    if (!parent || !ElementApi.isElement(parent[0]) || parent[0].type !== KEYS.toggle) {
      continue;
    }

    const id = elementId(parent[0]);
    if (id === undefined) {
      continue;
    }

    toggleOpen(editor, id, true);
  }
}

function scrollToBlock(editor: SlateEditor, node: TElement): void {
  const dom = editor.api.toDOMNode(node);
  if (!(dom instanceof HTMLElement) || typeof dom.scrollIntoView !== "function") {
    return;
  }

  dom.scrollIntoView({
    behavior: prefersReducedMotion() ? "auto" : "smooth",
    block: "start",
  });
}

export function goToSyncedOriginal(editor: SlateEditor, at?: number[]): void {
  if (!isEditable(editor)) {
    return;
  }

  const refEntry = at === undefined ? selectedSyncedRef(editor) : nodeAt(editor, at);
  if (!refEntry || refEntry[0].type !== SYNCED_REF_KEY) {
    return;
  }

  const targetId = targetIdOf(refEntry[0]);
  const target = isStoredSyncedTargetId(targetId) ? findBlockById(editor, targetId) : undefined;
  if (!target || syncedTargetStatus(target[0], targetId) !== "live") {
    return;
  }

  openAncestorToggles(editor, target[1]);
  const start = editor.api.start(target[1]);
  if (!start) {
    return;
  }

  editor.tf.withoutSaving(() => {
    editor.tf.select(start, { focus: true });
  });
  scrollToBlock(editor, target[0]);
}

function collectIds(value: readonly Descendant[]): Set<string> {
  return new Set(indexElements(value).keys());
}

export function convertSyncedRefAt(editor: SlateEditor, path: number[]): boolean {
  if (!isEditable(editor)) {
    return false;
  }

  const refEntry = nodeAt(editor, path);
  if (!refEntry || refEntry[0].type !== SYNCED_REF_KEY) {
    return false;
  }

  const targetId = targetIdOf(refEntry[0]);
  const target = isStoredSyncedTargetId(targetId) ? findBlockById(editor, targetId) : undefined;
  if (!target || syncedTargetStatus(target[0], targetId) !== "live") {
    return false;
  }

  const clone = cloneWithFreshIds(target[0], collectIds(editor.children));
  editor.tf.withoutNormalizing(() => {
    editor.tf.removeNodes({ at: path, voids: true });
    editor.tf.insertNodes(clone, { at: path, select: true });
  });
  return true;
}

export function removeSyncedRefAt(editor: SlateEditor, path: number[]): boolean {
  if (!isEditable(editor)) {
    return false;
  }

  const refEntry = nodeAt(editor, path);
  if (!refEntry || refEntry[0].type !== SYNCED_REF_KEY) {
    return false;
  }

  editor.tf.removeNodes({ at: path, voids: true });
  if (editor.children.length === 0) {
    editor.tf.insertNodes({ type: KEYS.p, children: [{ text: "" }] }, { at: [0] });
  }

  return true;
}

type KeyEvent = {
  key: string;
  shiftKey: boolean;
  metaKey: boolean;
  ctrlKey: boolean;
  altKey: boolean;
  defaultPrevented: boolean;
  preventDefault: () => void;
};

export function onSyncedRefKeyDown(editor: SlateEditor, event: KeyEvent): void {
  if (
    event.defaultPrevented ||
    event.key !== "Enter" ||
    event.shiftKey ||
    event.metaKey ||
    event.ctrlKey ||
    event.altKey ||
    !isEditable(editor)
  ) {
    return;
  }

  const block = editor.api.block();
  if (!block || !ElementApi.isElement(block[0]) || block[0].type !== SYNCED_REF_KEY) {
    return;
  }

  event.preventDefault();
  goToSyncedOriginal(editor, block[1]);
}

function selectedTargetIsLive(editor: SlateEditor): boolean {
  const selected = selectedSyncedRef(editor);
  if (!selected) {
    return false;
  }

  const targetId = targetIdOf(selected[0]);
  const target = isStoredSyncedTargetId(targetId) ? findBlockById(editor, targetId) : undefined;
  return syncedTargetStatus(target?.[0], targetId) === "live";
}

export const createSyncedRef: EditorCommand = {
  id: "block.synced.create-ref",
  label: SYNCED_CREATE_LABEL,
  group: "insert",
  isEnabled: (editor) => isEditable(editor) && createSyncedRefReason(editor) === undefined,
  disabledReason: (editor) => createSyncedRefReason(editor),
  run: (editor) => {
    insertSyncedRef(editor);
  },
};

export const goToSyncedOriginalCommand: EditorCommand = {
  id: "block.synced.go-to-original",
  label: SYNCED_GO_LABEL,
  group: "action",
  isEnabled: (editor) => isEditable(editor) && selectedTargetIsLive(editor),
  run: (editor) => {
    goToSyncedOriginal(editor);
  },
};

export const convertSyncedRef: EditorCommand = {
  id: "block.synced.convert",
  label: SYNCED_CONVERT_LABEL,
  group: "action",
  isEnabled: (editor) => isEditable(editor) && selectedTargetIsLive(editor),
  run: (editor) => {
    const selected = selectedSyncedRef(editor);
    if (!selected) {
      return;
    }

    convertSyncedRefAt(editor, selected[1]);
  },
};

export const removeSyncedRef: EditorCommand = {
  id: "block.synced.remove",
  label: SYNCED_REMOVE_LABEL,
  group: "action",
  isEnabled: (editor) => isEditable(editor) && selectedSyncedRef(editor) !== undefined,
  run: (editor) => {
    const selected = selectedSyncedRef(editor);
    if (!selected) {
      return;
    }

    removeSyncedRefAt(editor, selected[1]);
  },
};

import { ElementApi, KEYS, type Descendant, type TElement } from "platejs";

import { formatBlockLabel } from "../document/editor-document";
import type { Repair } from "../document/editor-document-ids";
import { SYNCED_REF_KEY, isStoredSyncedTargetId } from "../document/editor-document-schema";
import type { EditorValue } from "../document/editor-value";

export type SyncedTargetStatus = "live" | "missing" | "invalid";

function isElement(node: Descendant): node is TElement {
  return ElementApi.isElement(node);
}

function containsSyncedRef(node: TElement): boolean {
  for (const child of node.children) {
    if (!isElement(child)) {
      continue;
    }
    if (child.type === SYNCED_REF_KEY || containsSyncedRef(child)) {
      return true;
    }
  }

  return false;
}

function indexElements(value: readonly Descendant[]): Map<string, TElement> {
  const index = new Map<string, TElement>();
  const visit = (node: Descendant): void => {
    if (!isElement(node)) {
      return;
    }
    if (typeof node.id === "string" && node.id.length > 0 && !index.has(node.id)) {
      index.set(node.id, node);
    }
    node.children.forEach(visit);
  };
  value.forEach(visit);
  return index;
}

export function syncedTargetStatus(
  target: TElement | undefined,
  targetId: string,
): SyncedTargetStatus {
  if (!isStoredSyncedTargetId(targetId)) {
    return "invalid";
  }
  if (!target) {
    return "missing";
  }
  if (
    target.type === SYNCED_REF_KEY ||
    target.type === KEYS.toc ||
    target.type === KEYS.columnGroup ||
    containsSyncedRef(target)
  ) {
    return "invalid";
  }
  return "live";
}

export function syncedRefRepairs(value: EditorValue): Repair[] {
  const index = indexElements(value);
  const repairs: Repair[] = [];
  const visit = (node: Descendant, path: number[]): void => {
    if (!isElement(node)) {
      return;
    }
    if (node.type === SYNCED_REF_KEY) {
      const targetId = typeof node.targetBlockId === "string" ? node.targetBlockId : "";
      if (isStoredSyncedTargetId(targetId)) {
        const status = syncedTargetStatus(index.get(targetId), targetId);
        if (status === "invalid") {
          repairs.push({
            path,
            message: `${formatBlockLabel(path)} points at a block that cannot be synced. The reference is kept.`,
          });
        }
      }
    }
    node.children.forEach((child, childIndex) => {
      visit(child, [...path, childIndex]);
    });
  };
  value.forEach((node, nodeIndex) => {
    visit(node, [nodeIndex]);
  });
  return repairs;
}

import { formatBlockLabel } from "../document/editor-document";

// One grid check for the validator, the normalizer, and paste.
// Plate stores colSpan and rowSpan on the cell (constants-6xljcM3U.js getColSpan
// line 44, getRowSpan line 53). Absence means 1. 1 is never stored.
// colSizes is one entry per grid column. null means that column is automatic.
// 0 is not automatic: Plate uses 0 as an unset fill, and this schema rejects it.

export const TABLE_MIN_COLUMN_WIDTH = 48;
export const TABLE_MAX_COLUMN_WIDTH = 1200;

export type TableGridIssue = {
  path: number[];
  message: string;
};

type TableGridLimits = {
  maxRows: number;
  maxColumns: number;
};

type TableGridResult = {
  issues: TableGridIssue[];
  repairs: TableGridIssue[];
  next?: Record<string, unknown>;
};

export type CoveredCell = {
  rowIndex: number;
  cellIndex: number;
  row: number;
  column: number;
  rowSpan: number;
  colSpan: number;
};

type RowCells = {
  row: Record<string, unknown>;
  cells: Record<string, unknown>[];
};

type PlacedCell = {
  node: Record<string, unknown>;
  row: number;
  column: number;
  rowSpan: number;
  colSpan: number;
  requestedRowSpan: number;
  requestedColSpan: number;
};

type SpanRead = {
  span: number;
  storedOne: boolean;
  invalid: boolean;
};

const DEFAULT_LIMITS: TableGridLimits = { maxRows: 50, maxColumns: 20 };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isElement(value: unknown): value is Record<string, unknown> {
  return isRecord(value) && typeof value.type === "string" && Array.isArray(value.children);
}

function elementChildren(node: Record<string, unknown>): Record<string, unknown>[] {
  if (!Array.isArray(node.children)) {
    return [];
  }

  return node.children.filter(isElement);
}

function readSpan(cell: Record<string, unknown>, key: "colSpan" | "rowSpan"): SpanRead {
  if (!(key in cell)) {
    return { span: 1, storedOne: false, invalid: false };
  }

  const value = cell[key];
  if (value === 1) {
    return { span: 1, storedOne: true, invalid: false };
  }

  if (typeof value === "number" && Number.isInteger(value) && value >= 2) {
    return { span: value, storedOne: false, invalid: false };
  }

  return { span: 1, storedOne: false, invalid: true };
}

function attributeSpan(
  cell: Record<string, unknown>,
  name: "colspan" | "rowspan",
): number | undefined {
  const attributes = cell.attributes;
  if (!isRecord(attributes) || !(name in attributes)) {
    return undefined;
  }

  const value = attributes[name];
  if (typeof value === "number" && Number.isInteger(value) && value > 1) {
    return value;
  }

  if (typeof value === "string" && /^[0-9]+$/.test(value)) {
    const parsed = Number(value);
    if (parsed > 1) {
      return parsed;
    }
  }

  return undefined;
}

function requestedSpans(cell: Record<string, unknown>): {
  colSpan: number;
  rowSpan: number;
  col: SpanRead;
  row: SpanRead;
} {
  const col = readSpan(cell, "colSpan");
  const row = readSpan(cell, "rowSpan");
  const attributeCol =
    col.span === 1 && !col.storedOne ? attributeSpan(cell, "colspan") : undefined;
  const attributeRow =
    row.span === 1 && !row.storedOne ? attributeSpan(cell, "rowspan") : undefined;

  return {
    colSpan: attributeCol ?? col.span,
    rowSpan: attributeRow ?? row.span,
    col,
    row,
  };
}

function tableRows(
  node: Record<string, unknown>,
  maxRows: number,
): { rows: RowCells[]; trimmed: boolean } {
  const rows = elementChildren(node)
    .filter((child) => child.type === "tr")
    .slice(0, maxRows)
    .map((row) => ({
      row,
      cells: elementChildren(row).filter((cell) => cell.type === "td" || cell.type === "th"),
    }));

  const trimmed = elementChildren(node).filter((child) => child.type === "tr").length > rows.length;
  return { rows, trimmed };
}

function columnCountOf(rows: readonly RowCells[], maxColumns: number): number {
  let count = 1;
  for (const row of rows) {
    let sum = 0;
    for (const cell of row.cells) {
      sum += requestedSpans(cell).colSpan;
    }

    if (sum > count) {
      count = sum;
    }
  }

  return Math.min(maxColumns, Math.max(1, count));
}

function cellNode(
  cell: Record<string, unknown>,
  colSpan: number,
  rowSpan: number,
): Record<string, unknown> {
  const next: Record<string, unknown> = { ...cell, children: cell.children };
  delete next.colSpan;
  delete next.rowSpan;
  delete next.attributes;
  if (colSpan > 1) {
    next.colSpan = colSpan;
  }

  if (rowSpan > 1) {
    next.rowSpan = rowSpan;
  }

  return next;
}

function emptyCell(header: boolean): Record<string, unknown> {
  return {
    type: header ? "th" : "td",
    children: [{ type: "p", children: [{ text: "" }] }],
  };
}

function rowIsHeader(cells: readonly Record<string, unknown>[]): boolean {
  return cells.length > 0 && cells.every((cell) => cell.type === "th");
}

function sameJson(left: unknown, right: unknown): boolean {
  return JSON.stringify(left) === JSON.stringify(right);
}

type WidthRepair = {
  issues: TableGridIssue[];
  repairs: TableGridIssue[];
  value: (number | null)[] | undefined;
  changed: boolean;
};

function repairWidths(raw: unknown, columnCount: number, path: number[]): WidthRepair {
  const issues: TableGridIssue[] = [];
  const repairs: TableGridIssue[] = [];
  if (raw === undefined) {
    return { issues, repairs, value: undefined, changed: false };
  }

  if (!Array.isArray(raw)) {
    issues.push({
      path,
      message: `${formatBlockLabel(path)} has an unsupported colSizes. Column widths were removed.`,
    });
    repairs.push({
      path,
      message: `${formatBlockLabel(path)} column widths were removed because none were valid.`,
    });
    return { issues, repairs, value: undefined, changed: true };
  }

  const cleaned: (number | null)[] = [];
  let anyExplicit = false;
  for (const entry of raw) {
    if (entry === null) {
      cleaned.push(null);
      continue;
    }

    if (typeof entry !== "number" || !Number.isFinite(entry)) {
      issues.push({
        path,
        message: `${formatBlockLabel(path)} has a colSizes entry that is not a finite number.`,
      });
      repairs.push({
        path,
        message: `${formatBlockLabel(path)} dropped a column width that was not a finite number. That column stays automatic.`,
      });
      cleaned.push(null);
      continue;
    }

    if (!Number.isInteger(entry)) {
      const rounded = Math.min(
        TABLE_MAX_COLUMN_WIDTH,
        Math.max(TABLE_MIN_COLUMN_WIDTH, Math.round(entry)),
      );
      issues.push({
        path,
        message: `${formatBlockLabel(path)} has a non-integer colSizes entry.`,
      });
      repairs.push({
        path,
        message: `${formatBlockLabel(path)} rounded a non-integer column width to ${rounded}px.`,
      });
      cleaned.push(rounded);
      anyExplicit = true;
      continue;
    }

    if (entry < TABLE_MIN_COLUMN_WIDTH || entry > TABLE_MAX_COLUMN_WIDTH) {
      const clamped = Math.min(TABLE_MAX_COLUMN_WIDTH, Math.max(TABLE_MIN_COLUMN_WIDTH, entry));
      const detail = entry === 0 ? "0" : entry < 0 ? "a negative width" : "a width above 1200";
      issues.push({
        path,
        message: `${formatBlockLabel(path)} has colSizes ${detail}.`,
      });
      repairs.push({
        path,
        message: `${formatBlockLabel(path)} clamped a column width of ${entry}px to ${clamped}px.`,
      });
      cleaned.push(clamped);
      anyExplicit = true;
      continue;
    }

    cleaned.push(entry);
    anyExplicit = true;
  }

  if (!anyExplicit) {
    issues.push({
      path,
      message: `${formatBlockLabel(path)} has colSizes with no explicit column width.`,
    });
    repairs.push({
      path,
      message: `${formatBlockLabel(path)} column widths were removed because none were valid.`,
    });
    return { issues, repairs, value: undefined, changed: true };
  }

  if (cleaned.length > columnCount) {
    issues.push({
      path,
      message: `${formatBlockLabel(path)} has colSizes length ${cleaned.length}. The table has ${columnCount} columns.`,
    });
    repairs.push({
      path,
      message: `${formatBlockLabel(path)} truncated column widths to ${columnCount} columns.`,
    });
    cleaned.length = columnCount;
  } else if (cleaned.length < columnCount) {
    issues.push({
      path,
      message: `${formatBlockLabel(path)} has colSizes length ${cleaned.length}. The table has ${columnCount} columns.`,
    });
    repairs.push({
      path,
      message: `${formatBlockLabel(path)} padded column widths to ${columnCount} columns. Added columns stay automatic.`,
    });
    while (cleaned.length < columnCount) {
      cleaned.push(null);
    }
  }

  return {
    issues,
    repairs,
    value: cleaned,
    changed: !sameJson(raw, cleaned),
  };
}

function occupied(
  grid: (PlacedCell | undefined)[][],
  row: number,
  column: number,
  rowSpan: number,
  colSpan: number,
  ignore?: PlacedCell,
): boolean {
  for (let rowOffset = 0; rowOffset < rowSpan; rowOffset += 1) {
    for (let columnOffset = 0; columnOffset < colSpan; columnOffset += 1) {
      const cell = grid[row + rowOffset]?.[column + columnOffset];
      if (cell && cell !== ignore) {
        return true;
      }
    }
  }

  return false;
}

function mark(grid: (PlacedCell | undefined)[][], cell: PlacedCell): void {
  for (let rowOffset = 0; rowOffset < cell.rowSpan; rowOffset += 1) {
    for (let columnOffset = 0; columnOffset < cell.colSpan; columnOffset += 1) {
      const row = grid[cell.row + rowOffset];
      if (row) {
        row[cell.column + columnOffset] = cell;
      }
    }
  }
}

function rebuild(grid: (PlacedCell | undefined)[][], placed: readonly PlacedCell[]): void {
  for (const row of grid) {
    row.fill(undefined);
  }

  for (const cell of placed) {
    mark(grid, cell);
  }
}

function freeSlots(grid: (PlacedCell | undefined)[][], row: number, columnCount: number): number {
  let free = 0;
  for (let column = 0; column < columnCount; column += 1) {
    if (!grid[row]?.[column]) {
      free += 1;
    }
  }

  return free;
}

export function checkTableGrid(
  node: Record<string, unknown>,
  path: number[],
  limits: TableGridLimits = DEFAULT_LIMITS,
): TableGridResult {
  const issues: TableGridIssue[] = [];
  const repairs: TableGridIssue[] = [];
  if (node.type !== "table" || !Array.isArray(node.children)) {
    return { issues, repairs };
  }

  const { rows, trimmed } = tableRows(node, limits.maxRows);
  if (rows.length === 0) {
    return { issues, repairs };
  }

  let dirty = trimmed;
  const rowCount = rows.length;
  const columnCount = columnCountOf(rows, limits.maxColumns);
  const grid: (PlacedCell | undefined)[][] = Array.from({ length: rowCount }, () => []);
  const placed: PlacedCell[] = [];

  for (let rowIndex = 0; rowIndex < rows.length; rowIndex += 1) {
    const row = rows[rowIndex];
    if (!row) {
      continue;
    }

    let guard = 0;
    while (
      freeSlots(grid, rowIndex, columnCount) < row.cells.length &&
      guard < columnCount + row.cells.length
    ) {
      guard += 1;
      const blocker = placed.find(
        (cell) => cell.row < rowIndex && rowIndex < cell.row + cell.rowSpan && cell.rowSpan > 1,
      );
      if (!blocker) {
        break;
      }

      blocker.rowSpan = rowIndex - blocker.row;
      dirty = true;
      issues.push({
        path: path.concat(blocker.row),
        message: `${formatBlockLabel(path)} has a cell that overlaps another cell.`,
      });
      repairs.push({
        path: path.concat(blocker.row),
        message: `${formatBlockLabel(path)} shrank an overlapping rowSpan to ${blocker.rowSpan === 1 ? "one row" : `${blocker.rowSpan} rows`}.`,
      });
      rebuild(grid, placed);
    }

    let column = 0;
    for (const cell of row.cells) {
      const requested = requestedSpans(cell);
      const cellPath = path.concat(rowIndex, column);
      if (requested.col.storedOne) {
        dirty = true;
        issues.push({
          path: cellPath,
          message: `${formatBlockLabel(cellPath)} stores colSpan 1. Absence means one column.`,
        });
        repairs.push({
          path: cellPath,
          message: `${formatBlockLabel(cellPath)} removed stored colSpan 1.`,
        });
      }

      if (requested.row.storedOne) {
        dirty = true;
        issues.push({
          path: cellPath,
          message: `${formatBlockLabel(cellPath)} stores rowSpan 1. Absence means one row.`,
        });
        repairs.push({
          path: cellPath,
          message: `${formatBlockLabel(cellPath)} removed stored rowSpan 1.`,
        });
      }

      if (requested.col.invalid) {
        dirty = true;
        issues.push({
          path: cellPath,
          message: `${formatBlockLabel(cellPath)} has an unsupported colSpan.`,
        });
        repairs.push({
          path: cellPath,
          message: `${formatBlockLabel(cellPath)} removed an invalid colSpan.`,
        });
      }

      if (requested.row.invalid) {
        dirty = true;
        issues.push({
          path: cellPath,
          message: `${formatBlockLabel(cellPath)} has an unsupported rowSpan.`,
        });
        repairs.push({
          path: cellPath,
          message: `${formatBlockLabel(cellPath)} removed an invalid rowSpan.`,
        });
      }

      if (
        attributeSpan(cell, "colspan") !== undefined ||
        attributeSpan(cell, "rowspan") !== undefined ||
        isRecord(cell.attributes)
      ) {
        dirty = true;
      }

      while (column < columnCount && grid[rowIndex]?.[column]) {
        column += 1;
      }

      if (column >= columnCount) {
        dirty = true;
        issues.push({
          path: cellPath,
          message: `${formatBlockLabel(path)} has a cell that overlaps another cell.`,
        });
        repairs.push({
          path: cellPath,
          message: `${formatBlockLabel(path)} kept overlapping cell text in the row and dropped the extra grid slot.`,
        });
        const host = placed.find((item) => item.row === rowIndex) ?? placed[placed.length - 1];
        if (host && Array.isArray(host.node.children) && Array.isArray(cell.children)) {
          host.node = {
            ...host.node,
            children: [...host.node.children, ...cell.children],
          };
        }
        continue;
      }

      let colSpan = requested.colSpan;
      let rowSpan = requested.rowSpan;
      if (rowIndex + rowSpan > rowCount) {
        const nextSpan = rowCount - rowIndex;
        issues.push({
          path: cellPath,
          message: `${formatBlockLabel(cellPath)} has rowSpan ${rowSpan}, which extends past the table.`,
        });
        repairs.push({
          path: cellPath,
          message: `${formatBlockLabel(cellPath)} shrank rowSpan from ${rowSpan} to ${nextSpan}.`,
        });
        rowSpan = nextSpan;
        dirty = true;
      }

      if (column + colSpan > columnCount || occupied(grid, rowIndex, column, rowSpan, colSpan)) {
        const original = colSpan;
        while (
          colSpan > 1 &&
          (column + colSpan > columnCount || occupied(grid, rowIndex, column, rowSpan, colSpan))
        ) {
          colSpan -= 1;
        }

        if (column + colSpan > columnCount) {
          colSpan = Math.max(1, columnCount - column);
        }

        while (rowSpan > 1 && occupied(grid, rowIndex, column, rowSpan, colSpan)) {
          rowSpan -= 1;
        }

        if (original !== colSpan || requested.rowSpan !== rowSpan) {
          dirty = true;
          const pastEdge = column + original > columnCount;
          issues.push({
            path: cellPath,
            message: pastEdge
              ? `${formatBlockLabel(cellPath)} has colSpan ${original}, which extends past the table.`
              : `${formatBlockLabel(path)} has a cell that overlaps another cell.`,
          });
          repairs.push({
            path: cellPath,
            message: pastEdge
              ? `${formatBlockLabel(cellPath)} shrank colSpan from ${original} to ${colSpan}.`
              : `${formatBlockLabel(cellPath)} shrank an overlapping span to ${colSpan} by ${rowSpan}.`,
          });
        }
      }

      const placedCell: PlacedCell = {
        node: cell,
        row: rowIndex,
        column,
        rowSpan,
        colSpan,
        requestedRowSpan: requested.rowSpan,
        requestedColSpan: requested.colSpan,
      };
      placed.push(placedCell);
      mark(grid, placedCell);
      column += colSpan;
    }
  }

  for (let rowIndex = 0; rowIndex < rowCount; rowIndex += 1) {
    let missing = false;
    for (let column = 0; column < columnCount; column += 1) {
      if (!grid[rowIndex]?.[column]) {
        missing = true;
        break;
      }
    }

    if (!missing) {
      continue;
    }

    dirty = true;
    repairs.push({
      path: path.concat(rowIndex),
      message: `${formatBlockLabel(path)} filled an empty cell so the row stays rectangular.`,
    });
  }

  const widths = repairWidths(node.colSizes, columnCount, path);
  issues.push(...widths.issues);
  repairs.push(...widths.repairs);
  if (widths.changed) {
    dirty = true;
  }

  if (!dirty) {
    return { issues, repairs };
  }

  const nextRows = rows.map((row, rowIndex) => {
    const header = rowIsHeader(row.cells);
    const children: Record<string, unknown>[] = [];
    let column = 0;
    const starts = placed
      .filter((cell) => cell.row === rowIndex)
      .sort((left, right) => left.column - right.column);
    for (const cell of starts) {
      while (column < cell.column) {
        if (!grid[rowIndex]?.[column]) {
          children.push(emptyCell(header));
        }
        column += 1;
      }

      children.push(cellNode(cell.node, cell.colSpan, cell.rowSpan));
      column = cell.column + cell.colSpan;
    }

    while (column < columnCount) {
      if (!grid[rowIndex]?.[column]) {
        children.push(emptyCell(header));
      }
      column += 1;
    }

    return { ...row.row, children };
  });

  const next: Record<string, unknown> = { ...node, children: nextRows };
  if (widths.value === undefined) {
    delete next.colSizes;
  } else {
    next.colSizes = widths.value;
  }

  return { issues, repairs, next };
}

export function tableCoverage(
  node: Record<string, unknown>,
  maxColumns = DEFAULT_LIMITS.maxColumns,
): {
  rowCount: number;
  columnCount: number;
  cells: CoveredCell[];
} {
  const { rows } = tableRows(node, DEFAULT_LIMITS.maxRows);
  const columnCount = columnCountOf(rows, maxColumns);
  const grid: (CoveredCell | undefined)[][] = Array.from({ length: rows.length }, () => []);
  const cells: CoveredCell[] = [];

  for (let rowIndex = 0; rowIndex < rows.length; rowIndex += 1) {
    const row = rows[rowIndex];
    if (!row) {
      continue;
    }

    let column = 0;
    for (let cellIndex = 0; cellIndex < row.cells.length; cellIndex += 1) {
      const cell = row.cells[cellIndex];
      if (!cell) {
        continue;
      }

      while (column < columnCount && grid[rowIndex]?.[column]) {
        column += 1;
      }

      if (column >= columnCount) {
        break;
      }

      const spans = requestedSpans(cell);
      const covered: CoveredCell = {
        rowIndex,
        cellIndex,
        row: rowIndex,
        column,
        rowSpan: Math.min(spans.rowSpan, rows.length - rowIndex),
        colSpan: Math.min(spans.colSpan, columnCount - column),
      };
      cells.push(covered);
      for (let rowOffset = 0; rowOffset < covered.rowSpan; rowOffset += 1) {
        for (let columnOffset = 0; columnOffset < covered.colSpan; columnOffset += 1) {
          const line = grid[rowIndex + rowOffset];
          if (line) {
            line[column + columnOffset] = covered;
          }
        }
      }
      column += covered.colSpan;
    }
  }

  return { rowCount: rows.length, columnCount, cells };
}

export function rowSliceIsClean(node: Record<string, unknown>, row: number): boolean {
  const coverage = tableCoverage(node);
  return coverage.cells.every(
    (cell) =>
      cell.row + cell.rowSpan - 1 < row ||
      cell.row > row ||
      (cell.row === row && cell.rowSpan === 1),
  );
}

// One-shot "fit to width". Proportions come from the current widths.
// A non-positive or non-finite width stands in for a column that has no stored size.
// When the minimums cannot fit, every column becomes the minimum and the caller scrolls.
export function fitColumnWidths(
  widths: readonly number[],
  available: number,
  min = TABLE_MIN_COLUMN_WIDTH,
  max = TABLE_MAX_COLUMN_WIDTH,
): number[] {
  const count = widths.length;
  if (count === 0 || !Number.isFinite(available)) {
    return [];
  }

  const target = Math.round(available);
  if (count * min >= target) {
    return Array.from({ length: count }, () => min);
  }
  if (count * max <= target) {
    return Array.from({ length: count }, () => max);
  }

  const basis = widths.map((width) => (Number.isFinite(width) && width > 0 ? width : min));
  const total = basis.reduce((sum, width) => sum + width, 0);
  const ideal = basis.map((width) => (width / total) * target);
  const next = ideal.map((width) => Math.min(max, Math.max(min, Math.round(width))));
  let drift = target - next.reduce((sum, width) => sum + width, 0);

  while (drift !== 0) {
    const grow = drift > 0;
    let best = -1;
    let bestGap = grow ? Number.NEGATIVE_INFINITY : Number.POSITIVE_INFINITY;
    for (let index = 0; index < count; index += 1) {
      const width = next[index] ?? 0;
      if (grow ? width >= max : width <= min) {
        continue;
      }

      const gap = (ideal[index] ?? 0) - width;
      if (grow ? gap > bestGap : gap < bestGap) {
        bestGap = gap;
        best = index;
      }
    }
    if (best < 0) {
      break;
    }

    next[best] = (next[best] ?? 0) + (grow ? 1 : -1);
    drift += grow ? -1 : 1;
  }

  return next;
}

export function boundaryIsClean(
  node: Record<string, unknown>,
  axis: "row" | "column",
  index: number,
  neighbor: number,
): boolean {
  const coverage = tableCoverage(node);
  return coverage.cells.every((cell) => {
    const start = axis === "row" ? cell.row : cell.column;
    const end = axis === "row" ? cell.row + cell.rowSpan - 1 : cell.column + cell.colSpan - 1;
    const coversIndex = start <= index && index <= end;
    const coversNeighbor = start <= neighbor && neighbor <= end;
    return !(coversIndex && coversNeighbor);
  });
}

import { insertTableColumn, insertTableRow } from "@platejs/table";
import {
  KEYS,
  PathApi,
  PointApi,
  type Descendant,
  type SlateEditor,
  type TElement,
  type TText,
} from "platejs";

import type { Repair } from "../document/editor-document-ids";
import {
  allowedChildTypes,
  maxChildren,
  TABLE_MAX_COLUMNS,
  TABLE_MAX_ROWS,
} from "../document/editor-document-schema";
import { checkTableGrid, tableCoverage, type CoveredCell } from "./editor-table-grid";

export type TableCellContext = {
  tablePath: number[];
  cellPath: number[];
  rowIndex: number;
  /** Grid column. A colspan starts at this column. */
  columnIndex: number;
  cellIndex: number;
  rowCount: number;
  columnCount: number;
  colSpan: number;
  rowSpan: number;
};

export function tableMaxRows(): number {
  return maxChildren(KEYS.table) ?? TABLE_MAX_ROWS;
}

export function tableMaxColumns(): number {
  return maxChildren(KEYS.tr) ?? TABLE_MAX_COLUMNS;
}

export function pastedTableTruncationMessage(): string {
  return `Pasted table kept the first ${tableMaxRows()} rows and ${tableMaxColumns()} columns. Cells past that cap were dropped.`;
}

function isTElement(node: unknown): node is TElement {
  return (
    typeof node === "object" &&
    node !== null &&
    "type" in node &&
    typeof node.type === "string" &&
    "children" in node &&
    Array.isArray(node.children)
  );
}

function emptyParagraph(text = ""): TElement {
  return { type: KEYS.p, children: [{ text }] };
}

function emptyTableCell(header: boolean, text = ""): TElement {
  return {
    type: header ? KEYS.th : KEYS.td,
    children: [emptyParagraph(text)],
  };
}

export function createTableNode(rows: number, cols: number): TElement {
  const tableRows: TElement[] = [];
  for (let row = 0; row < rows; row += 1) {
    const cells: TElement[] = [];
    for (let column = 0; column < cols; column += 1) {
      cells.push(emptyTableCell(false));
    }
    tableRows.push({ type: KEYS.tr, children: cells });
  }

  return { type: KEYS.table, children: tableRows };
}

export function clampTableCount(value: number | undefined, fallback: number, max: number): number {
  if (value === undefined || !Number.isInteger(value)) {
    return fallback;
  }

  if (value < 1) {
    return 1;
  }

  if (value > max) {
    return max;
  }

  return value;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function elementChildren(node: TElement): TElement[] {
  return node.children.filter(isTElement);
}

function tableRecord(node: TElement): Record<string, unknown> {
  const record: Record<string, unknown> = {};
  for (const key of Object.keys(node)) {
    record[key] = node[key];
  }

  return record;
}

function elementFromRecord(node: Record<string, unknown>): TElement | undefined {
  if (typeof node.type !== "string" || !Array.isArray(node.children)) {
    return undefined;
  }

  const children: Descendant[] = [];
  for (const child of node.children) {
    if (!isRecord(child)) {
      return undefined;
    }

    if (typeof child.text === "string") {
      const text: TText = { text: child.text };
      for (const key of Object.keys(child)) {
        if (key !== "text") {
          text[key] = child[key];
        }
      }
      children.push(text);
      continue;
    }

    const element = elementFromRecord(child);
    if (!element) {
      return undefined;
    }

    children.push(element);
  }

  const element: TElement = { type: node.type, children };
  for (const key of Object.keys(node)) {
    if (key === "type" || key === "children") {
      continue;
    }

    element[key] = node[key];
  }

  return element;
}

export function capPastedTable(node: TElement, repairs: Repair[] | undefined): TElement {
  if (node.type !== KEYS.table) {
    return node;
  }

  const maxRows = tableMaxRows();
  const maxColumns = tableMaxColumns();
  const sourceRows = elementChildren(node);
  let truncated = sourceRows.length > maxRows;
  const keptRows = sourceRows.slice(0, maxRows);
  let changed = keptRows.length !== node.children.length;
  const nextRows = keptRows.map((row) => {
    const cells = elementChildren(row);
    if (cells.length <= maxColumns) {
      return row;
    }

    truncated = true;
    changed = true;
    return { ...row, children: cells.slice(0, maxColumns) };
  });

  if (
    truncated &&
    repairs !== undefined &&
    !repairs.some((repair) => repair.message === pastedTableTruncationMessage())
  ) {
    repairs.push({ path: [], message: pastedTableTruncationMessage() });
  }

  if (!changed && !truncated) {
    return node;
  }

  return { ...node, children: nextRows };
}

function isCellElement(node: unknown): node is TElement {
  return isTElement(node) && (node.type === KEYS.td || node.type === KEYS.th);
}

function contextForCell(editor: SlateEditor, cellPath: number[]): TableCellContext | undefined {
  const tableEntry = editor.api.above({
    at: cellPath,
    match: (node) => isTElement(node) && node.type === KEYS.table,
  });
  if (!tableEntry || !isTElement(tableEntry[0])) {
    return undefined;
  }

  const rowIndex = cellPath[cellPath.length - 2];
  const cellIndex = cellPath[cellPath.length - 1];
  if (rowIndex === undefined || cellIndex === undefined) {
    return undefined;
  }

  const coverage = tableCoverage(tableRecord(tableEntry[0]), tableMaxColumns());
  const covered = coverage.cells.find(
    (cell) => cell.rowIndex === rowIndex && cell.cellIndex === cellIndex,
  );

  return {
    tablePath: tableEntry[1],
    cellPath,
    rowIndex,
    columnIndex: covered?.column ?? cellIndex,
    cellIndex,
    rowCount: coverage.rowCount,
    columnCount: coverage.columnCount,
    colSpan: covered?.colSpan ?? 1,
    rowSpan: covered?.rowSpan ?? 1,
  };
}

export function tableCellContext(editor: SlateEditor): TableCellContext | undefined {
  if (!editor.selection) {
    return undefined;
  }

  const cellEntry = editor.api.above({
    match: (node) => isCellElement(node),
  });
  if (!cellEntry || !isCellElement(cellEntry[0])) {
    return undefined;
  }

  return contextForCell(editor, cellEntry[1]);
}

// Plate's Tab selects the whole next cell, so the range is expanded but still
// inside one cell. A range that crosses cells is left for Plate.
export function selectedCellContext(editor: SlateEditor): TableCellContext | undefined {
  const selection = editor.selection;
  if (!selection) {
    return undefined;
  }

  const anchorEntry = editor.api.above({
    at: selection.anchor,
    match: (node) => isCellElement(node),
  });
  const focusEntry = editor.api.above({
    at: selection.focus,
    match: (node) => isCellElement(node),
  });
  if (!anchorEntry || !focusEntry || !isCellElement(anchorEntry[0])) {
    return undefined;
  }

  if (!PathApi.equals(anchorEntry[1], focusEntry[1])) {
    return undefined;
  }

  return contextForCell(editor, anchorEntry[1]);
}

export function caretAtCellStart(editor: SlateEditor, cellPath: number[]): boolean {
  if (!editor.selection || !editor.api.isCollapsed()) {
    return false;
  }

  const start = editor.api.start(cellPath);
  return start !== undefined && PointApi.equals(editor.selection.anchor, start);
}

export function replaceTableWithParagraph(editor: SlateEditor, tablePath: number[]): void {
  editor.tf.removeNodes({ at: tablePath });
  editor.tf.insertNodes(emptyParagraph(), { at: tablePath, select: true });
}

function liveTable(editor: SlateEditor, tablePath: number[]): TElement | undefined {
  const entry = editor.api.node(tablePath);
  return entry && isTElement(entry[0]) && entry[0].type === KEYS.table ? entry[0] : undefined;
}

function rowCountOf(table: TElement): number {
  return table.children.length;
}

function columnCountOf(table: TElement): number {
  return tableCoverage(tableRecord(table), tableMaxColumns()).columnCount;
}

function anchorAt(
  table: TElement,
  gridRow: number,
  gridColumn: number,
): CoveredCell | "covered" | undefined {
  const owner = tableCoverage(tableRecord(table), tableMaxColumns()).cells.find(
    (cell) =>
      cell.row <= gridRow &&
      gridRow < cell.row + cell.rowSpan &&
      cell.column <= gridColumn &&
      gridColumn < cell.column + cell.colSpan,
  );
  if (!owner) {
    return undefined;
  }

  if (owner.row !== gridRow || owner.column !== gridColumn) {
    return "covered";
  }

  return owner;
}

export function neutralizeInsertedColumnWidths(editor: SlateEditor, tablePath: number[]): void {
  const table = liveTable(editor, tablePath);
  const raw = table?.colSizes;
  if (!table || !Array.isArray(raw)) {
    return;
  }

  let changed = false;
  const next = raw.map((value) => {
    if (value === 0) {
      changed = true;
      return null;
    }

    return value;
  });
  if (!changed) {
    return;
  }

  if (next.every((value) => value === null)) {
    editor.tf.unsetNodes("colSizes", { at: tablePath });
    return;
  }

  editor.tf.setNodes({ colSizes: next }, { at: tablePath });
}

export function repairTableGrid(node: TElement, repairs: Repair[] | undefined): TElement {
  const checked = checkTableGrid(tableRecord(node), [], {
    maxRows: tableMaxRows(),
    maxColumns: tableMaxColumns(),
  });
  if (repairs !== undefined) {
    repairs.push(...checked.repairs);
  }

  if (checked.next === undefined) {
    return node;
  }

  return elementFromRecord(checked.next) ?? node;
}

function tsvGrid(text: string): string[][] | undefined {
  if (!text.includes("\t")) {
    return undefined;
  }

  const normalized = text.replaceAll("\r\n", "\n").replaceAll("\r", "\n");
  const lines = normalized.split("\n");
  if (lines.at(-1) === "") {
    lines.pop();
  }

  if (lines.length === 0) {
    return undefined;
  }

  return lines.map((line) => line.split("\t"));
}

function writeCellText(editor: SlateEditor, cellPath: number[], text: string): void {
  if (!editor.api.node(cellPath)) {
    return;
  }

  editor.tf.replaceNodes(emptyParagraph(text), { at: cellPath, children: true });
}

export function fillTableWithTsv(
  editor: SlateEditor,
  text: string,
): { handled: boolean; truncated: boolean } {
  const grid = tsvGrid(text);
  const origin = tableCellContext(editor);
  if (!grid || !origin) {
    return { handled: false, truncated: false };
  }

  const maxRows = tableMaxRows();
  const maxColumns = tableMaxColumns();
  let truncated = false;

  editor.tf.withoutNormalizing(() => {
    for (let rowOffset = 0; rowOffset < grid.length; rowOffset += 1) {
      const targetRow = origin.rowIndex + rowOffset;
      if (targetRow >= maxRows) {
        truncated = true;
        break;
      }

      let table = liveTable(editor, origin.tablePath);
      if (!table) {
        return;
      }

      while (rowCountOf(table) <= targetRow) {
        if (rowCountOf(table) >= maxRows) {
          truncated = true;
          break;
        }

        const before = rowCountOf(table);
        // fromRow, not the selection: writing a cell replaces its children and
        // moves the caret out of the table, and insertTableRow then no-ops.
        insertTableRow(editor, {
          select: false,
          fromRow: origin.tablePath.concat(before - 1),
        });
        table = liveTable(editor, origin.tablePath);
        if (!table || rowCountOf(table) === before) {
          truncated = true;
          return;
        }
      }

      const row = grid[rowOffset];
      if (!row || !table) {
        continue;
      }

      for (let columnOffset = 0; columnOffset < row.length; columnOffset += 1) {
        const targetColumn = origin.columnIndex + columnOffset;
        if (targetColumn >= maxColumns) {
          truncated = true;
          continue;
        }

        table = liveTable(editor, origin.tablePath);
        if (!table) {
          return;
        }

        while (columnCountOf(table) <= targetColumn) {
          if (columnCountOf(table) >= maxColumns) {
            truncated = true;
            break;
          }

          const before = columnCountOf(table);
          const firstRow = table.children[0];
          const lastCell = isTElement(firstRow) ? firstRow.children.length - 1 : 0;
          // fromCell is the last cell, so the new column is appended. The caret
          // is not a reliable anchor after writeCellText replaces a cell.
          insertTableColumn(editor, {
            select: false,
            fromCell: origin.tablePath.concat(0, lastCell),
          });
          neutralizeInsertedColumnWidths(editor, origin.tablePath);
          table = liveTable(editor, origin.tablePath);
          if (!table || columnCountOf(table) === before) {
            truncated = true;
            return;
          }
        }

        table = liveTable(editor, origin.tablePath);
        if (!table) {
          return;
        }

        const slot = anchorAt(table, targetRow, targetColumn);
        if (slot === "covered" || slot === undefined) {
          continue;
        }

        const cellText = row[columnOffset] ?? "";
        writeCellText(editor, origin.tablePath.concat(slot.rowIndex, slot.cellIndex), cellText);
      }
    }
  });

  return { handled: true, truncated };
}

// A root table always gets a paragraph after it: that paragraph is the only place for a caret below the table.
function followingParagraphAllowed(editor: SlateEditor, tablePath: number[]): boolean {
  if (tablePath.length === 1) {
    return true;
  }

  const parent = editor.api.node(tablePath.slice(0, -1));
  if (!parent || !isTElement(parent[0])) {
    return false;
  }

  const childTypes = allowedChildTypes(parent[0].type);
  return (
    childTypes !== undefined &&
    childTypes.some((type) => type === KEYS.p) &&
    childTypes.some((type) => type === KEYS.table)
  );
}

function ensureParagraphAfterTable(editor: SlateEditor, tablePath: number[]): boolean {
  if (!followingParagraphAllowed(editor, tablePath)) {
    return false;
  }

  const next = PathApi.next(tablePath);
  if (!next || editor.api.node(next)) {
    return false;
  }

  editor.tf.insertNodes(emptyParagraph(), { at: next });
  return true;
}

export function normalizeTableNode(
  editor: SlateEditor,
  node: { type: string; children?: unknown },
  path: number[],
): boolean {
  if (node.type !== KEYS.table || !Array.isArray(node.children)) {
    return false;
  }

  const rows = node.children.filter(isTElement);
  if (rows.length === 0) {
    editor.tf.removeNodes({ at: path });
    if (editor.children.length === 0) {
      editor.tf.insertNodes(emptyParagraph(), { at: path.length === 1 ? path : [0], select: true });
    }
    return true;
  }

  if (rows.length > tableMaxRows()) {
    editor.tf.removeNodes({ at: path.concat(tableMaxRows()) });
    return true;
  }

  if (!isRecord(node)) {
    return false;
  }

  const checked = checkTableGrid(node, path, {
    maxRows: tableMaxRows(),
    maxColumns: tableMaxColumns(),
  });
  const replacement = checked.next === undefined ? undefined : elementFromRecord(checked.next);
  if (replacement) {
    editor.tf.withoutNormalizing(() => {
      editor.tf.removeNodes({ at: path });
      editor.tf.insertNodes(replacement, { at: path });
    });
    return true;
  }

  return ensureParagraphAfterTable(editor, path);
}

export function rowIsHeader(table: TElement): boolean {
  const row = table.children[0];
  if (!isTElement(row) || row.children.length === 0) {
    return false;
  }

  return row.children.every((cell) => isTElement(cell) && cell.type === KEYS.th);
}

export function columnIsHeader(table: TElement): boolean {
  const anchors = tableCoverage(tableRecord(table), tableMaxColumns()).cells.filter(
    (cell) => cell.column === 0,
  );
  if (anchors.length === 0) {
    return false;
  }

  return anchors.every((anchor) => {
    const row = table.children[anchor.rowIndex];
    const cell = isTElement(row) ? row.children[anchor.cellIndex] : undefined;
    return isTElement(cell) && cell.type === KEYS.th;
  });
}

export function wholeTableSelection(editor: SlateEditor): number[] | undefined {
  if (!editor.selection || editor.api.isCollapsed()) {
    return undefined;
  }

  const matchesTable = (node: unknown): boolean => isTElement(node) && node.type === KEYS.table;
  if (!editor.api.isAt({ block: true, match: matchesTable })) {
    return undefined;
  }

  const entry = editor.api.block({ match: matchesTable });
  return entry?.[1];
}

import type { MouseEvent } from "react";
import { ElementApi, KEYS, NodeApi, TextApi, type SlateEditor, type TNode } from "platejs";

import { focusEditorWithoutScroll, retainScroll } from "../../components/ui/block-toolbar";
import { insertParagraphBelow, runEditorCommand } from "../commands/editor-commands";
import { clearBlockSelection } from "../plugins/editor-block-selection";
import { editorOptions } from "../plugins/editor-config";

type TailClickAction = "append" | "focus-last" | "none";

// An empty plain paragraph: no list marker and no text, so nothing to add to.
function isEmptyPlainParagraph(node: TNode): boolean {
  return (
    ElementApi.isElement(node) &&
    node.type === KEYS.p &&
    node.listStyleType === undefined &&
    node.children.every((child) => TextApi.isText(child)) &&
    NodeApi.string(node) === ""
  );
}

// What a click in the empty space below the document does. `last` is the
// document's last top-level node.
export function tailClickAction(last: TNode | undefined, readOnly: boolean): TailClickAction {
  if (readOnly || last === undefined || !ElementApi.isElement(last)) {
    return "none";
  }
  return isEmptyPlainParagraph(last) ? "focus-last" : "append";
}

// A primary click on the editable itself, below its last block, is the empty
// space under the document. Returns true when the click is handled, which stops
// Slate's own mousedown handling. With the appendOnTailClick option off, the
// browser handles every click.
export function handleTailMouseDown(
  editor: SlateEditor,
  event: MouseEvent<HTMLElement>,
  readOnly: boolean,
): true | undefined {
  if (!editorOptions(editor).appendOnTailClick) {
    return undefined;
  }
  if (event.button !== 0 || event.target !== event.currentTarget) {
    return undefined;
  }
  const lastIndex = editor.children.length - 1;
  const last = editor.children[lastIndex];
  const lastDom = last ? editor.api.toDOMNode(last) : undefined;
  if (
    !(lastDom instanceof HTMLElement) ||
    event.clientY <= lastDom.getBoundingClientRect().bottom
  ) {
    return undefined;
  }

  const action = tailClickAction(last, readOnly);
  if (action === "none") {
    return undefined;
  }

  event.preventDefault();
  clearBlockSelection(editor, false);
  const root = event.currentTarget;
  retainScroll(() => {
    if (action === "append") {
      runEditorCommand(editor, insertParagraphBelow, { path: [lastIndex] });
    } else {
      const start = editor.api.start([lastIndex]);
      if (start) {
        editor.tf.select(start);
      }
    }
    focusEditorWithoutScroll(root);
  });
  return true;
}

import { ElementApi, KEYS, NodeApi, type Descendant, type TElement } from "platejs";

export const TOC_DEPTHS = [1, 2, 3] as const;
export type TocDepth = (typeof TOC_DEPTHS)[number];
export const TOC_DEFAULT_DEPTH: TocDepth = 3;
export const TOC_EMPTY_PLACEHOLDER = "Add headings to build a table of contents.";
export const TOC_UNTITLED = "Untitled";

export type TocEntry = {
  id: string;
  depth: TocDepth;
  title: string;
  path: number[];
};

export function isTocDepth(value: unknown): value is TocDepth {
  return value === 1 || value === 2 || value === 3;
}

export function storedTocDepth(node: TElement): TocDepth {
  return isTocDepth(node.maxDepth) ? node.maxDepth : TOC_DEFAULT_DEPTH;
}

export function headingPlainText(node: TElement): string {
  return NodeApi.string(node).replace(/\s+/g, " ").trim();
}

function headingDepth(type: string): TocDepth | undefined {
  if (type === KEYS.h1) return 1;
  if (type === KEYS.h2) return 2;
  if (type === KEYS.h3) return 3;
  return undefined;
}

export function tocEntriesFromValue(value: readonly Descendant[], maxDepth: TocDepth): TocEntry[] {
  const entries: TocEntry[] = [];
  const visit = (node: Descendant, path: number[]): void => {
    if (!ElementApi.isElement(node) || typeof node.type !== "string") {
      return;
    }
    const depth = headingDepth(node.type);
    if (
      depth !== undefined &&
      depth <= maxDepth &&
      typeof node.id === "string" &&
      node.id.length > 0
    ) {
      entries.push({
        id: node.id,
        depth,
        title: headingPlainText(node),
        path: [...path],
      });
    }
    node.children.forEach((child, index) => {
      visit(child, path.concat(index));
    });
  };
  value.forEach((node, index) => {
    visit(node, [index]);
  });
  return entries;
}

export function shallowestDepth(entries: readonly { depth: TocDepth }[]): TocDepth {
  let shallowest: TocDepth = TOC_DEFAULT_DEPTH;
  for (const entry of entries) {
    if (entry.depth < shallowest) {
      shallowest = entry.depth;
    }
  }
  return shallowest;
}

import { ElementApi, KEYS, PathApi, type SlateEditor, type TElement } from "platejs";

import type { EditorCommand } from "../commands/editor-commands";
import { headingAnchorId } from "../../components/elements/heading-styles";
import { toggleOpen } from "../plugins/editor-toggle";
import {
  TOC_DEFAULT_DEPTH,
  headingPlainText,
  isTocDepth,
  type TocDepth,
  type TocEntry,
} from "./editor-toc-outline";

export {
  TOC_DEFAULT_DEPTH,
  TOC_DEPTHS,
  TOC_EMPTY_PLACEHOLDER,
  TOC_UNTITLED,
  headingPlainText,
  isTocDepth,
  shallowestDepth,
  storedTocDepth,
  type TocDepth,
  type TocEntry,
} from "./editor-toc-outline";

function headingDepth(type: string): TocDepth | undefined {
  if (type === KEYS.h1) {
    return 1;
  }
  if (type === KEYS.h2) {
    return 2;
  }
  if (type === KEYS.h3) {
    return 3;
  }
  return undefined;
}

export function tocEntries(editor: SlateEditor, maxDepth: TocDepth): TocEntry[] {
  // A synced_ref is a void and is not a heading, so a reference does not list a heading twice.
  const entries: TocEntry[] = [];
  for (const [node, path] of editor.api.nodes({
    at: [],
    match: (candidate) => {
      if (!ElementApi.isElement(candidate) || typeof candidate.type !== "string") {
        return false;
      }
      const depth = headingDepth(candidate.type);
      return depth !== undefined && depth <= maxDepth;
    },
  })) {
    if (!ElementApi.isElement(node) || typeof node.id !== "string" || node.id.length === 0) {
      continue;
    }
    const depth = typeof node.type === "string" ? headingDepth(node.type) : undefined;
    if (depth === undefined) {
      continue;
    }
    entries.push({
      id: node.id,
      depth,
      title: headingPlainText(node),
      path: [...path],
    });
  }
  return entries;
}

export function prefersReducedMotion(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
    return false;
  }
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function openClosedAncestors(editor: SlateEditor, path: readonly number[]): void {
  for (let length = 1; length < path.length; length += 1) {
    const parent = editor.api.node(path.slice(0, length));
    if (!parent || !ElementApi.isElement(parent[0]) || parent[0].type !== KEYS.toggle) {
      continue;
    }
    const id = parent[0].id;
    if (typeof id !== "string" || id.length === 0) {
      continue;
    }
    toggleOpen(editor, id, true);
  }
}

function scrollingParent(element: HTMLElement): HTMLElement | null {
  let parent = element.parentElement;
  while (parent) {
    const overflow = getComputedStyle(parent).overflowY;
    if (
      (overflow === "auto" || overflow === "scroll") &&
      parent.scrollHeight > parent.clientHeight + 1
    ) {
      return parent;
    }
    parent = parent.parentElement;
  }
  return null;
}

function placeCaret(editor: SlateEditor, entry: TocEntry, readOnly: boolean): void {
  const element = document.getElementById(headingAnchorId(entry.id));
  if (readOnly) {
    if (!element) {
      return;
    }
    element.tabIndex = -1;
    element.setAttribute("tabindex", "-1");
    element.focus({ preventScroll: true });
    return;
  }
  const start = editor.api.start(entry.path);
  if (!start) {
    return;
  }
  // Selecting without focus updates the model only. The visible caret needs the editor focused.
  editor.tf.withoutSaving(() => {
    editor.tf.select(start, { focus: true });
  });
}

function revealTarget(editor: SlateEditor, entry: TocEntry, readOnly: boolean): void {
  const behavior = prefersReducedMotion() ? "auto" : "smooth";
  const element = document.getElementById(headingAnchorId(entry.id));
  const scroller = element && behavior === "smooth" ? scrollingParent(element) : null;
  if (element) {
    element.scrollIntoView({ behavior, block: "start" });
  }
  // Slate scrolls a new selection with scrollMode "if-needed". Doing that while a
  // smooth scroll is running pulls the heading to the middle of the pane. Wait
  // until the scroll finishes, when the heading is already in view.
  if (scroller) {
    let placed = false;
    const place = () => {
      if (placed) {
        return;
      }
      placed = true;
      placeCaret(editor, entry, readOnly);
    };
    let moved = false;
    const mark = () => {
      moved = true;
    };
    scroller.addEventListener("scroll", mark);
    scroller.addEventListener(
      "scrollend",
      () => {
        scroller.removeEventListener("scroll", mark);
        place();
      },
      { once: true },
    );
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (!moved) {
          scroller.removeEventListener("scroll", mark);
          place();
        }
      });
    });
    return;
  }
  placeCaret(editor, entry, readOnly);
}

export function activateTocEntry(editor: SlateEditor, entry: TocEntry, readOnly: boolean): void {
  openClosedAncestors(editor, entry.path);
  const reveal = () => {
    revealTarget(editor, entry, readOnly);
  };
  if (typeof requestAnimationFrame === "function") {
    requestAnimationFrame(reveal);
    return;
  }
  reveal();
}

function tocNode(): TElement {
  return { type: KEYS.toc, children: [{ text: "" }] };
}

function insertTocBlock(editor: SlateEditor): void {
  const current = editor.api.block({ highest: true });
  if (!current) {
    editor.tf.insertNodes(tocNode(), { at: [0], select: true });
    return;
  }
  const at = PathApi.next(current[1]);
  if (!at) {
    return;
  }
  editor.tf.insertNodes(tocNode(), { at, select: true });
}

// Insert a table of contents as the next sibling of `path`, inside its
// container. Used by the Add picker.
export function insertTocBelow(editor: SlateEditor, path: readonly number[]): void {
  const at = PathApi.next([...path]);
  if (!at) {
    return;
  }
  editor.tf.insertNodes(tocNode(), { at, select: true });
}

function tocAbove(editor: SlateEditor): [TElement, number[]] | undefined {
  const entry = editor.api.above({
    match: (node) => ElementApi.isElement(node) && node.type === KEYS.toc,
    voids: true,
  });
  if (!entry || !ElementApi.isElement(entry[0])) {
    return undefined;
  }
  return [entry[0], entry[1]];
}

export function setTocDepth(editor: SlateEditor, path: number[], depth: TocDepth): void {
  const node = editor.api.node(path);
  if (!node || !ElementApi.isElement(node[0]) || node[0].type !== KEYS.toc) {
    return;
  }
  const current = isTocDepth(node[0].maxDepth) ? node[0].maxDepth : undefined;
  const stored = depth === TOC_DEFAULT_DEPTH ? undefined : depth;
  if (current === stored) {
    return;
  }
  if (stored === undefined) {
    editor.tf.unsetNodes("maxDepth", { at: path });
    return;
  }
  editor.tf.setNodes({ maxDepth: stored }, { at: path });
}

export function removeToc(editor: SlateEditor, path: number[]): void {
  editor.tf.removeNodes({ at: path, voids: true });
  if (editor.children.length === 0) {
    editor.tf.insertNodes({ type: KEYS.p, children: [{ text: "" }] }, { at: [0] });
  }
}

export const insertToc: EditorCommand = {
  id: "block.insert.toc",
  label: "Table of contents",
  group: "insert",
  run: (editor) => {
    insertTocBlock(editor);
  },
};

export const setTocDepthCommand: EditorCommand<TocDepth> = {
  id: "block.toc.set-depth",
  label: "Table of contents depth",
  group: "action",
  isEnabled: (editor) => tocAbove(editor) !== undefined,
  run: (editor, depth) => {
    const entry = tocAbove(editor);
    if (!entry) {
      return;
    }
    setTocDepth(editor, entry[1], depth);
  },
};

export const removeTocCommand: EditorCommand = {
  id: "block.toc.remove",
  label: "Delete",
  group: "action",
  isEnabled: (editor) => tocAbove(editor) !== undefined,
  run: (editor) => {
    const entry = tocAbove(editor);
    if (!entry) {
      return;
    }
    removeToc(editor, entry[1]);
  },
};

import {
  cleanFileName,
  cleanFileText,
  sanitizeMimeType,
  sanitizeUploadedFile,
} from "./editor-file-url";
import type { FileUploadAdapter, UploadedFile } from "./editor-file-upload";

export type UploadState =
  | { status: "uploading"; name: string; size: number; progress: number } // progress 0..1
  | { status: "failed"; name: string; size: number; message: string };

export type UploadController = {
  start: (blockId: string, file: File) => void;
  cancel: (blockId: string) => void; // aborts and forgets the upload; no onDone
  retry: (blockId: string) => void; // only from "failed"; uploads the same File again
  get: (blockId: string) => UploadState | undefined;
  ids: () => string[]; // blocks with an upload that is running or failed
  subscribe: (listener: () => void) => () => void;
  dispose: () => void; // aborts everything
};

const ERROR_MESSAGE_MAX = 200;
const FALLBACK_MESSAGE = "Upload failed.";
const INVALID_MESSAGE = "The upload returned an invalid file.";

// One record per block. A record is live only while it is the block's current record and
// its controller has not been aborted.
type Record = {
  file: File;
  state: UploadState;
  abort?: AbortController; // present only while the upload is running
};

function errorMessage(error: unknown): string {
  if (error instanceof Error) {
    return cleanFileText(error.message, ERROR_MESSAGE_MAX) ?? FALLBACK_MESSAGE;
  }

  return FALLBACK_MESSAGE;
}

function displayName(file: File): string {
  return cleanFileName(file.name) ?? "";
}

// The browser type can carry parameters, such as "text/plain;charset=utf-8". Only the type is kept.
function fileMimeType(file: File): string | undefined {
  const [essence = ""] = file.type.split(";");
  return sanitizeMimeType(essence.trim());
}

function uploadingState(file: File, progress: number): UploadState {
  return { status: "uploading", name: displayName(file), size: file.size, progress };
}

export function createUploadController(options: {
  adapter: FileUploadAdapter;
  onDone: (blockId: string, file: UploadedFile) => void;
}): UploadController {
  const { adapter, onDone } = options;
  const records = new Map<string, Record>();
  const listeners = new Set<() => void>();
  let disposed = false;

  function notify(): void {
    for (const listener of [...listeners]) {
      try {
        listener();
      } catch {
        // A listener that throws must not stop the others.
      }
    }
  }

  function isLive(blockId: string, record: Record): boolean {
    return (
      records.get(blockId) === record && record.abort !== undefined && !record.abort.signal.aborted
    );
  }

  function setProgress(blockId: string, record: Record, fraction: number): void {
    if (!isLive(blockId, record) || record.state.status !== "uploading") {
      return;
    }

    // Progress is clamped, ignores NaN, and never goes backwards.
    if (Number.isNaN(fraction)) {
      return;
    }

    const next = Math.min(1, Math.max(0, fraction));
    if (next <= record.state.progress) {
      return;
    }

    record.state = { ...record.state, progress: next };
    notify();
  }

  function setFailed(blockId: string, record: Record, message: string): void {
    records.set(blockId, {
      file: record.file,
      state: { status: "failed", name: displayName(record.file), size: record.file.size, message },
    });
    notify();
  }

  function finish(blockId: string, record: Record, raw: unknown): void {
    if (!isLive(blockId, record)) {
      return;
    }

    const valid = sanitizeUploadedFile(raw);
    if (valid === null) {
      setFailed(blockId, record, INVALID_MESSAGE);
      return;
    }

    // The File fills in fields the adapter left out. Each value is cleaned the same way.
    const done: UploadedFile = { url: valid.url };
    const name = valid.name ?? cleanFileName(record.file.name);
    if (name !== undefined) {
      done.name = name;
    }

    done.size = valid.size ?? record.file.size;

    const mime = valid.mime ?? fileMimeType(record.file);
    if (mime !== undefined) {
      done.mime = mime;
    }

    records.delete(blockId);
    notify();
    onDone(blockId, done);
  }

  function fail(blockId: string, record: Record, error: unknown): void {
    if (!isLive(blockId, record)) {
      return;
    }

    setFailed(blockId, record, errorMessage(error));
  }

  function run(blockId: string, record: Record): void {
    const abort = record.abort;
    if (abort === undefined) {
      return;
    }

    // The executor turns a synchronous throw from the adapter into a rejection.
    const pending = new Promise<UploadedFile>((resolve) => {
      resolve(
        adapter.upload(record.file, {
          signal: abort.signal,
          onProgress: (fraction) => {
            setProgress(blockId, record, fraction);
          },
        }),
      );
    });

    pending.then(
      (result) => {
        finish(blockId, record, result);
      },
      (error: unknown) => {
        fail(blockId, record, error);
      },
    );
  }

  function start(blockId: string, file: File): void {
    if (disposed) {
      return;
    }

    records.get(blockId)?.abort?.abort();
    const record: Record = {
      file,
      abort: new AbortController(),
      state: uploadingState(file, 0),
    };
    records.set(blockId, record);
    notify();
    run(blockId, record);
  }

  function cancel(blockId: string): void {
    const record = records.get(blockId);
    if (record === undefined) {
      return;
    }

    // Forget the record before aborting, so a synchronous abort handler cannot report progress.
    records.delete(blockId);
    record.abort?.abort();
    notify();
  }

  function retry(blockId: string): void {
    if (disposed) {
      return;
    }

    const record = records.get(blockId);
    if (record === undefined || record.state.status !== "failed") {
      return;
    }

    start(blockId, record.file);
  }

  return {
    start,
    cancel,
    retry,
    get(blockId) {
      return records.get(blockId)?.state;
    },
    ids() {
      return [...records.keys()];
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    dispose() {
      if (disposed) {
        return;
      }

      disposed = true;
      const active = [...records.values()];
      records.clear();
      for (const record of active) {
        record.abort?.abort();
      }

      if (active.length > 0) {
        notify();
      }

      listeners.clear();
    },
  };
}

