export const PASTE_HTML_CHAR_LIMIT = 2_000_000;
export const PASTE_BLOCK_LIMIT = 2_000;
export const PASTE_TEXT_CHAR_LIMIT = 1_000_000;

export function pasteTooLargeMessage(kind: "blocks" | "characters"): string {
  if (kind === "blocks") {
    return "The paste was too large. Only the first 2,000 blocks were inserted.";
  }

  return "The paste was too large. Only the first 1,000,000 characters were inserted.";
}

export function clipboardWithinHtmlLimit(data: DataTransfer): DataTransfer {
  const html = data.getData("text/html");
  if (html.length <= PASTE_HTML_CHAR_LIMIT) {
    return data;
  }

  const next = new DataTransfer();
  for (const type of data.types) {
    if (type === "text/html") {
      continue;
    }

    const value = data.getData(type);
    if (value.length > 0) {
      next.setData(type, value);
    }
  }

  return next;
}

export { pasteRepairsOf, setPasteRepairs };

type PasteSanitizeOptions = {
  isInline?: (node: Record<string, unknown>) => boolean;
  seenIds?: Set<string>;
  /** True for a node type whose feature is off. Such a node never becomes its own type. */
  featureOff?: (type: string) => boolean;
  /** Truncation and other paste repairs. The same list is what the editor reports. */
  repairs?: Repair[];
};

let activePasteRepairs: Repair[] | undefined;
let activeFeatureOff: ((type: string) => boolean) | undefined;

// Only the sanitizer pass that is running reads this.
function pasteTypeOff(type: string): boolean {
  return activeFeatureOff?.(type) === true;
}

// The table override sanitizes the fragment again. A repair from the first pass
// is gone on the second, so those repairs are kept until the outer insert finishes.
let pendingImageRepairs: Repair[] = [];
let pendingLimitRepairs: Repair[] = [];

function rememberLimitRepair(repair: Repair): void {
  if (!pendingLimitRepairs.some((item) => item.message === repair.message)) {
    pendingLimitRepairs.push(repair);
  }
}

function clearPendingLimitRepairs(): void {
  pendingLimitRepairs = [];
}
let pendingMentionInputRepairs: Repair[] = [];

function rememberImageRepair(repair: Repair): void {
  activePasteRepairs?.push(repair);
  pendingImageRepairs.push(repair);
}

function clearPendingImageRepairs(): void {
  pendingImageRepairs = [];
}

function clearPendingMentionInputRepairs(): void {
  pendingMentionInputRepairs = [];
}

type IsInline = (node: Record<string, unknown>) => boolean;

type Nesting = ReadonlyMap<string, number>;

const emptyNesting: Nesting = new Map();

type PasteChild =
  | { kind: "text"; node: TText }
  | { kind: "inline"; node: TElement }
  | { kind: "block"; node: TElement };

// Plate sorts plugins high-priority first, then tries HTML deserializers in reverse.
// 1000 runs after the default priority of 100, so a later heading or list plugin matches first.
const PASTE_FALLBACK_PRIORITY = 1000;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isTextNode(node: Record<string, unknown>): boolean {
  return typeof node.text === "string" && !Array.isArray(node.children);
}

function isElementNode(node: Record<string, unknown>): node is TElement {
  return typeof node.type === "string" && Array.isArray(node.children);
}

function sanitizeText(node: Record<string, unknown>, allowMarks: boolean): TText {
  const text = typeof node.text === "string" ? node.text : "";
  if (!allowMarks) {
    return { text };
  }

  const next: TText = { text };

  for (const key of Object.keys(node)) {
    if (key === "text" || !isAllowedMark(key) || !isAllowedMarkValue(key, node[key])) {
      continue;
    }

    next[key] = node[key];
  }

  // Inline code and kbd are mutually exclusive. Code wins, as it does when typed.
  if (next[KEYS.code] === true) {
    delete next[KEYS.kbd];
  }

  return next;
}

function classifyPasteChild(
  child: unknown,
  isInline: IsInline,
  allowMarks = true,
): PasteChild | undefined {
  if (typeof child === "string") {
    return { kind: "text", node: { text: child } };
  }

  if (!isRecord(child)) {
    return undefined;
  }

  if (isTextNode(child)) {
    return { kind: "text", node: sanitizeText(child, allowMarks) };
  }

  if (!isElementNode(child)) {
    return undefined;
  }

  if (isInline(child)) {
    return { kind: "inline", node: child };
  }

  return { kind: "block", node: child };
}

function takeId(node: Record<string, unknown>, seen: Set<string>): string | undefined {
  if (typeof node.id !== "string" || node.id.length === 0 || seen.has(node.id)) {
    return undefined;
  }

  seen.add(node.id);
  return node.id;
}

function integerSpan(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }

  if (typeof value === "string" && /^-?[0-9]+$/.test(value)) {
    return Number(value);
  }

  return undefined;
}

function copyCellSpans(node: Record<string, unknown>, props: TElement): void {
  if (props.type !== "td" && props.type !== "th") {
    return;
  }

  const attributes = isRecord(node.attributes) ? node.attributes : undefined;
  const colSpan = integerSpan(node.colSpan) ?? integerSpan(attributes?.colspan);
  const rowSpan = integerSpan(node.rowSpan) ?? integerSpan(attributes?.rowspan);
  if (colSpan !== undefined) {
    props.colSpan = colSpan;
  }

  if (rowSpan !== undefined) {
    props.rowSpan = rowSpan;
  }
}

// A pasted indent above the cap is clamped. Below 1 or non-integer is left to the attr check.
function pastedIndent(value: unknown): unknown {
  if (typeof value === "number" && Number.isInteger(value) && value > BLOCK_INDENT_MAX) {
    return BLOCK_INDENT_MAX;
  }
  return value;
}

function copyAllowedAttrs(node: Record<string, unknown>, props: TElement): void {
  const allowed = allowedElementAttrs(props.type);
  if (allowed === undefined) {
    return;
  }

  for (const key of allowed) {
    const value = key === "indent" ? pastedIndent(node[key]) : node[key];
    if (
      key === "id" ||
      key === "colSpan" ||
      key === "rowSpan" ||
      !(key in node) ||
      !isAllowedElementAttrValue(props.type, key, value)
    ) {
      continue;
    }

    props[key] = value;
  }

  copyCellSpans(node, props);

  for (const dependent of unsatisfiedDependentAttrs(props.type, props)) {
    Reflect.deleteProperty(props, dependent);
  }
}

function elementNode(type: string, children: Descendant[], id: string | undefined): TElement {
  const props: TElement = { type, children };
  if (id !== undefined) {
    props.id = id;
  }

  return props;
}

// KEYS.video and KEYS.audio are the same strings as the video and audio blocks, so they are not
// dropped here. The video and audio sanitizers keep a node of those types as a block, as they do for
// KEYS.file and the file block. HTML video and audio elements still become unsupported_media.
function isDroppedMediaType(type: string): boolean {
  // Media and embed types with their feature off are dropped the way an unsupported image is.
  const feature = nodeFeature(type);
  if (feature === "media" || feature === "embeds") {
    return pasteTypeOff(type);
  }
  return (
    type === KEYS.img || type === KEYS.mediaEmbed || type === "pdf" || type === "unsupported_media"
  );
}

// A dropped image, file, or embed keeps its readable text (alt, caption, name)
// so the paste is never silently emptied. The media itself is not stored.
// The paragraphs that still hold text. A feature-off block with no readable text leaves nothing.
function readableParagraphs(blocks: TElement[]): TElement[] {
  return blocks.filter((block) => nodeText(block).length > 0);
}

function droppedMediaLabel(node: Record<string, unknown>): string | undefined {
  // A bookmark or an embed with its feature off keeps its URL as text. The label is used only without one.
  if (pasteTypeOff(String(node.type)) && nodeFeature(String(node.type)) === "embeds") {
    const url = typeof node.url === "string" ? stripControlCharacters(node.url).trim() : "";
    if (url.length > 0) {
      return url;
    }
  }

  for (const key of ["alt", "caption", "name"]) {
    const value = node[key];
    if (typeof value !== "string") {
      continue;
    }

    const text = stripControlCharacters(value).trim();
    if (text.length > 0) {
      return text;
    }
  }

  return undefined;
}

function stripControlCharacters(value: string): string {
  let text = "";
  for (const character of value) {
    const code = character.codePointAt(0) ?? 0;
    if (code < 0x20 || code === 0x7f) {
      continue;
    }

    text += character;
  }

  return text;
}

function noteDroppedMedia(): void {
  rememberImageRepair({ path: [], message: MEDIA_NOT_SUPPORTED });
}

function pastedBookmark(node: TElement, seen: Set<string>): TElement[] {
  void seen;
  const stored = storedBookmark(node);
  if (stored === undefined) {
    rememberImageRepair({ path: [], message: BOOKMARK_PASTE_DROPPED });
    return [];
  }

  return [bookmarkElement(stored, nanoid())];
}

// Keeps the image and its valid fields. A field that cannot be cleaned is left out, and the repair
// says so. The url is the only field whose loss makes the image a placeholder.
function pastedImage(node: TElement, seen: Set<string>): TElement[] {
  const cleaned = cleanImageFields(node);
  if (cleaned.dropped) {
    rememberImageRepair({ path: [], message: IMAGE_ATTRS_CLEANED });
  }

  return [imageElement(cleaned.fields, takeId(node, seen))];
}

// Keeps the file and its valid fields, as pastedImage does for an image.
function pastedFile(node: TElement, seen: Set<string>): TElement[] {
  const cleaned = cleanFileFields(node);
  if (cleaned.dropped) {
    rememberImageRepair({ path: [], message: FILE_ATTRS_CLEANED });
  }

  return [fileElement(cleaned.fields, takeId(node, seen))];
}

// Keeps the video and its valid fields, as pastedImage does for an image.
function pastedVideo(node: TElement, seen: Set<string>): TElement[] {
  const cleaned = cleanVideoFields(node);
  if (cleaned.dropped) {
    rememberImageRepair({ path: [], message: VIDEO_ATTRS_CLEANED });
  }

  return [videoElement(cleaned.fields, takeId(node, seen))];
}

// Keeps the embed and its valid fields, as pastedVideo does for a video.
function pastedEmbed(node: TElement, seen: Set<string>): TElement[] {
  const cleaned = cleanEmbedFields(node);
  if (cleaned.cleared) {
    rememberImageRepair({ path: [], message: EMBED_SOURCE_REMOVED });
  } else if (cleaned.dropped) {
    rememberImageRepair({ path: [], message: EMBED_ATTRS_CLEANED });
  }

  return [embedElement(cleaned.fields, takeId(node, seen))];
}

// Keeps the audio and its valid fields, as pastedImage does for an image.
function pastedAudio(node: TElement, seen: Set<string>): TElement[] {
  const cleaned = cleanAudioFields(node);
  if (cleaned.dropped) {
    rememberImageRepair({ path: [], message: AUDIO_ATTRS_CLEANED });
  }

  return [audioElement(cleaned.fields, takeId(node, seen))];
}

function pastedPageLink(node: TElement, seen: Set<string>): TElement[] {
  const stored = storedPageLink(node);
  if (stored === undefined) {
    rememberImageRepair({ path: [], message: PAGE_LINK_PASTE_DROPPED });
    return [];
  }

  if (stored.title !== node.title) {
    rememberImageRepair({ path: [], message: PAGE_LINK_TITLE_CLEANED });
  }
  return [pageLinkNode(stored.pageId, stored.title, stored.kind, takeId(node, seen))];
}

function hasContent(nodes: readonly Descendant[]): boolean {
  for (const node of nodes) {
    if ("children" in node) {
      return true;
    }

    if (typeof node.text === "string" && node.text.length > 0) {
      return true;
    }
  }

  return false;
}

function paragraph(children: Descendant[], id?: string): TElement {
  return elementNode("p", children.length > 0 ? children : [{ text: "" }], id);
}

function collectIds(value: unknown, seen: Set<string>): void {
  if (!isRecord(value)) {
    return;
  }

  if (typeof value.id === "string" && value.id.length > 0) {
    seen.add(value.id);
  }

  if (!Array.isArray(value.children)) {
    return;
  }

  for (const child of value.children) {
    collectIds(child, seen);
  }
}

function stripForbiddenAttrs(node: TElement, forbidden: readonly string[]): TElement {
  if (forbidden.length === 0 || forbidden.every((key) => !(key in node))) {
    return node;
  }

  const next: TElement = { ...node, children: node.children };
  for (const key of forbidden) {
    Reflect.deleteProperty(next, key);
  }

  for (const dependent of unsatisfiedDependentAttrs(next.type, next)) {
    Reflect.deleteProperty(next, dependent);
  }

  return next;
}

function withFirstChild(type: string, blocks: TElement[]): TElement[] {
  const labels = firstChildTypes(type);
  const expected = firstChildType(type);
  if (labels === undefined || expected === undefined) {
    return blocks;
  }

  const first = blocks[0];
  if (first === undefined || !allowsFirstChild(type, first.type)) {
    return [elementNode(expected, [{ text: "" }], undefined), ...blocks];
  }

  const stripped = stripForbiddenAttrs(first, firstChildForbiddenAttrs(type));
  if (stripped === first) {
    return blocks;
  }

  return [stripped, ...blocks.slice(1)];
}

function disallowedVoid(node: TElement, parentType: string): boolean {
  if (!isVoidElementType(node.type)) {
    return false;
  }

  const childTypes = allowedChildTypes(parentType);
  return childTypes !== undefined && !childTypes.some((type) => type === node.type);
}

function placeInParent(
  node: TElement,
  parentType: string,
  isInline: IsInline,
  seen: Set<string>,
  nesting: Nesting = emptyNesting,
  asLabel = false,
): TElement[] {
  if (isDroppedMediaType(node.type)) {
    return expandBlock(node, isInline, seen, nesting);
  }

  // A void is never retyped. A container that cannot hold it splits around the void.
  if (isVoidElementType(node.type)) {
    return expandBlock(node, isInline, seen, nesting);
  }

  const parentTypes = allowedChildTypes(parentType) ?? [];
  if (
    parentTypes.some((type) => type === node.type) ||
    (asLabel && allowsFirstChild(parentType, node.type))
  ) {
    return expandBlock(node, isInline, seen, nesting);
  }

  if (allowedChildTypes(node.type) !== undefined) {
    const placed: TElement[] = [];
    for (const piece of containerPieces(node, isInline, seen, nesting)) {
      if (isVoidElementType(piece.type)) {
        placed.push(piece);
        continue;
      }

      for (const child of piece.children) {
        if (isElementNode(child)) {
          placed.push(...placeInParent(child, parentType, isInline, seen, nesting));
        }
      }
    }

    return placed;
  }

  const target = containerContentType(parentType);
  if (target === undefined) {
    return expandBlock(node, isInline, seen, nesting);
  }

  // The new type may allow marks. Strip first when the node being retyped does not.
  return expandBlock({ ...plainTextElement(node), type: target }, isInline, seen, nesting);
}

function plainTextElement(node: TElement): TElement {
  if (elementAllowsMarks(node.type)) {
    return node;
  }

  let changed = false;
  const children = node.children.map((child) => {
    if (!isRecord(child) || typeof child.text !== "string" || "children" in child) {
      return child;
    }

    if (Object.keys(child).length === 1) {
      return child;
    }

    changed = true;
    return { text: child.text };
  });

  return changed ? { ...node, children } : node;
}

// One container, or several pieces when a disallowed void splits it:
// quote(a), hr, quote(b). An empty piece on either side is not emitted.
function liftedChildren(
  children: readonly unknown[],
  isInline: IsInline,
  seen: Set<string>,
  nesting: Nesting,
): TElement[] {
  const pieces: TElement[] = [];
  let inlines: Descendant[] = [];

  const flush = (): void => {
    if (inlines.length === 0) {
      return;
    }

    pieces.push(paragraph(inlines));
    inlines = [];
  };

  for (const child of children) {
    const classified = classifyPasteChild(child, isInline);
    if (classified === undefined) {
      continue;
    }

    if (classified.kind === "text") {
      inlines.push(classified.node);
      continue;
    }

    if (classified.kind === "inline") {
      inlines.push(...inlineNodes(classified.node, isInline, seen));
      continue;
    }

    flush();
    pieces.push(...expandBlock(classified.node, isInline, seen, nesting));
  }

  flush();
  return pieces;
}

function containerPieces(
  node: TElement,
  isInline: IsInline,
  seen: Set<string>,
  nesting: Nesting = emptyNesting,
): TElement[] {
  const limit = maxNesting(node.type);
  const depth = (nesting.get(node.type) ?? 0) + 1;
  const nextNesting = new Map(nesting);
  if (limit !== undefined) {
    nextNesting.set(node.type, depth);
  }

  if (limit !== undefined && depth > limit) {
    return liftedChildren(node.children, isInline, seen, nextNesting);
  }

  const contentType = containerContentType(node.type);
  const contentAllowsMarks = contentType === undefined || elementAllowsMarks(contentType);
  const pieces: TElement[] = [];
  let blocks: TElement[] = [];
  let inlines: Descendant[] = [];
  let usedId = false;

  const flushInlines = (): void => {
    if (inlines.length === 0 || contentType === undefined) {
      inlines = [];
      return;
    }

    blocks.push(elementNode(contentType, inlines, undefined));
    inlines = [];
  };

  const flushContainer = (): void => {
    flushInlines();
    if (blocks.length === 0) {
      return;
    }

    const id = usedId ? undefined : takeId(node, seen);
    usedId = true;
    const props = elementNode(node.type, withFirstChild(node.type, blocks), id);
    copyAllowedAttrs(node, props);
    pieces.push(props);
    blocks = [];
  };

  for (const child of node.children) {
    const classified = classifyPasteChild(child, isInline, contentAllowsMarks);
    if (classified === undefined) {
      continue;
    }

    if (classified.kind === "text") {
      inlines.push(classified.node);
      continue;
    }

    if (classified.kind === "inline") {
      inlines.push(...inlineNodes(classified.node, isInline, seen, contentAllowsMarks));
      continue;
    }

    flushInlines();
    for (const part of placeInParent(
      classified.node,
      node.type,
      isInline,
      seen,
      nextNesting,
      blocks.length === 0,
    )) {
      if (disallowedVoid(part, node.type)) {
        flushContainer();
        pieces.push(part);
        continue;
      }

      blocks.push(part);
    }
  }

  flushContainer();

  if (pieces.length > 0) {
    return finishTable(node, pieces);
  }

  const props = elementNode(
    node.type,
    withFirstChild(node.type, [elementNode(contentType ?? "p", [{ text: "" }], undefined)]),
    takeId(node, seen),
  );
  copyAllowedAttrs(node, props);
  return finishTable(node, [props]);
}

type HtmlWidthPlan = {
  widths: (number | null)[] | undefined;
  repairs: Repair[];
};

let htmlWidthPlans: HtmlWidthPlan[] = [];
// The table override sanitizes, then PasteFallback sanitizes the same fragment.
// The first pass consumes the width plan. These repairs are merged back so the
// second pass does not replace the report with an empty list.
let pendingWidthRepairs: Repair[] = [];

function widthRepair(raw: string): Repair {
  const message = raw.endsWith("%")
    ? `A column width of ${raw} was dropped. The column stays automatic.`
    : `A column width of ${raw} was dropped. Only widths from ${TABLE_MIN_COLUMN_WIDTH}px to ${TABLE_MAX_COLUMN_WIDTH}px are kept.`;
  return { path: [], message };
}

function parsedPixelWidth(raw: string): { px: number } | { drop: string } {
  const value = raw.trim();
  const percent = /^(\d+(?:\.\d+)?)%$/.exec(value);
  if (percent) {
    return { drop: value };
  }

  const pixels = /^(\d+(?:\.\d+)?)(?:px)?$/.exec(value);
  const token = pixels?.[1];
  if (token === undefined) {
    return { drop: value.length > 0 ? value : raw };
  }

  const px = Number(token);
  if (!Number.isInteger(px) || px < TABLE_MIN_COLUMN_WIDTH || px > TABLE_MAX_COLUMN_WIDTH) {
    return { drop: value.endsWith("%") ? value : `${px}px` };
  }

  return { px };
}

function elementWidth(element: Element): string | null {
  const style = element.getAttribute("style");
  if (style !== null) {
    const match = /(?:^|;)\s*width\s*:\s*([^;]+)/i.exec(style);
    const declared = match?.[1]?.trim();
    if (declared) {
      return declared;
    }
  }

  const width = element.getAttribute("width");
  return width === null || width.trim().length === 0 ? null : width.trim();
}

function directColumns(table: Element): Element[] {
  const columns: Element[] = [];
  for (const child of table.children) {
    if (child.tagName === "COL") {
      columns.push(child);
      continue;
    }

    if (child.tagName !== "COLGROUP") {
      continue;
    }

    for (const column of child.children) {
      if (column.tagName === "COL") {
        columns.push(column);
      }
    }
  }

  return columns;
}

function widthsFromElements(elements: readonly Element[], spans: readonly number[]): HtmlWidthPlan {
  const widths: (number | null)[] = [];
  const repairs: Repair[] = [];
  let column = 0;
  for (let index = 0; index < elements.length; index += 1) {
    const element = elements[index];
    const span = spans[index] ?? 1;
    if (!element) {
      continue;
    }

    const raw = elementWidth(element);
    const parsed = raw === null ? undefined : parsedPixelWidth(raw);
    if (parsed && "px" in parsed) {
      widths[column] = parsed.px;
    } else {
      if (parsed && "drop" in parsed) {
        repairs.push(widthRepair(parsed.drop));
      }
      widths[column] = null;
    }

    for (let offset = 1; offset < span; offset += 1) {
      widths[column + offset] = null;
    }
    column += span;
  }

  const explicit = widths.some((width) => typeof width === "number");
  return { widths: explicit ? widths : undefined, repairs };
}

function positiveSpan(element: Element): number {
  const raw = element.getAttribute("colspan");
  if (raw === null || !/^[0-9]+$/.test(raw)) {
    return 1;
  }

  const parsed = Number(raw);
  return parsed > 1 ? parsed : 1;
}

// A bare `<col>` is invalid until a parser wraps it in `<colgroup>`. happy-dom
// leaves that column as the table's previous sibling, so the width would be lost.
function adoptedColumns(table: Element): Element[] {
  const gathered: Element[] = [];
  let sibling = table.previousElementSibling;
  while (sibling && (sibling.tagName === "COL" || sibling.tagName === "COLGROUP")) {
    gathered.push(sibling);
    sibling = sibling.previousElementSibling;
  }

  gathered.reverse();
  const columns: Element[] = [];
  for (const element of gathered) {
    if (element.tagName === "COL") {
      columns.push(element);
      continue;
    }

    for (const column of element.children) {
      if (column.tagName === "COL") {
        columns.push(column);
      }
    }
  }

  return columns;
}

function widthsFromHtmlTable(table: Element): HtmlWidthPlan {
  const nested = directColumns(table);
  const columns = nested.length > 0 ? nested : adoptedColumns(table);
  if (columns.length > 0) {
    return widthsFromElements(
      columns,
      columns.map(() => 1),
    );
  }

  const row = table.querySelector("tr");
  const cells =
    row === null
      ? []
      : Array.from(row.children).filter(
          (child) => child.tagName === "TD" || child.tagName === "TH",
        );
  return widthsFromElements(
    cells,
    cells.map((cell) => positiveSpan(cell)),
  );
}

export function rememberHtmlTableWidths(html: string): void {
  const document = new DOMParser().parseFromString(html, "text/html");
  pendingWidthRepairs = [];
  htmlWidthPlans = Array.from(document.querySelectorAll("table")).map((table) =>
    widthsFromHtmlTable(table),
  );
}

export function clearHtmlTableWidths(): void {
  htmlWidthPlans = [];
  pendingWidthRepairs = [];
}

function applyRememberedWidths(table: TElement, repairs: Repair[] | undefined): TElement {
  const plan = htmlWidthPlans.shift();
  if (plan === undefined) {
    return table;
  }

  pendingWidthRepairs.push(...plan.repairs);
  if (repairs !== undefined) {
    repairs.push(...plan.repairs);
  }

  if (plan.widths === undefined) {
    return table;
  }

  return { ...table, colSizes: plan.widths };
}

function finishTable(node: TElement, pieces: TElement[]): TElement[] {
  if (node.type !== "table") {
    return pieces;
  }

  return pieces.map((piece) => {
    if (piece.type !== "table") {
      return piece;
    }

    const capped = capPastedTable(piece, activePasteRepairs);
    const sized = applyRememberedWidths(capped, activePasteRepairs);
    return repairTableGrid(sized, activePasteRepairs);
  });
}

function noteMentionInputPaste(): void {
  const repair: Repair = {
    path: [],
    message: "A mention input was turned into plain text.",
  };
  activePasteRepairs?.push(repair);
  pendingMentionInputRepairs.push(repair);
}

// A valid inline equation keeps its source and gets a fresh id. An invalid one
// becomes its source as plain text, with control characters removed.
function pastedInlineEquationNodes(node: TElement, allowMarks: boolean): Descendant[] {
  const tex = typeof node.texExpression === "string" ? node.texExpression : "";
  if (allowMarks && isStoredEquationExpression(tex)) {
    return [inlineEquationNode(tex)];
  }

  const text = Array.from(tex)
    .filter((char) => {
      const code = char.codePointAt(0) ?? 0;
      return char === "\t" || char === "\n" || (code > 0x1f && code !== 0x7f);
    })
    .join("");
  return text.length > 0 ? [{ text }] : [];
}

// A valid inline date keeps its date with a fresh id where inline marks are allowed. Elsewhere
// (a code line) it becomes the formatted label. An invalid one becomes its raw value as text.
function pastedInlineDateNodes(node: TElement, allowMarks: boolean): Descendant[] {
  const stored = node.date;
  if (isStoredDate(stored)) {
    return allowMarks ? [inlineDateNode(stored)] : [{ text: formatStoredDate(stored) }];
  }

  const raw = typeof stored === "string" ? stored : "";
  const text = Array.from(raw)
    .filter((char) => {
      const code = char.codePointAt(0) ?? 0;
      return char === "\t" || char === "\n" || (code > 0x1f && code !== 0x7f);
    })
    .join("");
  return text.length > 0 ? [{ text }] : [];
}

// A reference keeps its id and gets a fresh node id. Only inline marks can hold one, so a code line
// drops it. Pasted HTML never reaches this path, so a foreign <sup> stays plain text.
function pastedFootnoteRefNodes(node: TElement, allowMarks: boolean): Descendant[] {
  const stored = node.footnoteId;
  if (!allowMarks || !isFootnoteId(stored)) {
    return [];
  }

  return [footnoteReferenceNode(stored)];
}

function pastedMentionNodes(node: TElement, seen: Set<string>): Descendant[] {
  if (!isRecord(node) || !isStoredMention(node)) {
    const label = typeof node.label === "string" ? sanitizeMentionLabel(node.label) : undefined;
    return label === undefined ? [] : [{ text: label }];
  }

  const mention = elementNode(KEYS.mention, [{ text: "" }], allocateMentionId(seen));
  mention.entityType = MENTION_ENTITY_TYPE;
  mention.entityId = node.entityId;
  mention.label = node.label;
  return [mention];
}

function expandBlock(
  node: TElement,
  isInline: IsInline,
  seen: Set<string>,
  nesting: Nesting = emptyNesting,
): TElement[] {
  if (isDroppedMediaType(node.type)) {
    noteDroppedMedia();
    const label = droppedMediaLabel(node);
    return label === undefined ? [] : [paragraph([{ text: label }])];
  }

  // An inline type with its feature off is read as plain text, the way an unknown inline is.
  if (pasteTypeOff(node.type) && isInlinePasteType(node.type)) {
    const nodes = inlineNodes(node, isInline, seen, false);
    return [paragraph(nodes.length > 0 ? nodes : [{ text: "" }])];
  }

  // A block with its feature off is kept as paragraphs of its content, not as its own type.
  // A block equation keeps its TeX source. A page link keeps its title. A toc or footnote
  // definition with no readable text is dropped, so no empty paragraph is left behind.
  if (pasteTypeOff(node.type)) {
    if (node.type === KEYS.equation) {
      return readableParagraphs([paragraph(pastedInlineEquationNodes(node, false))]);
    }

    if (node.type === PAGE_LINK_KEY) {
      const title = typeof node.title === "string" ? stripControlCharacters(node.title).trim() : "";
      return readableParagraphs([paragraph([{ text: title }])]);
    }

    const flattened = expandBlock({ ...node, type: KEYS.p }, isInline, seen, nesting);
    return node.type === KEYS.toc || node.type === FOOTNOTE_DEF_KEY
      ? readableParagraphs(flattened)
      : flattened;
  }

  if (node.type === KEYS.mentionInput) {
    noteMentionInputPaste();
    const text = isRecord(node) ? mentionInputPlainText(node) : "@";
    return [paragraph([{ text }])];
  }

  if (node.type === KEYS.mention) {
    const nodes = pastedMentionNodes(node, seen);
    return [paragraph(nodes.length > 0 ? nodes : [{ text: "" }])];
  }

  if (node.type === KEYS.inlineEquation) {
    const nodes = pastedInlineEquationNodes(node, true);
    return [paragraph(nodes.length > 0 ? nodes : [{ text: "" }])];
  }

  if (node.type === KEYS.date) {
    const nodes = pastedInlineDateNodes(node, true);
    return [paragraph(nodes.length > 0 ? nodes : [{ text: "" }])];
  }

  if (node.type === FOOTNOTE_REF_KEY) {
    const nodes = pastedFootnoteRefNodes(node, true);
    return [paragraph(nodes.length > 0 ? nodes : [{ text: "" }])];
  }

  if (isVoidElementType(node.type) && allowedElementAttrs(node.type) !== undefined) {
    if (node.type === BOOKMARK_KEY) {
      return pastedBookmark(node, seen);
    }

    if (node.type === IMAGE_KEY) {
      return pastedImage(node, seen);
    }

    if (node.type === FILE_KEY) {
      return pastedFile(node, seen);
    }

    if (node.type === VIDEO_KEY) {
      return pastedVideo(node, seen);
    }

    if (node.type === AUDIO_KEY) {
      return pastedAudio(node, seen);
    }

    if (node.type === EMBED_KEY) {
      return pastedEmbed(node, seen);
    }

    if (node.type === PAGE_LINK_KEY) {
      return pastedPageLink(node, seen);
    }

    if (node.type === KEYS.toc) {
      const toc = elementNode(KEYS.toc, [{ text: "" }], takeId(node, seen));
      copyAllowedAttrs(node, toc);
      return [toc];
    }

    if (node.type === KEYS.equation) {
      const equation = elementNode(KEYS.equation, [{ text: "" }], takeId(node, seen));
      equation.texExpression = isStoredEquationExpression(node.texExpression)
        ? node.texExpression
        : "";
      return [equation];
    }

    if (node.type === SYNCED_REF_KEY) {
      const synced = elementNode(SYNCED_REF_KEY, [{ text: "" }], takeId(node, seen));
      if (isStoredSyncedTargetId(node.targetBlockId)) {
        synced.targetBlockId = node.targetBlockId;
      }
      return [synced];
    }

    return [elementNode(node.type, [{ text: "" }], takeId(node, seen))];
  }

  if (allowedChildTypes(node.type) !== undefined) {
    return containerPieces(node, isInline, seen, nesting);
  }

  const allowed = allowedElementAttrs(node.type) !== undefined;
  const allowMarks = elementAllowsMarks(node.type);
  const paragraphs: TElement[] = [];
  let inlines: Descendant[] = [];
  let usedOwnId = false;
  let sawDroppedMedia = false;

  const flush = (): void => {
    if (inlines.length === 0) {
      return;
    }

    if (allowed) {
      const id = usedOwnId ? undefined : takeId(node, seen);
      usedOwnId = true;
      const props = elementNode(node.type, inlines, id);
      copyAllowedAttrs(node, props);
      paragraphs.push(props);
    } else {
      paragraphs.push(paragraph(inlines));
    }

    inlines = [];
  };

  for (const child of node.children) {
    if (isRecord(child) && typeof child.type === "string" && isDroppedMediaType(child.type)) {
      noteDroppedMedia();
      sawDroppedMedia = true;
      const label = droppedMediaLabel(child);
      if (label !== undefined) {
        inlines.push({ text: label });
      }
      continue;
    }

    const classified = classifyPasteChild(child, isInline, allowMarks);
    if (classified === undefined) {
      continue;
    }

    if (classified.kind === "text") {
      inlines.push(classified.node);
      continue;
    }

    if (classified.kind === "inline") {
      inlines.push(...inlineNodes(classified.node, isInline, seen, allowMarks));
      continue;
    }

    flush();
    paragraphs.push(...expandBlock(classified.node, isInline, seen, nesting));
  }

  if (sawDroppedMedia && paragraphs.length === 0 && !hasContent(inlines)) {
    return [];
  }

  flush();

  if (paragraphs.length > 0) {
    return paragraphs;
  }

  if (allowed) {
    const props = elementNode(node.type, [{ text: "" }], takeId(node, seen));
    copyAllowedAttrs(node, props);
    return [props];
  }

  return [paragraph([])];
}

function inlineNodes(
  node: TElement,
  isInline: IsInline,
  seen: Set<string>,
  allowMarks = true,
): Descendant[] {
  if (isDroppedMediaType(node.type)) {
    noteDroppedMedia();
    const label = droppedMediaLabel(node);
    return label === undefined ? [] : [{ text: label }];
  }

  if (node.type === KEYS.mentionInput) {
    noteMentionInputPaste();
    const text = isRecord(node) ? mentionInputPlainText(node) : "@";
    return text.length > 0 ? [{ text }] : [];
  }

  const gated = pasteTypeOff(node.type);
  if (node.type === KEYS.mention) {
    if (!allowMarks || gated) {
      const label = typeof node.label === "string" ? sanitizeMentionLabel(node.label) : undefined;
      return label === undefined ? [] : [{ text: label }];
    }

    return pastedMentionNodes(node, seen);
  }

  if (node.type === KEYS.inlineEquation) {
    return pastedInlineEquationNodes(node, allowMarks && !gated);
  }

  if (node.type === KEYS.date) {
    return pastedInlineDateNodes(node, allowMarks && !gated);
  }

  if (node.type === FOOTNOTE_REF_KEY) {
    return pastedFootnoteRefNodes(node, allowMarks && !gated);
  }

  if (node.type === KEYS.link) {
    const url = typeof node.url === "string" ? node.url : "";
    const safe = sanitizeLinkUrl(url);
    if (!allowMarks || safe === undefined) {
      if (safe === undefined && url.length > 0) {
        noteUnsafePastedLink();
      }

      return unwrapInline(node.children, isInline, seen, allowMarks);
    }
  }

  if (allowedElementAttrs(node.type) === undefined) {
    return unwrapInline(node.children, isInline, seen, allowMarks);
  }

  const children: Descendant[] = [];
  for (const child of node.children) {
    const classified = classifyPasteChild(child, isInline, allowMarks);
    if (classified === undefined || classified.kind === "block") {
      continue;
    }

    if (classified.kind === "text") {
      children.push(classified.node);
      continue;
    }

    children.push(...inlineNodes(classified.node, isInline, seen, allowMarks));
  }

  const props = elementNode(
    node.type,
    children.length > 0 ? children : [{ text: "" }],
    takeId(node, seen),
  );
  copyAllowedAttrs(node, props);
  return [props];
}

function unwrapInline(
  children: unknown[],
  isInline: IsInline,
  seen: Set<string>,
  allowMarks = true,
): Descendant[] {
  const nodes: Descendant[] = [];
  for (const child of children) {
    const classified = classifyPasteChild(child, isInline, allowMarks);
    if (classified === undefined || classified.kind === "block") {
      continue;
    }

    if (classified.kind === "text") {
      nodes.push(classified.node);
      continue;
    }

    nodes.push(...inlineNodes(classified.node, isInline, seen, allowMarks));
  }

  return nodes;
}

export function sanitizePastedFragment(
  fragment: readonly unknown[],
  options?: PasteSanitizeOptions,
): EditorValue {
  const seen = options?.seenIds ?? new Set<string>();
  const isInline = options?.isInline ?? (() => false);
  const previousRepairs = activePasteRepairs;
  activePasteRepairs = options?.repairs;
  const previousFeatureOff = activeFeatureOff;
  activeFeatureOff = options?.featureOff;
  const paragraphs: EditorValue = [];
  let inlines: Descendant[] = [];

  const flush = (): void => {
    if (!hasContent(inlines)) {
      inlines = [];
      return;
    }

    paragraphs.push(paragraph(inlines));
    inlines = [];
  };

  for (const node of fragment) {
    const classified = classifyPasteChild(node, isInline);
    if (classified === undefined) {
      continue;
    }

    if (classified.kind === "text") {
      inlines.push(classified.node);
      continue;
    }

    if (classified.kind === "inline") {
      inlines.push(...inlineNodes(classified.node, isInline, seen));
      continue;
    }

    flush();
    paragraphs.push(...expandBlock(classified.node, isInline, seen));
  }

  flush();

  activePasteRepairs = previousRepairs;
  activeFeatureOff = previousFeatureOff;
  htmlWidthPlans = [];
  return paragraphs;
}

function collectEditorIds(value: readonly unknown[]): Set<string> {
  const seen = new Set<string>();
  for (const node of value) {
    collectIds(node, seen);
  }

  return seen;
}

export function preparePastedFragment(
  editor: SlateEditor,
  fragment: readonly unknown[],
): EditorValue {
  const repairs: Repair[] = [];
  const sanitized = sanitizePastedFragment(fragment, {
    isInline: (node) => isElementNode(node) && editor.api.isInline(node),
    seenIds: collectEditorIds(editor.children),
    repairs,
    featureOff: (type) => {
      const feature = nodeFeature(type);
      return feature !== undefined && !featureEnabled(editor, feature);
    },
  });
  // A pasted definition keeps its id only when the document has no definition with it.
  const footnotes = repairFootnoteContent(sanitized, footnoteIndex(editor).definitions);
  const value = footnotes.content;
  repairs.push(...footnotes.repairs);
  for (const repair of pendingWidthRepairs) {
    if (!repairs.some((item) => item.message === repair.message)) {
      repairs.push(repair);
    }
  }
  for (const repair of pendingImageRepairs) {
    if (!repairs.some((item) => item.message === repair.message)) {
      repairs.push(repair);
    }
  }
  for (const repair of pendingMentionInputRepairs) {
    if (!repairs.some((item) => item.message === repair.message)) {
      repairs.push(repair);
    }
  }
  for (const repair of unsafePastedLinkRepairs()) {
    if (!repairs.some((item) => item.message === repair.message)) {
      repairs.push(repair);
    }
  }
  const limited = limitPastedValue(value, repairs);
  for (const repair of pendingLimitRepairs) {
    if (!repairs.some((item) => item.message === repair.message)) {
      repairs.push(repair);
    }
  }
  setPasteRepairs(editor, repairs);
  return limited;
}

function fitPasteForCell(editor: SlateEditor, value: EditorValue): EditorValue {
  const cell = editor.api.above({
    match: (node) => ElementApi.isElement(node) && (node.type === KEYS.td || node.type === KEYS.th),
  });
  if (cell === undefined) {
    return value;
  }

  return value.map((node) => {
    if (node.type === KEYS.p) {
      // Cells own their colour, so a pasted paragraph keeps no block tone.
      const copy = structuredClone(node);
      Reflect.deleteProperty(copy, "textTone");
      Reflect.deleteProperty(copy, "backgroundTone");
      return copy;
    }

    return { type: KEYS.p, children: [{ text: nodeText(node) }] };
  });
}

function nodeText(node: TElement): string {
  let text = "";
  const visit = (child: Descendant): void => {
    if (TextApi.isText(child)) {
      text += child.text;
      return;
    }

    if (ElementApi.isElement(child)) {
      child.children.forEach(visit);
    }
  };

  node.children.forEach(visit);
  return text;
}

function isInlinePasteType(type: string): boolean {
  return (
    type === KEYS.link ||
    type === KEYS.mention ||
    type === KEYS.inlineEquation ||
    type === KEYS.date ||
    type === FOOTNOTE_REF_KEY ||
    type === "a"
  );
}

function countPasteBlocks(nodes: readonly unknown[]): number {
  let count = 0;
  for (const node of nodes) {
    if (isRecord(node) && isElementNode(node) && !isInlinePasteType(node.type)) {
      count += 1;
    }
  }

  return count;
}

function countPasteText(nodes: readonly unknown[]): number {
  let count = 0;
  const visit = (node: unknown): void => {
    if (!isRecord(node)) {
      return;
    }

    if (isTextNode(node) && typeof node.text === "string") {
      count += node.text.length;
      return;
    }

    if (!Array.isArray(node.children)) {
      return;
    }

    for (const child of node.children) {
      visit(child);
    }
  };

  for (const node of nodes) {
    visit(node);
  }

  return count;
}

function takeBlocks(nodes: EditorValue, budget: { left: number }): EditorValue {
  const kept: EditorValue = [];
  for (const node of nodes) {
    if (!isElementNode(node) || isInlinePasteType(node.type)) {
      kept.push(node);
      continue;
    }

    if (budget.left <= 0) {
      break;
    }

    budget.left -= 1;
    kept.push(node);
  }

  return kept;
}

function takeText(nodes: Descendant[], budget: { left: number }): Descendant[] {
  const kept: Descendant[] = [];
  for (const node of nodes) {
    if (budget.left <= 0) {
      break;
    }

    if (TextApi.isText(node)) {
      const text = node.text.slice(0, budget.left);
      budget.left -= text.length;
      kept.push({ ...node, text });
      continue;
    }

    if (!ElementApi.isElement(node)) {
      continue;
    }

    kept.push({ ...node, children: takeText(node.children, budget) });
  }

  return kept;
}

function limitPastedValue(value: EditorValue, _repairs: Repair[]): EditorValue {
  let next = value;
  if (countPasteBlocks(next) > PASTE_BLOCK_LIMIT) {
    next = takeBlocks(next, { left: PASTE_BLOCK_LIMIT });
    rememberLimitRepair({ path: [], message: pasteTooLargeMessage("blocks") });
  }

  if (countPasteText(next) > PASTE_TEXT_CHAR_LIMIT) {
    next = takeText(next, { left: PASTE_TEXT_CHAR_LIMIT }) as EditorValue;
    rememberLimitRepair({ path: [], message: pasteTooLargeMessage("characters") });
  }

  return next;
}

// A void block (divider, bookmark) or a node that holds blocks (container, table).
function isStructuralNode(editor: SlateEditor, node: TElement): boolean {
  if (editor.api.isInline(node)) {
    return false;
  }

  return (
    editor.api.isVoid(node) ||
    node.children.some((child) => ElementApi.isElement(child) && !editor.api.isInline(child))
  );
}

// True when the fragment starts or ends with a structural block. Other fragments insert as before.
function hasStructuralEdge(editor: SlateEditor, fragment: EditorValue): boolean {
  const first = fragment[0];
  const last = fragment[fragment.length - 1];
  return (
    (first !== undefined && isStructuralNode(editor, first)) ||
    (last !== undefined && isStructuralNode(editor, last))
  );
}

// Inserts a collapsed caret's fragment as whole blocks when the caret is in a non-empty text block.
// Slate would merge the fragment's first text block into that block and drop a container around it.
// Returns false when the normal insert should run instead.
function insertBlocksAtCaret(editor: SlateEditor, fragment: EditorValue): boolean {
  const first = fragment[0];
  const last = fragment[fragment.length - 1];
  if (first === undefined || last === undefined || !editor.selection) {
    return false;
  }

  const firstStructural = isStructuralNode(editor, first);
  if (!firstStructural && !isStructuralNode(editor, last)) {
    return false;
  }

  const block = editor.api.block();
  if (
    block === undefined ||
    editor.api.isVoid(block[0]) ||
    selectionInCodeBlock(editor) ||
    editor.api.isEmpty(editor.selection, { block: true })
  ) {
    return false;
  }

  const atStart = editor.api.isAt({ start: true });
  const atEnd = editor.api.isAt({ end: true });
  if (!firstStructural && atEnd) {
    return false;
  }

  const blockPath = block[1];
  const after = PathApi.next(blockPath);
  if (after === undefined) {
    return false;
  }

  editor.tf.withoutNormalizing(() => {
    if (!atStart && !atEnd) {
      // The second half gets a new id when the document normalizes.
      editor.tf.splitNodes({ always: true });
    }
    editor.tf.insertNodes(fragment, { at: atStart ? blockPath : after, select: true });
  });
  return true;
}

export const PasteFallbackPlugin = createSlatePlugin({
  key: "pasteFallback",
  priority: PASTE_FALLBACK_PRIORITY,
  parsers: {
    html: {
      deserializer: {
        isElement: true,
        rules: [{ validNodeName: "*" }],
        parse: () => ({ type: "p" }),
        query: ({ element }) => isHtmlBlockElement(element),
      },
    },
  },
}).overrideEditor(({ editor, tf: { insertFragment } }) => ({
  transforms: {
    insertFragment(fragment, options) {
      // TablePlugin inserts a one-table fragment before this fallback, so the
      // table override sanitizes that path too. This still covers every other fragment.
      // Repairs are remembered across the table override's second sanitize.
      try {
        const prepared = fitPasteForCell(editor, preparePastedFragment(editor, fragment));
        // An explicit `at` names its own location, so the caret-based path does not apply.
        if (options?.at !== undefined || !hasStructuralEdge(editor, prepared)) {
          insertFragment(prepared, options);
        } else {
          // The delete of an expanded selection and the insert undo as one step.
          editor.tf.withNewBatch(() => {
            if (editor.selection && !editor.api.isCollapsed()) {
              editor.tf.deleteFragment();
            }
            if (!insertBlocksAtCaret(editor, prepared)) {
              insertFragment(prepared, options);
            }
          });
        }
      } finally {
        clearPendingImageRepairs();
        clearPendingMentionInputRepairs();
        clearPendingLimitRepairs();
        clearUnsafePastedLinkRepairs();
      }
    },
  },
}));

function transferFileCount(data: DataTransfer): number {
  const files = Reflect.get(data, "files");
  if (typeof files !== "object" || files === null) {
    return 0;
  }

  const length = Reflect.get(files, "length");
  return typeof length === "number" && Number.isFinite(length) ? length : 0;
}

type MediaDropEvent = {
  preventDefault: () => void;
  dataTransfer: DataTransfer | null;
};

export function rejectDroppedFiles(editor: SlateEditor, event: MediaDropEvent): boolean {
  const data = event.dataTransfer;
  if (data === null || transferFileCount(data) === 0) {
    return false;
  }

  event.preventDefault();
  setPasteRepairs(editor, [{ path: [], message: MEDIA_NOT_SUPPORTED }]);
  return true;
}

// The Slate fragment type. A clipboard or drop with one keeps the fragment path, and its files are not used.
const SLATE_FRAGMENT_TYPE = "application/x-slate-fragment";

function isFileValue(value: unknown): value is File {
  return value instanceof File;
}

// Files become media blocks when an upload adapter is set: an image file an image block, and every
// other file a file block. Each block is placed after the current block, as one undo step, and its
// upload starts. Returns false when no block was inserted, so the caller keeps the existing notice.
function insertTransferFiles(editor: SlateEditor, data: DataTransfer): boolean {
  const controller = uploadControllerOf(editor);
  if (controller === null) {
    return false;
  }

  const listed: unknown[] = Array.from(data.files);
  const files = listed.filter(isFileValue);
  if (files.length === 0) {
    return false;
  }

  const notices: string[] = [];
  if (files.length > MEDIA_FILE_LIMIT) {
    notices.push(MEDIA_FILE_LIMIT_MESSAGE);
  }

  if (!editor.selection) {
    const end = editor.api.end([]);
    if (end === undefined) {
      return false;
    }
    editor.tf.select(end);
  }

  const inserted = insertMediaFiles(editor, controller, files.slice(0, MEDIA_FILE_LIMIT));
  if (!inserted) {
    return false;
  }

  setPasteRepairs(
    editor,
    notices.map((message) => ({ path: [], message })),
  );
  return true;
}

// The caret goes to the drop point, as slate-react does before insertData. slate-react throws when the
// point cannot be resolved, so a throw here keeps the current selection instead.
function selectDropPoint(editor: SlateEditor, event: MediaDropEvent): void {
  try {
    const range = editor.api.findEventRange(event);
    if (range !== undefined) {
      editor.tf.select(range);
    }
  } catch {
    // No point could be resolved. The current selection is used.
  }
}

// Registered after the paste-url plugin so a file list is rejected before a
// link, a table, or a code block reads the same clipboard.
// toPlatePlugin, not createSlatePlugin: a Slate plugin's handlers have no onDrop.
export const unsupportedMediaPlugin = toPlatePlugin(
  createSlatePlugin({
    key: "unsupportedMedia",
    parsers: {
      html: {
        deserializer: {
          isElement: true,
          rules: [
            { validNodeName: "IMG" },
            { validNodeName: "VIDEO" },
            { validNodeName: "AUDIO" },
            { validNodeName: "IFRAME" },
          ],
          parse: ({ element }) => {
            // Carry the readable text so the sanitizer can keep it and report the drop.
            const alt = element.getAttribute("alt") ?? element.getAttribute("title") ?? "";
            const label = alt.trim();
            const node: Record<string, unknown> = {
              type: "unsupported_media",
              children: [{ text: "" }],
            };
            if (label.length > 0) {
              node.alt = label;
            }

            return node;
          },
        },
      },
    },
  }).overrideEditor(({ editor, tf: { insertData } }) => ({
    transforms: {
      insertData(data: DataTransfer) {
        if (transferFileCount(data) === 0) {
          insertData(data);
          return;
        }

        if (uploadControllerOf(editor) !== null && data.getData(SLATE_FRAGMENT_TYPE) !== "") {
          insertData(data);
          return;
        }

        if (insertTransferFiles(editor, data)) {
          return;
        }

        setPasteRepairs(editor, [{ path: [], message: MEDIA_NOT_SUPPORTED }]);
      },
    },
  })),
  {
    handlers: {
      // A file drop is claimed here, so slate-react's own drop code does not run for it.
      onDrop: ({ editor, event }: { editor: SlateEditor; event: MediaDropEvent }) => {
        const data = event.dataTransfer;
        if (data === null || transferFileCount(data) === 0) {
          return undefined;
        }

        if (uploadControllerOf(editor) === null) {
          return rejectDroppedFiles(editor, event);
        }

        if (data.getData(SLATE_FRAGMENT_TYPE) !== "") {
          return undefined;
        }

        event.preventDefault();
        selectDropPoint(editor, event);
        if (!insertTransferFiles(editor, data)) {
          setPasteRepairs(editor, [{ path: [], message: MEDIA_NOT_SUPPORTED }]);
        }
        return true;
      },
    },
  },
);

import {
  ElementApi,
  PathApi,
  RangeApi,
  createSlatePlugin,
  type SlateEditor,
  type TElement,
} from "platejs";
import { toPlatePlugin } from "platejs/react";

import { runEditorCommand, type EditorCommand } from "../commands/editor-commands";
import { moveBlockAt } from "../features/editor-block-drop";
import { targetBlockAtPath } from "../features/editor-block-handle";
import { cloneWithFreshIds, collectIds, deleteBlockAt } from "../features/editor-block-menu";
import {
  adjacentBlockId,
  blockRun,
  caretLanding,
  normalizeBlockIds,
  runMoveTarget,
  selectionCoversBlock,
  topLevelBlockIds,
  type BlockRun,
} from "../features/editor-block-selection";
import { findBlockById } from "../features/editor-synced-block";
import { slashMenuOpen } from "./editor-slash";

const BLOCK_SELECTION_PRIORITY = 3000;
const BLOCK_SELECTION_ENTER_PRIORITY = 50;

type SelectionOptions = {
  ids: string[];
  anchorId: string;
  focusId: string;
  caretPath: number[] | null;
  caretOffset: number;
};

type KeyEvent = {
  key: string;
  code?: string;
  metaKey: boolean;
  ctrlKey: boolean;
  altKey: boolean;
  shiftKey: boolean;
  defaultPrevented?: boolean;
  preventDefault: () => void;
};

const EMPTY: SelectionOptions = {
  ids: [],
  anchorId: "",
  focusId: "",
  caretPath: null,
  caretOffset: 0,
};

function selectionOptions(): SelectionOptions {
  return { ...EMPTY, ids: [] };
}

function modKey(event: { metaKey: boolean; ctrlKey: boolean }): boolean {
  return event.metaKey !== event.ctrlKey;
}

function read(editor: SlateEditor): SelectionOptions {
  return {
    ids: [...editor.getOption(blockSelectionPlugin, "ids")],
    anchorId: editor.getOption(blockSelectionPlugin, "anchorId"),
    focusId: editor.getOption(blockSelectionPlugin, "focusId"),
    caretPath: editor.getOption(blockSelectionPlugin, "caretPath"),
    caretOffset: editor.getOption(blockSelectionPlugin, "caretOffset"),
  };
}

function write(editor: SlateEditor, next: SelectionOptions): void {
  editor.setOption(blockSelectionPlugin, "ids", [...next.ids]);
  editor.setOption(blockSelectionPlugin, "anchorId", next.anchorId);
  editor.setOption(blockSelectionPlugin, "focusId", next.focusId);
  editor.setOption(blockSelectionPlugin, "caretPath", next.caretPath);
  editor.setOption(blockSelectionPlugin, "caretOffset", next.caretOffset);
}

export function blockSelectionIds(editor: SlateEditor): readonly string[] {
  return editor.getOption(blockSelectionPlugin, "ids");
}

export function blockSelectionActive(editor: SlateEditor): boolean {
  return blockSelectionIds(editor).length > 0;
}

function rememberCaret(editor: SlateEditor, state: SelectionOptions): SelectionOptions {
  const selection = editor.selection;
  if (!selection || !RangeApi.isCollapsed(selection) || state.ids.length > 0) {
    return state;
  }
  return {
    ...state,
    caretPath: [...selection.anchor.path],
    caretOffset: selection.anchor.offset,
  };
}

function hideCaret(editor: SlateEditor): void {
  editor.tf.withoutSaving(() => {
    editor.tf.deselect();
  });
  const editable = editor.api.toDOMNode(editor.children[0] ?? { text: "" });
  const root = editable?.closest("[data-slate-editor]");
  if (root instanceof HTMLElement) {
    root.focus({ preventScroll: true });
  }
  window.getSelection()?.removeAllRanges();
}

function scrollBlockIntoView(editor: SlateEditor, id: string): void {
  const entry = findBlockById(editor, id);
  if (!entry) {
    return;
  }
  const dom: unknown = editor.api.toDOMNode(entry[0]);
  if (dom instanceof HTMLElement) {
    dom.scrollIntoView({ block: "nearest" });
  }
}

export function setBlockSelection(
  editor: SlateEditor,
  ids: readonly string[],
  edge?: { anchorId?: string; focusId?: string; scroll?: boolean },
): string[] {
  if (editor.dom.readOnly === true) {
    return [];
  }
  const normalized = normalizeBlockIds(editor, ids);
  const current = read(editor);
  const remembered = rememberCaret(editor, current);
  if (normalized.length === 0) {
    write(editor, { ...EMPTY, ids: [] });
    return [];
  }
  const anchorId =
    edge?.anchorId && normalized.includes(edge.anchorId) ? edge.anchorId : (normalized[0] ?? "");
  const focusId =
    edge?.focusId && normalized.includes(edge.focusId)
      ? edge.focusId
      : (normalized[normalized.length - 1] ?? anchorId);
  write(editor, { ...remembered, ids: normalized, anchorId, focusId });
  hideCaret(editor);
  const focus = normalized.includes(focusId) ? focusId : normalized[normalized.length - 1];
  if (edge?.scroll && focus) {
    scrollBlockIntoView(editor, focus);
  }
  return normalized;
}

// A click updates the DOM selection before Slate's onSelect copies it onto
// editor.selection. Read the DOM when the editor has no selection yet.
export function readLiveSelection(editor: SlateEditor): SlateEditor["selection"] {
  if (editor.selection) {
    return editor.selection;
  }
  if (typeof window === "undefined" || typeof window.getSelection !== "function") {
    return null;
  }
  const dom = window.getSelection();
  if (!dom || dom.rangeCount === 0 || !dom.anchorNode) {
    return null;
  }
  const anchor = dom.anchorNode instanceof Element ? dom.anchorNode : dom.anchorNode.parentElement;
  if (!anchor?.closest("[data-slate-editor]")) {
    return null;
  }
  const converter = Reflect.get(editor.api, "toSlateRange") as
    ((domRange: Range) => SlateEditor["selection"]) | undefined;
  if (typeof converter !== "function") {
    return null;
  }
  try {
    const range = converter(dom.getRangeAt(0));
    if (!range) {
      return null;
    }
    editor.tf.withoutSaving(() => {
      editor.tf.select(range);
    });
    return editor.selection ?? range;
  } catch {
    return null;
  }
}

export function clearBlockSelection(editor: SlateEditor, restoreCaret: boolean): void {
  const state = read(editor);
  write(editor, { ...EMPTY, ids: [] });
  if (!restoreCaret || state.ids.length === 0) {
    return;
  }
  const saved = state.caretPath;
  const savedNode = saved ? editor.api.node(saved) : undefined;
  if (saved && savedNode) {
    editor.tf.withoutSaving(() => {
      editor.tf.select({ path: [...saved], offset: state.caretOffset });
    });
    return;
  }
  const first = state.ids[0];
  const entry = first ? findBlockById(editor, first) : undefined;
  const start = entry ? editor.api.start(entry[1]) : undefined;
  if (start) {
    editor.tf.withoutSaving(() => {
      editor.tf.select(start);
    });
  }
}

function runOf(editor: SlateEditor): BlockRun | null {
  return blockRun(editor, blockSelectionIds(editor));
}

function placePoint(editor: SlateEditor, path: number[], edge: "start" | "end"): void {
  const point = edge === "end" ? editor.api.end(path) : editor.api.start(path);
  if (point) {
    editor.tf.select(point);
  }
}

export const deleteBlocks: EditorCommand<{ parent: number[]; start: number; end: number }> = {
  id: "block.selection.delete",
  label: "Delete blocks",
  group: "action",
  run: (editor, payload) => {
    const siblings =
      payload.parent.length === 0
        ? editor.children
        : (() => {
            const parent = editor.api.node(payload.parent);
            const node = parent?.[0];
            return parent && ElementApi.isElement(node) ? node.children : [];
          })();
    const landing = caretLanding(
      siblings.length,
      payload.start,
      payload.end,
      payload.parent.length === 0,
    );
    clearBlockSelection(editor, false);
    for (let index = payload.end - 1; index >= payload.start; index -= 1) {
      if (index === payload.start) {
        deleteBlockAt(editor, [...payload.parent, payload.start]);
      } else {
        editor.tf.removeNodes({ at: [...payload.parent, index] });
      }
    }
    if (landing === "previous-end") {
      placePoint(editor, [...payload.parent, payload.start - 1], "end");
    }
  },
};

export const duplicateBlocks: EditorCommand<{ parent: number[]; start: number; end: number }> = {
  id: "block.selection.duplicate",
  label: "Duplicate blocks",
  group: "action",
  run: (editor, payload) => {
    const seen = collectIds(editor);
    const copies: TElement[] = [];
    for (let index = payload.start; index < payload.end; index += 1) {
      const entry = editor.api.node([...payload.parent, index]);
      const node = entry?.[0];
      if (!entry || !ElementApi.isElement(node)) {
        return;
      }
      copies.push(cloneWithFreshIds(node, seen));
    }
    let at = [...payload.parent, payload.end];
    for (const copy of copies) {
      editor.tf.insertNodes(copy, { at, select: false });
      const next = PathApi.next(at);
      if (!next) {
        return;
      }
      at = next;
    }
    const ids = copies.map((node) => {
      const id: unknown = Reflect.get(node, "id");
      return typeof id === "string" ? id : "";
    });
    setBlockSelection(editor, ids);
  },
};

export const moveBlocks: EditorCommand<{
  from: number[];
  to: number[];
  span: readonly [number, number];
}> = {
  id: "block.selection.move",
  label: "Move blocks",
  group: "action",
  run: (editor, payload) => {
    const ids = [...blockSelectionIds(editor)];
    moveBlockAt(editor, payload.from, payload.to, payload.span);
    if (ids.length > 0) {
      setBlockSelection(editor, ids);
    }
  },
};

export function moveSelectedBlocks(editor: SlateEditor, direction: "up" | "down"): boolean {
  const run = runOf(editor);
  if (!run) {
    return false;
  }
  const step = runMoveTarget(editor, run, direction);
  if (!step.ok) {
    return false;
  }
  return runEditorCommand(editor, moveBlocks, {
    from: [...run.parent, run.start],
    to: step.to,
    span: [run.start, run.end],
  });
}

export function deleteSelectedBlocks(editor: SlateEditor): boolean {
  const run = runOf(editor);
  if (!run) {
    return false;
  }
  return runEditorCommand(editor, deleteBlocks, {
    parent: [...run.parent],
    start: run.start,
    end: run.end,
  });
}

export function duplicateSelectedBlocks(editor: SlateEditor): boolean {
  const run = runOf(editor);
  if (!run) {
    return false;
  }
  return runEditorCommand(editor, duplicateBlocks, {
    parent: [...run.parent],
    start: run.start,
    end: run.end,
  });
}

function fragmentRange(editor: SlateEditor, run: BlockRun): void {
  const start = editor.api.start([...run.parent, run.start]);
  const end = editor.api.end([...run.parent, run.end - 1]);
  if (!start || !end) {
    return;
  }
  editor.tf.withoutSaving(() => {
    editor.tf.select({ anchor: start, focus: end });
  });
}

export function writeBlockFragment(editor: SlateEditor, data: DataTransfer): boolean {
  const run = runOf(editor);
  if (!run) {
    return false;
  }
  const previous = editor.selection;
  suspendPrune += 1;
  try {
    fragmentRange(editor, run);
    const fragment = editor.api.getFragment();
    const encoded = window.btoa(encodeURIComponent(JSON.stringify(fragment)));
    const rendered = editor.api.toDOMNode(editor.children[0] ?? { text: "" });
    const writer = Reflect.get(editor, "setFragmentData");
    if (rendered && typeof writer === "function") {
      try {
        writer.call(editor, data);
      } catch {
        data.setData("application/x-slate-fragment", encoded);
      }
    }
    if (data.getData("application/x-slate-fragment").length === 0) {
      data.setData("application/x-slate-fragment", encoded);
    }
    editor.tf.withoutSaving(() => {
      if (previous) {
        editor.tf.select(previous);
      } else {
        editor.tf.deselect();
      }
    });
  } finally {
    suspendPrune -= 1;
  }
  return true;
}

function cutSelectedBlocks(editor: SlateEditor, data: DataTransfer): boolean {
  if (!writeBlockFragment(editor, data)) {
    return false;
  }
  return deleteSelectedBlocks(editor);
}

function selectUnitText(editor: SlateEditor, path: number[]): void {
  const start = editor.api.start(path);
  const end = editor.api.end(path);
  if (start && end) {
    editor.tf.select({ anchor: start, focus: end });
  }
}

function pressedModA(editor: SlateEditor, event: KeyEvent): boolean {
  if (!modKey(event) || event.altKey || event.shiftKey || event.key.toLowerCase() !== "a") {
    return false;
  }
  if (blockSelectionActive(editor)) {
    event.preventDefault();
    setBlockSelection(editor, topLevelBlockIds(editor));
    return true;
  }
  const selection = readLiveSelection(editor);
  if (!selection) {
    return false;
  }
  const hit = targetBlockAtPath(editor, selection.anchor.path);
  if (!hit) {
    return false;
  }
  const focusHit = targetBlockAtPath(editor, selection.focus.path);
  if (!focusHit || focusHit.id !== hit.id) {
    return false;
  }
  const covered = selectionCoversBlock(editor, hit.path);
  event.preventDefault();
  if (covered === "covered" || covered === "empty") {
    setBlockSelection(editor, topLevelBlockIds(editor));
    return true;
  }
  selectUnitText(editor, hit.path);
  return true;
}

function historyKey(event: KeyEvent): boolean {
  if (!modKey(event) || event.altKey) {
    return false;
  }
  const key = event.key.toLowerCase();
  return key === "z" || key === "y";
}

function dragInProgress(): boolean {
  return typeof document !== "undefined" && document.body.hasAttribute("data-block-dragging");
}

function escapeConsumedByUi(): boolean {
  if (typeof document === "undefined") {
    return false;
  }
  return (
    document.querySelector(
      "[data-block-menu], [data-block-add-menu], [data-slash-menu], [data-link-popover], [data-bookmark-url-popover]",
    ) !== null
  );
}

function moveCaretToEndOfFirst(editor: SlateEditor): void {
  const run = runOf(editor);
  const first = run ? editor.api.node([...run.parent, run.start]) : undefined;
  const node = first?.[0];
  clearBlockSelection(editor, false);
  if (!first || !ElementApi.isElement(node)) {
    return;
  }
  if (editor.api.isVoid(node)) {
    editor.tf.select(first[1]);
    return;
  }
  placePoint(editor, [...first[1]], "end");
}

export function onBlockSelectionKeyDown(editor: SlateEditor, event: KeyEvent): boolean {
  if (editor.dom.readOnly === true) {
    return false;
  }
  if (pressedModA(editor, event)) {
    return true;
  }
  if (!blockSelectionActive(editor)) {
    return false;
  }
  if (historyKey(event)) {
    return false;
  }
  if (dragInProgress() && event.key === "Escape") {
    event.preventDefault();
    return true;
  }
  const key = event.key;
  const mod = modKey(event);
  if (key === "ArrowUp" || key === "ArrowDown") {
    if (mod && event.altKey && event.shiftKey) {
      event.preventDefault();
      moveSelectedBlocks(editor, key === "ArrowUp" ? "up" : "down");
      return true;
    }
    if (mod || event.altKey) {
      event.preventDefault();
      return true;
    }
    const state = read(editor);
    const direction = key === "ArrowUp" ? "up" : "down";
    if (event.shiftKey) {
      const from = state.focusId || state.ids[state.ids.length - 1] || state.ids[0];
      const next = from ? (adjacentBlockId(editor, from, direction) ?? from) : from;
      if (from && next) {
        event.preventDefault();
        setBlockSelection(editor, [state.anchorId || from, next], {
          anchorId: state.anchorId || from,
          focusId: next,
          scroll: true,
        });
      }
      return true;
    }
    const edge = direction === "up" ? state.ids[0] : state.ids[state.ids.length - 1];
    const next = edge ? (adjacentBlockId(editor, edge, direction) ?? edge) : edge;
    if (next) {
      event.preventDefault();
      setBlockSelection(editor, [next], { scroll: true });
    }
    return true;
  }
  if (key === "Enter" && !mod && !event.shiftKey && !event.altKey) {
    event.preventDefault();
    moveCaretToEndOfFirst(editor);
    return true;
  }
  if (key === "Escape") {
    event.preventDefault();
    clearBlockSelection(editor, true);
    return true;
  }
  if (key === "Backspace" || key === "Delete") {
    event.preventDefault();
    deleteSelectedBlocks(editor);
    return true;
  }
  if (mod && !event.shiftKey && !event.altKey && event.key.toLowerCase() === "d") {
    event.preventDefault();
    duplicateSelectedBlocks(editor);
    return true;
  }
  if (mod && event.shiftKey && event.altKey && (key === "ArrowUp" || key === "ArrowDown")) {
    event.preventDefault();
    moveSelectedBlocks(editor, key === "ArrowUp" ? "up" : "down");
    return true;
  }
  if (mod && !event.altKey && !event.shiftKey && (event.key === "/" || event.code === "Slash")) {
    event.preventDefault();
    return true;
  }
  if (
    mod &&
    !event.altKey &&
    !event.shiftKey &&
    (event.key.toLowerCase() === "c" || event.key.toLowerCase() === "x")
  ) {
    return true;
  }
  if (key === "Tab") {
    event.preventDefault();
    return true;
  }
  if (key.length === 1 && !mod) {
    event.preventDefault();
    return true;
  }
  event.preventDefault();
  return true;
}

export function onBlockSelectionEnterKeyDown(editor: SlateEditor, event: KeyEvent): boolean {
  if (event.key !== "Escape" || event.defaultPrevented || editor.dom.readOnly === true) {
    return false;
  }
  if (blockSelectionActive(editor) || slashMenuOpen(editor) || escapeConsumedByUi()) {
    return false;
  }
  const selection = readLiveSelection(editor);
  if (!selection || !RangeApi.isCollapsed(selection)) {
    return false;
  }
  const hit = targetBlockAtPath(editor, selection.anchor.path);
  if (!hit) {
    return false;
  }
  event.preventDefault();
  setBlockSelection(editor, [hit.id]);
  return true;
}

export function onBlockSelectionCopy(
  editor: SlateEditor,
  event: { preventDefault: () => void; clipboardData: DataTransfer | null },
): boolean {
  if (!blockSelectionActive(editor) || !event.clipboardData) {
    return false;
  }
  event.preventDefault();
  return writeBlockFragment(editor, event.clipboardData);
}

export function onBlockSelectionPaste(
  editor: SlateEditor,
  event: { preventDefault: () => void; clipboardData: DataTransfer | null },
): boolean {
  if (!blockSelectionActive(editor) || event.clipboardData === null) {
    return false;
  }

  const run = runOf(editor);
  if (!run) {
    return false;
  }

  event.preventDefault();
  const data = event.clipboardData;
  suspendPrune += 1;
  try {
    editor.tf.withNewBatch(() => {
      fragmentRange(editor, run);
      clearBlockSelection(editor, false);
      editor.tf.insertData(data);
    });
  } finally {
    suspendPrune -= 1;
  }

  return true;
}

export function onBlockSelectionCut(
  editor: SlateEditor,
  event: { preventDefault: () => void; clipboardData: DataTransfer | null },
): boolean {
  if (!blockSelectionActive(editor) || !event.clipboardData) {
    return false;
  }
  event.preventDefault();
  return cutSelectedBlocks(editor, event.clipboardData);
}

let suspendPrune = 0;

function prune(editor: SlateEditor): void {
  if (suspendPrune > 0) {
    return;
  }
  const ids = blockSelectionIds(editor);
  if (ids.length === 0) {
    return;
  }
  const selection = editor.selection;
  if (selection && !RangeApi.isCollapsed(selection)) {
    clearBlockSelection(editor, false);
    return;
  }
  const next = normalizeBlockIds(editor, ids);
  if (next.length === 0) {
    write(editor, { ...EMPTY, ids: [] });
    return;
  }
  if (next.join("\n") !== ids.join("\n")) {
    const state = read(editor);
    write(editor, {
      ...state,
      ids: next,
      anchorId: next.includes(state.anchorId) ? state.anchorId : (next[0] ?? ""),
      focusId: next.includes(state.focusId) ? state.focusId : (next[next.length - 1] ?? ""),
    });
  }
}

const selectionBase = createSlatePlugin({
  key: "blockSelection",
  priority: BLOCK_SELECTION_PRIORITY,
  options: selectionOptions(),
});

export const blockSelectionWatchPlugin = createSlatePlugin({
  key: "blockSelectionWatch",
  priority: 0,
}).overrideEditor(({ editor }) => {
  const apply = editor.apply as (operation: { type: string }) => void;
  editor.apply = (operation: { type: string }) => {
    apply(operation);
    if (
      operation.type === "remove_node" ||
      operation.type === "insert_node" ||
      operation.type === "move_node" ||
      operation.type === "set_selection"
    ) {
      prune(editor);
    }
  };
  return { transforms: {} };
});

export const blockSelectionPlugin = toPlatePlugin(selectionBase, {
  handlers: {
    onKeyDown: ({ editor, event }) => onBlockSelectionKeyDown(editor, event),
    onCopy: ({ editor, event }) => onBlockSelectionCopy(editor, event),
    onCut: ({ editor, event }) => onBlockSelectionCut(editor, event),
    onPaste: ({ editor, event }) => onBlockSelectionPaste(editor, event),
    onBeforeInput: ({ editor, event }) => {
      if (!blockSelectionActive(editor)) {
        return false;
      }
      event.preventDefault();
      return true;
    },
  },
});

export const blockSelectionEnterPlugin = toPlatePlugin(
  createSlatePlugin({
    key: "blockSelectionEnter",
    priority: BLOCK_SELECTION_ENTER_PRIORITY,
  }),
  {
    handlers: {
      onKeyDown: ({ editor, event }) => onBlockSelectionEnterKeyDown(editor, event),
    },
  },
);

export function selectedRunDrop(
  editor: SlateEditor,
  path: readonly number[],
): { from: number[]; span?: readonly [number, number] } {
  const run = runOf(editor);
  const index = path[path.length - 1] ?? 0;
  if (
    !run ||
    index < run.start ||
    index >= run.end ||
    path.slice(0, -1).join(".") !== run.parent.join(".")
  ) {
    return { from: [...path] };
  }
  return { from: [...run.parent, run.start], span: [run.start, run.end] };
}

import {
  ElementApi,
  KEYS,
  NodeApi,
  PathApi,
  TextApi,
  createSlatePlugin,
  nanoid,
  type SlateEditor,
  type TElement,
} from "platejs";

import { blockPlacementRefusal } from "../features/editor-block-menu";
import {
  BOOKMARK_INVALID_URL,
  BOOKMARK_KEY,
  bookmarkElement,
  normalizeBookmarkUrl,
} from "../features/editor-bookmark-url";
import { blockTextOffset, findSlashBlock, pointAtBlockOffset } from "../features/editor-slash";

type BookmarkUrlOptions = {
  open: boolean;
  blockId: string;
  offset: number;
  error: string;
};

function bookmarkUrlOptions(): BookmarkUrlOptions {
  return { open: false, blockId: "", offset: 0, error: "" };
}

function isEditorOnChange(value: unknown): value is (options?: { operation?: unknown }) => void {
  return typeof value === "function";
}

export const bookmarkUrlPlugin = createSlatePlugin({
  key: "bookmarkUrl",
  options: bookmarkUrlOptions(),
}).overrideEditor(({ editor }) => {
  const { onChange } = editor;
  if (isEditorOnChange(onChange)) {
    editor.onChange = (options?: { operation?: unknown }) => {
      onChange(options);
      if (editor.dom.readOnly === true && editor.getOption(bookmarkUrlPlugin, "open") === true) {
        cancelBookmarkUrl(editor);
      }
    };
  }
  return { transforms: {} };
});

export function bookmarkUrlOpen(editor: SlateEditor): boolean {
  return editor.getOption(bookmarkUrlPlugin, "open") === true;
}

export function openBookmarkUrlPopover(editor: SlateEditor, blockId: string): void {
  const block = findSlashBlock(editor, blockId);
  const offset =
    block !== null && editor.selection !== null
      ? (blockTextOffset(editor, block[1], editor.selection.anchor) ?? 0)
      : 0;
  editor.setOption(bookmarkUrlPlugin, "open", true);
  editor.setOption(bookmarkUrlPlugin, "blockId", blockId);
  editor.setOption(bookmarkUrlPlugin, "offset", offset);
  editor.setOption(bookmarkUrlPlugin, "error", "");
}

export function bookmarkUrlAnchorPoint(
  editor: SlateEditor,
): { path: number[]; offset: number } | null {
  if (!bookmarkUrlOpen(editor)) {
    return null;
  }

  const block = findSlashBlock(editor, editor.getOption(bookmarkUrlPlugin, "blockId"));
  if (block === null) {
    return null;
  }

  return pointAtBlockOffset(editor, block[1], editor.getOption(bookmarkUrlPlugin, "offset"));
}

export function cancelBookmarkUrl(editor: SlateEditor): void {
  if (!bookmarkUrlOpen(editor)) {
    return;
  }

  const blockId = editor.getOption(bookmarkUrlPlugin, "blockId");
  const offset = editor.getOption(bookmarkUrlPlugin, "offset");
  clearBookmarkUrl(editor);
  restoreBookmarkCaret(editor, blockId, offset);
  editor.tf.focus();
}

export function submitBookmarkUrl(editor: SlateEditor, raw: string): boolean {
  if (!bookmarkUrlOpen(editor)) {
    return false;
  }

  if (editor.dom.readOnly === true) {
    cancelBookmarkUrl(editor);
    return false;
  }

  const blockId = editor.getOption(bookmarkUrlPlugin, "blockId");
  const block = findSlashBlock(editor, blockId);
  if (block === null) {
    clearBookmarkUrl(editor);
    editor.tf.focus();
    return false;
  }

  const url = normalizeBookmarkUrl(raw);
  if (url === undefined) {
    editor.setOption(bookmarkUrlPlugin, "error", BOOKMARK_INVALID_URL);
    return false;
  }

  const element = bookmarkElement({ url }, nanoid());
  if (!placeBlockBesideSlash(editor, blockId, element, BOOKMARK_KEY)) {
    cancelBookmarkUrl(editor);
    return false;
  }

  clearBookmarkUrl(editor);
  editor.tf.focus();
  return true;
}

// The one placement for blocks picked from a slash menu: beside the slash block, replacing it when
// it is an empty paragraph, in one undo entry. Refused where the block type is not allowed.
// `inCommand` is set when the caller already runs this inside one command, so the placement joins that
// command's undo entry. Otherwise the placement is its own entry, and the next edit starts another.
export function placeBlockBesideSlash(
  editor: SlateEditor,
  blockId: string,
  element: TElement,
  type: string,
  inCommand = false,
): boolean {
  const block = findSlashBlock(editor, blockId);
  if (block === null) {
    return false;
  }

  const [node, path] = block;
  if (!slashBlockPlaceable(editor, path, node, type)) {
    return false;
  }

  const at = PathApi.next([...path]);
  if (at === undefined) {
    return false;
  }

  const id = typeof node.id === "string" ? node.id : undefined;
  const replace = isEmptyParagraph(node);
  const place = (): void => {
    editor.tf.insertNodes(element, { at, select: true });
    if (!replace || id === undefined) {
      return;
    }

    const left = findSlashBlock(editor, id);
    if (left !== null && isEmptyParagraph(left[0])) {
      editor.tf.removeNodes({ at: left[1] });
    }
  };

  if (inCommand) {
    place();
    return true;
  }

  editor.tf.withNewBatch(place);
  editor.tf.setSplittingOnce(true);
  return true;
}

function clearBookmarkUrl(editor: SlateEditor): void {
  editor.setOption(bookmarkUrlPlugin, "open", false);
  editor.setOption(bookmarkUrlPlugin, "blockId", "");
  editor.setOption(bookmarkUrlPlugin, "offset", 0);
  editor.setOption(bookmarkUrlPlugin, "error", "");
}

function restoreBookmarkCaret(editor: SlateEditor, blockId: string, offset: number): void {
  const block = findSlashBlock(editor, blockId);
  if (block === null) {
    return;
  }

  const point = pointAtBlockOffset(editor, block[1], offset) ?? editor.api.end(block[1]);
  if (point !== undefined) {
    editor.tf.select(point);
  }
}

function slashBlockPlaceable(
  editor: SlateEditor,
  path: number[],
  node: TElement,
  type: string,
): boolean {
  const index = path[path.length - 1];
  if (index === undefined) {
    return false;
  }

  const parentPath = path.slice(0, -1);
  let parentType: string | null = null;
  if (parentPath.length > 0) {
    const parent = editor.api.node(parentPath);
    if (!parent || !ElementApi.isElement(parent[0]) || typeof parent[0].type !== "string") {
      return false;
    }
    parentType = parent[0].type;
  }

  const toIndex = isEmptyParagraph(node) ? index : index + 1;
  return blockPlacementRefusal(parentType, toIndex, type, false) === undefined;
}

function isEmptyParagraph(node: TElement): boolean {
  return (
    node.type === KEYS.p &&
    NodeApi.string(node) === "" &&
    node.children.every((child) => TextApi.isText(child))
  );
}

import { ElementApi, createSlatePlugin, type SlateEditor, type TElement } from "platejs";

import { BOOKMARK_KEY } from "../features/editor-bookmark-url";
import { blockSelectionActive } from "./editor-block-selection";

type BookmarkToolbarOptions = {
  open: boolean;
  blockId: string;
};

function bookmarkToolbarOptions(): BookmarkToolbarOptions {
  return { open: false, blockId: "" };
}

// A click on a bookmark card (or Enter on the selected void) opens one popover
// with the card actions. Nothing else about the card changes on hover.
export const bookmarkToolbarPlugin = createSlatePlugin({
  key: "bookmarkToolbar",
  options: bookmarkToolbarOptions(),
}).overrideEditor(({ editor }) => {
  const { onChange } = editor;
  if (isEditorOnChange(onChange)) {
    editor.onChange = (options?: { operation?: unknown }) => {
      onChange(options);
      if (editor.dom.readOnly === true && bookmarkToolbarOpen(editor)) {
        closeBookmarkToolbar(editor);
      }
    };
  }
  return { transforms: {} };
});

function isEditorOnChange(value: unknown): value is (options?: { operation?: unknown }) => void {
  return typeof value === "function";
}

export function bookmarkToolbarOpen(editor: SlateEditor): boolean {
  return editor.getOption(bookmarkToolbarPlugin, "open") === true;
}

export function bookmarkToolbarBlockId(editor: SlateEditor): string {
  return editor.getOption(bookmarkToolbarPlugin, "blockId");
}

export function openBookmarkToolbar(editor: SlateEditor, blockId: string): void {
  if (editor.dom.readOnly === true || blockId.length === 0) {
    return;
  }

  if (blockSelectionActive(editor)) {
    return;
  }

  editor.setOption(bookmarkToolbarPlugin, "blockId", blockId);
  editor.setOption(bookmarkToolbarPlugin, "open", true);
}

export function closeBookmarkToolbar(editor: SlateEditor): void {
  if (!bookmarkToolbarOpen(editor)) {
    return;
  }

  editor.setOption(bookmarkToolbarPlugin, "open", false);
  editor.setOption(bookmarkToolbarPlugin, "blockId", "");
}

function selectedBookmarkEntry(editor: SlateEditor): [TElement, number[]] | undefined {
  const entry = editor.api.above({
    match: (node) => ElementApi.isElement(node) && node.type === editor.getType(BOOKMARK_KEY),
  });
  if (entry === undefined || !ElementApi.isElement(entry[0])) {
    return undefined;
  }

  return [entry[0], entry[1]];
}

export function bookmarkToolbarSelectionOn(editor: SlateEditor, blockId: string): boolean {
  if (blockId.length === 0) {
    return false;
  }

  return (
    editor.api.above({
      match: (node) => ElementApi.isElement(node) && node.id === blockId,
    }) !== undefined
  );
}

type BookmarkKeyEvent = {
  key: string;
  altKey?: boolean;
  shiftKey?: boolean;
  metaKey?: boolean;
  ctrlKey?: boolean;
  preventDefault: () => void;
};

// Enter on the selected bookmark opens the popover instead of inserting a break.
export function onBookmarkToolbarKeyDown(editor: SlateEditor, event: BookmarkKeyEvent): boolean {
  if (editor.dom.readOnly === true || event.key !== "Enter") {
    return false;
  }

  if (event.altKey || event.shiftKey || event.metaKey || event.ctrlKey) {
    return false;
  }

  if (bookmarkToolbarOpen(editor)) {
    return false;
  }

  const entry = selectedBookmarkEntry(editor);
  if (entry === undefined) {
    return false;
  }

  const id = typeof entry[0].id === "string" ? entry[0].id : "";
  if (id.length === 0) {
    return false;
  }

  event.preventDefault();
  openBookmarkToolbar(editor, id);
  return true;
}

import { createSlatePlugin, type SlateEditor } from "platejs";

import { DEFAULT_EDITOR_OPTIONS, type ResolvedEditorOptions } from "../features/editor-options";
import {
  DEFAULT_EDITOR_FEATURES,
  itemFeature,
  type EditorFeature,
  type ResolvedEditorFeatures,
} from "../features/editor-features";

// Carries the host's resolved options and features on the editor. It has no handlers and no
// transforms, so it changes nothing about how the editor edits.
export const editorConfigPlugin = createSlatePlugin({
  key: "editorConfig",
  options: { resolved: DEFAULT_EDITOR_OPTIONS, features: DEFAULT_EDITOR_FEATURES },
});

// The options of this editor. An editor without the config plugin (a static
// editor or a bare test editor) gets the defaults. This never throws.
export function editorOptions(editor: SlateEditor): ResolvedEditorOptions {
  return editor.getOption(editorConfigPlugin, "resolved") ?? DEFAULT_EDITOR_OPTIONS;
}

// The features of this editor. An editor without the config plugin gets the defaults.
export function editorFeatures(editor: SlateEditor): ResolvedEditorFeatures {
  return editor.getOption(editorConfigPlugin, "features") ?? DEFAULT_EDITOR_FEATURES;
}

export function featureEnabled(editor: SlateEditor, feature: EditorFeature): boolean {
  return editorFeatures(editor)[feature];
}

// An item that no feature gates is always enabled. Others follow their feature.
export function itemFeatureEnabled(editor: SlateEditor, itemId: string): boolean {
  const feature = itemFeature(itemId);
  return feature === undefined || featureEnabled(editor, feature);
}

import { createSlatePlugin, type SlateEditor } from "platejs";
import { toPlatePlugin } from "platejs/react";

import { runEditorCommand, type EditorCommand } from "../commands/editor-commands";
import {
  EMOJI_SUGGEST_LIMIT,
  loadEmojiEntries,
  loadedEmojiEntries,
  readClosingEmoji,
  readEmojiSession,
  searchEmoji,
  type EmojiReplacement,
} from "../features/editor-emoji";
import type { EmojiEntry } from "../features/emoji-data";
import { pointAtBlockOffset } from "../features/editor-slash";
import { slashMenuOpen } from "./editor-slash";
import { featureEnabled } from "./editor-config";

// Below the slash menu (2000), so an open slash menu handles its keys first.
// Above the list, table and indent handlers (0), so Tab chooses an emoji instead of indenting.
export const EMOJI_HANDLER_PRIORITY = 1000;

type EmojiOptions = {
  open: boolean;
  activeIndex: number;
  ready: boolean;
  // The token the menu is for. The popover subscribes to it, so every token change re-renders.
  query: string;
};

type EmojiKeyEvent = {
  key: string;
  shiftKey?: boolean;
  metaKey?: boolean;
  ctrlKey?: boolean;
  altKey?: boolean;
  preventDefault: () => void;
};

function isEditorOnChange(value: unknown): value is (options?: { operation?: unknown }) => void {
  return typeof value === "function";
}

// Escape hides one token. The key is the block, the colon offset and the token, so editing the token reopens it.
const lastTokenKey = new WeakMap<SlateEditor, string>();
const dismissedToken = new WeakSet<SlateEditor>();
const requestedData = new WeakSet<SlateEditor>();

function emojiOptions(): EmojiOptions {
  return { open: false, activeIndex: 0, ready: false, query: "" };
}

export function emojiMenuOpen(editor: SlateEditor): boolean {
  return editor.getOption(emojiUiPlugin, "open") === true;
}

export function closeEmojiMenu(editor: SlateEditor): void {
  if (emojiMenuOpen(editor)) {
    editor.setOption(emojiUiPlugin, "open", false);
  }
  if (editor.getOption(emojiUiPlugin, "activeIndex") !== 0) {
    editor.setOption(emojiUiPlugin, "activeIndex", 0);
  }
}

function dismissEmojiMenu(editor: SlateEditor): void {
  dismissedToken.add(editor);
  closeEmojiMenu(editor);
}

function activeEmojiIndex(editor: SlateEditor, count: number): number {
  return Math.min(editor.getOption(emojiUiPlugin, "activeIndex"), count - 1);
}

// Rows are empty while the data loads, when the menu is closed, or when a slash menu is open.
export function emojiMenuItems(editor: SlateEditor): EmojiEntry[] {
  if (!emojiMenuOpen(editor) || slashMenuOpen(editor)) {
    return [];
  }
  const session = readEmojiSession(editor);
  const entries = loadedEmojiEntries();
  if (session === null || entries === null) {
    return [];
  }
  return searchEmoji(entries, session.token, EMOJI_SUGGEST_LIMIT);
}

function moveEmojiHighlight(editor: SlateEditor, delta: number): void {
  const count = emojiMenuItems(editor).length;
  if (count === 0) {
    return;
  }
  const current = activeEmojiIndex(editor, count);
  editor.setOption(emojiUiPlugin, "activeIndex", (current + delta + count) % count);
}

function requestEmojiData(editor: SlateEditor): void {
  if (loadedEmojiEntries() !== null || requestedData.has(editor)) {
    return;
  }
  requestedData.add(editor);
  loadEmojiEntries()
    .then(() => {
      requestedData.delete(editor);
      // Changing an option re-renders the popover, which then reads the loaded data.
      editor.setOption(emojiUiPlugin, "ready", true);
      syncEmojiMenu(editor);
    })
    .catch(() => {
      requestedData.delete(editor);
    });
}

function setEmojiQuery(editor: SlateEditor, query: string): void {
  if (editor.getOption(emojiUiPlugin, "query") !== query) {
    editor.setOption(emojiUiPlugin, "query", query);
  }
}

function syncEmojiMenu(editor: SlateEditor): void {
  const session = slashMenuOpen(editor) ? null : readEmojiSession(editor);
  setEmojiQuery(editor, session?.token ?? "");
  if (session === null) {
    lastTokenKey.delete(editor);
    dismissedToken.delete(editor);
    closeEmojiMenu(editor);
    return;
  }

  const key = `${session.blockId}:${session.colon}:${session.token}`;
  if (lastTokenKey.get(editor) !== key) {
    lastTokenKey.set(editor, key);
    dismissedToken.delete(editor);
    if (editor.getOption(emojiUiPlugin, "activeIndex") !== 0) {
      editor.setOption(emojiUiPlugin, "activeIndex", 0);
    }
  }

  if (dismissedToken.has(editor)) {
    closeEmojiMenu(editor);
    return;
  }
  if (!emojiMenuOpen(editor)) {
    editor.setOption(emojiUiPlugin, "open", true);
  }
  requestEmojiData(editor);
}

// One command for the popover choice and the closing colon, so one undo restores the typed text.
export const insertEmojiText: EditorCommand<EmojiReplacement> = {
  id: "insert.emoji",
  label: "Emoji",
  group: "insert",
  isEnabled: (editor) => editor.dom.readOnly !== true,
  run: (editor, replacement) => {
    const start = pointAtBlockOffset(editor, replacement.blockPath, replacement.start);
    const end = pointAtBlockOffset(editor, replacement.blockPath, replacement.end);
    if (start === null || end === null) {
      return;
    }
    // Insert by range so the token is never selected. The undo then restores a collapsed caret.
    editor.tf.insertText(replacement.emoji, { at: { anchor: start, focus: end } });
    const after = pointAtBlockOffset(
      editor,
      replacement.blockPath,
      replacement.start + replacement.emoji.length,
    );
    if (after !== null) {
      editor.tf.select(after);
    }
  },
};

export function chooseEmojiSuggestion(editor: SlateEditor, emoji: string): void {
  const session = readEmojiSession(editor);
  closeEmojiMenu(editor);
  if (session === null) {
    return;
  }
  runEditorCommand(editor, insertEmojiText, {
    emoji,
    blockPath: session.blockPath,
    start: session.colon,
    end: session.caret,
  });
}

function convertClosingEmoji(editor: SlateEditor): void {
  if (slashMenuOpen(editor) || !featureEnabled(editor, "emoji")) {
    return;
  }
  const entries = loadedEmojiEntries();
  if (entries === null) {
    requestEmojiData(editor);
    return;
  }
  const replacement = readClosingEmoji(editor, entries);
  if (replacement === null) {
    return;
  }
  closeEmojiMenu(editor);
  runEditorCommand(editor, insertEmojiText, replacement);
}

export function onEmojiKeyDown(editor: SlateEditor, event: EmojiKeyEvent): boolean {
  if (event.metaKey === true || event.ctrlKey === true || event.altKey === true) {
    return false;
  }
  const items = emojiMenuItems(editor);
  if (items.length === 0) {
    return false;
  }
  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
    event.preventDefault();
    moveEmojiHighlight(editor, event.key === "ArrowDown" ? 1 : -1);
    return true;
  }
  if ((event.key === "Enter" || event.key === "Tab") && event.shiftKey !== true) {
    event.preventDefault();
    const item = items[activeEmojiIndex(editor, items.length)];
    if (item !== undefined) {
      chooseEmojiSuggestion(editor, item.emoji);
    }
    return true;
  }
  if (event.key === "Escape") {
    event.preventDefault();
    dismissEmojiMenu(editor);
    return true;
  }
  return false;
}

const emojiBase = createSlatePlugin({
  key: "emojiUi",
  priority: EMOJI_HANDLER_PRIORITY,
  options: emojiOptions(),
}).overrideEditor(({ editor, tf: { insertText } }) => {
  return {
    transforms: {
      insertText(text, options) {
        insertText(text, options);
        // A multi-character insert ending in a colon counts too, so a paste of :name: converts.
        if (text.endsWith(":") && (options === undefined || options.at === undefined)) {
          convertClosingEmoji(editor);
        }
        // Slate's onChange runs later, so typing opens or closes the menu at once.
        syncEmojiMenu(editor);
      },
    },
  };
});

export const emojiWatchPlugin = createSlatePlugin({
  key: "emojiWatch",
  priority: -1,
}).overrideEditor(({ editor }) => {
  const { onChange } = editor;
  if (isEditorOnChange(onChange)) {
    editor.onChange = (options?: { operation?: unknown }) => {
      onChange(options);
      syncEmojiMenu(editor);
    };
  }
  return { transforms: {} };
});

export const emojiUiPlugin = toPlatePlugin(emojiBase, {
  handlers: {
    onKeyDown: ({ editor, event }) => onEmojiKeyDown(editor, event),
    onBlur: ({ editor, event }) => {
      const related = "relatedTarget" in event ? event.relatedTarget : null;
      if (related instanceof Element && related.closest("[data-emoji-suggest]") !== null) {
        return;
      }
      queueMicrotask(() => {
        const active = document.activeElement;
        if (active instanceof Element && active.closest("[data-slate-editor]") !== null) {
          return;
        }
        if (active instanceof Element && active.closest("[data-emoji-suggest]") !== null) {
          return;
        }
        closeEmojiMenu(editor);
      });
    },
  },
});

import { PathApi, RangeApi, type SlateEditor } from "platejs";

import { FIND_QUERY_MAX } from "../features/editor-find";
import { shortcutPlatformOf } from "../features/editor-shortcuts";
import { blockSelectionActive } from "./editor-block-selection";
import { findPlugin, openFind, revealFindMatch, setFindQuery } from "./editor-find";
import { featureEnabled } from "./editor-config";

type FindKeyEvent = {
  key: string;
  altKey: boolean;
  shiftKey: boolean;
  metaKey: boolean;
  ctrlKey: boolean;
};

export function isMacPlatform(): boolean {
  return shortcutPlatformOf(typeof navigator === "undefined" ? undefined : navigator) === "mac";
}

// Cmd+F on macOS, Ctrl+F elsewhere. Shift or Alt makes it another shortcut.
export function isFindOpenKey(event: FindKeyEvent, mac: boolean): boolean {
  if (event.key.toLowerCase() !== "f" || event.shiftKey || event.altKey) {
    return false;
  }

  return mac ? event.metaKey && !event.ctrlKey : event.ctrlKey && !event.metaKey;
}

// The selected text, when it sits inside one block and fits in a query.
function selectionFindQuery(editor: SlateEditor): string | undefined {
  const selection = editor.selection;
  if (selection === null || RangeApi.isCollapsed(selection)) {
    return undefined;
  }

  const start = editor.api.block({ at: RangeApi.start(selection) });
  const end = editor.api.block({ at: RangeApi.end(selection) });
  if (start === undefined || end === undefined || !PathApi.equals(start[1], end[1])) {
    return undefined;
  }

  const text = editor.api.string(selection);
  return text.length > 0 && text.length <= FIND_QUERY_MAX ? text : undefined;
}

type FindOpenEvent = FindKeyEvent & {
  defaultPrevented: boolean;
  preventDefault: () => void;
};

// Mod+F in the editor opens the bar with the selection as the query, and asks the bar for focus.
// The bar attaches it to the editable element, so it also works in a read-only editor.
export function onFindKeyDown(editor: SlateEditor, event: FindOpenEvent): void {
  // With find off the key is not handled, so the browser's own find still opens.
  if (
    event.defaultPrevented ||
    !featureEnabled(editor, "find") ||
    !isFindOpenKey(event, isMacPlatform())
  ) {
    return;
  }

  event.preventDefault();
  const query = blockSelectionActive(editor) ? undefined : selectionFindQuery(editor);
  if (query !== undefined) {
    setFindQuery(editor, query);
  }
  openFind(editor);
  revealFindMatch(editor);
  editor.setOption(findPlugin, "focusRequest", editor.getOption(findPlugin, "focusRequest") + 1);
}

type Box = { top: number; bottom: number; left: number; right: number };

// The find bar covers the top of the scroll area, so a match there is not counted as visible.
const FIND_BAR_TOP_INSET = 96;

// Whether a match box is fully inside the scroll area, below the bar's band.
export function isHighlightVisible(rect: Box, container: Box): boolean {
  return (
    rect.top >= container.top + FIND_BAR_TOP_INSET &&
    rect.bottom <= container.bottom &&
    rect.left >= container.left &&
    rect.right <= container.right
  );
}

import { createElement, type ReactNode } from "react";
import {
  ElementApi,
  KEYS,
  PointApi,
  RangeApi,
  TextApi,
  createSlatePlugin,
  type Point,
  type SlateEditor,
} from "platejs";

import {
  findMatches,
  normalizeFindQuery,
  type FindMatch,
  type FindResult,
} from "../features/editor-find";
import { toggleOpen } from "./editor-toggle";

export type FindState = {
  open: boolean;
  query: string;
  matchCase: boolean;
  count: number;
  activeIndex: number;
  truncated: boolean;
};

type FindGroup = { index: number; match: FindMatch };

type FindCache = {
  children: SlateEditor["children"];
  query: string;
  matchCase: boolean;
  result: FindResult;
  // Matches keyed by the path of the text block that holds them.
  groups: Map<string, FindGroup[]>;
  // The resolved active index. Reads use this, never the plugin option, so reads write nothing.
  index: number;
};

type FindLeafProps = {
  attributes?: { className?: string };
  children?: ReactNode;
  leaf?: { findActive?: unknown };
};

// The decorated leaf carries findActive, set by decorate. Plate picks this renderer by the plugin key.
function FindHighlight({ attributes, children, leaf }: FindLeafProps) {
  const slateClass = typeof attributes?.className === "string" ? attributes.className : "";
  const active = leaf?.findActive === true;
  return createElement(
    "span",
    {
      ...attributes,
      "data-find-match": "",
      "data-find-active": active ? "" : undefined,
      className: `${slateClass} rounded-sm ${active ? "bg-primary/40" : "bg-primary/15"}`.trim(),
    },
    children,
  );
}

export const findPlugin = createSlatePlugin({
  key: "find",
  node: {
    isLeaf: true,
    isDecoration: true,
  },
  render: {
    node: FindHighlight,
  },
  options: {
    open: false,
    query: "",
    matchCase: false,
    activeIndex: 0,
    // Bumped by a Mod+F press so the bar moves focus to its input again.
    focusRequest: 0,
  },
  decorate: ({ editor, entry }) => {
    if (!editor.getOption(findPlugin, "open")) {
      return undefined;
    }

    const [node, path] = entry;
    if (!TextApi.isText(node)) {
      return undefined;
    }

    const cache = currentFind(editor);
    if (cache.result.matches.length === 0) {
      return undefined;
    }

    const block = editor.api.block({ at: path });
    if (block === undefined) {
      return undefined;
    }

    const groups = cache.groups.get(blockKey(block[1])) ?? [];
    const activeIndex = cache.index;
    const leafStart: Point = { path, offset: 0 };
    const leafEnd: Point = { path, offset: node.text.length };
    const ranges: { anchor: Point; focus: Point; find: true; findActive: boolean }[] = [];
    for (const { index, match } of groups) {
      const anchor = PointApi.compare(match.anchor, leafStart) < 0 ? leafStart : match.anchor;
      const focus = PointApi.compare(match.focus, leafEnd) > 0 ? leafEnd : match.focus;
      if (PointApi.compare(anchor, focus) < 0) {
        ranges.push({ anchor, focus, find: true, findActive: index === activeIndex });
      }
    }

    return ranges.length === 0 ? undefined : ranges;
  },
});

// The last computed result per editor. Recomputed when editor.children, the query or matchCase changes.
const caches = new WeakMap<SlateEditor, FindCache>();
// The start of the active match. It is the anchor to find the next active match after a document change.
const rememberedStarts = new WeakMap<SlateEditor, Point>();

function blockKey(path: readonly number[]): string {
  return path.join(",");
}

function clampIndex(value: number, result: FindResult): number {
  const count = result.matches.length;
  if (count === 0) {
    return 0;
  }
  return Math.min(Math.max(value, 0), count - 1);
}

// The first match whose anchor is at or after the point. Without a point, or none after it, 0.
function indexAtOrAfter(result: FindResult, point: Point | undefined): number {
  if (point === undefined) {
    return 0;
  }

  const index = result.matches.findIndex((match) => PointApi.compare(match.anchor, point) >= 0);
  return index < 0 ? 0 : index;
}

function rememberActive(editor: SlateEditor, cache: FindCache): void {
  const match = cache.result.matches[cache.index];
  if (match === undefined) {
    rememberedStarts.delete(editor);
  } else {
    rememberedStarts.set(editor, match.anchor);
  }
}

// Stores a result in the cache only. It writes no plugin option, so it is safe during render.
function cacheFind(editor: SlateEditor, result: FindResult, index: number): FindCache {
  const groups = new Map<string, FindGroup[]>();
  result.matches.forEach((match, matchIndex) => {
    const block = editor.api.block({ at: match.anchor.path });
    if (block === undefined) {
      return;
    }

    const key = blockKey(block[1]);
    const list = groups.get(key) ?? [];
    list.push({ index: matchIndex, match });
    groups.set(key, list);
  });

  const cache: FindCache = {
    children: editor.children,
    query: editor.getOption(findPlugin, "query"),
    matchCase: editor.getOption(findPlugin, "matchCase"),
    result,
    groups,
    index: clampIndex(index, result),
  };
  caches.set(editor, cache);
  rememberActive(editor, cache);
  return cache;
}

// Returns the cache for the current document. A new document keeps the active match at its place.
function currentFind(editor: SlateEditor): FindCache {
  const query = editor.getOption(findPlugin, "query");
  const matchCase = editor.getOption(findPlugin, "matchCase");
  const cached = caches.get(editor);
  if (
    cached !== undefined &&
    cached.children === editor.children &&
    cached.query === query &&
    cached.matchCase === matchCase
  ) {
    return cached;
  }

  const result = findMatches(editor, query, { matchCase });
  const sameQuery =
    cached !== undefined && cached.query === query && cached.matchCase === matchCase;
  const index = sameQuery ? indexAtOrAfter(result, rememberedStarts.get(editor)) : 0;
  return cacheFind(editor, result, index);
}

// Explicit moves only (navigation, query and match case changes). Writes the activeIndex option.
function setActiveIndex(editor: SlateEditor, index: number): void {
  const cache = currentFind(editor);
  cache.index = clampIndex(index, cache.result);
  rememberActive(editor, cache);
  editor.setOption(findPlugin, "activeIndex", cache.index);
}

// The matches of the current document, for the replace commands.
export function currentFindResult(editor: SlateEditor): FindResult {
  return currentFind(editor).result;
}

// Sets the active match to the first one at or after the point, after a replace.
export function settleFind(editor: SlateEditor, point: Point | undefined): void {
  const result = findMatches(editor, editor.getOption(findPlugin, "query"), {
    matchCase: editor.getOption(findPlugin, "matchCase"),
  });
  const cache = cacheFind(editor, result, indexAtOrAfter(result, point));
  editor.setOption(findPlugin, "activeIndex", cache.index);
  editor.api.redecorate();
}

export function openFind(editor: SlateEditor): void {
  editor.setOption(findPlugin, "open", true);
  editor.api.redecorate();
}

export function closeFind(editor: SlateEditor): void {
  editor.setOption(findPlugin, "open", false);
  editor.api.redecorate();
}

// The active match goes to the first match at or after the selection start.
function resetActiveToSelection(editor: SlateEditor): void {
  const cache = currentFind(editor);
  const start = editor.selection === null ? undefined : RangeApi.start(editor.selection);
  setActiveIndex(editor, indexAtOrAfter(cache.result, start));
  editor.api.redecorate();
}

export function setFindQuery(editor: SlateEditor, raw: string): void {
  editor.setOption(findPlugin, "query", normalizeFindQuery(raw));
  resetActiveToSelection(editor);
}

export function setFindMatchCase(editor: SlateEditor, value: boolean): void {
  editor.setOption(findPlugin, "matchCase", value);
  resetActiveToSelection(editor);
}

function moveActive(editor: SlateEditor, step: number): void {
  const cache = currentFind(editor);
  const count = cache.result.matches.length;
  if (count === 0) {
    return;
  }

  setActiveIndex(editor, (cache.index + step + count) % count);
  editor.api.redecorate();
}

export function findNext(editor: SlateEditor): void {
  moveActive(editor, 1);
}

export function findPrevious(editor: SlateEditor): void {
  moveActive(editor, -1);
}

export function findState(editor: SlateEditor): FindState {
  const cache = currentFind(editor);
  const count = cache.result.matches.length;
  return {
    open: editor.getOption(findPlugin, "open"),
    query: editor.getOption(findPlugin, "query"),
    matchCase: editor.getOption(findPlugin, "matchCase"),
    count,
    activeIndex: count === 0 ? -1 : cache.index,
    truncated: cache.result.truncated,
  };
}

export function findActiveMatch(editor: SlateEditor): FindMatch | undefined {
  const cache = currentFind(editor);
  if (cache.result.matches.length === 0) {
    return undefined;
  }

  return cache.result.matches[cache.index];
}

// Opens each collapsed toggle that hides the active match. Selection and history are untouched.
export function revealFindMatch(editor: SlateEditor): void {
  const match = findActiveMatch(editor);
  if (match === undefined) {
    return;
  }

  const path = match.anchor.path;
  for (let depth = 1; depth < path.length; depth += 1) {
    const childIndex = path[depth];
    const ancestor = editor.api.node(path.slice(0, depth));
    if (
      childIndex === undefined ||
      childIndex === 0 ||
      ancestor === undefined ||
      !ElementApi.isElement(ancestor[0]) ||
      ancestor[0].type !== KEYS.toggle
    ) {
      continue;
    }

    const id = ancestor[0].id;
    if (typeof id === "string" && id.length > 0) {
      toggleOpen(editor, id, true);
    }
  }
}

import { ElementApi, type Point, type SlateEditor } from "platejs";

import type { EditorCommand } from "../commands/editor-commands";
import { FOOTNOTE_DEF_KEY, FOOTNOTE_REF_KEY } from "../document/editor-document-schema";
import {
  footnoteDefinitionIdAt,
  footnoteDefinitionEntry,
  footnoteInsertAllowed,
  footnoteReferenceEntries,
  insertFootnote,
  selectAfterFootnoteReference,
  selectFootnoteDefinition,
  selectFootnoteReference,
} from "../features/editor-footnote";
import { blockSelectionActive } from "./editor-block-selection";

// Scrolls the node's DOM into view. Used after a jump, so the target is visible.
function scrollPathIntoView(editor: SlateEditor, path: readonly number[]): void {
  const node = editor.api.node([...path])?.[0];
  const dom = node ? editor.api.toDOMNode(node) : undefined;
  if (dom instanceof HTMLElement) {
    dom.scrollIntoView({ block: "nearest" });
  }
}

const REVEAL_ATTEMPTS = 20;

function revealDefinitionWhenRendered(editor: SlateEditor, id: string, attempts: number): void {
  setTimeout(() => {
    const entry = footnoteDefinitionEntry(editor, id);
    const node = entry === undefined ? undefined : editor.api.node(entry[1])?.[0];
    const dom = node === undefined ? undefined : editor.api.toDOMNode(node);
    if (dom === undefined) {
      if (attempts > 0) {
        revealDefinitionWhenRendered(editor, id, attempts - 1);
      }
      return;
    }

    scrollPathIntoView(editor, entry?.[1] ?? []);
    editor.tf.focus();
  }, 0);
}

// Edit mode moves the caret to the end of the definition and keeps focus. Read-only only scrolls.
export function jumpToFootnoteDefinition(editor: SlateEditor, footnoteId: string): boolean {
  const entry = footnoteDefinitionEntry(editor, footnoteId);
  if (entry === undefined) {
    return false;
  }

  if (editor.dom.readOnly === true) {
    scrollPathIntoView(editor, entry[1]);
    return true;
  }

  if (!selectFootnoteDefinition(editor, footnoteId)) {
    return false;
  }
  scrollPathIntoView(editor, entry[1]);
  editor.tf.focus();
  return true;
}

// Jumps back to the first reference. In edit mode the caret lands right after it.
export function jumpToFootnoteReference(editor: SlateEditor, footnoteId: string): boolean {
  const entry = footnoteReferenceEntries(editor, footnoteId)[0];
  if (entry === undefined) {
    return false;
  }

  if (editor.dom.readOnly === true) {
    scrollPathIntoView(editor, entry[1]);
    return true;
  }

  if (!selectFootnoteReference(editor, footnoteId)) {
    return false;
  }
  scrollPathIntoView(editor, entry[1]);
  editor.tf.focus();
  return true;
}

// A click on a reference whose definition is missing only selects that reference.
export function selectMissingFootnoteReference(editor: SlateEditor, path: readonly number[]): void {
  if (editor.dom.readOnly === true) {
    return;
  }
  selectAfterFootnoteReference(editor, [...path]);
  editor.tf.focus();
}

type FootnoteKeyEvent = {
  key: string;
  altKey: boolean;
  shiftKey: boolean;
  metaKey: boolean;
  ctrlKey: boolean;
  defaultPrevented: boolean;
  preventDefault: () => void;
};

// Enter on a selected reference jumps to its definition, the same way the date chip opens.
export function onFootnoteRefKeyDown(editor: SlateEditor, event: FootnoteKeyEvent): void {
  if (
    event.defaultPrevented ||
    event.key !== "Enter" ||
    event.shiftKey ||
    event.metaKey ||
    event.ctrlKey ||
    event.altKey ||
    editor.dom.readOnly === true ||
    blockSelectionActive(editor)
  ) {
    return;
  }

  const ref = editor.api.above({
    match: (node) => ElementApi.isElement(node) && node.type === FOOTNOTE_REF_KEY,
  });
  if (ref === undefined || !ElementApi.isElement(ref[0]) || typeof ref[0].footnoteId !== "string") {
    return;
  }

  event.preventDefault();
  jumpToFootnoteDefinition(editor, ref[0].footnoteId);
}

// Runs from the registered Mod+Enter shortcut. True when the caret is in a definition, which
// consumes the key whether or not a reference exists.
export function jumpFromCaretDefinition(editor: SlateEditor): boolean {
  const block = editor.api.block();
  if (
    block === undefined ||
    !ElementApi.isElement(block[0]) ||
    block[0].type !== FOOTNOTE_DEF_KEY
  ) {
    return false;
  }

  const id = footnoteDefinitionIdAt(editor, block[1]);
  if (id !== undefined) {
    jumpToFootnoteReference(editor, id);
  }
  return true;
}

// Mod+Enter inside a definition jumps back to its first reference.
export function onFootnoteDefKeyDown(editor: SlateEditor, event: FootnoteKeyEvent): void {
  if (
    event.defaultPrevented ||
    event.key !== "Enter" ||
    event.shiftKey ||
    event.altKey ||
    !(event.metaKey || event.ctrlKey) ||
    editor.dom.readOnly === true ||
    blockSelectionActive(editor)
  ) {
    return;
  }

  const block = editor.api.block();
  if (
    block === undefined ||
    !ElementApi.isElement(block[0]) ||
    block[0].type !== FOOTNOTE_DEF_KEY
  ) {
    return;
  }
  const id = block[0].footnoteId;
  if (typeof id !== "string") {
    return;
  }

  event.preventDefault();
  jumpToFootnoteReference(editor, id);
}

// The slash query goes and the reference and definition arrive as one undo step.
export const insertSlashFootnote: EditorCommand<{ start: Point; end: Point }> = {
  id: "inline.footnote.slash",
  label: "Footnote",
  group: "insert",
  isEnabled: (editor) => footnoteInsertAllowed(editor),
  run: (editor, { start, end }) => {
    editor.tf.delete({ at: { anchor: start, focus: end } });
    insertFootnote.run(editor, undefined);

    // The caret is in the new definition. Its DOM node appears on a later render, so the reveal
    // retries on short timeouts until the node exists, then does the same scroll and focus as a
    // reference click.
    const block = editor.api.block();
    const id =
      block !== undefined && ElementApi.isElement(block[0]) && block[0].type === FOOTNOTE_DEF_KEY
        ? footnoteDefinitionIdAt(editor, block[1])
        : undefined;
    if (id !== undefined) {
      revealDefinitionWhenRendered(editor, id, REVEAL_ATTEMPTS);
    }
  },
};

import {
  ElementApi,
  KEYS,
  PathApi,
  createSlatePlugin,
  type SlateEditor,
  type TElement,
} from "platejs";

import { FOOTNOTE_DEF_KEY, FOOTNOTE_REF_KEY } from "../document/editor-document-schema";
import { createFootnoteId, isFootnoteId } from "../features/editor-footnote-id";

// The definition is a block with inline text. Its own rules are below, and it has no other keys.
export const footnoteDefPlugin = createSlatePlugin({
  key: FOOTNOTE_DEF_KEY,
  node: { isElement: true },
});

function footnoteDefinitionBlock(editor: SlateEditor): [TElement, number[]] | undefined {
  const block = editor.api.block();
  if (!block || !ElementApi.isElement(block[0]) || block[0].type !== FOOTNOTE_DEF_KEY) {
    return undefined;
  }

  return [block[0], block[1]];
}

// Enter splits the definition, and the block after the caret becomes a paragraph. The split is
// splitNodes, not insertBreak: at offset 0 Plate's break inserts an empty block above and would
// turn the definition itself into a paragraph. Both halves change in one batch, so normalize
// never sees two definitions with one id.
function breakFootnoteDefinition(editor: SlateEditor): boolean {
  const entry = footnoteDefinitionBlock(editor);
  if (entry === undefined || !editor.api.isCollapsed()) {
    return false;
  }

  editor.tf.withNewBatch(() => {
    editor.tf.withoutNormalizing(() => {
      editor.tf.splitNodes({ always: true });
      const next = PathApi.next(entry[1]);
      if (next !== undefined) {
        editor.tf.unsetNodes(["footnoteId"], { at: next });
        editor.tf.setNodes({ type: KEYS.p }, { at: next });
      }
    });
  });
  return true;
}

// Backspace at the start keeps the text. The definition becomes a paragraph and nothing merges.
function backspaceFootnoteDefinition(editor: SlateEditor): boolean {
  const entry = footnoteDefinitionBlock(editor);
  if (entry === undefined || !editor.api.isCollapsed() || !editor.api.isAt({ start: true })) {
    return false;
  }

  editor.tf.withNewBatch(() => {
    editor.tf.setNodes({ type: KEYS.p }, { at: entry[1] });
    editor.tf.unsetNodes(["footnoteId"], { at: entry[1] });
  });
  return true;
}

function footnoteReferencePaths(editor: SlateEditor, path: number[]): number[][] {
  const paths: number[][] = [];
  for (const [, refPath] of editor.api.nodes({
    at: path,
    voids: true,
    match: (candidate) => ElementApi.isElement(candidate) && candidate.type === FOOTNOTE_REF_KEY,
  })) {
    paths.push(refPath);
  }

  return paths;
}

// Live rules for a definition that the editor creates or moves. Each rule makes one change and
// returns true, so Slate normalizes again. Every path ends as a valid block, so the loop stops.
function normalizeFootnoteDefinition(editor: SlateEditor, node: TElement, path: number[]): boolean {
  if (node.type !== FOOTNOTE_DEF_KEY) {
    return false;
  }

  const references = footnoteReferencePaths(editor, path);
  if (references.length > 0) {
    editor.tf.withoutNormalizing(() => {
      for (const refPath of [...references].reverse()) {
        editor.tf.removeNodes({ at: refPath, voids: true });
      }
    });
    return true;
  }

  const index = path[0];
  if (path.length !== 1 || index === undefined || !isFootnoteId(node.footnoteId)) {
    editor.tf.withoutNormalizing(() => {
      editor.tf.unsetNodes(["footnoteId"], { at: path });
      editor.tf.setNodes({ type: KEYS.p }, { at: path });
    });
    return true;
  }

  const footnoteId = node.footnoteId;
  const earlier = editor.children.some(
    (child, position) =>
      position < index &&
      ElementApi.isElement(child) &&
      child.type === FOOTNOTE_DEF_KEY &&
      child.footnoteId === footnoteId,
  );
  if (earlier) {
    editor.tf.setNodes({ footnoteId: createFootnoteId() }, { at: path });
    return true;
  }

  return false;
}

// Runs before the column and child-type normalizers, so a definition moved out of a column
// becomes a paragraph in place, not a lifted definition. Enter and Backspace rules are here too.
export const footnoteNormalizePlugin = createSlatePlugin({
  key: "footnoteNormalize",
}).overrideEditor(
  ({ editor, tf: { normalizeNode, insertBreak, deleteBackward, deleteForward } }) => ({
    transforms: {
      normalizeNode(entry) {
        const [node, path] = entry;
        if (ElementApi.isElement(node) && normalizeFootnoteDefinition(editor, node, path)) {
          return;
        }

        normalizeNode(entry);
      },
      insertBreak() {
        if (breakFootnoteDefinition(editor)) {
          return;
        }

        insertBreak();
      },
      deleteBackward(unit) {
        if (backspaceFootnoteDefinition(editor) || backspaceBeforeReference(editor)) {
          return;
        }

        deleteBackward(unit);
      },
      deleteForward(unit) {
        if (deleteForwardIntoReference(editor)) {
          return;
        }

        deleteForward(unit);
      },
    },
  }),
);

function containsReference(editor: SlateEditor, path: number[]): boolean {
  return !editor.api
    .nodes({
      at: path,
      voids: true,
      match: (candidate) => ElementApi.isElement(candidate) && candidate.type === FOOTNOTE_REF_KEY,
    })
    .next().done;
}

// Merging a block that holds a reference into the block above drops the reference. Backspace
// at the start of such a block after a definition moves the caret to the definition's end.
function backspaceBeforeReference(editor: SlateEditor): boolean {
  const block = editor.api.block();
  if (block === undefined || !editor.api.isCollapsed() || !editor.api.isAt({ start: true })) {
    return false;
  }

  const [, path] = block;
  const index = path[0];
  if (path.length !== 1 || index === undefined || index === 0) {
    return false;
  }

  const above = editor.children[index - 1];
  if (!ElementApi.isElement(above) || above.type !== FOOTNOTE_DEF_KEY) {
    return false;
  }

  if (!containsReference(editor, path)) {
    return false;
  }

  const end = editor.api.end([index - 1]);
  if (end === undefined) {
    return false;
  }
  editor.tf.select(end);
  return true;
}

// Delete at the end of a definition would merge the next block in. A block with a reference
// stays where it is, so Delete does nothing.
function deleteForwardIntoReference(editor: SlateEditor): boolean {
  const block = editor.api.block();
  if (
    block === undefined ||
    !ElementApi.isElement(block[0]) ||
    block[0].type !== FOOTNOTE_DEF_KEY
  ) {
    return false;
  }
  if (!editor.api.isCollapsed() || !editor.api.isAt({ end: true })) {
    return false;
  }

  const [, path] = block;
  const index = path[0];
  if (path.length !== 1 || index === undefined) {
    return false;
  }

  const below = editor.children[index + 1];
  if (below === undefined || !ElementApi.isElement(below)) {
    return false;
  }

  return containsReference(editor, [index + 1]);
}

import { ElementApi, KEYS, PathApi, createSlatePlugin, type SlateEditor } from "platejs";

import { runEditorCommand, type EditorCommand } from "../commands/editor-commands";
import {
  inlineDateEntry,
  inlineDateRefusal,
  insertInlineDate,
  removeInlineDate,
  setInlineDate,
} from "../features/editor-inline-date";
import { todayStoredDate } from "../features/editor-date-value";
import { blockSelectionActive } from "./editor-block-selection";
import { featureEnabled } from "./editor-config";

// The popover holds only which chip is open. Every choice writes at once, so there is no draft.
export const inlineDateUiPlugin = createSlatePlugin({
  key: "inlineDateUi",
  options: { editingId: "" },
}).overrideEditor(({ editor }) => {
  const { onChange } = editor;
  if (isEditorOnChange(onChange)) {
    editor.onChange = (options?: { operation?: unknown }) => {
      onChange(options);
      // A node removed while open, or a switch to read-only, closes the popover without writing.
      const id = inlineDateEditingId(editor);
      if (
        id.length > 0 &&
        (editor.dom.readOnly === true || inlineDateEntry(editor, id) === undefined)
      ) {
        resetInlineDateEditor(editor);
      }
    };
  }
  return { transforms: {} };
});

function isEditorOnChange(value: unknown): value is (options?: { operation?: unknown }) => void {
  return typeof value === "function";
}

export function inlineDateEditingId(editor: SlateEditor): string {
  return editor.getOption(inlineDateUiPlugin, "editingId");
}

// Drops the popover state without writing the document or moving the selection.
export function resetInlineDateEditor(editor: SlateEditor): void {
  editor.setOption(inlineDateUiPlugin, "editingId", "");
}

// The caret goes right after the chip and the editor takes focus. Used by every close.
function finishInlineDateEditor(editor: SlateEditor, id: string): void {
  resetInlineDateEditor(editor);
  selectAfterInlineDate(editor, id);
  editor.tf.focus();
}

function selectAfterInlineDate(editor: SlateEditor, id: string): void {
  const entry = inlineDateEntry(editor, id);
  if (entry === undefined) {
    return;
  }

  const after = editor.api.after(entry[1]);
  if (after !== undefined) {
    editor.tf.select(after);
  }
}

// Opens the popover on one chip. Opening another chip closes the open one first, without writing.
export function openInlineDateEditor(editor: SlateEditor, id: string): void {
  if (editor.dom.readOnly === true || blockSelectionActive(editor) || id.length === 0) {
    return;
  }

  if (inlineDateEditingId(editor) === id) {
    return;
  }

  const entry = inlineDateEntry(editor, id);
  if (entry === undefined) {
    return;
  }

  editor.setOption(inlineDateUiPlugin, "editingId", id);
  editor.tf.select(entry[1]);
}

// Escape and a press outside. Nothing is written, and the chip stays where it is.
export function closeInlineDateEditor(editor: SlateEditor): void {
  const id = inlineDateEditingId(editor);
  if (id.length === 0) {
    return;
  }

  finishInlineDateEditor(editor, id);
}

// A calendar pick or Today. The write is one undo step, and the same day only closes.
export function pickInlineDate(editor: SlateEditor, id: string, date: string): void {
  const entry = inlineDateEntry(editor, id);
  if (inlineDateEditingId(editor) !== id || entry === undefined) {
    resetInlineDateEditor(editor);
    return;
  }

  if (entry[0].date !== date) {
    runEditorCommand(editor, setInlineDate, { id, date });
  }
  finishInlineDateEditor(editor, id);
}

// Removes the chip as one undo step and closes the popover.
export function removeInlineDateFromPopover(editor: SlateEditor, id: string): void {
  if (inlineDateEditingId(editor) !== id) {
    return;
  }

  resetInlineDateEditor(editor);
  const entry = inlineDateEntry(editor, id);
  if (entry === undefined) {
    return;
  }

  const previous = PathApi.previous(entry[1]);
  const block = editor.api.block({ at: entry[1] });
  runEditorCommand(editor, removeInlineDate, { id });

  const target = previous === undefined ? undefined : editor.api.end(previous);
  if (target !== undefined) {
    editor.tf.select(target);
  } else if (block !== undefined) {
    const start = editor.api.start(block[1]);
    if (start !== undefined) {
      editor.tf.select(start);
    }
  }
  editor.tf.focus();
}

// Creates today's date at the selection and opens its popover. Escape keeps the chip.
export const insertTodayDate: EditorCommand = {
  id: "inline.date",
  label: "Date",
  group: "insert",
  isEnabled: (editor) => editor.dom.readOnly !== true && inlineDateRefusal(editor) === undefined,
  disabledReason: (editor) => {
    const refusal = inlineDateRefusal(editor);
    if (refusal === "span") {
      return "Dates cannot span blocks.";
    }

    return refusal === undefined ? undefined : "Dates are not available here.";
  },
  run: (editor) => {
    if (editor.selection === null) {
      return;
    }

    const id = insertInlineDate(editor, todayStoredDate());
    if (id !== null) {
      openInlineDateEditor(editor, id);
    }
  },
};

type InlineDateKeyEvent = {
  key: string;
  altKey: boolean;
  shiftKey: boolean;
  metaKey: boolean;
  ctrlKey: boolean;
  defaultPrevented: boolean;
  preventDefault: () => void;
};

// Mod+; inserts today's date. Enter on a selected inline date opens it.
export function onInlineDateKeyDown(editor: SlateEditor, event: InlineDateKeyEvent): void {
  if (event.defaultPrevented || event.altKey || editor.dom.readOnly === true) {
    return;
  }

  if ((event.metaKey || event.ctrlKey) && !event.shiftKey && event.key === ";") {
    if (featureEnabled(editor, "dates") && runEditorCommand(editor, insertTodayDate, undefined)) {
      event.preventDefault();
    }
    return;
  }

  if (event.key !== "Enter" || event.shiftKey || event.metaKey || event.ctrlKey) {
    return;
  }

  if (blockSelectionActive(editor)) {
    return;
  }

  const block = editor.api.above({
    match: (node) => ElementApi.isElement(node) && node.type === KEYS.date,
  });
  if (block === undefined || !ElementApi.isElement(block[0])) {
    return;
  }

  const id = typeof block[0].id === "string" ? block[0].id : "";
  if (id.length === 0) {
    return;
  }

  event.preventDefault();
  openInlineDateEditor(editor, id);
}

import {
  ElementApi,
  KEYS,
  PathApi,
  RangeApi,
  createSlatePlugin,
  type SlateEditor,
  type TElement,
} from "platejs";

import { runEditorCommand, type EditorCommand } from "../commands/editor-commands";
import { isStoredEquationExpression } from "../document/editor-document-schema";
import {
  inlineEquationEntry,
  inlineEquationRefusal,
  insertInlineEquation,
} from "../features/editor-inline-equation";
import { blockSelectionActive } from "./editor-block-selection";
import { featureEnabled } from "./editor-config";

// The popover edits a draft held in these options. The document is written once, on commit.
// createdUndoDepth is the undo depth before the node was inserted, or -1 when it was not created here.
export const inlineEquationUiPlugin = createSlatePlugin({
  key: "inlineEquationUi",
  options: { editingId: "", draft: "", original: "", created: false, createdUndoDepth: -1 },
}).overrideEditor(({ editor }) => {
  const { onChange } = editor;
  if (isEditorOnChange(onChange)) {
    editor.onChange = (options?: { operation?: unknown }) => {
      onChange(options);
      // A node removed while open, or a switch to read-only, closes the popover without writing.
      const id = inlineEquationEditingId(editor);
      if (
        id.length > 0 &&
        (editor.dom.readOnly === true || inlineEquationEntry(editor, id) === undefined)
      ) {
        resetInlineEquationState(editor);
      }
    };
  }
  return { transforms: {} };
});

function isEditorOnChange(value: unknown): value is (options?: { operation?: unknown }) => void {
  return typeof value === "function";
}

export function inlineEquationEditingId(editor: SlateEditor): string {
  return editor.getOption(inlineEquationUiPlugin, "editingId");
}

function storedSource(node: TElement): string {
  return typeof node.texExpression === "string" ? node.texExpression : "";
}

function resetInlineEquationState(editor: SlateEditor): void {
  editor.setOption(inlineEquationUiPlugin, "editingId", "");
  editor.setOption(inlineEquationUiPlugin, "draft", "");
  editor.setOption(inlineEquationUiPlugin, "original", "");
  editor.setOption(inlineEquationUiPlugin, "created", false);
  editor.setOption(inlineEquationUiPlugin, "createdUndoDepth", -1);
}

export function setInlineEquationDraft(editor: SlateEditor, draft: string): void {
  if (inlineEquationEditingId(editor).length === 0) {
    return;
  }

  editor.setOption(inlineEquationUiPlugin, "draft", draft);
}

// Opening another equation commits the open one first. A refused commit keeps both as they are.
export function openInlineEquationEditor(
  editor: SlateEditor,
  id: string,
  options: { created?: boolean; createdUndoDepth?: number } = {},
): void {
  if (editor.dom.readOnly === true || blockSelectionActive(editor) || id.length === 0) {
    return;
  }

  if (inlineEquationEditingId(editor) === id) {
    return;
  }

  if (inlineEquationEditingId(editor).length > 0 && !commitInlineEquationEditor(editor)) {
    return;
  }

  // The commit can remove a node and shift paths, so the entry is read after it.
  const entry = inlineEquationEntry(editor, id);
  if (entry === undefined) {
    return;
  }

  const stored = storedSource(entry[0]);
  editor.setOption(inlineEquationUiPlugin, "editingId", id);
  editor.setOption(inlineEquationUiPlugin, "draft", stored);
  editor.setOption(inlineEquationUiPlugin, "original", stored);
  editor.setOption(inlineEquationUiPlugin, "created", options.created === true);
  editor.setOption(inlineEquationUiPlugin, "createdUndoDepth", options.createdUndoDepth ?? -1);
  editor.tf.select(entry[1]);
}

// Returns false when the draft cannot be written, so the popover stays open.
export function commitInlineEquationEditor(editor: SlateEditor): boolean {
  const id = inlineEquationEditingId(editor);
  if (id.length === 0) {
    return false;
  }

  const draft = editor.getOption(inlineEquationUiPlugin, "draft").trim();
  if (draft.length > 0 && !isStoredEquationExpression(draft)) {
    return false;
  }

  const created = editor.getOption(inlineEquationUiPlugin, "created");
  const createdUndoDepth = editor.getOption(inlineEquationUiPlugin, "createdUndoDepth");
  resetInlineEquationState(editor);
  const entry = inlineEquationEntry(editor, id);
  if (entry === undefined) {
    return true;
  }

  if (draft.length === 0) {
    if (created) {
      removeCreatedInlineEquation(editor, id, createdUndoDepth);
    } else {
      removeInlineEquation(editor, id);
    }
  } else {
    if (draft !== storedSource(entry[0])) {
      runEditorCommand(editor, setInlineEquationSource, { id, expression: draft });
    }
    selectAfterInlineEquation(editor, id);
  }
  editor.tf.focus();
  return true;
}

// Removes a node that was just created with an empty source. Any other cancel only leaves the caret after it.
export function cancelInlineEquationEditor(editor: SlateEditor): void {
  const id = inlineEquationEditingId(editor);
  if (id.length === 0) {
    return;
  }

  const created = editor.getOption(inlineEquationUiPlugin, "created");
  const createdUndoDepth = editor.getOption(inlineEquationUiPlugin, "createdUndoDepth");
  resetInlineEquationState(editor);
  const entry = inlineEquationEntry(editor, id);
  if (entry !== undefined) {
    if (created && storedSource(entry[0]).length === 0) {
      removeCreatedInlineEquation(editor, id, createdUndoDepth);
    } else {
      selectAfterInlineEquation(editor, id);
    }
  }
  editor.tf.focus();
}

function selectAfterInlineEquation(editor: SlateEditor, id: string): void {
  const entry = inlineEquationEntry(editor, id);
  if (entry === undefined) {
    return;
  }

  const after = editor.api.after(entry[1]);
  if (after !== undefined) {
    editor.tf.select(after);
  }
}

// When the insertion is the only entry since it was made, undo it and drop its redo, so
// neither undo nor redo brings the empty node back. Otherwise remove it with a new entry.
function removeCreatedInlineEquation(
  editor: SlateEditor,
  id: string,
  createdUndoDepth: number,
): void {
  if (createdUndoDepth >= 0 && editor.history.undos.length === createdUndoDepth + 1) {
    const redoDepth = editor.history.redos.length;
    editor.tf.undo();
    editor.history.redos.splice(redoDepth);
    return;
  }

  removeInlineEquation(editor, id);
}

// The caret goes to the end of the text before the node, or to the start of the block when there is none.
function removeInlineEquation(editor: SlateEditor, id: string): void {
  const entry = inlineEquationEntry(editor, id);
  if (entry === undefined) {
    return;
  }

  const previous = PathApi.previous(entry[1]);
  const block = editor.api.block({ at: entry[1] });
  runEditorCommand(editor, removeInlineEquationNode, { id });

  const target = previous === undefined ? undefined : editor.api.end(previous);
  if (target !== undefined) {
    editor.tf.select(target);
  } else if (block !== undefined) {
    const start = editor.api.start(block[1]);
    if (start !== undefined) {
      editor.tf.select(start);
    }
  }
}

const setInlineEquationSource: EditorCommand<{ id: string; expression: string }> = {
  id: "inline.equation.source",
  label: "Edit equation",
  group: "action",
  run: (editor, { id, expression }) => {
    const entry = inlineEquationEntry(editor, id);
    if (entry !== undefined) {
      editor.tf.setNodes({ texExpression: expression }, { at: entry[1], voids: true });
    }
  },
};

const removeInlineEquationNode: EditorCommand<{ id: string }> = {
  id: "inline.equation.remove",
  label: "Remove equation",
  group: "action",
  run: (editor, { id }) => {
    const entry = inlineEquationEntry(editor, id);
    if (entry !== undefined) {
      editor.tf.removeNodes({ at: entry[1], voids: true });
    }
  },
};

export const toggleInlineEquation: EditorCommand = {
  id: "inline.equation",
  label: "Equation",
  group: "insert",
  isEnabled: (editor) =>
    editor.dom.readOnly !== true &&
    featureEnabled(editor, "equations") &&
    inlineEquationRefusal(editor) === undefined,
  disabledReason: (editor) => {
    const refusal = inlineEquationRefusal(editor);
    if (refusal === "span") {
      return "Equations cannot span blocks.";
    }

    return refusal === undefined ? undefined : "Equations are not available here.";
  },
  run: (editor) => {
    const selection = editor.selection;
    if (selection === null) {
      return;
    }

    // A caret makes an empty equation. A selection becomes its source, and cancel keeps it.
    const created = RangeApi.isCollapsed(selection);
    const undoDepth = editor.history.undos.length;
    const id = insertInlineEquation(editor, created ? "" : editor.api.string(selection));
    if (id !== null) {
      openInlineEquationEditor(editor, id, { created, createdUndoDepth: undoDepth });
    }
  },
};

type InlineEquationKeyEvent = {
  key: string;
  altKey: boolean;
  shiftKey: boolean;
  metaKey: boolean;
  ctrlKey: boolean;
  defaultPrevented: boolean;
  preventDefault: () => void;
};

// Mod+Shift+E inserts or wraps an equation. Enter on a selected inline equation opens it.
export function onInlineEquationKeyDown(editor: SlateEditor, event: InlineEquationKeyEvent): void {
  if (event.defaultPrevented || event.altKey || editor.dom.readOnly === true) {
    return;
  }

  if ((event.metaKey || event.ctrlKey) && event.shiftKey && event.key.toLowerCase() === "e") {
    // With equations off the key is not handled, so the browser keeps its default.
    if (!featureEnabled(editor, "equations")) {
      return;
    }
    event.preventDefault();
    runEditorCommand(editor, toggleInlineEquation, undefined);
    return;
  }

  if (event.key !== "Enter" || event.shiftKey || event.metaKey || event.ctrlKey) {
    return;
  }

  if (blockSelectionActive(editor)) {
    return;
  }

  const block = editor.api.above({
    match: (node) => ElementApi.isElement(node) && node.type === KEYS.inlineEquation,
  });
  if (block === undefined || !ElementApi.isElement(block[0])) {
    return;
  }

  const id = typeof block[0].id === "string" ? block[0].id : "";
  if (id.length === 0) {
    return;
  }

  event.preventDefault();
  openInlineEquationEditor(editor, id);
}

import {
  ElementApi,
  KEYS,
  NodeApi,
  TextApi,
  createSlatePlugin,
  type SlateEditor,
  type TElement,
  type TRange,
} from "platejs";

import {
  formatBold,
  formatCode,
  formatItalic,
  formatStrikethrough,
  insertDivider,
  setListRestart,
  writeChecked,
} from "../commands/editor-commands";
import {
  applyBlockTurn,
  blockMenuDecisions,
  blockPlacementRefusal,
  menuBlockView,
  type BlockMenuKind,
} from "../features/editor-block-menu";
import {
  matchBlockInputTrigger,
  matchInlineInputTrigger,
  type InlineInputMark,
} from "../features/editor-input-rules";
import { itemFeatureEnabled } from "./editor-config";

const justConverted = new WeakSet<SlateEditor>();
const compositionPending = new WeakSet<SlateEditor>();
const pasteDepth = new WeakMap<SlateEditor, number>();
const applying = new WeakSet<SlateEditor>();

const MARK_COMMAND = {
  bold: formatBold,
  italic: formatItalic,
  strikethrough: formatStrikethrough,
  code: formatCode,
} as const satisfies Record<InlineInputMark, { run: (editor: SlateEditor) => void; key?: string }>;

const MARK_KEY: Record<InlineInputMark, string> = {
  bold: KEYS.bold,
  italic: KEYS.italic,
  strikethrough: KEYS.strikethrough,
  code: KEYS.code,
};

function isPasting(editor: SlateEditor): boolean {
  return (pasteDepth.get(editor) ?? 0) > 0;
}

function runAsPaste(editor: SlateEditor, apply: () => void): void {
  pasteDepth.set(editor, (pasteDepth.get(editor) ?? 0) + 1);
  try {
    apply();
  } finally {
    const next = (pasteDepth.get(editor) ?? 1) - 1;
    if (next <= 0) {
      pasteDepth.delete(editor);
    } else {
      pasteDepth.set(editor, next);
    }
  }
}

type TextPoint = { path: number[]; offset: number };

function walkText(
  editor: SlateEditor,
  node: TElement | { text: string },
  path: number[],
  start: number,
  end: number,
  state: { offset: number; anchor?: TextPoint; focus?: TextPoint; dirty: boolean },
): void {
  if (state.dirty) {
    return;
  }

  if (TextApi.isText(node)) {
    const next = state.offset + node.text.length;
    if (start < next && end > state.offset && node[KEYS.code] === true) {
      state.dirty = true;
      return;
    }

    if (state.anchor === undefined && start >= state.offset && start <= next) {
      state.anchor = { path: [...path], offset: start - state.offset };
    }

    if (state.focus === undefined && end >= state.offset && end <= next) {
      state.focus = { path: [...path], offset: end - state.offset };
    }

    state.offset = next;
    return;
  }

  if (!ElementApi.isElement(node)) {
    return;
  }

  if (editor.api.isInline(node)) {
    const length = NodeApi.string(node).length;
    if (start < state.offset + length && end > state.offset) {
      state.dirty = true;
      return;
    }

    state.offset += length;
    return;
  }

  node.children.forEach((child, index) => {
    walkText(editor, child as TElement, path.concat(index), start, end, state);
  });
}

function rangeForOffsets(
  editor: SlateEditor,
  blockPath: number[],
  start: number,
  end: number,
): TRange | "dirty" | null {
  const entry = editor.api.node(blockPath);
  const node = entry?.[0];
  if (!entry || !ElementApi.isElement(node)) {
    return null;
  }

  const state: { offset: number; anchor?: TextPoint; focus?: TextPoint; dirty: boolean } = {
    offset: 0,
    dirty: false,
  };
  walkText(editor, node, [...blockPath], start, end, state);
  if (state.dirty) {
    return "dirty";
  }

  if (state.anchor === undefined || state.focus === undefined) {
    return null;
  }

  return { anchor: state.anchor, focus: state.focus };
}

function textBeforeCaret(editor: SlateEditor, blockPath: number[]): string | null {
  const selection = editor.selection;
  const start = editor.api.start(blockPath);
  if (!selection || !start) {
    return null;
  }

  return editor.api.string({ anchor: start, focus: selection.anchor });
}

function charAfterInBlock(editor: SlateEditor, blockPath: number[]): string | undefined {
  const selection = editor.selection;
  if (!selection) {
    return undefined;
  }

  const after = editor.api.after(selection, { distance: 1, unit: "character" });
  if (!after || after.path.length < blockPath.length) {
    return undefined;
  }

  if (!blockPath.every((value, index) => after.path[index] === value)) {
    return undefined;
  }

  const text = editor.api.string({ anchor: selection.anchor, focus: after });
  return text.length > 0 ? text : undefined;
}

function paragraphAllowsTrigger(editor: SlateEditor): number[] | null {
  // The lowest block above the caret, read from its ancestors. `api.block()` would walk
  // the document from its root to the caret.
  const block = editor.selection ? editor.api.above({ block: true }) : undefined;
  if (!block || !ElementApi.isElement(block[0])) {
    return null;
  }

  if (editor.api.above({ match: { type: editor.getType(KEYS.codeBlock) } }) !== undefined) {
    return null;
  }

  const view = menuBlockView(editor, block[1]);
  if (
    !view ||
    view.type !== KEYS.p ||
    view.listStyleType !== undefined ||
    view.parentType === KEYS.th
  ) {
    return null;
  }

  return block[1];
}

function applyBlockTrigger(editor: SlateEditor): boolean {
  const selection = editor.selection;
  const path = paragraphAllowsTrigger(editor);
  if (!selection || !path || !editor.api.isCollapsed()) {
    return false;
  }

  const before = textBeforeCaret(editor, path);
  if (before === null) {
    return false;
  }

  const trigger = matchBlockInputTrigger(before);
  if (trigger === null) {
    return false;
  }

  if (rangeForOffsets(editor, path, 0, before.length) === "dirty") {
    return false;
  }

  const view = menuBlockView(editor, path);
  if (!view) {
    return false;
  }

  const start = editor.api.start(path);
  if (!start) {
    return false;
  }

  if (trigger.kind === "divider") {
    if (path.length !== 1) {
      return false;
    }

    if (blockPlacementRefusal(view.parentType, view.index, KEYS.hr, false) !== undefined) {
      return false;
    }

    editor.tf.withNewBatch(() => {
      editor.tf.delete({ at: { anchor: start, focus: selection.anchor } });
      insertDivider.run(editor);
    });
    editor.tf.setSplittingOnce(true);
    return true;
  }

  // A trigger for a feature that is off does not fire, so the typed text stays.
  if (!itemFeatureEnabled(editor, trigger.kind)) {
    return false;
  }

  const kind: BlockMenuKind = trigger.kind;
  const decision = blockMenuDecisions(view)?.find((item) => item.kind === kind);
  if (decision === undefined || !decision.allowed || decision.effect === "same") {
    return false;
  }

  editor.tf.withNewBatch(() => {
    const focus = editor.selection?.anchor ?? selection.anchor;
    editor.tf.delete({ at: { anchor: start, focus } });
    applyBlockTurn(editor, path, kind);
    if (kind === "numbered" && trigger.restart !== undefined) {
      setListRestart.run(editor, trigger.restart);
    }

    if (kind === "todo" && trigger.checked === true) {
      writeChecked(editor, [path], true);
    }
  });
  editor.tf.setSplittingOnce(true);
  return true;
}

function applyInlineTrigger(editor: SlateEditor): boolean {
  const selection = editor.selection;
  const path = paragraphAllowsTrigger(editor);
  if (!selection || !path || !editor.api.isCollapsed() || insideLink(editor)) {
    return false;
  }

  const before = textBeforeCaret(editor, path);
  if (before === null) {
    return false;
  }

  const match = matchInlineInputTrigger(before, charAfterInBlock(editor, path));
  if (match === null) {
    return false;
  }

  const open = rangeForOffsets(editor, path, match.openStart, match.openEnd);
  const close = rangeForOffsets(editor, path, match.closeStart, match.closeEnd);
  const inner = rangeForOffsets(editor, path, match.openEnd, match.closeStart);
  if (
    open === "dirty" ||
    close === "dirty" ||
    inner === "dirty" ||
    open === null ||
    close === null ||
    inner === null
  ) {
    return false;
  }

  const command = MARK_COMMAND[match.mark];
  const key = MARK_KEY[match.mark];
  editor.tf.withNewBatch(() => {
    editor.tf.delete({ at: close });
    editor.tf.delete({ at: open });
    const nextInner = rangeForOffsets(
      editor,
      path,
      match.openStart,
      match.openStart + (match.closeStart - match.openEnd),
    );
    if (nextInner === null || nextInner === "dirty") {
      return;
    }

    editor.tf.select(nextInner);
    command.run(editor);
    editor.tf.collapse({ edge: "end" });
    editor.tf.removeMark(key);
  });
  editor.tf.setSplittingOnce(true);
  return true;
}

function insideLink(editor: SlateEditor): boolean {
  return editor.api.above({ match: { type: editor.getType(KEYS.link) } }) !== undefined;
}

function applyTypedTrigger(editor: SlateEditor): boolean {
  if (applying.has(editor)) {
    return false;
  }

  applying.add(editor);
  try {
    return applyBlockTrigger(editor) || applyInlineTrigger(editor);
  } finally {
    applying.delete(editor);
  }
}

function isComposing(editor: SlateEditor, options: unknown): boolean {
  const composingOption =
    typeof options === "object" &&
    options !== null &&
    "composing" in options &&
    options.composing === true;
  if (composingOption || editor.composing === true) {
    return true;
  }

  const dom: unknown = editor.dom;
  return typeof dom === "object" && dom !== null && "composing" in dom && dom.composing === true;
}

export const editorInputRulesPlugin = createSlatePlugin({
  key: "editorInputRules",
}).overrideEditor(
  ({ editor, tf: { deleteBackward, insertData, insertFragment, insertText, redo, undo } }) => ({
    transforms: {
      insertData(data) {
        justConverted.delete(editor);
        runAsPaste(editor, () => {
          insertData(data);
        });
      },
      insertFragment(fragment, options) {
        justConverted.delete(editor);
        runAsPaste(editor, () => {
          insertFragment(fragment, options);
        });
      },
      insertText(text, options) {
        const composing = isComposing(editor, options);
        const commit = !composing && compositionPending.has(editor);
        if (composing) {
          compositionPending.add(editor);
        } else if (commit) {
          compositionPending.delete(editor);
        }

        const expanded = editor.selection !== null && !editor.api.isCollapsed();
        insertText(text, options);
        if (composing || commit || expanded || isPasting(editor) || applying.has(editor)) {
          if (!applying.has(editor)) {
            justConverted.delete(editor);
          }
          return;
        }

        if (applyTypedTrigger(editor)) {
          justConverted.add(editor);
          return;
        }

        justConverted.delete(editor);
      },
      deleteBackward(unit) {
        if (justConverted.has(editor)) {
          justConverted.delete(editor);
          editor.tf.undo();
          return;
        }

        deleteBackward(unit);
      },
      undo() {
        justConverted.delete(editor);
        undo();
      },
      redo() {
        justConverted.delete(editor);
        redo();
      },
    },
  }),
);

import { createElement, type ReactNode } from "react";
import { BaseLinkPlugin, unwrapLink, upsertLinkText } from "@platejs/link";
import {
  ElementApi,
  KEYS,
  PathApi,
  RangeApi,
  TextApi,
  createSlatePlugin,
  type SlateEditor,
  type TElement,
  type TRange,
} from "platejs";

import type { EditorCommand } from "../commands/editor-commands";
import { selectionInCodeBlock } from "../features/editor-code";
import { elementAllowsMarks, isVoidElementType } from "../document/editor-document-schema";
import {
  clearUnsafePastedLinkRepairs,
  isExternalLinkUrl,
  normalizeLinkInput,
  noteUnsafePastedLink,
  sanitizeLinkUrl,
  typedAutolinkUrl,
} from "../features/editor-link-url";

// Native LinkRules.autolink (dist/index.js getAutolinkMatch) keeps trailing
// punctuation in the link and does not skip code blocks. submitFloatingLink
// writes target. This plugin never stores target or rel.

const TRAILING_PUNCTUATION = new Set([
  ".",
  ",",
  ";",
  ":",
  "!",
  "?",
  ")",
  '"',
  "'",
  "\u201d",
  "\u2019",
]);
const LEADING_PUNCTUATION = new Set(["(", '"', "'", "\u201c", "\u2018"]);

const savedSelections = new WeakMap<SlateEditor, TRange>();
const hoverCloseTimers = new WeakMap<SlateEditor, ReturnType<typeof setTimeout>>();

const LINK_HOVER_CLOSE_MS = 200;

export function linkAnchorRange(editor: SlateEditor): TRange | null {
  return savedSelections.get(editor) ?? editor.selection;
}

type HighlightProps = {
  attributes?: { className?: string };
  children?: ReactNode;
};

function LinkAnchorHighlight({ attributes, children }: HighlightProps) {
  const slateClass = typeof attributes?.className === "string" ? attributes.className : "";
  return createElement(
    "span",
    {
      ...attributes,
      "data-link-anchor-highlight": "",
      className: `${slateClass} rounded-sm bg-accent`.trim(),
    },
    children,
  );
}

export const linkUiPlugin = createSlatePlugin({
  key: "linkUi",
  node: {
    isLeaf: true,
    isDecoration: true,
  },
  render: {
    node: LinkAnchorHighlight,
  },
  options: {
    mode: "closed",
    draftUrl: "",
    draftLabel: "",
    error: "",
    hoverId: "",
    hold: null as TRange | null,
  },
  decorate: ({ editor, entry }) => {
    const mode = editor.getOption(linkUiPlugin, "mode");
    const anchor =
      mode === "closed" ? editor.getOption(linkUiPlugin, "hold") : savedSelections.get(editor);
    const node = entry[0];
    const path = entry[1];
    if (!anchor || !TextApi.isText(node)) {
      return undefined;
    }

    const start = editor.api.start(path);
    const end = editor.api.end(path);
    if (!start || !end) {
      return undefined;
    }

    const intersection = RangeApi.intersection(anchor, { anchor: start, focus: end });
    if (!intersection) {
      return undefined;
    }

    return [{ ...intersection, linkUi: true }];
  },
});

export const linkPlugin = BaseLinkPlugin.configure({
  options: {
    allowedSchemes: ["http", "https", "mailto", "tel"],
    isUrl: (text) => sanitizeLinkUrl(text) !== undefined,
    keepSelectedTextOnPaste: true,
    defaultLinkAttributes: {},
  },
  node: {
    dangerouslyAllowAttributes: [],
  },
  parsers: {
    html: {
      deserializer: {
        rules: [{ validNodeName: "A" }],
        parse: ({ element, type }) => {
          const href = element.getAttribute("href");
          if (href === null || href.length === 0) {
            return undefined;
          }

          const url = sanitizeLinkUrl(href);
          if (url === undefined) {
            noteUnsafePastedLink();
            return undefined;
          }

          return { type, url };
        },
      },
    },
  },
}).overrideEditor(({ editor, tf: { insertBreak, insertData, insertText, normalizeNode } }) => ({
  transforms: {
    insertText(text, options) {
      if (
        text === " " &&
        (options === undefined || options.at === undefined) &&
        autolinkMatch(editor) !== undefined
      ) {
        // The space and the wrap are one undo. Earlier URL characters stay.
        editor.tf.withNewBatch(() => {
          applyAutolink(editor);
          insertText(text, options);
        });
        editor.tf.setSplittingOnce(true);
        return;
      }

      insertText(text, options);
    },
    insertBreak() {
      if (autolinkMatch(editor) !== undefined) {
        editor.tf.withNewBatch(() => {
          applyAutolink(editor);
          insertBreak();
        });
        editor.tf.setSplittingOnce(true);
        return;
      }

      insertBreak();
    },
    insertData(data) {
      clearUnsafePastedLinkRepairs();
      const html = data.getData("text/html");
      const url = html.trim().length === 0 ? pastedLinkUrl(data.getData("text/plain")) : undefined;
      if (url !== undefined && !selectionInCodeBlock(editor)) {
        insertPastedLink(editor, url);
        return;
      }

      insertData(data);
    },
    normalizeNode(entry) {
      const [node, path] = entry;
      if (ElementApi.isElement(node) && node.type === editor.getType(KEYS.link)) {
        if (normalizeLinkNode(editor, node, path)) {
          return;
        }
      }

      normalizeNode(entry);
    },
  },
}));

export function setLinkComposing(editor: SlateEditor, composing: boolean): void {
  editor.composing = composing;
}

type LinkKeyEvent = {
  key: string;
  altKey: boolean;
  shiftKey: boolean;
  metaKey: boolean;
  ctrlKey: boolean;
  preventDefault: () => void;
  stopPropagation: () => void;
};

export function onLinkKeyDown(editor: SlateEditor, event: LinkKeyEvent): boolean {
  if (event.altKey || event.shiftKey || event.key.toLowerCase() !== "k") {
    return false;
  }

  if (!event.metaKey && !event.ctrlKey) {
    return false;
  }

  if (editor.dom.readOnly === true) {
    return false;
  }

  event.preventDefault();
  event.stopPropagation();
  openLinkPopover(editor);
  return true;
}

export function openLinkPopover(editor: SlateEditor): void {
  if (editor.dom.readOnly === true || editor.selection === null) {
    return;
  }

  savedSelections.set(editor, editor.selection);
  editor.setOption(linkUiPlugin, "error", "");

  const existing = linkEntry(editor);
  if (existing !== undefined) {
    const url = typeof existing[0].url === "string" ? existing[0].url : "";
    editor.setOption(linkUiPlugin, "mode", "edit");
    editor.setOption(linkUiPlugin, "draftUrl", url);
    editor.setOption(linkUiPlugin, "draftLabel", editor.api.string(existing[1]));
    editor.api.redecorate();
    return;
  }

  editor.setOption(linkUiPlugin, "mode", editor.api.isCollapsed() ? "label" : "insert");
  editor.setOption(linkUiPlugin, "draftUrl", "");
  editor.setOption(linkUiPlugin, "draftLabel", "");
  editor.api.redecorate();
}

export function holdSelectionHighlight(editor: SlateEditor, range: TRange | null): void {
  const current = editor.getOption(linkUiPlugin, "hold");
  if (current === range) {
    return;
  }
  if (current && range && JSON.stringify(current) === JSON.stringify(range)) {
    return;
  }

  editor.setOption(linkUiPlugin, "hold", range);
  editor.api.redecorate();
}

export function closeLinkPopover(editor: SlateEditor): void {
  savedSelections.delete(editor);
  editor.setOption(linkUiPlugin, "mode", "closed");
  editor.setOption(linkUiPlugin, "error", "");
  editor.api.redecorate();
}

// Escape and Remove link: the popover input is removed, so focus goes back to the editor
// on the range the popover was opened on.
export function cancelLinkPopover(editor: SlateEditor): void {
  const saved = savedSelections.get(editor);
  closeLinkPopover(editor);
  if (saved !== undefined) {
    editor.tf.select(saved);
  }
  editor.tf.focus();
}

export function commitLinkPopover(editor: SlateEditor, urlRaw: string, labelRaw: string): boolean {
  const url = sanitizeLinkUrl(normalizeLinkInput(urlRaw));
  if (url === undefined) {
    editor.setOption(linkUiPlugin, "error", "Enter a valid URL.");
    return false;
  }

  const mode = editor.getOption(linkUiPlugin, "mode");
  const saved = savedSelections.get(editor);
  const label = labelRaw.trim().length > 0 ? labelRaw.trim() : url;
  editor.tf.withNewBatch(() => {
    if (saved !== undefined) {
      editor.tf.select(saved);
    }

    if (mode === "edit") {
      updateLink(editor, url, label);
      return;
    }

    if (saved !== undefined && !RangeApi.isCollapsed(saved)) {
      wrapSelection(editor, url);
      return;
    }

    insertLinkNode(editor, url, label);
  });
  editor.tf.setSplittingOnce(true);
  closeLinkPopover(editor);
  // Save keeps the selection the command left, so focus goes to the editor without restoring it.
  editor.tf.focus();
  return true;
}

export function cancelLinkHoverClose(editor: SlateEditor): void {
  const timer = hoverCloseTimers.get(editor);
  if (timer === undefined) {
    return;
  }

  clearTimeout(timer);
  hoverCloseTimers.delete(editor);
}

export function scheduleLinkHoverClose(editor: SlateEditor): void {
  cancelLinkHoverClose(editor);
  const timer = setTimeout(() => {
    hoverCloseTimers.delete(editor);
    const active = document.activeElement;
    if (active instanceof Element && active.closest("[data-link-toolbar]") !== null) {
      return;
    }

    setLinkHover(editor, "");
  }, LINK_HOVER_CLOSE_MS);
  hoverCloseTimers.set(editor, timer);
}

export function setLinkHover(editor: SlateEditor, id: string): void {
  cancelLinkHoverClose(editor);
  if (editor.getOption(linkUiPlugin, "hoverId") === id) {
    return;
  }

  editor.setOption(linkUiPlugin, "hoverId", id);
}

function openLinkUrl(url: string): void {
  const safe = sanitizeLinkUrl(url);
  if (safe === undefined || typeof window === "undefined") {
    return;
  }

  const features = isExternalLinkUrl(safe) ? "noopener,noreferrer" : undefined;
  window.open(safe, isExternalLinkUrl(safe) ? "_blank" : "_self", features);
}

export const insertInlineLink: EditorCommand = {
  id: "inline.link.insert",
  label: "Link",
  group: "insert",
  isEnabled: (editor) => editor.dom.readOnly !== true && editor.selection !== null,
  run: (editor) => {
    openLinkPopover(editor);
  },
};

export const editInlineLink: EditorCommand = {
  id: "inline.link.edit",
  label: "Edit link",
  group: "action",
  isEnabled: (editor) => editor.dom.readOnly !== true && linkEntry(editor) !== undefined,
  run: (editor) => {
    openLinkPopover(editor);
  },
};

export const removeInlineLink: EditorCommand = {
  id: "inline.link.remove",
  label: "Remove link",
  group: "action",
  isEnabled: (editor) => editor.dom.readOnly !== true && linkEntry(editor) !== undefined,
  run: (editor) => {
    unwrapLink(editor);
  },
};

export const openInlineLink: EditorCommand = {
  id: "inline.link.open",
  label: "Open link",
  group: "action",
  isEnabled: (editor) => selectedLinkUrl(editor) !== undefined,
  run: (editor) => {
    const url = selectedLinkUrl(editor);
    if (url !== undefined) {
      openLinkUrl(url);
    }
  },
};

type LinkMatch = {
  anchor: NonNullable<SlateEditor["selection"]>["anchor"];
  focus: NonNullable<SlateEditor["selection"]>["focus"];
  url: string;
  trailing: string;
};

function linkIsComposing(editor: SlateEditor): boolean {
  if (editor.composing === true) {
    return true;
  }

  const dom: unknown = editor.dom;
  return typeof dom === "object" && dom !== null && "composing" in dom && dom.composing === true;
}

function linkEntry(editor: SlateEditor): [TElement, number[]] | undefined {
  const entry = editor.api.above({
    match: (node) => ElementApi.isElement(node) && node.type === editor.getType(KEYS.link),
  });
  if (entry === undefined || !ElementApi.isElement(entry[0])) {
    return undefined;
  }

  return [entry[0], entry[1]];
}

function selectedLinkUrl(editor: SlateEditor): string | undefined {
  const entry = linkEntry(editor);
  if (entry === undefined || typeof entry[0].url !== "string") {
    return undefined;
  }

  return sanitizeLinkUrl(entry[0].url);
}

function pastedLinkUrl(plain: string): string | undefined {
  const trimmed = plain.trim();
  if (trimmed.length === 0 || /\s/.test(trimmed)) {
    return undefined;
  }

  return sanitizeLinkUrl(trimmed);
}

function insertPastedLink(editor: SlateEditor, url: string): void {
  if (!editor.api.isCollapsed()) {
    wrapSelection(editor, url);
    return;
  }

  if (linkEntry(editor) !== undefined) {
    editor.tf.insertText(url);
    return;
  }

  insertLinkNode(editor, url, url);
}

function insertLinkNode(editor: SlateEditor, url: string, label: string): void {
  editor.tf.insertNodes({
    type: editor.getType(KEYS.link),
    url,
    children: [linkLeaf(label, editor.api.marks())],
  });
  const entry = linkEntry(editor);
  if (entry === undefined) {
    return;
  }

  moveAfterLink(editor, entry[1]);
}

function linkLeaf(label: string, marks: ReturnType<SlateEditor["api"]["marks"]>): { text: string } {
  const leaf: { text: string } & Record<string, unknown> = { text: label };
  if (marks === null) {
    return leaf;
  }

  for (const [key, value] of Object.entries(marks)) {
    if (key !== "text") {
      leaf[key] = value;
    }
  }

  return leaf;
}

function wrapSelection(editor: SlateEditor, url: string): void {
  unwrapLink(editor, { split: true });
  editor.tf.wrapNodes({ type: editor.getType(KEYS.link), url, children: [] }, { split: true });
}

function updateLink(editor: SlateEditor, url: string, label: string): void {
  const entry = linkEntry(editor);
  if (entry === undefined) {
    return;
  }

  editor.tf.setNodes({ url }, { at: entry[1] });
  if (editor.api.string(entry[1]) !== label) {
    upsertLinkText(editor, { text: label, url });
  }
}

function applyAutolink(editor: SlateEditor): boolean {
  const match = autolinkMatch(editor);
  if (match === undefined) {
    return false;
  }

  editor.tf.withoutNormalizing(() => {
    editor.tf.select({ anchor: match.anchor, focus: match.focus });
    editor.tf.wrapNodes(
      { type: editor.getType(KEYS.link), url: match.url, children: [] },
      { split: true },
    );
    const entry = linkEntry(editor);
    if (entry === undefined) {
      return;
    }

    if (match.trailing.length === 0) {
      moveAfterLink(editor, entry[1]);
      return;
    }

    const next = PathApi.next(entry[1]);
    editor.tf.select({ path: next, offset: match.trailing.length });
  });
  return true;
}

function moveAfterLink(editor: SlateEditor, linkPath: number[]): void {
  const next = editor.api.start(linkPath, { next: true });
  if (next !== undefined) {
    editor.tf.select(next);
    return;
  }

  const nextPath = PathApi.next(linkPath);
  editor.tf.insertNodes({ text: "" }, { at: nextPath });
  editor.tf.select({ path: nextPath, offset: 0 });
}

function autolinkMatch(editor: SlateEditor): LinkMatch | undefined {
  if (linkIsComposing(editor) || selectionInCodeBlock(editor)) {
    return undefined;
  }

  const selection = editor.selection;
  if (selection === null || selection === undefined || !editor.api.isCollapsed()) {
    return undefined;
  }

  let before = editor.api.range("before", selection, {
    before: {
      afterMatch: true,
      matchBlockStart: true,
      matchString: " ",
      skipInvalid: true,
    },
  });
  if (!before) {
    before = editor.api.range("start", selection);
  }
  if (!before) {
    return undefined;
  }

  if (
    editor.api.some({
      at: before,
      match: { type: editor.getType(KEYS.link) },
    })
  ) {
    return undefined;
  }

  const text = editor.api.string(before);
  const token = trimLinkToken(text);
  if (token === undefined) {
    return undefined;
  }

  const anchor =
    token.lead === 0
      ? before.anchor
      : editor.api.after(before.anchor, { distance: token.lead, unit: "character" });
  const focus =
    token.trailing.length === 0
      ? selection.anchor
      : editor.api.before(selection.anchor, {
          distance: token.trailing.length,
          unit: "character",
        });
  if (anchor === undefined || focus === undefined) {
    return undefined;
  }

  return { anchor, focus, url: token.url, trailing: token.trailing };
}

function trimLinkToken(text: string): { url: string; lead: number; trailing: string } | undefined {
  let end = text.length;
  while (end > 0 && TRAILING_PUNCTUATION.has(text.charAt(end - 1))) {
    end -= 1;
  }

  const direct = typedAutolinkUrl(text.slice(0, end));
  if (direct !== undefined) {
    return { url: direct, lead: 0, trailing: text.slice(end) };
  }

  if (end > 1 && LEADING_PUNCTUATION.has(text.charAt(0))) {
    const wrapped = typedAutolinkUrl(text.slice(1, end));
    if (wrapped !== undefined) {
      return { url: wrapped, lead: 1, trailing: text.slice(end) };
    }
  }

  return undefined;
}

function normalizeLinkNode(editor: SlateEditor, node: TElement, path: number[]): boolean {
  if ("target" in node || "rel" in node) {
    const drop = ["target", "rel"].filter((key) => key in node);
    editor.tf.unsetNodes(drop, { at: path });
    return true;
  }

  const parent = editor.api.parent(path);
  const parentType =
    parent !== undefined && ElementApi.isElement(parent[0]) ? parent[0].type : undefined;
  if (
    parentType === KEYS.codeLine ||
    parentType === KEYS.codeBlock ||
    parentType === KEYS.link ||
    (parentType !== undefined && (!elementAllowsMarks(parentType) || isVoidElementType(parentType)))
  ) {
    editor.tf.unwrapNodes({ at: path });
    return true;
  }

  const url = typeof node.url === "string" ? node.url : "";
  if (sanitizeLinkUrl(url) !== url) {
    editor.tf.unwrapNodes({ at: path });
    return true;
  }

  if (editor.api.string(path).length === 0) {
    editor.tf.removeNodes({ at: path });
    return true;
  }

  return false;
}

import { ElementApi, createSlatePlugin, type SlateEditor } from "platejs";
import { toPlatePlugin } from "platejs/react";

import { isMediaBlockType } from "../features/editor-media-source";
import { findBlockById } from "../features/editor-synced-block";
import type { UploadController } from "../features/editor-upload-controller";
import { blockSelectionActive } from "./editor-block-selection";
import { featureEnabled } from "./editor-config";

// Which media block has its source popover, action popover or hover toolbar open. Each holds one
// block id, or the empty string when closed. Any block type can use them.
type MediaUiOptions = {
  source: string;
  actions: string;
  hoverId: string;
};

function mediaUiOptions(): MediaUiOptions {
  return { source: "", actions: "", hoverId: "" };
}

function isEditorOnChange(value: unknown): value is (options?: { operation?: unknown }) => void {
  return typeof value === "function";
}

export const mediaUiPlugin = createSlatePlugin({
  key: "mediaUi",
  options: mediaUiOptions(),
}).overrideEditor(({ editor }) => {
  const { onChange } = editor;
  if (isEditorOnChange(onChange)) {
    editor.onChange = (options?: { operation?: unknown }) => {
      onChange(options);
      const readOnly = editor.dom.readOnly === true;
      if (readOnly) {
        closeMediaSource(editor);
        closeMediaActions(editor);
      }
      reconcileUploads(editor, readOnly);
    };
  }
  return { transforms: {} };
});

// The upload controller of the mounted file scope. Null when no adapter is set.
const controllers = new WeakMap<SlateEditor, UploadController>();

export function attachUploadController(editor: SlateEditor, controller: UploadController | null) {
  if (controller === null) {
    controllers.delete(editor);
    return;
  }

  controllers.set(editor, controller);
}

// With media off there is no upload controller, the same as with no adapter.
export function uploadControllerOf(editor: SlateEditor): UploadController | null {
  if (!featureEnabled(editor, "media")) {
    return null;
  }
  return controllers.get(editor) ?? null;
}

// Cancels the uploads whose block is gone, and every upload when the editor is read-only. A block
// that only moved keeps its id, so its upload is kept. With no uploads this does no walk.
export function reconcileUploads(editor: SlateEditor, readOnly: boolean): void {
  const controller = controllers.get(editor);
  if (controller === undefined) {
    return;
  }

  for (const id of controller.ids()) {
    if (readOnly || findBlockById(editor, id) === undefined) {
      controller.cancel(id);
    }
  }
}

export function mediaSourceBlockId(editor: SlateEditor): string {
  return editor.getOption(mediaUiPlugin, "source");
}

export function mediaActionsBlockId(editor: SlateEditor): string {
  return editor.getOption(mediaUiPlugin, "actions");
}

export function mediaHoverBlockId(editor: SlateEditor): string {
  return editor.getOption(mediaUiPlugin, "hoverId");
}

// The hover toolbar opens after a short rest, and closes a moment after the pointer leaves the block
// and the toolbar, so the pointer can cross the gap between them.
export const MEDIA_HOVER_OPEN_MS = 120;
export const MEDIA_HOVER_CLOSE_MS = 200;

// Each block has its own pending open, so a change to another block does not cancel it. There is one
// pending close per editor.
const openTimers = new WeakMap<SlateEditor, Map<string, ReturnType<typeof setTimeout>>>();
const closeTimers = new WeakMap<SlateEditor, ReturnType<typeof setTimeout>>();

function openTimersOf(editor: SlateEditor): Map<string, ReturnType<typeof setTimeout>> {
  const existing = openTimers.get(editor);
  if (existing !== undefined) {
    return existing;
  }

  const created = new Map<string, ReturnType<typeof setTimeout>>();
  openTimers.set(editor, created);
  return created;
}

// Where the pointer was when the event that scheduled a hover change ran. The browser can report an
// enter or a leave that the pointer did not make, after a layout change, so a timer checks this point
// against the layout at the time it fires, and not the enter or leave alone.
export type MediaPoint = { x: number; y: number };

function elementAt(point: MediaPoint | undefined): Element | null {
  if (point === undefined || typeof document.elementFromPoint !== "function") {
    return null;
  }

  return document.elementFromPoint(point.x, point.y);
}

function pointIsOverBlock(point: MediaPoint | undefined, blockId: string): boolean {
  const anchor = elementAt(point)?.closest("[data-media-anchor]");
  return anchor?.closest("[data-block-id]")?.getAttribute("data-block-id") === blockId;
}

function pointIsOverToolbar(point: MediaPoint | undefined): boolean {
  return elementAt(point)?.closest("[data-media-actions]") != null;
}

export function cancelMediaOpen(editor: SlateEditor, blockId: string): void {
  const timers = openTimersOf(editor);
  const timer = timers.get(blockId);
  if (timer === undefined) {
    return;
  }

  clearTimeout(timer);
  timers.delete(blockId);
}

export function cancelMediaHoverClose(editor: SlateEditor): void {
  const timer = closeTimers.get(editor);
  if (timer === undefined) {
    return;
  }

  clearTimeout(timer);
  closeTimers.delete(editor);
}

// Opens the source popover for one block. Only one popover of each kind is open at a time.
export function openMediaSource(editor: SlateEditor, blockId: string): void {
  if (
    editor.dom.readOnly === true ||
    blockId.length === 0 ||
    findBlockById(editor, blockId) === undefined
  ) {
    return;
  }

  clearMediaHover(editor);
  editor.setOption(mediaUiPlugin, "actions", "");
  editor.setOption(mediaUiPlugin, "source", blockId);
}

export function closeMediaSource(editor: SlateEditor): void {
  if (mediaSourceBlockId(editor) === "") {
    return;
  }

  editor.setOption(mediaUiPlugin, "source", "");
}

export function openMediaActions(editor: SlateEditor, blockId: string): void {
  if (
    editor.dom.readOnly === true ||
    blockId.length === 0 ||
    findBlockById(editor, blockId) === undefined
  ) {
    return;
  }

  clearMediaHover(editor);
  editor.setOption(mediaUiPlugin, "source", "");
  editor.setOption(mediaUiPlugin, "actions", blockId);
}

export function closeMediaActions(editor: SlateEditor): void {
  clearMediaHover(editor);
  if (mediaActionsBlockId(editor) === "") {
    return;
  }

  editor.setOption(mediaUiPlugin, "actions", "");
}

function setMediaHover(editor: SlateEditor, blockId: string): void {
  if (mediaHoverBlockId(editor) === blockId) {
    return;
  }

  editor.setOption(mediaUiPlugin, "hoverId", blockId);
}

// Drops the hover toolbar and any change still waiting to open or close it.
export function clearMediaHover(editor: SlateEditor): void {
  cancelMediaHoverClose(editor);
  for (const blockId of [...openTimersOf(editor).keys()]) {
    cancelMediaOpen(editor, blockId);
  }
  setMediaHover(editor, "");
}

// Opens the hover toolbar of one block. It does nothing while a source popover is open, or while a toolbar
// was opened by a click or Enter: that toolbar stays until its own dismissal. Hover never changes the
// explicit toolbar, and it never moves the selection or the focus.
export function openMediaHover(editor: SlateEditor, blockId: string): void {
  if (
    editor.dom.readOnly === true ||
    blockId.length === 0 ||
    findBlockById(editor, blockId) === undefined ||
    mediaSourceBlockId(editor) !== "" ||
    mediaActionsBlockId(editor) !== ""
  ) {
    return;
  }

  setMediaHover(editor, blockId);
}

// Opens the block's hover toolbar after the short rest, if the pointer is still over the block.
export function scheduleMediaHover(editor: SlateEditor, blockId: string, point: MediaPoint): void {
  cancelMediaOpen(editor, blockId);
  const timers = openTimersOf(editor);
  const timer = setTimeout(() => {
    timers.delete(blockId);
    if (pointIsOverBlock(point, blockId)) {
      openMediaHover(editor, blockId);
    }
  }, MEDIA_HOVER_OPEN_MS);
  timers.set(blockId, timer);
}

// Closes the hover toolbar once the pointer has left the block and the toolbar. A pointer that is still
// over the block, or over a media toolbar, keeps it open.
export function scheduleMediaHoverClose(editor: SlateEditor, point?: MediaPoint): void {
  cancelMediaHoverClose(editor);
  // Only the toolbar that was hovered when the close was scheduled is closed. Another block's toolbar
  // that opened since is left alone.
  const hovered = mediaHoverBlockId(editor);
  const timer = setTimeout(() => {
    closeTimers.delete(editor);
    if (hovered === "" || mediaHoverBlockId(editor) !== hovered) {
      return;
    }
    if (pointIsOverBlock(point, hovered)) {
      return;
    }
    if (pointIsOverToolbar(point)) {
      return;
    }

    setMediaHover(editor, "");
  }, MEDIA_HOVER_CLOSE_MS);
  closeTimers.set(editor, timer);
}

// Selects the block, so its popover and focus return both point at it.
export function selectMediaBlock(editor: SlateEditor, blockId: string): void {
  const entry = findBlockById(editor, blockId);
  if (entry !== undefined) {
    editor.tf.select(entry[1]);
  }
}

// The media block (image or file) that holds the selection, or the empty string.
export function selectedMediaId(editor: SlateEditor): string {
  const entry = editor.api.above({
    match: (node) => ElementApi.isElement(node) && isMediaBlockType(node.type),
  });
  if (entry === undefined || !ElementApi.isElement(entry[0])) {
    return "";
  }

  return typeof entry[0].id === "string" ? entry[0].id : "";
}

type MediaKeyEvent = {
  key: string;
  altKey?: boolean;
  shiftKey?: boolean;
  metaKey?: boolean;
  ctrlKey?: boolean;
  target?: EventTarget | null;
  preventDefault: () => void;
};

// A focused control keeps its own keys. Enter on the selected image opens its actions.
export function onMediaUiKeyDown(editor: SlateEditor, event: MediaKeyEvent): boolean {
  if (editor.dom.readOnly === true || event.key !== "Enter") {
    return false;
  }

  if (event.altKey || event.shiftKey || event.metaKey || event.ctrlKey) {
    return false;
  }

  if (mediaActionsBlockId(editor) !== "" || blockSelectionActive(editor)) {
    return false;
  }

  const target = event.target;
  if (target instanceof Element && target.closest("button, input, textarea, [role='separator']")) {
    return false;
  }

  const id = selectedMediaId(editor);
  if (id.length === 0) {
    return false;
  }

  event.preventDefault();
  openMediaActions(editor, id);
  return true;
}

// toPlatePlugin, not createSlatePlugin: a Slate plugin's handlers have no onKeyDown.
export const mediaUiPlatePlugin = toPlatePlugin(mediaUiPlugin, {
  handlers: {
    onKeyDown: ({ editor, event }) => {
      onMediaUiKeyDown(editor, event);
    },
  },
});

import { BaseMentionPlugin } from "@platejs/mention";
import { ElementApi, KEYS, createSlatePlugin, type SlateEditor, type TElement } from "platejs";

import type { EditorCommand } from "../commands/editor-commands";
import { selectionInCodeBlock } from "../features/editor-code";
import {
  MENTION_ENTITY_TYPE,
  allocateMentionId,
  isStoredMentionEntityId,
  mentionInputPlainText,
  sanitizeMentionLabel,
  type MentionEntity,
  type MentionProvider,
} from "../features/editor-mention-node";
import { featureEnabled } from "./editor-config";

export const MENTION_SEARCH_DEBOUNCE_MS = 150;
export const MENTION_EMPTY_LABEL = "No people found";
export const MENTION_ERROR_LABEL = "Couldn't load people";
export const MENTION_LOADING_LABEL = "Loading…";
export const MENTION_UNKNOWN_LABEL = "Unknown person";

export type { MentionEntity, MentionProvider };

type MentionSearchStatus = "idle" | "loading" | "ready" | "empty" | "error";

type MentionSearchClock = {
  setTimeout: (callback: () => void, delayMs: number) => unknown;
  clearTimeout: (id: unknown) => void;
};

type MentionSearchSession = {
  generation: number;
  timer: unknown;
  controller: AbortController | null;
};

type MentionInputKey = {
  key: string;
  preventDefault: () => void;
  shiftKey?: boolean;
  defaultPrevented?: boolean;
};

const providers = new WeakMap<SlateEditor, MentionProvider>();
const clocks = new WeakMap<SlateEditor, MentionSearchClock>();
const sessions = new WeakMap<SlateEditor, MentionSearchSession>();
const inputComposing = new WeakMap<SlateEditor, boolean>();
const committing = new WeakSet<SlateEditor>();

const browserHandles = new Map<number, ReturnType<typeof setTimeout>>();
let browserHandleId = 1;

const browserClock: MentionSearchClock = {
  setTimeout: (callback, delayMs) => {
    const id = browserHandleId;
    browserHandleId += 1;
    browserHandles.set(id, setTimeout(callback, delayMs));
    return id;
  },
  clearTimeout: (id) => {
    if (typeof id !== "number") {
      return;
    }

    const handle = browserHandles.get(id);
    if (handle === undefined) {
      return;
    }

    clearTimeout(handle);
    browserHandles.delete(id);
  },
};

function mentionUiOptions(): {
  query: string;
  status: MentionSearchStatus;
  results: MentionEntity[];
  activeIndex: number;
} {
  return {
    query: "",
    status: "idle",
    results: [],
    activeIndex: 0,
  };
}

export const mentionUiPlugin = createSlatePlugin({
  key: "mentionUi",
  options: mentionUiOptions(),
});

function sessionFor(editor: SlateEditor): MentionSearchSession {
  const existing = sessions.get(editor);
  if (existing !== undefined) {
    return existing;
  }

  const created: MentionSearchSession = { generation: 0, timer: undefined, controller: null };
  sessions.set(editor, created);
  return created;
}

function clockFor(editor: SlateEditor): MentionSearchClock {
  return clocks.get(editor) ?? browserClock;
}

function isAbortError(error: unknown): boolean {
  return (
    typeof error === "object" && error !== null && "name" in error && error.name === "AbortError"
  );
}

function resetMentionUi(editor: SlateEditor): void {
  const session = sessionFor(editor);
  session.generation += 1;
  if (session.controller !== null) {
    session.controller.abort();
    session.controller = null;
  }

  if (session.timer !== undefined) {
    clockFor(editor).clearTimeout(session.timer);
    session.timer = undefined;
  }

  editor.setOption(mentionUiPlugin, "query", "");
  editor.setOption(mentionUiPlugin, "status", "idle");
  editor.setOption(mentionUiPlugin, "results", []);
  editor.setOption(mentionUiPlugin, "activeIndex", 0);
}

export function attachMentionProvider(editor: SlateEditor, provider: MentionProvider | null): void {
  if (provider === null) {
    providers.delete(editor);
    return;
  }

  providers.set(editor, provider);
}

export function setMentionSearchClock(editor: SlateEditor, clock: MentionSearchClock | null): void {
  if (clock === null) {
    clocks.delete(editor);
    return;
  }

  clocks.set(editor, clock);
}

export function setMentionComposing(editor: SlateEditor, composing: boolean): void {
  editor.composing = composing;
}

export function setMentionInputComposing(editor: SlateEditor, composing: boolean): void {
  inputComposing.set(editor, composing);
}

export function editorIsComposing(editor: SlateEditor): boolean {
  if (editor.composing === true || inputComposing.get(editor) === true) {
    return true;
  }

  const dom: unknown = editor.dom;
  return typeof dom === "object" && dom !== null && "composing" in dom && dom.composing === true;
}

export function inlineTriggerBlocked(editor: SlateEditor): boolean {
  return (
    selectionInCodeBlock(editor) ||
    caretInLink(editor) ||
    caretHasCodeMark(editor) ||
    mentionInputEntry(editor) !== undefined
  );
}

function mentionInputEntry(editor: SlateEditor): [TElement, number[]] | undefined {
  for (const entry of editor.api.nodes({
    at: [],
    match: (node) => ElementApi.isElement(node) && node.type === editor.getType(KEYS.mentionInput),
  })) {
    if (ElementApi.isElement(entry[0])) {
      return [entry[0], entry[1]];
    }
  }

  return undefined;
}

function caretInLink(editor: SlateEditor): boolean {
  return (
    editor.api.above({
      match: (node) => ElementApi.isElement(node) && node.type === editor.getType(KEYS.link),
    }) !== undefined
  );
}

function caretHasCodeMark(editor: SlateEditor): boolean {
  const marks = editor.api.marks();
  return marks !== null && Reflect.get(marks, KEYS.code) === true;
}

function mentionTriggerAllowed(editor: SlateEditor): boolean {
  if (
    editor.dom.readOnly === true ||
    editorIsComposing(editor) ||
    !featureEnabled(editor, "mentions")
  ) {
    return false;
  }

  if (providers.get(editor) === undefined) {
    return false;
  }

  if (editor.selection === null || !editor.api.isCollapsed()) {
    return false;
  }

  return !inlineTriggerBlocked(editor);
}

export const mentionPlugin = BaseMentionPlugin.configure({
  node: { isMarkableVoid: false },
  options: {
    trigger: "@",
    triggerPreviousCharPattern: /^\s?$/,
    insertSpaceAfterMention: false,
    triggerQuery: (editor) => mentionTriggerAllowed(editor),
    createComboboxInput: (trigger) => ({
      children: [{ text: "" }],
      trigger,
      type: KEYS.mentionInput,
    }),
  },
});

function storedPeople(results: readonly MentionEntity[]): MentionEntity[] {
  const people: MentionEntity[] = [];
  for (const entity of results) {
    const label = sanitizeMentionLabel(entity.label);
    if (
      entity.entityType !== MENTION_ENTITY_TYPE ||
      !isStoredMentionEntityId(entity.entityId) ||
      label === undefined
    ) {
      continue;
    }

    people.push({ ...entity, label });
  }

  return people;
}

async function runMentionSearch(
  editor: SlateEditor,
  query: string,
  generation: number,
): Promise<void> {
  const session = sessionFor(editor);
  if (session.generation !== generation || editor.dom.readOnly === true) {
    return;
  }

  const provider = providers.get(editor);
  if (provider === undefined) {
    editor.setOption(mentionUiPlugin, "status", "idle");
    editor.setOption(mentionUiPlugin, "results", []);
    return;
  }

  const controller = new AbortController();
  session.controller = controller;
  try {
    const results = await provider.search(query, controller.signal);
    if (session.generation !== generation || controller.signal.aborted) {
      return;
    }

    const people = storedPeople(results);
    editor.setOption(mentionUiPlugin, "results", people);
    editor.setOption(mentionUiPlugin, "status", people.length === 0 ? "empty" : "ready");
    editor.setOption(mentionUiPlugin, "activeIndex", 0);
  } catch (error: unknown) {
    if (session.generation !== generation || controller.signal.aborted || isAbortError(error)) {
      return;
    }

    editor.setOption(mentionUiPlugin, "results", []);
    editor.setOption(mentionUiPlugin, "status", "error");
  }
}

function scheduleMentionSearch(editor: SlateEditor, query: string): void {
  const session = sessionFor(editor);
  session.generation += 1;
  const generation = session.generation;
  if (session.controller !== null) {
    session.controller.abort();
    session.controller = null;
  }

  const clock = clockFor(editor);
  if (session.timer !== undefined) {
    clock.clearTimeout(session.timer);
    session.timer = undefined;
  }

  editor.setOption(mentionUiPlugin, "status", "loading");
  editor.setOption(mentionUiPlugin, "results", []);
  session.timer = clock.setTimeout(() => {
    session.timer = undefined;
    void runMentionSearch(editor, query, generation);
  }, MENTION_SEARCH_DEBOUNCE_MS);
}

export function setMentionQuery(editor: SlateEditor, query: string): void {
  editor.setOption(mentionUiPlugin, "query", query);
  editor.setOption(mentionUiPlugin, "activeIndex", 0);
  if (editorIsComposing(editor) || editor.dom.readOnly === true) {
    return;
  }

  scheduleMentionSearch(editor, query);
}

function moveActiveMention(editor: SlateEditor, delta: number): void {
  const results = editor.getOption(mentionUiPlugin, "results");
  if (results.length === 0) {
    return;
  }

  const current = editor.getOption(mentionUiPlugin, "activeIndex");
  const next = Math.min(results.length - 1, Math.max(0, current + delta));
  editor.setOption(mentionUiPlugin, "activeIndex", next);
}

function insertMentionAtom(editor: SlateEditor, entity: MentionEntity): void {
  const label = sanitizeMentionLabel(entity.label);
  if (
    entity.entityType !== MENTION_ENTITY_TYPE ||
    !isStoredMentionEntityId(entity.entityId) ||
    label === undefined
  ) {
    return;
  }

  const input = mentionInputEntry(editor);
  editor.tf.withNewBatch(() => {
    if (input !== undefined) {
      editor.tf.select(input[1]);
      editor.tf.removeNodes({ at: input[1] });
    }

    editor.tf.insertNodes({
      type: editor.getType(KEYS.mention),
      id: allocateMentionId(),
      entityType: MENTION_ENTITY_TYPE,
      entityId: entity.entityId,
      label,
      children: [{ text: "" }],
    });
    const inserted =
      editor.selection === null
        ? undefined
        : editor.api.above({
            at: editor.selection,
            match: (node) =>
              ElementApi.isElement(node) && node.type === editor.getType(KEYS.mention),
          });
    if (inserted !== undefined) {
      const after = editor.api.after(inserted[1]);
      if (after !== undefined) {
        editor.tf.select(after);
      }
    }
    editor.tf.insertText(" ");
  });
  editor.tf.setSplittingOnce(true);
  resetMentionUi(editor);
  // The input is removed on commit, so focus goes back to the editor after the mention.
  editor.tf.focus();
}

export function commitMention(editor: SlateEditor, entity: MentionEntity): boolean {
  committing.add(editor);
  try {
    insertMentionAtom(editor, entity);
  } finally {
    committing.delete(editor);
  }

  return true;
}

export function commitActiveMention(editor: SlateEditor): boolean {
  const results = editor.getOption(mentionUiPlugin, "results");
  const entity = results[editor.getOption(mentionUiPlugin, "activeIndex")];
  if (entity === undefined) {
    return false;
  }

  return commitMention(editor, entity);
}

export function cancelMentionInput(editor: SlateEditor): void {
  if (committing.has(editor)) {
    return;
  }

  const input = mentionInputEntry(editor);
  if (input === undefined) {
    return;
  }

  const text = mentionInputPlainText(input[0], editor.getOption(mentionUiPlugin, "query"));
  editor.tf.withNewBatch(() => {
    editor.tf.select(input[1]);
    editor.tf.removeNodes({ at: input[1] });
    // `at` skips the combobox trigger. A bare "@" would otherwise reopen the input.
    const at = editor.selection;
    if (at !== null) {
      editor.tf.insertText(text, { at });
    }
  });
  editor.tf.setSplittingOnce(true);
  resetMentionUi(editor);
  // The input is removed on cancel, so focus goes back to the editor after the typed text.
  editor.tf.focus();
}

export function onMentionInputKeyDown(editor: SlateEditor, event: MentionInputKey): boolean {
  if (event.key === "ArrowDown") {
    event.preventDefault();
    moveActiveMention(editor, 1);
    return true;
  }

  if (event.key === "ArrowUp") {
    event.preventDefault();
    moveActiveMention(editor, -1);
    return true;
  }

  if (event.key === "Enter" || (event.key === "Tab" && event.shiftKey !== true)) {
    event.preventDefault();
    commitActiveMention(editor);
    return true;
  }

  if (event.key === "Escape") {
    event.preventDefault();
    cancelMentionInput(editor);
    return true;
  }

  if (event.key === "Backspace" && editor.getOption(mentionUiPlugin, "query").length === 0) {
    event.preventDefault();
    cancelMentionInput(editor);
    return true;
  }

  return false;
}

function skipMentionArrow(editor: SlateEditor, key: "ArrowLeft" | "ArrowRight"): boolean {
  const selection = editor.selection;
  if (selection === null || !editor.api.isCollapsed()) {
    return false;
  }

  const mentionType = editor.getType(KEYS.mention);
  const anchor = selection.anchor;
  const parentPath = anchor.path.slice(0, -1);
  const parentEntry = editor.api.node(parentPath);
  if (parentEntry === undefined || !ElementApi.isElement(parentEntry[0])) {
    return false;
  }

  const parent = parentEntry[0];
  if (parent.type === mentionType) {
    const point =
      key === "ArrowLeft" ? editor.api.before(parentPath) : editor.api.after(parentPath);
    if (point === undefined) {
      return false;
    }

    editor.tf.select(point);
    return true;
  }

  const index = anchor.path[anchor.path.length - 1];
  if (index === undefined) {
    return false;
  }

  if (key === "ArrowLeft" && anchor.offset === 0) {
    const previousPath = [...parentPath, index - 1];
    const previous = editor.api.node(previousPath);
    if (
      previous !== undefined &&
      ElementApi.isElement(previous[0]) &&
      previous[0].type === mentionType
    ) {
      const point = editor.api.before(previousPath);
      if (point === undefined) {
        return false;
      }

      editor.tf.select(point);
      return true;
    }
  }

  if (key === "ArrowRight") {
    const current = parent.children[index];
    const length =
      current !== undefined && "text" in current && typeof current.text === "string"
        ? current.text.length
        : 0;
    if (anchor.offset !== length) {
      return false;
    }

    const nextPath = [...parentPath, index + 1];
    const next = editor.api.node(nextPath);
    if (next !== undefined && ElementApi.isElement(next[0]) && next[0].type === mentionType) {
      const point = editor.api.after(nextPath);
      if (point === undefined) {
        return false;
      }

      editor.tf.select(point);
      return true;
    }
  }

  return false;
}

export function onMentionKeyDown(editor: SlateEditor, event: MentionInputKey): void {
  if (
    (event.key === "ArrowLeft" || event.key === "ArrowRight") &&
    mentionInputEntry(editor) === undefined &&
    skipMentionArrow(editor, event.key)
  ) {
    event.preventDefault();
    return;
  }

  if (event.key !== "Escape" || mentionInputEntry(editor) === undefined || event.defaultPrevented) {
    return;
  }

  onMentionInputKeyDown(editor, event);
}

export function openMentionInput(editor: SlateEditor): boolean {
  if (editor.dom.readOnly === true || !mentionTriggerAllowed(editor)) {
    return false;
  }

  editor.tf.insertNodes({
    type: editor.getType(KEYS.mentionInput),
    trigger: "@",
    children: [{ text: "" }],
  });
  setMentionQuery(editor, "");
  return true;
}

export const insertMention: EditorCommand = {
  id: "inline.mention.insert",
  label: "Mention",
  group: "insert",
  isEnabled: (editor) => editor.dom.readOnly !== true && mentionTriggerAllowed(editor),
  run: (editor) => {
    if (editor.dom.readOnly === true) {
      return;
    }

    openMentionInput(editor);
  },
};

import { createSlatePlugin, type SlateEditor } from "platejs";

import { runEditorCommand } from "../commands/editor-commands";
import type { PageEntity } from "../features/editor-page-link";
import { insertPageLink } from "../features/editor-page-link-command";
import { blockTextOffset, findSlashBlock, pointAtBlockOffset } from "../features/editor-slash";
import { pageLinkProvider } from "./editor-page-link";
import { featureEnabled } from "./editor-config";

type PageLinkPickerOptions = {
  open: boolean;
  blockId: string;
  offset: number;
};

function pageLinkPickerOptions(): PageLinkPickerOptions {
  return { open: false, blockId: "", offset: 0 };
}

function isEditorOnChange(value: unknown): value is (options?: { operation?: unknown }) => void {
  return typeof value === "function";
}

// The picker closes when its block goes away or the editor becomes read-only. Nothing is inserted then.
export const pageLinkPickerPlugin = createSlatePlugin({
  key: "pageLinkPicker",
  options: pageLinkPickerOptions(),
}).overrideEditor(({ editor }) => {
  const { onChange } = editor;
  if (isEditorOnChange(onChange)) {
    editor.onChange = (options?: { operation?: unknown }) => {
      onChange(options);
      if (!pageLinkPickerOpen(editor)) {
        return;
      }

      const blockId = editor.getOption(pageLinkPickerPlugin, "blockId");
      if (editor.dom.readOnly === true || findSlashBlock(editor, blockId) === null) {
        clearPageLinkPicker(editor);
      }
    };
  }
  return { transforms: {} };
});

export function pageLinkPickerOpen(editor: SlateEditor): boolean {
  return editor.getOption(pageLinkPickerPlugin, "open") === true;
}

// Opens where the slash menu was used. The offset is the caret, which sits where the "/" was.
export function openPageLinkPicker(editor: SlateEditor, blockId: string): void {
  if (
    editor.dom.readOnly === true ||
    pageLinkProvider(editor) === null ||
    !featureEnabled(editor, "pageLinks")
  ) {
    return;
  }

  const block = findSlashBlock(editor, blockId);
  const offset =
    block !== null && editor.selection !== null
      ? (blockTextOffset(editor, block[1], editor.selection.anchor) ?? 0)
      : 0;
  editor.setOption(pageLinkPickerPlugin, "open", true);
  editor.setOption(pageLinkPickerPlugin, "blockId", blockId);
  editor.setOption(pageLinkPickerPlugin, "offset", offset);
}

export function pageLinkPickerAnchorPoint(
  editor: SlateEditor,
): { path: number[]; offset: number } | null {
  if (!pageLinkPickerOpen(editor)) {
    return null;
  }

  const block = findSlashBlock(editor, editor.getOption(pageLinkPickerPlugin, "blockId"));
  if (block === null) {
    return null;
  }

  return pointAtBlockOffset(editor, block[1], editor.getOption(pageLinkPickerPlugin, "offset"));
}

export function cancelPageLinkPicker(editor: SlateEditor): void {
  if (!pageLinkPickerOpen(editor)) {
    return;
  }

  const blockId = editor.getOption(pageLinkPickerPlugin, "blockId");
  const offset = editor.getOption(pageLinkPickerPlugin, "offset");
  clearPageLinkPicker(editor);
  restoreCaret(editor, blockId, offset);
  editor.tf.focus();
}

// One undo entry for the insert. The query was removed earlier, in its own entry.
export function choosePageLink(editor: SlateEditor, page: PageEntity): boolean {
  if (!pageLinkPickerOpen(editor)) {
    return false;
  }

  const blockId = editor.getOption(pageLinkPickerPlugin, "blockId");
  const offset = editor.getOption(pageLinkPickerPlugin, "offset");
  clearPageLinkPicker(editor);
  if (findSlashBlock(editor, blockId) === null) {
    return false;
  }

  restoreCaret(editor, blockId, offset);
  const inserted = runEditorCommand(editor, insertPageLink, {
    pageId: page.pageId,
    title: page.title,
    kind: "link",
    beside: { blockId },
  });
  editor.tf.focus();
  return inserted;
}

function clearPageLinkPicker(editor: SlateEditor): void {
  editor.setOption(pageLinkPickerPlugin, "open", false);
  editor.setOption(pageLinkPickerPlugin, "blockId", "");
  editor.setOption(pageLinkPickerPlugin, "offset", 0);
}

function restoreCaret(editor: SlateEditor, blockId: string, offset: number): void {
  const block = findSlashBlock(editor, blockId);
  if (block === null) {
    return;
  }

  const point = pointAtBlockOffset(editor, block[1], offset) ?? editor.api.end(block[1]);
  if (point !== undefined) {
    editor.tf.select(point);
  }
}

import {
  ElementApi,
  createSlatePlugin,
  type Descendant,
  type SlateEditor,
  type TElement,
} from "platejs";

import { plainText, type PlainTextHook } from "../features/editor-inline-date";
import {
  PAGE_LINK_KEY,
  isStoredPageId,
  pageLinkDisplayTitle,
  storedPageLinkKind,
  type PageLinkHost,
  type PageLinkStatus,
  type PageOpenRequest,
  type PageProvider,
} from "../features/editor-page-link";
import { blockSelectionActive } from "./editor-block-selection";

const hosts = new WeakMap<SlateEditor, PageLinkHost>();
const statuses = new WeakMap<SlateEditor, Map<string, PageLinkStatus>>();

const pageLinkText: PlainTextHook = (node) => {
  if (node.type !== PAGE_LINK_KEY) {
    return undefined;
  }

  return pageLinkDisplayTitle(typeof node.title === "string" ? node.title : "");
};

export const pageLinkPlugin = createSlatePlugin({
  key: PAGE_LINK_KEY,
  node: { isElement: true, isVoid: true },
}).overrideEditor(({ editor, tf: { setFragmentData } }) => ({
  transforms: {
    setFragmentData(data, originEvent) {
      setFragmentData(data, originEvent);
      // The page link is written last, so a fragment with a date or equation keeps their text too.
      const fragment = editor.api.getFragment();
      if (!fragment.some((node) => containsPageLink(node))) {
        return;
      }

      data.setData("text/plain", fragment.map((node) => plainText(node, pageLinkText)).join("\n"));
    },
  },
}));

function containsPageLink(node: Descendant): boolean {
  if (!ElementApi.isElement(node)) {
    return false;
  }

  return node.type === PAGE_LINK_KEY || node.children.some((child) => containsPageLink(child));
}

// The scope sets the host during render, so a row that resolves in the same commit sees it.
export function attachPageLinkHost(editor: SlateEditor, host: PageLinkHost): void {
  hosts.set(editor, host);
}

// The slash menu offers Page link only when a provider is attached.
export function pageLinkProvider(editor: SlateEditor): PageProvider | null {
  return hosts.get(editor)?.provider ?? null;
}

// The row reports its status so a missing or denied page cannot be opened from the keyboard.
export function setPageLinkStatus(
  editor: SlateEditor,
  blockId: string,
  status: PageLinkStatus | undefined,
): void {
  if (blockId.length === 0) {
    return;
  }

  let map = statuses.get(editor);
  if (map === undefined) {
    map = new Map<string, PageLinkStatus>();
    statuses.set(editor, map);
  }

  if (status === undefined) {
    map.delete(blockId);
    return;
  }

  map.set(blockId, status);
}

export function openPageLink(
  editor: SlateEditor,
  request: PageOpenRequest,
  blockId: string,
): boolean {
  if (!isStoredPageId(request.pageId) || blockSelectionActive(editor)) {
    return false;
  }

  const onOpenPage = hosts.get(editor)?.onOpenPage;
  if (!onOpenPage) {
    return false;
  }

  const status = statuses.get(editor)?.get(blockId);
  if (status === "missing" || status === "denied") {
    return false;
  }

  onOpenPage(request);
  return true;
}

type PageLinkKeyEvent = {
  key: string;
  altKey?: boolean;
  shiftKey?: boolean;
  metaKey?: boolean;
  ctrlKey?: boolean;
  preventDefault: () => void;
};

// Enter on the selected page link opens it. It never inserts a break, even when the page cannot open.
export function onPageLinkKeyDown(editor: SlateEditor, event: PageLinkKeyEvent): boolean {
  if (editor.dom.readOnly === true || event.key !== "Enter") {
    return false;
  }

  if (event.altKey || event.shiftKey || event.metaKey || event.ctrlKey) {
    return false;
  }

  const entry = editor.api.above({
    match: (node) => ElementApi.isElement(node) && node.type === PAGE_LINK_KEY,
  });
  if (entry === undefined || !ElementApi.isElement(entry[0])) {
    return false;
  }

  const node: TElement = entry[0];
  const id = typeof node.id === "string" ? node.id : "";
  event.preventDefault();
  openPageLink(
    editor,
    {
      pageId: typeof node.pageId === "string" ? node.pageId : "",
      kind: storedPageLinkKind(node.kind),
    },
    id,
  );
  return true;
}

import type { SlateEditor } from "platejs";

type HistoryKeyEvent = {
  key: string;
  altKey?: boolean;
  shiftKey?: boolean;
  metaKey?: boolean;
  ctrlKey?: boolean;
  target?: EventTarget | null;
  preventDefault: () => void;
};

// Mod+Z undoes, and Mod+Shift+Z or Mod+Y redoes. A popover or handle is outside the editable, where Slate
// reads these keys, so its keys go to the document history here. A text field keeps its own undo.
export function onPopoverHistoryKey(editor: SlateEditor, event: HistoryKeyEvent): boolean {
  if (!(event.metaKey || event.ctrlKey) || event.altKey) {
    return false;
  }

  const target = event.target;
  if (target instanceof Element && target.closest("input, textarea") !== null) {
    return false;
  }

  const key = event.key.toLowerCase();
  let action: "undo" | "redo" | null = null;
  if (key === "z") {
    action = event.shiftKey ? "redo" : "undo";
  } else if (key === "y" && event.shiftKey !== true) {
    action = "redo";
  }
  if (action === null) {
    return false;
  }

  event.preventDefault();
  if (action === "undo") {
    editor.tf.undo();
  } else {
    editor.tf.redo();
  }
  return true;
}

import {
  ElementApi,
  KEYS,
  NodeApi,
  TextApi,
  createSlatePlugin,
  nanoid,
  type SlateEditor,
} from "platejs";
import { toPlatePlugin } from "platejs/react";

import { runEditorCommand, type EditorCommand } from "../commands/editor-commands";
import { applyBlockTurn } from "../features/editor-block-menu";
import { AUDIO_KEY } from "../features/editor-audio";
import { FILE_KEY } from "../features/editor-file";
import { IMAGE_KEY } from "../features/editor-image";
import { mediaBlockElement } from "../features/editor-media-commands";
import { VIDEO_KEY } from "../features/editor-video";
import { EMBED_KEY } from "../features/editor-embed";
import { insertPickedBlock } from "../features/editor-block-picker";
import {
  blockTextOffset,
  pointAtBlockOffset,
  readSlashSession,
  slashAvailableItems,
  slashItemsForSession,
  slashQueryTooLong,
  slashTriggerAllowed,
  type SlashItem,
  type SlashSession,
} from "../features/editor-slash";
import { retainScroll } from "../../components/ui/block-toolbar";
import { openBookmarkUrlPopover, placeBlockBesideSlash } from "./editor-bookmark-popover";
import { openPageLinkPicker } from "./editor-page-link-picker";
import { insertSlashFootnote } from "./editor-footnote-ui";
import { openLinkPopover } from "./editor-link";
import { editorIsComposing, openMentionInput } from "./editor-mention";
import { openMediaSource } from "./editor-media-ui";

export const SLASH_HANDLER_PRIORITY = 2000;

type SlashOptions = {
  open: boolean;
  blockId: string;
  offset: number;
  activeIndex: number;
  query: string;
};

type SlashKeyEvent = {
  key: string;
  shiftKey?: boolean;
  metaKey?: boolean;
  ctrlKey?: boolean;
  altKey?: boolean;
  preventDefault: () => void;
};

function isEditorOnChange(value: unknown): value is (options?: { operation?: unknown }) => void {
  return typeof value === "function";
}

const compositionCommit = new WeakSet<SlateEditor>();
const seenQuery = new WeakMap<SlateEditor, string>();

function slashOptions(): SlashOptions {
  return { open: false, blockId: "", offset: 0, activeIndex: 0, query: "" };
}

function slashOpenSuppressed(editor: SlateEditor): boolean {
  return editorIsComposing(editor) || compositionCommit.has(editor);
}

export function setSlashComposing(editor: SlateEditor, composing: boolean): void {
  editor.composing = composing;
  if (composing) {
    return;
  }
  compositionCommit.add(editor);
  queueMicrotask(() => {
    compositionCommit.delete(editor);
  });
}

export function slashMenuOpen(editor: SlateEditor): boolean {
  return editor.getOption(slashUiPlugin, "open") === true;
}

export function closeSlashMenu(editor: SlateEditor): void {
  if (!slashMenuOpen(editor)) {
    return;
  }
  seenQuery.delete(editor);
  editor.setOption(slashUiPlugin, "open", false);
  editor.setOption(slashUiPlugin, "blockId", "");
  editor.setOption(slashUiPlugin, "offset", 0);
  editor.setOption(slashUiPlugin, "activeIndex", 0);
  editor.setOption(slashUiPlugin, "query", "");
}

export function slashSession(editor: SlateEditor): SlashSession | null {
  if (!slashMenuOpen(editor)) {
    return null;
  }
  return readSlashSession(editor, {
    blockId: editor.getOption(slashUiPlugin, "blockId"),
    offset: editor.getOption(slashUiPlugin, "offset"),
  });
}

export function slashMenuItems(editor: SlateEditor): SlashItem[] {
  const session = slashSession(editor);
  if (session === null) {
    return [];
  }
  return slashItemsForSession(editor, session);
}

function moveSlashHighlight(editor: SlateEditor, delta: number): void {
  const items = slashMenuItems(editor);
  if (items.length === 0) {
    return;
  }
  const current = editor.getOption(slashUiPlugin, "activeIndex");
  const next = (current + delta + items.length) % items.length;
  editor.setOption(slashUiPlugin, "activeIndex", next);
}

function syncSlashMenu(editor: SlateEditor): void {
  if (!slashMenuOpen(editor)) {
    return;
  }
  const session = slashSession(editor);
  if (session === null || slashQueryTooLong(session.query)) {
    closeSlashMenu(editor);
    return;
  }
  if (seenQuery.get(editor) === session.query) {
    return;
  }
  seenQuery.set(editor, session.query);
  editor.setOption(slashUiPlugin, "query", session.query);
  if (editor.getOption(slashUiPlugin, "activeIndex") !== 0) {
    editor.setOption(slashUiPlugin, "activeIndex", 0);
  }
}

function openSlashMenu(editor: SlateEditor): void {
  const selection = editor.selection;
  const block = selection === null ? undefined : editor.api.block();
  if (
    selection === null ||
    !block ||
    !ElementApi.isElement(block[0]) ||
    typeof block[0].id !== "string"
  ) {
    return;
  }
  const caret = blockTextOffset(editor, block[1], selection.anchor);
  if (caret === null || caret < 1) {
    return;
  }
  if (NodeApi.string(block[0])[caret - 1] !== "/") {
    return;
  }
  editor.setOption(slashUiPlugin, "open", true);
  editor.setOption(slashUiPlugin, "blockId", block[0].id);
  editor.setOption(slashUiPlugin, "offset", caret - 1);
  editor.setOption(slashUiPlugin, "activeIndex", 0);
  editor.setOption(slashUiPlugin, "query", "");
  seenQuery.set(editor, "");
}

function chooseSlash(editor: SlateEditor, id: string): void {
  const session = slashSession(editor);
  const item =
    session === null
      ? undefined
      : slashAvailableItems(editor, session).find((entry) => entry.id === id);
  closeSlashMenu(editor);
  if (session === null || item === undefined) {
    return;
  }
  const start = pointAtBlockOffset(editor, session.blockPath, session.anchor.offset);
  const end = pointAtBlockOffset(editor, session.blockPath, session.caretOffset);
  if (start === null || end === null) {
    return;
  }
  // One undo step: the query goes and the footnote arrives together.
  if (item.inline === "footnote") {
    runEditorCommand(editor, insertSlashFootnote, { start, end });
    return;
  }
  editor.tf.delete({ at: { anchor: start, focus: end } });
  if (item.inline === "mention") {
    openMentionInput(editor);
    return;
  }
  if (item.inline === "link") {
    openLinkPopover(editor);
    return;
  }
  if (item.bookmark === true) {
    editor.tf.setSplittingOnce(true);
    openBookmarkUrlPopover(editor, session.anchor.blockId);
    return;
  }
  if (item.pageLink === true) {
    editor.tf.setSplittingOnce(true);
    openPageLinkPicker(editor, session.anchor.blockId);
    return;
  }
  if (item.image === true) {
    insertMediaBesideSlash(editor, session.anchor.blockId, IMAGE_KEY);
    return;
  }
  if (item.file === true) {
    insertMediaBesideSlash(editor, session.anchor.blockId, FILE_KEY);
    return;
  }
  if (item.video === true) {
    insertMediaBesideSlash(editor, session.anchor.blockId, VIDEO_KEY);
    return;
  }
  if (item.audio === true) {
    insertMediaBesideSlash(editor, session.anchor.blockId, AUDIO_KEY);
    return;
  }
  if (item.embed === true) {
    insertMediaBesideSlash(editor, session.anchor.blockId, EMBED_KEY);
    return;
  }
  const block = item.block;
  if (block === undefined) {
    return;
  }
  if (isEmptyParagraph(editor, session.blockPath)) {
    if (block.kind === "paragraph" || block.kind === undefined) {
      if (block.kind === undefined) {
        replaceEmptyParagraph(editor, session.blockPath, block);
      }
      return;
    }
    applyBlockTurn(editor, session.blockPath, block.kind);
    return;
  }
  insertPickedBlock(editor, session.blockPath, block, { batch: false });
}

// An empty media block goes beside the slash line, and its source popover opens for it.
function insertMediaBesideSlash(
  editor: SlateEditor,
  blockId: string,
  type: typeof IMAGE_KEY | typeof FILE_KEY | typeof VIDEO_KEY | typeof AUDIO_KEY | typeof EMBED_KEY,
): void {
  const id = nanoid();
  const element = mediaBlockElement(type, id);
  if (!placeBlockBesideSlash(editor, blockId, element, type, true)) {
    return;
  }

  openMediaSource(editor, id);
}

function replaceEmptyParagraph(
  editor: SlateEditor,
  path: number[],
  item: NonNullable<SlashItem["block"]>,
): void {
  const node = editor.api.node(path)?.[0];
  const id =
    node && ElementApi.isElement(node) && typeof node.id === "string" ? node.id : undefined;
  insertPickedBlock(editor, path, item, { batch: false });
  if (id === undefined) {
    return;
  }
  const left = findParagraph(editor, id);
  if (left !== null && isEmptyParagraph(editor, left)) {
    editor.tf.removeNodes({ at: left });
  }
}

function findParagraph(editor: SlateEditor, id: string): number[] | null {
  for (const [node, path] of editor.api.nodes({
    at: [],
    match: (candidate) => ElementApi.isElement(candidate) && candidate.id === id,
  })) {
    if (ElementApi.isElement(node)) {
      return path;
    }
  }
  return null;
}

function isEmptyParagraph(editor: SlateEditor, path: number[]): boolean {
  const node = editor.api.node(path)?.[0];
  return (
    ElementApi.isElement(node) &&
    node.type === KEYS.p &&
    NodeApi.string(node) === "" &&
    node.children.every((child) => TextApi.isText(child))
  );
}

export const chooseSlashItem: EditorCommand<string> = {
  id: "insert.slash",
  label: "Insert",
  group: "insert",
  isEnabled: (editor) => slashMenuOpen(editor) && editor.dom.readOnly !== true,
  run: (editor, id) => {
    chooseSlash(editor, id);
  },
};

export function onSlashKeyDown(editor: SlateEditor, event: SlashKeyEvent): boolean {
  if (
    !slashMenuOpen(editor) ||
    event.metaKey === true ||
    event.ctrlKey === true ||
    event.altKey === true
  ) {
    return false;
  }
  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
    event.preventDefault();
    moveSlashHighlight(editor, event.key === "ArrowDown" ? 1 : -1);
    return true;
  }
  if ((event.key === "Enter" || event.key === "Tab") && event.shiftKey !== true) {
    event.preventDefault();
    const items = slashMenuItems(editor);
    const item = items[editor.getOption(slashUiPlugin, "activeIndex")];
    if (item === undefined) {
      closeSlashMenu(editor);
      return true;
    }
    retainScroll(() => {
      runEditorCommand(editor, chooseSlashItem, item.id);
      editor.tf.focus();
    });
    return true;
  }
  if (event.key === "Escape") {
    event.preventDefault();
    closeSlashMenu(editor);
    return true;
  }
  if (event.key === " " && slashMenuItems(editor).length === 0) {
    closeSlashMenu(editor);
  }
  return false;
}

const slashBase = createSlatePlugin({
  key: "slashUi",
  priority: SLASH_HANDLER_PRIORITY,
  options: slashOptions(),
}).overrideEditor(({ editor, tf: { insertText } }) => {
  return {
    transforms: {
      insertText(text, options) {
        const open =
          text === "/" &&
          (options === undefined || options.at === undefined) &&
          slashTriggerAllowed(editor, slashOpenSuppressed(editor));
        insertText(text, options);
        if (open) {
          openSlashMenu(editor);
        }
      },
    },
  };
});

export const slashWatchPlugin = createSlatePlugin({
  key: "slashWatch",
  priority: -1,
}).overrideEditor(({ editor }) => {
  const { onChange } = editor;
  if (isEditorOnChange(onChange)) {
    editor.onChange = (options?: { operation?: unknown }) => {
      onChange(options);
      syncSlashMenu(editor);
    };
  }
  return { transforms: {} };
});

export const slashUiPlugin = toPlatePlugin(slashBase, {
  handlers: {
    onKeyDown: ({ editor, event }) => onSlashKeyDown(editor, event),
    onCompositionStart: ({ editor }) => {
      setSlashComposing(editor, true);
    },
    onCompositionEnd: ({ editor }) => {
      setSlashComposing(editor, false);
    },
    onBlur: ({ editor, event }) => {
      const related = "relatedTarget" in event ? event.relatedTarget : null;
      if (related instanceof Element && related.closest("[data-slash-menu]") !== null) {
        return;
      }
      queueMicrotask(() => {
        const active = document.activeElement;
        if (active instanceof Element && active.closest("[data-slate-editor]") !== null) {
          return;
        }
        if (active instanceof Element && active.closest("[data-slash-menu]") !== null) {
          return;
        }
        closeSlashMenu(editor);
      });
    },
  },
});

import {
  ElementApi,
  KEYS,
  PathApi,
  TextApi,
  createSlatePlugin,
  type Descendant,
  type SlateEditor,
  type TElement,
} from "platejs";

import { allowsFirstChild } from "../document/editor-document-schema";

// Own container, not @platejs/toggle: its flat indent model collides with indent → listStyleType.
export const togglePlugin = createSlatePlugin({
  key: KEYS.toggle,
  node: { isElement: true },
  options: {
    openIds: new Set<string>(),
  },
  parsers: {
    html: {
      deserializer: {
        rules: [{ validNodeName: "DETAILS" }],
        parse: ({ editor, element, type }) => parseDetails(editor, element, type),
      },
    },
  },
});

type LabelContext = {
  id: string;
  labelPath: number[];
  togglePath: number[];
};

function isHtmlElementNode(value: unknown): value is HTMLElement {
  return (
    typeof value === "object" &&
    value !== null &&
    "nodeType" in value &&
    value.nodeType === 1 &&
    "nodeName" in value &&
    "childNodes" in value
  );
}

function nodeText(node: unknown): string {
  if (!node || typeof node !== "object") {
    return "";
  }

  if ("text" in node && typeof node.text === "string" && !("children" in node)) {
    return node.text;
  }

  if (!("children" in node) || !Array.isArray(node.children)) {
    return "";
  }

  return node.children.map((child: unknown) => nodeText(child)).join("");
}

function isDescendant(value: unknown): value is Descendant {
  return TextApi.isText(value) || ElementApi.isElement(value);
}

// deserialize() normalizes a document fragment. A non-body element comes back as one
// node, so wrap the element in a body first. Plate only returns an array for that.
function deserializedNodes(editor: SlateEditor, element: HTMLElement): Descendant[] {
  const body = element.ownerDocument.createElement("body");
  body.append(element.cloneNode(true));
  const parsed: unknown = editor.api.html.deserialize({ element: body });
  if (!Array.isArray(parsed)) {
    return [];
  }

  return parsed.filter(isDescendant);
}

function isToggleHeading(type: string): boolean {
  return type !== KEYS.p && allowsFirstChild(KEYS.toggle, type);
}

// Plate may wrap <summary><h2> in a paragraph. A summary is a heading label only
// when that heading is the only content.
function summaryHeading(nodes: readonly Descendant[]): TElement | undefined {
  let heading: TElement | undefined;
  let extra = false;

  const visit = (node: Descendant): void => {
    if (extra) {
      return;
    }

    if (TextApi.isText(node)) {
      if (node.text.trim().length > 0) {
        extra = true;
      }
      return;
    }

    if (!ElementApi.isElement(node)) {
      return;
    }

    if (isToggleHeading(node.type)) {
      if (heading !== undefined) {
        extra = true;
        return;
      }

      heading = node;
      return;
    }

    for (const child of node.children) {
      if (TextApi.isText(child) || ElementApi.isElement(child)) {
        visit(child);
      }
    }
  };

  for (const node of nodes) {
    visit(node);
  }

  return extra ? undefined : heading;
}

function summaryLabel(editor: SlateEditor, summary: HTMLElement): TElement {
  const heading = summaryHeading(deserializedNodes(editor, summary));
  if (heading !== undefined) {
    return heading;
  }

  return { type: KEYS.p, children: labelInlines(editor, summary) };
}

function textLeaves(node: TElement): Descendant[] {
  const leaves: Descendant[] = [];
  for (const child of node.children) {
    if (TextApi.isText(child)) {
      leaves.push(child);
      continue;
    }

    if (ElementApi.isElement(child)) {
      leaves.push(...textLeaves(child));
    }
  }

  return leaves;
}

function labelInlines(editor: SlateEditor, summary: HTMLElement): Descendant[] {
  const inlines: Descendant[] = [];
  for (const node of deserializedNodes(editor, summary)) {
    if (TextApi.isText(node)) {
      inlines.push(node);
      continue;
    }

    if (!ElementApi.isElement(node)) {
      continue;
    }

    if (node.type === KEYS.p) {
      for (const child of node.children) {
        if (
          ElementApi.isElement(child) &&
          (child.type === KEYS.p || allowsFirstChild(KEYS.toggle, child.type))
        ) {
          inlines.push(...textLeaves(child));
          continue;
        }

        inlines.push(child);
      }
      continue;
    }

    const text = nodeText(node);
    if (text.length > 0) {
      inlines.push({ text });
    }
  }

  return inlines.length > 0 ? inlines : [{ text: "" }];
}

function contentBlocks(editor: SlateEditor, node: ChildNode): TElement[] {
  if (node.nodeType === Node.TEXT_NODE) {
    const text = node.textContent ?? "";
    if (text.trim().length === 0) {
      return [];
    }

    return [{ type: KEYS.p, children: [{ text }] }];
  }

  if (!isHtmlElementNode(node)) {
    return [];
  }

  const blocks: TElement[] = [];
  for (const child of deserializedNodes(editor, node)) {
    if (ElementApi.isElement(child)) {
      blocks.push(child);
      continue;
    }

    if (TextApi.isText(child) && child.text.length > 0) {
      blocks.push({ type: KEYS.p, children: [child] });
    }
  }

  return blocks;
}

// SUMMARY is the label. Without one, the label is an empty paragraph and the
// rest stays content. The container sanitizer then enforces the nesting cap.
function parseDetails(editor: SlateEditor, element: HTMLElement, type: string): TElement {
  let summary: HTMLElement | undefined;
  const rest: ChildNode[] = [];
  for (const child of element.childNodes) {
    if (summary === undefined && isHtmlElementNode(child) && child.nodeName === "SUMMARY") {
      summary = child;
      continue;
    }

    rest.push(child);
  }

  const label = summary
    ? summaryLabel(editor, summary)
    : { type: KEYS.p, children: [{ text: "" }] };
  const content = rest.flatMap((child) => contentBlocks(editor, child));

  return {
    type,
    children: [label, ...content],
  };
}

export function readToggleOpenIds(editor: SlateEditor): Set<string> {
  const value: unknown = editor.getOption(togglePlugin, "openIds");
  if (!(value instanceof Set)) {
    return new Set();
  }

  const ids = new Set<string>();
  for (const id of value) {
    if (typeof id === "string" && id.length > 0) {
      ids.add(id);
    }
  }

  return ids;
}

function writeToggleOpenIds(editor: SlateEditor, ids: Set<string>): void {
  editor.setOption(togglePlugin, "openIds", ids);
}

function findToggle(editor: SlateEditor, id: string): [TElement, number[]] | undefined {
  for (const [node, path] of editor.api.nodes({
    at: [],
    match: (candidate) =>
      ElementApi.isElement(candidate) && candidate.type === KEYS.toggle && candidate.id === id,
  })) {
    if (ElementApi.isElement(node)) {
      return [node, path];
    }
  }

  return undefined;
}

function pathInside(parent: readonly number[], path: readonly number[]): boolean {
  if (path.length <= parent.length) {
    return false;
  }

  return parent.every((step, index) => path[index] === step);
}

function moveSelectionToLabelEnd(editor: SlateEditor, id: string): void {
  const selection = editor.selection;
  const entry = selection ? findToggle(editor, id) : undefined;
  if (!selection || !entry) {
    return;
  }

  const togglePath = entry[1];
  const focus = selection.focus.path;
  if (!pathInside(togglePath, focus)) {
    return;
  }

  const childIndex = focus[togglePath.length];
  if (childIndex === undefined || childIndex === 0) {
    return;
  }

  const end = editor.api.end(togglePath.concat(0));
  if (!end) {
    return;
  }

  editor.tf.withoutSaving(() => {
    editor.tf.select(end);
  });
}

export function toggleOpen(editor: SlateEditor, id: string, open?: boolean): void {
  const current = readToggleOpenIds(editor);
  const isOpen = current.has(id);
  const nextOpen = open ?? !isOpen;
  if (nextOpen === isOpen) {
    return;
  }

  if (!nextOpen) {
    moveSelectionToLabelEnd(editor, id);
  }

  const next = new Set(current);
  if (nextOpen) {
    next.add(id);
  } else {
    next.delete(id);
  }

  writeToggleOpenIds(editor, next);
}

export function openAncestorToggle(editor: SlateEditor): void {
  const entry = editor.api.above({
    match: (node) => ElementApi.isElement(node) && node.type === KEYS.toggle,
  });
  if (!entry || !ElementApi.isElement(entry[0]) || typeof entry[0].id !== "string") {
    return;
  }

  if (entry[0].id.length === 0) {
    return;
  }

  toggleOpen(editor, entry[0].id, true);
}

// Selection that lands in hidden content opens that toggle. Slate flushes editor.onChange
// in a microtask after select, undo, paste, and programmatic selection changes.
function revealClosedToggleContent(editor: SlateEditor): void {
  const selection = editor.selection;
  if (!selection) {
    return;
  }

  const next = readToggleOpenIds(editor);
  let path = selection.focus.path;
  let changed = false;
  while (path.length > 1) {
    const index = path[path.length - 1];
    path = path.slice(0, -1);
    if (index === undefined || index === 0) {
      continue;
    }

    const parent = editor.api.node(path);
    if (!parent || !ElementApi.isElement(parent[0]) || parent[0].type !== KEYS.toggle) {
      continue;
    }

    const id = parent[0].id;
    if (typeof id !== "string" || id.length === 0 || next.has(id)) {
      continue;
    }

    next.add(id);
    changed = true;
  }

  if (changed) {
    writeToggleOpenIds(editor, next);
  }
}

function isEditorOnChange(value: unknown): value is (options?: { operation?: unknown }) => void {
  return typeof value === "function";
}

export function installToggleOnChange(editor: SlateEditor): void {
  const onChange = editor.onChange;
  if (!isEditorOnChange(onChange)) {
    return;
  }

  editor.onChange = (options?: { operation?: unknown }) => {
    onChange(options);
    revealClosedToggleContent(editor);
  };
}

function labelContext(editor: SlateEditor): LabelContext | undefined {
  if (!editor.selection || !editor.api.isCollapsed()) {
    return undefined;
  }

  const block = editor.api.block();
  if (
    !block ||
    !ElementApi.isElement(block[0]) ||
    typeof block[0].type !== "string" ||
    !allowsFirstChild(KEYS.toggle, block[0].type) ||
    typeof block[0].listStyleType === "string" ||
    block[1][block[1].length - 1] !== 0
  ) {
    return undefined;
  }

  const parent = editor.api.parent(block[1]);
  if (
    !parent ||
    !ElementApi.isElement(parent[0]) ||
    parent[0].type !== KEYS.toggle ||
    typeof parent[0].id !== "string" ||
    parent[0].id.length === 0
  ) {
    return undefined;
  }

  return { id: parent[0].id, labelPath: block[1], togglePath: parent[1] };
}

function moveSplitAfterToggle(editor: SlateEditor, togglePath: number[]): void {
  const createdPath = togglePath.concat(1);
  const destination = PathApi.next(togglePath);
  if (!destination || !editor.api.node(createdPath)) {
    return;
  }

  editor.tf.moveNodes({ at: createdPath, to: destination });
  const start = editor.api.start(destination);
  if (start) {
    editor.tf.select(start);
  }
}

export function breakToggleLabel(editor: SlateEditor, insertBreak: () => void): boolean {
  const label = labelContext(editor);
  if (!label) {
    return false;
  }

  const atStart = editor.api.isAt({ start: true });
  const empty = editor.selection !== null && editor.api.isEmpty(editor.selection, { block: true });
  if ((atStart && !empty) || readToggleOpenIds(editor).has(label.id)) {
    return false;
  }

  insertBreak();
  moveSplitAfterToggle(editor, label.togglePath);
  return true;
}

export function backspaceToggleLabel(editor: SlateEditor): boolean {
  const label = labelContext(editor);
  if (!label || !editor.api.isAt({ start: true })) {
    return false;
  }

  const togglePath = label.togglePath;
  editor.tf.unwrapNodes({
    at: togglePath,
    match: (_node, path) => PathApi.equals(path, togglePath),
  });
  const start = editor.api.start(togglePath);
  if (start) {
    editor.tf.select(start);
  }

  return true;
}

export function collectToggleIds(editor: SlateEditor): Set<string> {
  const ids = new Set<string>();
  for (const [node] of editor.api.nodes({
    at: [],
    match: (candidate) => ElementApi.isElement(candidate) && candidate.type === KEYS.toggle,
  })) {
    if (ElementApi.isElement(node) && typeof node.id === "string" && node.id.length > 0) {
      ids.add(node.id);
    }
  }

  return ids;
}

export function openNewToggles(editor: SlateEditor, before: ReadonlySet<string>): void {
  const next = readToggleOpenIds(editor);
  let changed = false;
  for (const id of collectToggleIds(editor)) {
    if (before.has(id) || next.has(id)) {
      continue;
    }

    next.add(id);
    changed = true;
  }

  if (changed) {
    writeToggleOpenIds(editor, next);
  }
}

