    // Headings are not targets. Their leading stays on the heading component.
    nodeProps: {
      nodeKey: "lineHeight",
      defaultNodeValue: 0,
    },
    targetPlugins: [KEYS.p],
    targetPluginToInject: ({ editor }) => ({
      parsers: {
        html: {
          deserializer: {
            parse: ({ element }) => {
              const raw = element.style.lineHeight;
              if (!raw) {
