export type NotionLikeEditorBlockProps = {
  documentId: string;
  initialValue?: EditorValue;
  onChange?: (value: EditorValue) => void;
  readOnly?: boolean;
  placeholder?: string;
  ariaLabel?: string;
  className?: string;
  adapter?: EditorPersistenceAdapter;
  linkPreview?: LinkPreviewAdapter | null;
  mentionProvider?: MentionProvider | null;
  pageProvider?: PageProvider | null;
  onOpenPage?: (request: PageOpenRequest) => void;
  fileUpload?: FileUploadAdapter | null;
  options?: EditorOptions;
  features?: EditorFeatures;
};

export function NotionLikeEditorBlock(props: NotionLikeEditorBlockProps) {
  if (props.adapter) {
    return <PersistedEditor key={props.documentId} {...props} adapter={props.adapter} />;
  }

  return <MemoryEditor {...props} />;
}

import { createStaticEditor, PlateStatic } from "platejs/static";

import type { EditorValue } from "./lib/document/editor-value";
import { editorStaticPlugins } from "./lib/static/editor-static-plugins";
import { readStaticValue } from "./lib/static/read-static-value";

export type NotionLikeEditorStaticProps = {
  value: EditorValue;
  className?: string;
};

export function NotionLikeEditorStatic({ value, className }: NotionLikeEditorStaticProps) {
  const content = readStaticValue(value);
  if (content === null) {
    return <div className={className} />;
  }

  const editor = createStaticEditor({
    plugins: editorStaticPlugins,
    value: content,
  });

  const surface = className ? `${className} whitespace-pre-wrap` : "whitespace-pre-wrap";
  return <PlateStatic editor={editor} className={surface} />;
}

"use client";

import * as React from "react";
import { Check, Copy } from "lucide-react";

import { clickSoftSound } from "@/components/huanngdev/notion-like-editor/lib/click-soft";
import { playSound } from "@/components/huanngdev/notion-like-editor/lib/sound-engine";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

type CopyButtonProps = Omit<React.ComponentProps<typeof Button>, "onClick" | "children"> & {
  text: string;
  onCopy?: (text: string) => void;
};

export function CopyButton({
  text,
  onCopy,
  className,
  variant = "ghost",
  size = "icon",
  "aria-label": ariaLabel = "Copy to clipboard",
  ...props
}: CopyButtonProps) {
  const [copied, setCopied] = React.useState(false);
  const timeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);

  React.useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const handleClick = async () => {
    if (copied) return;
    try {
      await navigator.clipboard.writeText(text);
      void playSound(clickSoftSound.dataUri, { volume: 0.5 }).catch(() => {});
      setCopied(true);
      onCopy?.(text);
      timeoutRef.current = setTimeout(() => setCopied(false), 1000);
    } catch {
      // clipboard write failed; leave state as-is
    }
  };

  return (
    <Button
      type="button"
      variant={variant}
      size={size}
      onClick={handleClick}
      disabled={copied}
      aria-label={copied ? "Copied" : ariaLabel}
      data-copied={copied || undefined}
      className={cn("relative disabled:opacity-100", className)}
      {...props}
    >
      <Copy
        className={cn(
          "transition-all duration-200",
          copied ? "scale-0 opacity-0" : "scale-100 opacity-100",
        )}
      />
      <Check
        className={cn(
          "absolute transition-all duration-200",
          copied ? "scale-100 opacity-100" : "scale-0 opacity-0",
        )}
      />
    </Button>
  );
}

import type { SoundAsset } from "@/components/huanngdev/notion-like-editor/lib/sound-types";

export const clickSoftSound: SoundAsset = {
  name: "click-soft",
  dataUri:
    "data:audio/mpeg;base64,",
  duration: 0.007,
  format: "mp3",
  license: "CC0",
  author: "Kenney",
};

let audioContext: AudioContext | null = null;
const bufferCache = new Map<string, AudioBuffer>();

export function getAudioContext(): AudioContext {
  if (!audioContext) {
    audioContext = new AudioContext();
  }
  return audioContext;
}

export async function decodeAudioData(dataUri: string): Promise<AudioBuffer> {
  const cached = bufferCache.get(dataUri);
  if (cached) return cached;

  const ctx = getAudioContext();
  const base64 = dataUri.split(",")[1];
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }

  const audioBuffer = await ctx.decodeAudioData(bytes.buffer.slice(0));
  bufferCache.set(dataUri, audioBuffer);
  return audioBuffer;
}

export interface PlaySoundOptions {
  volume?: number;
  playbackRate?: number;
  onEnd?: () => void;
}

export interface SoundPlayback {
  stop: () => void;
}

export async function playSound(
  dataUri: string,
  options: PlaySoundOptions = {},
): Promise<SoundPlayback> {
  const { volume = 1, playbackRate = 1, onEnd } = options;
  const ctx = getAudioContext();
  if (ctx.state === "suspended") {
    await ctx.resume();
  }

  const buffer = await decodeAudioData(dataUri);
  const source = ctx.createBufferSource();
  const gain = ctx.createGain();

  source.buffer = buffer;
  source.playbackRate.value = playbackRate;
  gain.gain.value = volume;

  source.connect(gain);
  gain.connect(ctx.destination);

  source.onended = () => {
    onEnd?.();
  };

  source.start(0);

  return {
    stop: () => {
      try {
        source.stop();
      } catch {
        // No-op if already stopped.
      }
    },
  };
}

export interface SoundAsset {
  /** Unique identifier for the sound */
  name: string;
  /** Base64-encoded data URI (data:audio/mpeg;base64,...) */
  dataUri: string;
  /** Duration in seconds */
  duration: number;
  /** Audio format */
  format: "mp3" | "wav" | "ogg";
  /** License identifier */
  license: "CC0" | "OGA-BY" | "MIT";
  /** Original author/creator */
  author: string;
}

export interface UseSoundOptions {
  /** Volume level from 0 to 1. Default: 1 */
  volume?: number;
  /** Playback speed multiplier. Default: 1 */
  playbackRate?: number;
  /** If true, calling play() stops current playback first. Default: false */
  interrupt?: boolean;
  /** If false, play() does nothing. Useful for user preferences. Default: true */
  soundEnabled?: boolean;
  /** Called when playback starts */
  onPlay?: () => void;
  /** Called when playback ends naturally */
  onEnd?: () => void;
  /** Called when pause() is called */
  onPause?: () => void;
  /** Called when stop() is called */
  onStop?: () => void;
}

export type PlayFunction = (overrides?: { volume?: number; playbackRate?: number }) => void;

export interface SoundControls {
  stop: () => void;
  pause: () => void;
  isPlaying: boolean;
  duration: number | null;
  sound: SoundAsset;
}

export type UseSoundReturn = readonly [PlayFunction, SoundControls];
